const REPDB_EQUIPMENT={bodyweight:'Paša svars / iespējams balsts',dumbbell:'Hanteles',barbell:'Svaru stienis',kettlebell:'Svaru bumba',cable:'Kabeļu trenažieris',pull_up_bar:'Pievilkšanās stienis',ez_bar:'EZ stienis',smith_machine:'Smita trenažieris',flat_bench:'Sols',loop_band:'Gumijas cilpa',resistance_band:'Pretestības gumija',suspension_trainer:'Piekares siksnas',rings:'Vingrošanas riņķi',bosu_ball:'BOSU',stability_ball:'Vingrošanas bumba',leg_press:'Kāju preses trenažieris',dip_station:'Līdztekas',plates:'Svaru diski',leg_curl:'Kāju saliekšanas trenažieris',dip_machine:'Līdzteku trenažieris',battle_rope:'Treniņu virves',lat_pulldown_machine:'Augšējās vilkmes trenažieris',plyo_box:'Stabila kaste',hack_squat:'Hack pietupienu trenažieris',treadmill:'Skrejceliņš',leg_extension:'Kāju iztaisnošanas trenažieris',standing_calf_raise_machine:'Ikru trenažieris stāvus',shoulder_press_machine:'Plecu spiešanas trenažieris',plate_loaded_lateral_raise_machine:'Plecu sānu pacelšanas trenažieris',sled:'Spēka ragavas',ab_wheel:'Vēdera preses ritenis',air_bike:'Gaisa pretestības velotrenažieris',assisted_pullup_machine:'Pievilkšanās trenažieris ar atbalstu',chest_press_machine:'Krūšu spiešanas trenažieris',seated_row_machine:'Sēdus vilkmes trenažieris',bicycle:'Velosipēds',elliptical:'Eliptiskais trenažieris',trap_bar:'Trap stienis',hip_abduction_machine:'Gurnu atvēršanas trenažieris',hip_adduction_machine:'Gurnu savēršanas trenažieris',jump_rope:'Lecamaukla',back_extension_machine:'Muguras iztaisnošanas trenažieris',bicep_curl_machine:'Bicepsa trenažieris',chest_fly_machine:'Krūšu savēršanas trenažieris',preacher_curl_machine:'Bicepsa trenažieris ar balstu',reverse_fly_machine:'Plecu aizmugures trenažieris',ab_crunch_machine:'Vēdera preses trenažieris',tricep_extension_machine:'Tricepsa trenažieris',medicine_ball:'Medicīnas bumba',slam_ball:'Metamā bumba',glute_ham_developer:'GHD trenažieris',pec_deck:'Krūšu savēršanas trenažieris',donkey_calf_raise_machine:'Ikru trenažieris noliecienā',hip_thrust_machine:'Gurnu pacelšanas trenažieris',plate_loaded_dip_machine:'Līdzteku trenažieris ar diskiem',shrug_machine:'Trapeces trenažieris',climbing_rope:'Kāpšanas virve',rower:'Airēšanas trenažieris',sandbag:'Smilšu maiss',seated_calf_raise_machine:'Ikru trenažieris sēdus',ski_erg:'Slēpošanas ergometrs',stair_climber:'Kāpņu trenažieris',stationary_bike:'Velotrenažieris',wall_ball:'Sienas metienu bumba',wrist_roller:'Apakšdelmu veltnis'};
const REPDB_GROUPS={upper_legs:'Kājas',lower_legs:'Kājas',back:'Mugura',core:'Core',shoulders:'Pleci',upper_arms:'Rokas',lower_arms:'Rokas',chest:'Krūtis',full_body:'Pilns ķermenis'};
const REPDB_CATALOG=[["90-90-hold","90/90 Hold","beginner","bodyweight","upper_legs","A seated hip mobility hold: both knees are bent to about 90 degrees, one leg in front of you and turned out, the other out to the side and turned in. Holding the position with your trunk upright stretches the outer hip of the front leg and the front of the hip of the back leg.",["Sit on the floor and bend your front leg in front of you so your shin runs across your body and your knee is bent to about 90 degrees.","Place your back leg out to the side with that knee also bent to about 90 degrees, shin pointing back.","Put your hands on the floor beside your hips for support.","Sit up tall, with your chest lifted and both sitting bones as close to the floor as you can manage.","Hold the position, breathing slowly, feeling the stretch in the outer hip of the front leg and the front of the hip of the back leg.","Hold for the planned time, then switch the legs and hold on the other side."],["Keep the trunk upright; slumping takes the stretch out of the hips.","If the hips are tight, keep more weight on your hands or sit on a folded towel until you can sit taller.","Ease into the stretch and do not force the knees down; the position should feel strong, not painful."],{"main":"images/flat/90-90-hold-main.webp"},"stretching"],["90-90-switch","90/90 Switch","intermediate","bodyweight","upper_legs","A hip-mobility drill in which you sit with both knees bent at right angles and rotate your legs from one side to the other, keeping the 90/90 position on each side. It trains the internal and external rotation of both hips as you switch.",["Sit on the floor with the front knee bent at 90 degrees and the back knee bent at 90 degrees, and place your hands behind you for support.","Sit tall and keep your trunk upright.","Lift both knees slightly and rotate your legs to the other side in a controlled movement, so that the front leg becomes the back leg.","Settle into the 90/90 position on the new side, using your hands for balance.","Switch back to the first side, and repeat for the planned repetitions.","Keep the movement slow and smooth, without forcing the hips."],["Keep your trunk tall; leaning back too far takes the work out of the hips.","Do the 90/90 hold first if you cannot reach the position on both sides.","Move slowly and stop if you feel pinching in the hip or pain in the knee."],{"start":"images/flat/90-90-switch-start.webp","peak":"images/flat/90-90-switch-peak.webp"},"stretching"],["ab-wheel-rollout","Ab Wheel Rollout","intermediate","ab_wheel","core","A core exercise rolling a wheel forward and back, training anti-extension of the spine.",["Kneel on the floor and grip the ab wheel handles shoulder-width.","Brace the core hard so the lower back stays neutral.","Roll the wheel slowly forward, extending the body as far as you can control.","Stop before the hips sag or the back arches.","Pull the wheel back to the knees by contracting the abs."],["Brace the core before each rep - do not let the lower back arch.","Build range gradually, stopping short of any hip sag.","Drop to a wall stop if you cannot control the bottom."],{"start":"images/flat/ab-wheel-rollout-start.webp","peak":"images/flat/ab-wheel-rollout-peak.webp"},"strength"],["air-bike","Air Bike","intermediate","air_bike","full_body","A full-body conditioning exercise on the air bike, combining pedaling with an arm push-pull for sustained power output.",["Sit on the air bike and grip the moving handles.","Place your feet on the pedals and brace your core.","Push and pull the handles while pedaling at a steady pace.","Drive with both arms and legs to maintain power output.","Continue for the desired duration or distance."],["Keep your torso upright and avoid slumping over the handles.","Breathe rhythmically to sustain effort over longer intervals.","Pull the handles with your back, not just your arms."],{"main":"images/flat/air-bike-main.webp"},"cardio"],["archer-pull-ups","Archer Pull Ups","advanced","pull_up_bar","back","A unilateral pull-up shifting the body toward one hand while the other arm stays straight, building single-arm pulling strength.",["Grip the bar wider than shoulder width with palms facing away.","Pull yourself up while shifting your body toward one hand.","Keep the opposite arm straight as a support.","Lower yourself under control back to the hang.","Alternate sides each rep or complete reps on one side first."],["Keep the straight arm fully extended and use it only as a guide.","Pull your chin toward the working hand, not straight up.","Master wide-grip pull-ups before progressing to archers."],{"start":"images/flat/archer-pull-ups-start.webp","peak":"images/flat/archer-pull-ups-peak.webp"},"strength"],["archer-push-ups","Archer Push Ups","advanced","bodyweight","chest","A wide push-up lowering toward one hand while the opposite arm stays straight, loading one side at a time.",["Set up in a wide push-up position with arms straight.","Lower yourself toward one hand while keeping the other arm straight.","Keep your core tight and body in a straight line.","Press back up to the start position.","Alternate sides each rep for the desired number of reps."],["Keep your hips square to the floor as you shift sideways.","Let the straight arm assist as little as possible.","Start from wide push-ups and shift a little further each session."],{"start":"images/flat/archer-push-ups-start.webp","peak":"images/flat/archer-push-ups-peak.webp"},"strength"],["arnold-press","Arnold Press","intermediate","dumbbell","shoulders","An overhead press variation rotating the palms from facing the body to facing forward, working the front and side deltoids.",["Hold a pair of dumbbells at shoulder height with palms facing you.","Press the dumbbells overhead while rotating your palms to face forward.","Fully extend your arms at the top without locking the elbows.","Reverse the motion and rotate back to the start.","Repeat for the desired number of reps."],["Time the palm rotation evenly throughout the press, not all at once.","Avoid arching your lower back as the weight goes overhead.","Use a lighter load than a standard press to control the rotation."],{"start":"images/flat/arnold-press-start.webp","peak":"images/flat/arnold-press-peak.webp"},"strength"],["assisted-dips","Machine Assisted Dips","beginner","dip_machine","upper_arms","A beginner-friendly dip performed on an assisted machine that offsets body weight, training the chest and triceps.",["Step onto the assisted dip machine with knees on the pad.","Grip the parallel bars and support your weight with straight arms.","Lower your body by bending your elbows until shoulders are below elbows.","Press back up to the start position.","Repeat for the desired number of reps."],["Keep your elbows tracking back rather than flaring out wide.","Stop the descent if you feel pinching in the shoulders.","Reduce the assistance gradually as pressing strength improves."],{"start":"images/flat/assisted-dips-start.webp","peak":"images/flat/assisted-dips-peak.webp"},"strength"],["assisted-pull-ups","Assisted Pull Ups","beginner","assisted_pullup_machine","back","A machine-assisted pull-up reducing the effective body weight, allowing beginners to train the lats through a full range.",["Place your knees on the assisted pull-up machine pad.","Grip the bar with palms facing away, slightly wider than shoulders.","Pull your chest toward the bar by driving your elbows down.","Lower yourself under control to a full hang.","Repeat for the desired number of reps."],["Pull your shoulder blades down before bending your arms.","Avoid swinging or using momentum from the knee pad.","Decrease the assistance over time to progress toward unassisted reps."],{"start":"images/flat/assisted-pull-ups-start.webp","peak":"images/flat/assisted-pull-ups-peak.webp"},"strength"],["back-extension","Back Extension","beginner","bodyweight","back","An isolation movement targeting the lower back erector spinae on a hyperextension bench.",["Lie face down on a hyperextension bench with hips at the pad edge.","Lower your upper body toward the floor.","Raise your torso back up until your body is straight.","Repeat."],["Keep movements controlled.","Do not hyperextend beyond neutral spine."],{"start":"images/flat/back-extension-start.webp","peak":"images/flat/back-extension-peak.webp"},"strength"],["back-lever","Back Lever","advanced","pull_up_bar","full_body","An advanced gymnastic isometric: hanging from a bar, the body is held horizontal and face-down in a straight line, demanding total-body tension through the lats, core, and posterior chain.",["Hang from a bar with an overhand grip and rotate backward through the arms until inverted.","Lower the body forward and down until it is horizontal, facing the floor.","Keep the arms straight and the whole body in one rigid line from head to heels.","Brace the core and squeeze the glutes so the hips and shoulders do not sag.","Hold for time, then rotate back up under control."],["Build up with tucked and one-leg progressions before the full straight-body lever.","Depress and retract the shoulder blades to protect the shoulders.","Stay rigid -- any pike or arch collapses the hold."],{"main":"images/flat/back-lever-main.webp"},"strength"],["balance-dome-crunch","Balance Dome Crunch","intermediate","bosu_ball","core","A crunch done lying with your lower back on the domed side of a balance dome. The dome lets you start the curl from a slightly extended position, which lengthens the abdominals, and its instability makes the trunk work to keep you steady.",["Place the balance dome on the floor with the domed side up and sit on it, then lie back so your lower back rests on the dome.","Bend your knees and place your feet flat on the floor, about hip-width apart.","Put your hands behind your head with your elbows wide, without pulling on your neck.","Curl your shoulders and upper back up toward your hips by shortening the distance between your ribs and your pelvis.","Pause briefly at the top and keep your lower back on the dome.","Lower back slowly to the start and repeat for the planned repetitions."],["Lead with the ribcage rather than the head; your hands only support your head.","Do not let the dome roll away; keep your feet planted and your hips still.","Start with a small range and extend further back over the dome as your control improves."],{"start":"images/flat/balance-dome-crunch-start.webp","peak":"images/flat/balance-dome-crunch-peak.webp"},"strength"],["balance-dome-glute-bridge","Balance Dome Glute Bridge","intermediate","bosu_ball","upper_legs","A glute bridge with both feet on a balance dome: lying on your back with your heels or soles on the domed top, you lift your hips until your body is straight from shoulders to knees. The unstable surface makes the glutes and hamstrings work harder to keep the hips level.",["Lie on your back on the floor with your knees bent and place both feet on the top of a balance dome with the domed side up.","Rest your arms flat on the floor beside you with your palms down.","Brace your trunk and press through your feet to lift your hips off the floor.","Raise your hips until your body forms a straight line from your shoulders to your knees.","Squeeze your glutes at the top and keep your hips level while the dome moves under your feet.","Lower your hips slowly to the floor and repeat for the planned repetitions."],["Press your whole foot into the dome rather than only the heel, which keeps the surface steadier.","Do not arch your lower back at the top; finish the lift with your glutes.","Master the floor glute bridge first and move your feet closer to the dome only when you can keep your hips level."],{"start":"images/flat/balance-dome-glute-bridge-start.webp","peak":"images/flat/balance-dome-glute-bridge-peak.webp"},"strength"],["balance-dome-plank","Balance Dome Plank","intermediate","bosu_ball","core","A forearm plank with the elbows on a balance dome. The unstable surface makes the shoulders and the whole trunk work harder to keep the body in a straight line from head to heels.",["Place the balance dome on a flat floor with the domed side up and kneel behind it.","Put your forearms on the dome with your elbows under your shoulders.","Step your feet back into a plank with your body in a straight line from head to heels.","Squeeze your glutes and brace your abdominals, keeping your neck long.","Hold the position for the planned time while the dome moves under you.","Lower your knees to the floor to finish."],["Do not let your hips sag or pike up; a straight line from head to heels is the target.","Press your forearms into the dome and keep your shoulders away from your ears.","Make it easier by widening your feet, or harder by bringing them closer together."],{"main":"images/flat/balance-dome-plank-main.webp"},"strength"],["balance-dome-push-up","Balance Dome Push-Up","intermediate","bosu_ball","chest","A push-up with the hands on a balance dome turned flat side up. The dome tilts under your hands, so the chest, shoulders and triceps press you up while the shoulder stabilisers and the trunk keep you steady.",["Turn the balance dome over so that its flat platform faces up, and place your hands on the platform at about shoulder-width.","Step your feet back into a high plank with your body in a straight line from head to heels.","Brace your trunk and lower your chest toward the platform by bending your elbows.","Lower until your chest is just above the platform, keeping your elbows about 45 degrees from your body.","Press the platform away to straighten your arms, keeping the dome as level as you can.","Repeat for the planned repetitions."],["Do plain push-ups first; the dome adds instability to a movement you should already control.","Keep your hips level and do not let the dome tilt to one side; look slightly ahead of your hands.","Place the dome on a non-slip floor and make sure the platform is flat before you put your weight on it."],{"start":"images/flat/balance-dome-push-up-start.webp","peak":"images/flat/balance-dome-push-up-peak.webp"},"strength"],["balance-dome-single-leg-stand","Balance Dome Single-Leg Stand","advanced","bosu_ball","lower_legs","A balance hold on one leg on a balance dome, with the other knee lifted in front of you. The ankle, calf and hip muscles of the standing leg constantly adjust to the tilting surface, which makes it a demanding balance and rehabilitation exercise.",["Place the balance dome on a flat floor with the domed side up, next to a wall or a sturdy support.","Step onto the middle of the dome with one foot and stand tall with your knee slightly bent.","Shift your weight onto that leg and lift the other knee in front of you until the thigh is about hip height.","Keep your hips level, your chest tall and your eyes on a fixed point ahead.","Hold for the planned time, letting your ankle and calf make small corrections.","Lower the foot, rest and repeat on the other leg."],["Learn the two-foot balance dome stand first and keep a wall within reach.","Press the whole foot into the dome and let your toes spread; do not grip the surface with them.","Do not look down at your feet; a fixed point ahead helps your balance."],{"main":"images/flat/balance-dome-single-leg-stand-main.webp"},"strength"],["balance-dome-squat","Balance Dome Squat","intermediate","bosu_ball","upper_legs","A bodyweight squat done standing on the domed side of a balance dome. The surface moves under your feet, so the quadriceps and glutes lower and lift the body while the ankles and trunk work to keep you balanced.",["Place the balance dome on a flat floor with the domed side up and step onto the middle of it with both feet, about hip-width apart.","Find your balance and reach your arms straight out in front of you.","Push your hips back and bend your knees, lowering until your thighs are close to parallel with the floor.","Keep your chest up and your knees in line with your toes.","Press through your whole foot to stand back up.","Repeat for the planned repetitions and step off one foot at a time."],["Do the balance dome stand and squat hold first; the moving squat adds change of position to an unstable surface.","Keep your weight spread over the whole foot; heels lifting or knees caving inward are signs the surface is too hard for now.","Hold a wall or a rack with one hand until the movement feels steady."],{"start":"images/flat/balance-dome-squat-start.webp","peak":"images/flat/balance-dome-squat-peak.webp"},"strength"],["balance-dome-squat-hold","Balance Dome Squat Hold","intermediate","bosu_ball","upper_legs","A static squat held on a balance dome: you stand on the domed top and lower into a partial squat with your arms reaching forward, then stay there while the unstable surface keeps shifting. The quadriceps and glutes hold the position and the ankles and trunk work to keep you balanced.",["Place the balance dome on a flat floor with the domed side up and step onto the middle of it with both feet, about hip-width apart.","Stand tall and find your balance before you start to squat.","Push your hips back and bend your knees until your thighs are close to parallel with the floor.","Reach your arms straight out in front of you to counterbalance and keep your chest up.","Hold the position for the planned time, keeping your knees in line with your toes.","Stand up slowly and step off one foot at a time."],["Master the plain balance dome stand first; the squat adds load to an unstable surface.","Spread your weight across the whole foot and do not let your heels lift or your knees cave inward.","Hold a wall or a rack with one hand while you learn the position."],{"main":"images/flat/balance-dome-squat-hold-main.webp"},"strength"],["balance-dome-stand","Balance Dome Stand","beginner","bosu_ball","lower_legs","A balance hold on a balance dome, the half-sphere trainer with a flat base: you stand on its domed top with both feet and keep your body steady while the surface moves under you. The calves and the small muscles around the ankles work constantly to hold you upright.",["Place the balance dome on a flat floor with the domed side up and stand next to it.","Step onto the middle of the dome with one foot, then bring the other foot up beside it, about hip-width apart.","Stand tall with your arms relaxed at your sides and your knees slightly bent.","Keep your weight even across both feet and look at a point straight ahead.","Hold the position for the planned time, letting your ankles and calves make small corrections.","Step off one foot at a time to finish."],["Stand next to a wall or a sturdy support the first few times so you can steady yourself.","Grip the dome with the whole foot and keep your toes relaxed; clenching them makes the balance harder.","Do not stare at your feet; a fixed point ahead of you helps your balance."],{"main":"images/flat/balance-dome-stand-main.webp"},"strength"],["balance-dome-step-up","Balance Dome Step-Up","intermediate","bosu_ball","upper_legs","A single-leg step-up onto a balance dome: you place one foot on the domed top, stand up on it and then step back down. The surface tilts under your foot, so the quadriceps and glutes lift the body while the hips and ankle work to keep you steady.",["Stand facing the balance dome, placed domed side up on a flat floor.","Place one foot flat in the middle of the dome.","Press through the whole foot and straighten that leg to stand up on the dome, bringing your other foot beside it.","Stand tall for a moment and keep your weight centred over the dome.","Step back down with the other foot first, then the working foot.","Complete the planned repetitions on one leg, then switch legs."],["Put your foot in the middle of the dome; stepping near the edge makes it tip.","Push through the heel and the whole foot rather than hopping up from the back leg.","Hold a wall or a rack with one hand until you can step up and down smoothly."],{"start":"images/flat/balance-dome-step-up-start.webp","peak":"images/flat/balance-dome-step-up-peak.webp"},"strength"],["ball-leg-curl","Stability Ball Leg Curl","intermediate","stability_ball","upper_legs","A bodyweight hamstring curl using a stability ball, rolling the heels toward the glutes while bridging the hips.",["Lie face-up on the floor with your heels and lower calves on top of a stability ball, arms out for balance.","Press through the heels to raise your hips into a straight line from shoulders to ankles.","Keeping the hips up, bend the knees to roll the ball toward your glutes.","Extend the legs back out under control without dropping the hips.","Complete all reps, then lower the hips and step off the ball."],["Hips stay up for the whole set - this is a combo bridge plus curl.","Start with both feet; progress to single-leg when it becomes easy."],{"start":"images/flat/ball-leg-curl-start.webp","peak":"images/flat/ball-leg-curl-peak.webp"},"strength"],["ball-pike","Ball Pike","advanced","stability_ball","core","An advanced core exercise where the hips pike up while the feet roll a stability ball toward the chest.",["Place the shins on a stability ball and hands on the floor in a high plank.","Brace the core and keep the legs straight.","Pike the hips up, rolling the ball toward the chest as the body forms an inverted V.","Pause briefly at the top.","Roll the ball back out to the starting plank."],["Keep the legs straight throughout - no knee bend.","Move at the hips, not the lower back.","Build up with knee tucks first if the pike is too hard."],{"start":"images/flat/ball-pike-start.webp","peak":"images/flat/ball-pike-peak.webp"},"strength"],["band-assisted-pull-ups","Band Assisted Pull Ups","beginner","resistance_band","back","A pull-up variation using a resistance band for assistance, reducing the load to build toward unassisted reps.",["Loop a resistance band over the pull-up bar and step one foot into it.","Grip the bar with palms facing away, shoulder-width apart.","Pull your chest toward the bar by driving your elbows down.","Lower yourself under control to a full hang.","Repeat for the desired number of reps."],["Avoid letting the band's recoil bounce you out of the bottom.","Keep the banded foot steady so the band cannot slip off.","Progress to thinner bands as your pulling strength increases."],{"start":"images/flat/band-assisted-pull-ups-start.webp","peak":"images/flat/band-assisted-pull-ups-peak.webp"},"strength"],["band-pull-apart","Band Pull Apart","beginner","resistance_band","shoulders","A high-volume rear delt and scapular retractor exercise performed by pulling a resistance band apart at shoulder height.",["Stand holding a light resistance band with both hands, arms extended straight in front at shoulder height.","Hands start shoulder-width apart, palms facing down.","Keeping arms straight, pull the band apart by driving the hands out to the sides.","Finish with the band touching your chest and the shoulder blades squeezed together.","Return slowly to the starting position and repeat."],["Lead the movement with the little fingers - this externally rotates the shoulders.","Use a band light enough to do 15-30 clean reps; this is a high-rep prehab exercise."],{"start":"images/flat/band-pull-apart-start.webp","peak":"images/flat/band-pull-apart-peak.webp"},"strength"],["banded-adductor-stretch","Banded Adductor Stretch","beginner","resistance_band","upper_legs","A lying stretch that uses a band to guide one straight leg out to the side and lengthen the inner thigh.",["Lie on your back with a band looped around one foot.","Raise that leg and let it open out to the side.","Hold the band to control how far the leg lowers.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep your hips flat and both glutes on the floor.","Stretch to mild tension, never to pain."],{"main":"images/flat/banded-adductor-stretch-main.webp"},"stretching"],["banded-ankle-stretch","Banded Ankle Stretch","beginner","resistance_band","lower_legs","A seated stretch that uses a band around the forefoot to flex the ankle and lengthen the calf.",["Sit with one leg extended and a band around the forefoot.","Hold the band in both hands.","Pull so the toes draw back toward your shin.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep the leg straight and relaxed.","Stretch to mild tension, never to pain."],{"main":"images/flat/banded-ankle-stretch-main.webp"},"stretching"],["banded-calf-stretch","Banded Calf Stretch","beginner","resistance_band","lower_legs","A lying stretch that uses a band around the ball of the foot to flex the ankle and lengthen the calf.",["Lie on your back and loop a band around the ball of one foot.","Raise the leg and keep it fairly straight.","Pull the band so your toes draw back toward your shin.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep the pull steady, not jerky.","Keep the knee softly straight."],{"main":"images/flat/banded-calf-stretch-main.webp"},"stretching"],["banded-chest-stretch","Banded Chest Stretch","beginner","resistance_band","chest","A standing stretch that opens the chest by holding a band behind the back and drawing the arms apart.",["Hold a band behind your back with both hands.","Straighten your arms and draw them apart.","Lift your chest and squeeze your shoulder blades.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your shoulders down away from your ears.","Stretch to mild tension, never to pain."],{"main":"images/flat/banded-chest-stretch-main.webp"},"stretching"],["banded-clamshell","Banded Clamshell","beginner","loop_band","upper_legs","A clamshell hip-abduction performed with a loop band wrapped above the knees. The band adds constant tension on the gluteus medius - a small, focused isolation drill for hip stability.",["Lie on your side with hips and knees bent to roughly 45 degrees, feet stacked.","Place a loop band around both legs above the knees.","Keep the feet pressed together and the pelvis stable - do not roll back as you move.","Open the top knee upward against the band, like a clamshell opening, until you feel the glute fire.","Pause briefly at the top, then lower under control to the start.","Complete all reps on one side, then switch."],["The pelvis stays stacked - the moment you start rocking back, the glute disengages.","Slow controlled tempo beats heavy band; this is a stability drill, not a strength PR.","If you cramp in the side of the hip, that is exactly the right muscle. Shorten the set."],{"start":"images/flat/banded-clamshell-start.webp","peak":"images/flat/banded-clamshell-peak.webp"},"strength"],["banded-figure-4-stretch","Banded Figure-4 Stretch","beginner","resistance_band","upper_legs","A lying glute stretch in a figure-4 position, using a band to draw both legs toward the chest.",["Lie on your back and cross one ankle over the opposite thigh.","Loop a band around the supporting thigh.","Pull both legs toward your chest with the band.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep your head and shoulders relaxed on the floor.","Let the crossed knee fall open."],{"main":"images/flat/banded-figure-4-stretch-main.webp"},"stretching"],["banded-fire-hydrant","Banded Fire Hydrant","beginner","loop_band","upper_legs","This isolation exercise uses a loop band to target and strengthen the gluteus medius and maximus, improving hip abduction and stability.",["Place a loop band just above your knees and assume a quadruped position with hands under shoulders and knees under hips.","Keep your core engaged and back flat, maintaining a neutral spine throughout the movement.","Slowly lift one knee out to the side, keeping the knee bent at 90 degrees, until your thigh is parallel to the floor.","Hold briefly at the top, squeezing your glute, then slowly lower your leg back to the starting position with control.","Complete all repetitions on one side before switching to the other side."],["Focus on controlled movement; avoid using momentum to lift your leg.","Keep your hips stable and prevent your torso from rotating or leaning.","Ensure the band stays taut throughout the entire range of motion."],{"start":"images/flat/banded-fire-hydrant-start.webp","peak":"images/flat/banded-fire-hydrant-peak.webp"},"strength"],["banded-glute-bridge","Banded Glute Bridge","beginner","loop_band","upper_legs","A glute bridge with a loop band placed above the knees. Driving the knees out against the band recruits the gluteus medius alongside the prime glute-max bridge - a cheap accessory that doubles as hip activation.",["Lie on your back with the knees bent and feet flat on the floor, shoulder-width apart.","Place a loop band around both legs just above the knees.","Press the lower back into the floor and brace the core.","Drive through the heels and squeeze the glutes to lift the hips into a bridge - keep the band tension by pushing the knees outward.","At the top, the body forms a straight line from shoulders to knees. Pause briefly.","Lower under control to the start and repeat for the recommended number of repetitions."],["The knees want to cave inward - that is the band telling you to push them out.","Stop the lift when your hips are level with your shoulders and knees; do not hyperextend the lower back.","Squeeze hard at the top - a fast, half-rep bridge feels easy because it is."],{"start":"images/flat/banded-glute-bridge-start.webp","peak":"images/flat/banded-glute-bridge-peak.webp"},"strength"],["banded-good-morning","Banded Good Morning","beginner","loop_band","upper_legs","A hip-hinge with a loop band over the upper back, targeting the hamstrings and glutes.",["Stand on a loop band with both feet and pass it over the back of your neck.","Set feet hip-width with a soft bend in the knees.","Hinge at the hips, pushing them back with a flat back.","Lower until you feel a stretch in the hamstrings.","Drive the hips forward to return to standing."],["Move from the hips, not the lower back.","Keep the chest up and the back flat throughout.","Use a band light enough to allow full range of motion."],{"start":"images/flat/banded-good-morning-start.webp","peak":"images/flat/banded-good-morning-peak.webp"},"strength"],["banded-hamstring-stretch","Banded Hamstring Stretch","beginner","resistance_band","upper_legs","A lying stretch that uses a band around the foot to draw a straight leg toward the torso and lengthen the hamstring.",["Lie on your back and loop a band around one foot.","Raise that leg straight up, holding the band in both hands.","Gently pull the band to draw the leg toward you.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep the raised leg as straight as you can.","Keep the other leg flat on the floor."],{"main":"images/flat/banded-hamstring-stretch-main.webp"},"stretching"],["banded-hip-thrust","Banded Hip Thrust","beginner","loop_band","upper_legs","This exercise uses a loop band to increase glute activation during a hip thrust, effectively targeting the gluteus maximus, hamstrings, and gluteus medius for improved lower body strength.",["Place a loop band just above your knees and sit on the floor with your upper back against a bench.","Bend your knees, plant your feet hip-width apart, and position the band to create tension.","Drive through your heels, extend your hips, and lift your glutes off the floor until your body forms a straight line from shoulders to knees.","Squeeze your glutes forcefully at the top, ensuring your knees are pushed out against the band.","Slowly lower your hips back to the starting position with control."],["Maintain constant tension on the band throughout the movement.","Focus on a strong glute contraction at the peak of the thrust.","Keep your chin tucked and gaze forward to maintain a neutral spine.","Ensure your shins are vertical at the top of the movement."],{"start":"images/flat/banded-hip-thrust-start.webp","peak":"images/flat/banded-hip-thrust-peak.webp"},"strength"],["banded-it-band-stretch","Banded IT-Band Stretch","beginner","resistance_band","upper_legs","A lying stretch that uses a band to draw one leg across the body and target the outer thigh and hip.",["Lie on your back with a band around one raised foot.","Hold the band with the opposite hand.","Draw the straight leg across your body toward the floor.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep both shoulders down on the floor.","Stop when you feel a stretch along the outer thigh."],{"main":"images/flat/banded-it-band-stretch-main.webp"},"stretching"],["banded-kneeling-hip-thrust","Banded Kneeling Hip Thrust","beginner","loop_band","upper_legs","This exercise strengthens the glutes and hamstrings by driving the hips forward against band resistance from a kneeling position.",["Anchor a band low on a sturdy post, at the height of your hips when kneeling, and loop it around your hips. Kneel facing away from the post, torso upright and knees hip-width apart, far enough forward that the band is taut.","Sit your hips back toward your heels, leaning slightly forward with your back straight and core braced.","Initiate the movement by squeezing your glutes, driving your hips forward until your torso is upright.","Squeeze your glutes hard at the top, maintaining tension on the band.","Slowly reverse the movement, controlling the band's resistance as you return to the starting position."],["Focus on a strong glute contraction at the top of the movement.","Keep your core engaged throughout to prevent arching your lower back.","Kneel far enough from the post that the band stays taut even at the bottom."],{"start":"images/flat/banded-kneeling-hip-thrust-start.webp","peak":"images/flat/banded-kneeling-hip-thrust-peak.webp"},"strength"],["banded-lat-stretch","Banded Lat Stretch","beginner","resistance_band","back","A standing stretch that lengthens the lats by hinging forward while holding a band overhead under tension.",["Hold a band overhead with both hands under light tension.","Hinge forward at the hips with your arms reaching ahead.","Let your chest sink to lengthen the sides of your back.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your arms straight and shoulders relaxed.","Relax and keep breathing throughout."],{"main":"images/flat/banded-lat-stretch-main.webp"},"stretching"],["banded-lateral-walk","Banded Lateral Walk","beginner","loop_band","upper_legs","A side-stepping movement performed with a loop band wrapped above the knees or around the ankles. Constant abduction tension fires the gluteus medius - a staple warm-up and rehab drill for hip stability.",["Place a loop band around the legs above the knees (or around the ankles for a harder version).","Stand in a quarter-squat: feet shoulder-width, hips back, chest up, knees tracking over the toes.","Step one foot directly out to the side against the band tension.","Bring the trailing foot in toward the lead - keep tension on the band the entire time, do not let the feet snap together.","Continue side-stepping in one direction for the prescribed reps or distance, then reverse.","Stay low throughout; do not pop up between steps."],["Keep the toes pointing straight forward - do not let the lead foot turn out.","Hips stay level; do not rock side-to-side as you step.","If the knees cave inward, the band is too strong - drop to a lighter one."],{"start":"images/flat/banded-lateral-walk-start.webp","peak":"images/flat/banded-lateral-walk-peak.webp"},"strength"],["banded-rear-delt-stretch","Banded Rear Delt Stretch","beginner","resistance_band","shoulders","A standing stretch that targets the rear shoulder by pulling one arm across the body against band tension.",["Loop a band around one arm and hold the other end.","Draw that arm horizontally across your chest.","Use the band to deepen the pull gently.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep the working shoulder relaxed and down.","Relax and keep breathing throughout."],{"main":"images/flat/banded-rear-delt-stretch-main.webp"},"stretching"],["banded-romanian-deadlift","Banded Romanian Deadlift","beginner","loop_band","upper_legs","A Romanian deadlift using a loop band, ideal for warm-ups and learning the hip-hinge pattern.",["Stand on a loop band with both feet and grip the top of the band.","Set feet hip-width with a soft bend in the knees.","Hinge at the hips, sliding the hands down the legs.","Lower until you feel a stretch in the hamstrings.","Drive the hips forward to return to standing."],["Keep the band close to the legs throughout.","Stop at the bottom of your clean range - no rounded back.","The movement is a hinge, not a squat - knees barely bend."],{"start":"images/flat/banded-romanian-deadlift-start.webp","peak":"images/flat/banded-romanian-deadlift-peak.webp"},"strength"],["banded-seated-hip-abduction","Banded Seated Hip Abduction","beginner","loop_band","upper_legs","This isolation exercise targets the gluteus medius and maximus by externally rotating the hips against band resistance while seated.",["Sit on a bench or chair with a loop band around your knees.","Keep your feet flat on the floor, hip-width apart, and maintain an upright posture.","Push your knees outwards against the band, engaging your glutes.","Hold the peak contraction briefly, then slowly return your knees to the starting position.","Control the movement throughout the entire range of motion."],["Focus on squeezing your glutes to initiate the movement.","Avoid leaning back or using momentum; keep your torso stable.","Choose a band resistance that allows for controlled movement.","Maintain tension on the band even in the starting position."],{"start":"images/flat/banded-seated-hip-abduction-start.webp","peak":"images/flat/banded-seated-hip-abduction-peak.webp"},"strength"],["banded-shoulder-stretch","Banded Shoulder Stretch","beginner","resistance_band","shoulders","A standing stretch that opens the shoulders and chest by holding a band behind the back, one hand high and one low.",["Hold a band behind your back, one hand high and one low.","Keep light tension in the band.","Open your chest and draw your shoulders gently back.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your ribs down and avoid arching your back.","Move your hands farther apart to ease the stretch."],{"main":"images/flat/banded-shoulder-stretch-main.webp"},"stretching"],["banded-squat","Banded Squat","beginner","loop_band","upper_legs","A bodyweight squat with a loop band above the knees to teach knees-out tracking.",["Place a loop band just above the knees.","Stand with feet shoulder-width apart, toes slightly out.","Push the knees out against the band as you squat down.","Descend until thighs are parallel or below.","Drive through the heels to stand back up."],["Push the knees out against the band the whole rep.","Keep the chest up and the back flat.","Do not let the knees collapse inward."],{"start":"images/flat/banded-squat-start.webp","peak":"images/flat/banded-squat-peak.webp"},"strength"],["banded-standing-curl","Banded Standing Leg Curl","beginner","loop_band","upper_legs","A standing hamstring curl using a loop band anchored around the ankle, useful for travel or as a low-load hamstring finisher.",["Loop a resistance band around one ankle and anchor the other end under your standing foot or a fixed point in front of you.","Stand tall, holding onto something for balance if needed, with a slight bend in the standing knee.","Curl the banded heel up and back toward your glute, keeping the thigh still.","Squeeze the hamstring at the top, then lower under control to a full stretch.","Complete all reps on one side, then switch legs."],["Keep the thigh stationary - only the lower leg should move.","Avoid swinging the hips to generate momentum.","Use a lighter band if you can't control the descent."],{"start":"images/flat/banded-standing-curl-start.webp","peak":"images/flat/banded-standing-curl-peak.webp"},"strength"],["banded-standing-hip-abduction","Banded Standing Hip Abduction","beginner","loop_band","upper_legs","This isolation exercise targets the gluteus medius and maximus, improving hip stability and strength by abducting the leg against band resistance.",["Place a loop band around your ankles or just above your knees.","Stand tall with a slight bend in your knees and brace your core.","Shift your weight onto one leg, maintaining a stable torso.","Slowly abduct the free leg out to the side, feeling the glute contract.","Control the movement as you return the leg to the starting position.","Complete all reps per side before switching."],["Keep your torso upright and avoid leaning to the side.","Focus on a controlled movement, not momentum.","Ensure the band maintains tension throughout the entire range of motion.","Initiate the movement from your hip, not your foot."],{"start":"images/flat/banded-standing-hip-abduction-start.webp","peak":"images/flat/banded-standing-hip-abduction-peak.webp"},"strength"],["banded-standing-hip-adduction","Banded Standing Hip Adduction","beginner","loop_band","upper_legs","A standing hip adduction with a loop band, isolating the inner thigh adductors.",["Anchor a loop band to a sturdy upright at ankle height.","Step into the loop with the working leg facing the anchor side.","Stand a few feet away so the band has tension.","Sweep the working leg across the body toward the standing leg.","Return slowly to the start. Complete reps per side, then switch."],["Keep the standing leg slightly bent for stability.","Move only the working leg - torso stays still.","Control the eccentric for full adductor stretch."],{"start":"images/flat/banded-standing-hip-adduction-start.webp","peak":"images/flat/banded-standing-hip-adduction-peak.webp"},"strength"],["banded-sumo-walk","Banded Sumo Walk","beginner","loop_band","upper_legs","A wide-stance lateral walk with a loop band around the lower legs, targeting the glute medius and maximus.",["Place a loop band around your lower legs, just above the ankles.","Drop into a quarter squat with feet wider than shoulder-width.","Step sideways in a wide stance, keeping tension on the band.","Bring the trailing foot in only partway so the band stays taut, and keep stepping for the prescribed distance before leading with the other leg.","Stay low throughout - do not stand up between steps."],["Keep tension on the band the entire set.","Stay in a quarter-squat - do not stand tall between steps.","Take small, controlled steps with toes pointed slightly out."],{"start":"images/flat/banded-sumo-walk-start.webp","peak":"images/flat/banded-sumo-walk-peak.webp"},"strength"],["banded-terminal-knee-extension","Banded Terminal Knee Extension","beginner","loop_band","upper_legs","An isolation drill that locks out the knee against band resistance, often used for VMO and knee rehab.",["Anchor a loop band to a sturdy upright at knee height.","Step into the loop so the band sits behind one knee.","Step back so the band pulls the knee into a slight bend.","Extend the knee fully against the band, contracting the quad.","Return slowly. Complete reps per side, then switch."],["Squeeze the quadriceps hard at full extension.","Keep the foot flat - do not lift the heel.","Move only at the knee - the hip stays still."],{"start":"images/flat/banded-terminal-knee-extension-start.webp","peak":"images/flat/banded-terminal-knee-extension-peak.webp"},"strength"],["banded-triceps-stretch","Banded Triceps Stretch","beginner","resistance_band","upper_arms","A standing stretch that lengthens the triceps by reaching one hand behind the head against band tension.",["Hold a band that runs down your back, top hand behind your head.","Anchor the lower hand at your lower back.","Reach the top hand down to feel the triceps lengthen.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep your head upright and ribs down.","Relax and keep breathing throughout."],{"main":"images/flat/banded-triceps-stretch-main.webp"},"stretching"],["barbell-ab-rollout","Barbell Ab Rollout","intermediate","barbell","core","A kneeling ab rollout using a loaded barbell with plates, giving smoother rolling and adjustable load compared to an ab wheel.",["Load plates of equal size on both ends of a barbell and place it on the floor.","Kneel behind the bar and grip it shoulder-width, arms extended.","Brace the core hard, then roll the bar forward away from your body.","Go as far as you can keep a neutral spine - stop before the hips sag.","Pull the bar back to the starting position by contracting the abs and lats.","Repeat for the recommended number of repetitions."],["Start with small plates for a limited range; graduate to 45s for full rollouts.","The moment the lower back arches or drops, stop - you've exceeded your range."],{"start":"images/flat/barbell-ab-rollout-start.webp","peak":"images/flat/barbell-ab-rollout-peak.webp"},"strength"],["barbell-box-squat","Barbell Box Squat","intermediate","barbell","upper_legs","A back squat with a barbell in which you sit back onto a box or bench at the bottom, pause for a moment and stand up again. The box fixes the depth and teaches you to sit back into the hips, and the brief pause removes the rebound out of the bottom.",["Set a box or bench behind you at a height where your thighs end up about parallel to the floor when you sit on it.","Take the barbell on your upper back, step back and stand with your feet a little wider than shoulder-width.","Brace your trunk and push your hips back, then lower yourself under control toward the box.","Sit onto the box without dropping onto it, keeping your chest up and your shins close to vertical.","Pause briefly with your muscles still tight, without relaxing your back.","Drive through your whole foot to stand up, and repeat for the planned repetitions."],["Sit back rather than down; the box should be touched with your hips, not rested on with your weight.","Keep the torso tight in the pause; relaxing on the box is where most back injuries happen.","Use a box that cannot slide, and lower it as you progress until you can squat to full depth."],{"start":"images/flat/barbell-box-squat-start.webp","peak":"images/flat/barbell-box-squat-peak.webp"},"strength"],["barbell-bulgarian-split-squat","Barbell Bulgarian Split Squat","advanced","barbell","upper_legs","A single-leg squat with the rear foot raised on a bench and a barbell held across the upper back. The heavy, unilateral load works the quadriceps and glutes of the front leg and challenges balance and hip mobility.",["Set a barbell across the upper back and stand about two feet in front of a flat bench, facing away from it.","Place the top of one foot on the bench behind you, with the front foot far enough forward to keep the shin close to vertical when you lower.","Brace the trunk and lower the back knee toward the floor by bending the front hip and knee.","Descend until the front thigh is about parallel to the floor, keeping the chest up.","Drive through the middle of the front foot to return to the start.","Complete the repetitions on one leg, then switch."],["Keep most of the weight on the front leg; the back foot is only there for balance.","Keep the front knee tracking over the toes and the torso upright.","Use a lighter load than in a regular back squat, and set up the bar and a safe way to drop it before you step into position."],{"start":"images/flat/barbell-bulgarian-split-squat-start.webp","peak":"images/flat/barbell-bulgarian-split-squat-peak.webp"},"strength"],["barbell-calf-raise","Barbell Calf Raise","intermediate","barbell","lower_legs","A standing calf raise loaded with a barbell across the upper back, using a raised platform for a deeper heel stretch.",["Place a barbell across your upper back as in a squat.","Stand with the balls of your feet on a raised platform.","Push up onto your toes as high as possible.","Pause and squeeze your calves at the top.","Lower your heels below the platform and repeat."],["Avoid bouncing out of the bottom stretch position.","Keep your knees straight but not locked throughout the set.","Move slowly to stay balanced under the bar."],{"start":"images/flat/barbell-calf-raise-start.webp","peak":"images/flat/barbell-calf-raise-peak.webp"},"strength"],["barbell-curl","Barbell Curl","beginner","barbell","upper_arms","A classic biceps isolation exercise using a barbell for maximal loading.",["Stand holding a barbell with a shoulder-width underhand grip.","Curl the bar up toward your shoulders.","Squeeze at the top, then lower under control.","Repeat."],["Avoid swinging the torso.","Keep elbows pinned at your sides."],{"start":"images/flat/barbell-curl-start.webp","peak":"images/flat/barbell-curl-peak.webp"},"strength"],["barbell-front-raise","Barbell Front Raise","intermediate","barbell","shoulders","An isolation exercise raising a barbell from the thighs to shoulder height, targeting the front deltoids.",["Stand holding a barbell with an overhand grip at thigh level.","Keep your arms straight and core braced.","Raise the barbell in front of you to shoulder height.","Pause briefly at the top.","Lower under control and repeat."],["Use a light weight to avoid swinging the bar up.","Avoid leaning back as the bar rises.","Keep your wrists neutral rather than letting them bend backward."],{"start":"images/flat/barbell-front-raise-start.webp","peak":"images/flat/barbell-front-raise-peak.webp"},"strength"],["barbell-glute-bridge","Barbell Glute Bridge","intermediate","barbell","upper_legs","A weighted glute bridge using a barbell for increased resistance.",["Lie on the floor with a barbell across your hips and knees bent.","Drive your hips up by squeezing your glutes.","Hold at the top with hips fully extended.","Lower with control.","Repeat."],["Drive through your heels rather than your toes.","Finish with your ribs down to avoid arching the lower back.","Keep your knees in line with your feet, not caving inward."],{"start":"images/flat/barbell-glute-bridge-start.webp","peak":"images/flat/barbell-glute-bridge-peak.webp"},"strength"],["barbell-isometric-squat-hold","Barbell Isometric Squat Hold","intermediate","barbell","upper_legs","An isometric version of the barbell back squat: you squat down with the bar on your upper back and hold the bottom position. The quadriceps, glutes and the muscles that keep your back rigid stay under tension at the deepest, hardest point of the squat.",["Set the bar on your upper back, grip it just outside your shoulders and step back from the rack with your feet about shoulder-width apart.","Take a big breath into your belly, brace your core and keep your chest tall.","Sit down and back until your thighs are about parallel to the floor or a little below, with your knees tracking over your toes.","Stop at the bottom and hold the position, with your weight over the middle of your feet.","Keep your back flat and your knees pushed out while you hold for the planned time.","Drive up through your feet to stand, then rack the bar."],["Use safety arms or pins set just below your bottom position, since a long hold at depth is tiring.","Choose a lighter bar than your working squat weight; holding for time is harder than it looks.","Keep the knees pushed out over the toes instead of letting them collapse inward as you tire."],{"main":"images/flat/barbell-isometric-squat-hold-main.webp"},"strength"],["barbell-lunge","Barbell Lunge","intermediate","barbell","upper_legs","A forward lunge with a barbell across the upper back, training the quads and glutes one leg at a time.",["Place a barbell across your upper back and stand tall.","Step forward with one leg into a long stride.","Lower your back knee toward the ground until your front thigh is parallel.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],["Take a stride long enough that your front knee stays over your ankle.","Keep your torso upright and core braced under the bar.","Push the floor away through the front heel, not the toes."],{"start":"images/flat/barbell-lunge-start.webp","peak":"images/flat/barbell-lunge-peak.webp"},"strength"],["barbell-overhead-extension","Barbell Overhead Extension","intermediate","barbell","upper_arms","This isolation exercise effectively targets the triceps brachii by extending the elbows overhead, promoting muscle hypertrophy and strength.",["Load a barbell with an appropriate weight and stand or sit with a neutral spine.","Grip the barbell with an overhand, shoulder-width grip, and press it overhead.","Slowly lower the barbell behind your head by flexing your elbows, keeping your upper arms stable.","Extend your elbows to press the barbell back to the starting overhead position, squeezing your triceps.","Maintain control throughout the movement, avoiding momentum."],["Keep your elbows tucked in and pointing forward to maximize triceps engagement and protect your shoulders.","Control the eccentric (lowering) phase to enhance muscle tension and growth.","Avoid arching your lower back excessively; brace your core to maintain stability."],{"start":"images/flat/barbell-overhead-extension-start.webp","peak":"images/flat/barbell-overhead-extension-peak.webp"},"strength"],["barbell-preacher-curl","Barbell Preacher Curl","intermediate","barbell","upper_arms","This isolation exercise targets the biceps brachii and brachialis by fixing the upper arms on a preacher bench, minimizing momentum and maximizing tension.",["Sit on a preacher bench with your chest against the pad, gripping a barbell with an underhand, shoulder-width grip.","Position your upper arms firmly against the pad, ensuring your elbows are slightly bent at the start.","Curl the barbell upwards by contracting your biceps, keeping your upper arms stationary on the pad.","Squeeze your biceps at the top of the movement, focusing on peak contraction.","Slowly lower the barbell back to the starting position, controlling the eccentric phase.","Lower until your arms are almost fully extended to get a full stretch in the biceps."],["Maintain constant tension on the biceps throughout the entire range of motion.","Avoid lifting your elbows off the pad; this indicates you're using too much weight or momentum.","Lower the bar slowly and under control; the stretched bottom position is where the elbows are most exposed.","Keep your wrists straight and aligned with your forearms to prevent strain."],{"start":"images/flat/barbell-preacher-curl-start.webp","peak":"images/flat/barbell-preacher-curl-peak.webp"},"strength"],["barbell-pullover","Barbell Pullover","intermediate","barbell","back","A compound movement stretching and loading the lats and chest through a wide arc.",["Lie across a bench with a barbell held over your chest.","Lower the bar back over your head in an arc.","Pull it back to the start over your chest.","Repeat."],["Keep a slight bend in the elbows.","Engage the lats to drive the bar back."],{"start":"images/flat/barbell-pullover-start.webp","peak":"images/flat/barbell-pullover-peak.webp"},"strength"],["barbell-rear-delt-row","Barbell Rear Delt Row","intermediate","barbell","shoulders","A bent-over barbell row with flared elbows that shifts emphasis from the lats to the posterior deltoids and upper back.",["Hinge at the hips with a flat back until your torso is nearly parallel to the floor.","Hold a barbell with an overhand, wider-than-shoulder-width grip, arms hanging.","Row the bar up toward your upper chest with the elbows flaring out to the sides.","Pause and squeeze the rear delts and upper back at the top.","Lower the bar under control and repeat."],["Pull with the elbows, not the hands - think of driving them up and out.","Use a lighter load than a standard row; the wide grip reduces leverage."],{"start":"images/flat/barbell-rear-delt-row-start.webp","peak":"images/flat/barbell-rear-delt-row-peak.webp"},"strength"],["barbell-reverse-lunge","Barbell Reverse Lunge","intermediate","barbell","upper_legs","A barbell lunge stepping backward instead of forward, keeping the front shin vertical while loading the quads and glutes.",["Place a barbell across your upper back and stand tall.","Step one foot backward into a long stride.","Lower your back knee toward the ground under control.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],["Step back far enough to keep your front shin close to vertical.","Lower the back knee straight down rather than leaning forward.","Keep your chest tall and hips square throughout."],{"start":"images/flat/barbell-reverse-lunge-start.webp","peak":"images/flat/barbell-reverse-lunge-peak.webp"},"strength"],["barbell-row","Bent-Over Barbell Row","intermediate","barbell","back","A compound pulling movement that targets the upper and middle back.",["Hinge at the hips with a slight knee bend.","Grip the bar slightly wider than shoulder-width.","Pull the bar to your lower chest, squeezing your shoulder blades.","Lower the bar under control.","Repeat."],["Keep your torso at roughly 45 degrees.","Do not use momentum to swing the weight."],{"start":"images/flat/barbell-row-start.webp","peak":"images/flat/barbell-row-peak.webp"},"strength"],["barbell-wrist-curl","Barbell Wrist Curl","beginner","barbell","lower_arms","A barbell wrist curl that isolates the forearm flexors for grip and forearm size.",["Sit on a bench with forearms resting on the thighs, palms up.","Hold a barbell with hands shoulder-width, wrists hanging off the knees.","Let the bar roll down to the fingertips at the bottom.","Curl the bar up by flexing the wrists.","Lower under control."],["Move only at the wrist - keep the forearms still.","Roll the bar to the fingertips for full range.","Use a thumbless grip if it helps wrist comfort."],{"start":"images/flat/barbell-wrist-curl-start.webp","peak":"images/flat/barbell-wrist-curl-peak.webp"},"strength"],["barbell-zercher-hold","Barbell Zercher Hold","advanced","barbell","core","A standing hold with a barbell cradled in the crooks of your elbows against your abdomen. The abs and the trunk stabilizers resist the pull of the bar, while the biceps and the upper back keep it close to your body.",["Set a barbell on a rack at about the height of your lower ribs and place the crooks of your elbows under the bar.","Fold your arms and clasp your hands together in front of your chest to lock the bar against your body.","Lift the bar off the rack and step back, standing with your feet about shoulder-width apart.","Stand tall, brace your abs and keep your ribs down, so that the bar rests against your abdomen without pulling you forward.","Hold the position for the planned time, breathing slowly and keeping your elbows pressed together.","Return the bar to the rack, or lower it to the floor with control."],["Wrap a towel or a barbell pad around the bar, since it presses into the elbows and the abdomen.","Keep the bar close to your body and do not lean back to carry it; if you do, the weight is too heavy.","Start with a bar a little lighter than your Zercher squat load, since the bar rests on your arms for the whole hold."],{"main":"images/flat/barbell-zercher-hold-main.webp"},"strength"],["barbell-zercher-squat-hold","Barbell Zercher Squat Hold","advanced","barbell","upper_legs","An isometric version of the Zercher squat: you squat down with the barbell in the crooks of your elbows and hold the bottom position. The quadriceps, glutes and the trunk stay under tension at the deepest point, while the arms and upper back keep the bar close to you.",["Set a barbell on a rack at about the height of your lower ribs, place the crooks of your elbows under the bar and clasp your hands in front of your chest.","Lift the bar off the rack, step back and stand with your feet about shoulder-width apart.","Brace your abs and keep your chest tall, then sit down and back until your thighs are about parallel to the floor.","Stop at the bottom and hold, with your elbows resting inside your knees and your knees pushed out over your toes.","Keep the bar close to your abdomen and your back straight while you hold for the planned time.","Drive up through your feet to stand and return the bar to the rack."],["Wrap a towel or a barbell pad around the bar, since it presses into the elbows and the abdomen.","Use safety pins set just below your bottom position, since a long hold at depth is tiring.","Keep the chest tall; if the bar pulls you forward and your back rounds, the weight is too heavy."],{"main":"images/flat/barbell-zercher-squat-hold-main.webp"},"strength"],["battle-rope-double-slam","Battle Rope Double Slam","intermediate","battle_rope","full_body","A conditioning movement in which both rope ends are driven up and slammed down together, producing one large wave per rep instead of the alternating waves of the standard battle rope drill.",["Take one rope end in each hand and face the anchor, standing far enough back that the ropes have a slight slack.","Set your feet slightly wider than your hips and sit into a quarter squat with your chest up.","Swing both arms up together, letting the ropes rise in front of you as you extend through the hips.","Slam both ends down to the floor at the same time, hinging at the hips and driving through your lats.","Ride the rebound straight back into the next slam, keeping both arms moving in unison rather than alternating.","Keep slamming for the desired time or number of reps."],["Both arms move together - the moment they start alternating you are doing the standard wave drill, which is a different exercise.","Drive the slam with your hips and lats rather than your arms, or your shoulders will burn out long before your lungs do.","Stand at the right distance from the anchor: too close and the rope goes slack, too far and you cannot get a wave into it at all."],{"start":"images/flat/battle-rope-double-slam-start.webp","peak":"images/flat/battle-rope-double-slam-peak.webp"},"cardio"],["battle-ropes","Battle Ropes","intermediate","battle_rope","full_body","A high-intensity conditioning movement using thick ropes, training the upper back, shoulders, and grip.",["Anchor the ropes to a fixed point and grab one end in each hand.","Step back so the ropes have moderate slack.","Drop into a quarter squat with feet shoulder-width.","Drive each arm up and down rapidly to send waves through the ropes.","Continue for the prescribed work interval."],["Stay in the quarter-squat the entire interval.","Drive force from the legs and hips, not just the arms.","Keep the waves consistent and tight."],{"main":"images/flat/battle-ropes-main.webp"},"cardio"],["bear-crawl","Bear Crawl","beginner","bodyweight","full_body","A quadruped bodyweight crawl on hands and toes with the knees hovering just off the floor, building shoulder stability and core control as you travel forward.",["Start on all fours with your hands under your shoulders and knees under your hips.","Tuck your toes and lift your knees a few centimeters off the floor.","Keeping your back flat and hips low, step your right hand and left foot forward together.","Then move your left hand and right foot, crawling forward in a controlled rhythm.","Keep your core braced and your hips from swaying side to side."],["Move opposite hand and foot together, like an exaggerated crawl.","Keep your knees low and hips level - do not let them pop up or rock."],{"start":"images/flat/bear-crawl-start.webp","peak":"images/flat/bear-crawl-peak.webp"},"strength"],["bear-plank-hold","Bear Plank Hold","beginner","bodyweight","core","A static core hold on hands and knees in which the knees hover just above the floor while the back stays flat. It trains the abdominals and shoulders to stabilise the trunk and is a stepping stone to the full plank.",["Start on hands and knees with the hands under the shoulders and the knees under the hips.","Tuck the toes under and brace the abdominals so the back is flat.","Press into the hands and lift the knees a couple of inches off the floor.","Hold the position with the hips level and the head in line with the spine.","Breathe steadily, then lower the knees to rest."],["Keep the knees close to the floor; lifting them higher turns the hold into a pike.","Spread the fingers and push the floor away so the shoulders do not collapse.","Keep the neck long and look at the floor slightly ahead of the hands."],{"main":"images/flat/bear-plank-hold-main.webp"},"strength"],["behind-the-back-barbell-shrug","Behind the Back Barbell Shrug","intermediate","barbell","back","A shrug variation with the barbell held behind the body, targeting the trapezius.",["Stand holding a barbell behind your back with an overhand grip.","Keep your arms straight and chest up.","Shrug your shoulders straight up toward your ears.","Pause and squeeze at the top.","Lower under control and repeat."],["Lift straight up and down without rolling the shoulders.","Avoid bending your elbows to heave the weight higher.","Stand tall with a neutral neck and look straight ahead."],{"start":"images/flat/behind-the-back-barbell-shrug-start.webp","peak":"images/flat/behind-the-back-barbell-shrug-peak.webp"},"strength"],["behind-the-neck-lat-pulldown","Behind-the-Neck Lat Pulldown","advanced","lat_pulldown_machine","back","A wide-grip lat pulldown taken behind the head, targeting the upper lats and traps - requires full overhead shoulder mobility.",["Sit at a lat pulldown station with thighs secured under the pad.","Grip the bar with a wide, overhand grip - wider than shoulder-width.","Keep the torso upright and tuck the chin slightly forward.","Pull the bar down behind the head until it touches the base of the neck.","Return under control to the full overhead stretch.","Repeat for the recommended number of repetitions."],["Only perform this if you have full, pain-free overhead shoulder mobility.","Use a moderate load - this is not a strength lift, it's a hypertrophy accessory."],{"start":"images/flat/behind-the-neck-lat-pulldown-start.webp","peak":"images/flat/behind-the-neck-lat-pulldown-peak.webp"},"strength"],["behind-the-neck-press","Behind the Neck Press","intermediate","barbell","shoulders","An overhead press performed with the barbell starting behind the neck, emphasizing the front and side deltoids.",["Sit or stand with a barbell resting on your upper traps behind your neck.","Grip the bar wider than shoulder width.","Press the bar straight up overhead until your arms are extended.","Lower the bar back to the starting position under control.","Repeat for the desired number of reps."],["Lower the bar only as far as your shoulders allow comfortably.","Keep your forearms vertical under the bar throughout the press.","Brace your core to avoid arching the lower back overhead."],{"start":"images/flat/behind-the-neck-press-start.webp","peak":"images/flat/behind-the-neck-press-peak.webp"},"strength"],["behind-the-neck-pull-ups","Behind-the-Neck Pull-Up","advanced","pull_up_bar","back","A wide-grip pull-up pulled high enough that the bar passes behind the head at the top instead of under the chin, which forces the shoulders into end-range external rotation.",["Grip the pull-up bar with an overhand grip wider than shoulder-width and hang at full arm extension with your legs together.","Keep your torso vertical rather than leaning back, and pull your elbows down and out to the sides.","Continue pulling until the bar passes behind your head and the back of your neck comes level with it, without letting the bar touch your neck.","Lower yourself under control back to a full dead hang, keeping your head still rather than letting it snap forward.","Repeat for the desired number of reps."],["This variation is widely discouraged. Finishing behind the head loads the shoulder at the end of its external rotation, where the joint has the least capacity to protect itself, and any contact between the bar and the neck puts that load through the cervical spine.","A standard or wide-grip pull-up trains the same muscles through the same shoulder range - nothing about back development requires the bar to travel behind the head, so there is no benefit here to trade the risk against.","If you perform it anyway, stop well short of touching the bar to your neck and leave it out entirely if you lack full pain-free overhead shoulder mobility or have any history of shoulder or neck problems."],{"start":"images/flat/behind-the-neck-pull-ups-start.webp","peak":"images/flat/behind-the-neck-pull-ups-peak.webp"},"strength"],["bench-adductor-stretch","Bench Adductor Stretch","beginner","flat_bench","upper_legs","A standing stretch with one straight leg resting on a bench out to the side to lengthen the inner thigh.",["Stand side-on to a bench.","Rest one straight leg up on the bench out to the side.","Keep your torso upright and shift gently toward the bench.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep both legs straight.","Keep the standing foot pointing forward."],{"main":"images/flat/bench-adductor-stretch-main.webp"},"stretching"],["bench-ankle-stretch","Bench Ankle Stretch","beginner","flat_bench","lower_legs","A standing stretch with the foot flat on a bench, driving the knee forward over the toes to flex the ankle.",["Place one whole foot flat on top of a bench.","Keep your torso upright.","Drive that knee forward over your toes.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep your heel down on the bench.","Move slowly and keep the foot flat."],{"main":"images/flat/bench-ankle-stretch-main.webp"},"stretching"],["bench-bulgarian-split-stretch","Bench Bulgarian Split Stretch","beginner","flat_bench","upper_legs","A split-stance stretch with the rear foot on a bench, sinking the hips to open the hip flexors and quad.",["Rest the top of your rear foot on a bench behind you.","Set the front foot flat and bend that knee.","Sink your hips straight down.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Hold a wall for balance if needed.","Keep your torso upright."],{"main":"images/flat/bench-bulgarian-split-stretch-main.webp"},"stretching"],["bench-calf-stretch","Bench Calf Stretch","beginner","flat_bench","lower_legs","A standing stretch with the ball of the foot on a bench edge, dropping the heel to lengthen the calf.",["Place the ball of one foot on the edge of a bench.","Keep that knee straight.","Let your heel drop down below the toes.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Hold the bench or a wall for balance.","Keep the movement slow and controlled."],{"main":"images/flat/bench-calf-stretch-main.webp"},"stretching"],["bench-chest-stretch","Bench Chest Stretch","beginner","flat_bench","chest","A kneeling stretch with the hands behind on a bench, sinking the hips to open the chest and shoulders.",["Kneel with your back to a bench.","Place both hands behind you on the edge of the bench.","Sink your hips down to open the chest.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your shoulders down away from your ears.","Stretch to mild tension, never to pain."],{"main":"images/flat/bench-chest-stretch-main.webp"},"stretching"],["bench-childs-pose","Bench Child's Pose","beginner","flat_bench","back","A kneeling stretch with the arms resting on a bench, sitting the hips back to lengthen the lats and lower back.",["Kneel on the floor in front of a bench.","Extend both arms forward and rest them on the bench.","Sit your hips back toward your heels and let the chest sink.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your arms straight and relax your neck.","Relax and keep breathing throughout."],{"main":"images/flat/bench-childs-pose-main.webp"},"stretching"],["bench-couch-stretch","Bench Couch Stretch","beginner","flat_bench","upper_legs","A deep quad and hip-flexor stretch with the rear shin running up the front of a bench.",["Kneel with your rear shin against the front of a bench.","Place the front foot flat on the floor.","Bring your torso upright until the front of the thigh stretches.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Squeeze the rear glute to protect your lower back.","Pad the rear knee on a cushion for comfort."],{"main":"images/flat/bench-couch-stretch-main.webp"},"stretching"],["bench-decline-plank-hold","Bench Decline Plank Hold","intermediate","bodyweight","core","A plank with your hands on the floor and your feet on a bench behind you, so that your body slopes downward toward your hands. The raised feet shift more of your weight onto the shoulders and make the abdominal muscles work harder than in a normal plank.",["Place a bench behind you and put the tops of your feet on it, then put your hands on the floor under your shoulders with your arms straight.","Walk your hands to a position where your body is in one straight line from your head to your heels.","Squeeze your glutes, brace your abs and push the floor away so that your shoulders do not sink between your shoulder blades.","Keep your neck in line with your spine and look at the floor between your hands.","Hold the position for the planned time, breathing slowly.","Lower your knees to the floor and rest."],["Do not let the hips sag or rise above the line; stop the set when the line breaks.","Keep your hands directly under your shoulders so that the weight is carried by the skeleton, not by sore wrists.","Use a lower step if the bench is too high to keep a straight line."],{"main":"images/flat/bench-decline-plank-hold-main.webp"},"strength"],["bench-dips","Bench Dips","intermediate","bodyweight","upper_arms","A bodyweight pressing movement with hands on a bench behind the body, emphasizing the triceps.",["Sit on a bench and place your hands on the edge beside your hips.","Slide your hips off the bench with legs extended.","Lower your body by bending your elbows to 90 degrees.","Press through your palms to return to the start.","Repeat for the desired number of reps."],["Keep your hips close to the bench as you lower.","Avoid letting your shoulders roll forward at the bottom.","Bend your knees to make the movement easier."],{"start":"images/flat/bench-dips-start.webp","peak":"images/flat/bench-dips-peak.webp"},"strength"],["bench-figure-4-glute-stretch","Bench Figure-4 Glute Stretch","beginner","flat_bench","upper_legs","A seated stretch on a bench with one ankle crossed over the knee, hinging forward to target the glute.",["Sit on the end of a bench.","Cross one ankle over the opposite knee.","Keep your back flat and hinge forward over the crossed leg.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Let the crossed knee fall open.","Hinge from the hips, keeping the chest open."],{"main":"images/flat/bench-figure-4-glute-stretch-main.webp"},"stretching"],["bench-hamstring-stretch","Bench Hamstring Stretch","beginner","flat_bench","upper_legs","A standing stretch with the heel on a bench, hinging forward over the straight raised leg to lengthen the hamstring.",["Place one heel on a bench with that leg straight.","Stand tall on the supporting leg.","Hinge forward from the hips over the raised leg.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep your back flat as you fold forward.","Keep the raised leg straight, toes up."],{"main":"images/flat/bench-hamstring-stretch-main.webp"},"stretching"],["bench-hollow-hold","Bench Hollow Hold","intermediate","flat_bench","core","A static core hold performed lying on a flat bench: the arms reach overhead and the shoulders and straight legs are lifted into a shallow hollow shape while the lower back stays pressed into the bench.",["Lie on your back on a flat bench with the glutes and lower back on the pad and the legs extended.","Reach the arms overhead beside the ears.","Brace the abdominals and press the lower back into the bench.","Lift the shoulders and the straight legs a few inches to form a shallow hollow.","Hold the position while breathing steadily, then lower to rest."],["If the lower back arches off the pad, raise the legs higher or bend the knees slightly.","Keep the ribs pulled down and the neck relaxed.","Hold only as long as you can keep the lower back flat."],{"main":"images/flat/bench-hollow-hold-main.webp"},"strength"],["bench-lat-stretch","Bench Lat Stretch","beginner","flat_bench","back","A kneeling stretch with the hands on a bench, sinking the chest toward the floor to lengthen the lats.",["Kneel on the floor in front of a bench.","Place both hands on top of the bench.","Sit your hips back and let your chest sink down.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your arms straight and head between your arms.","Relax and keep breathing throughout."],{"main":"images/flat/bench-lat-stretch-main.webp"},"stretching"],["bench-leg-pull-in","Bench Leg Pull-In","beginner","bodyweight","core","A seated core exercise on a flat bench: leaning back with your hands on the bench, you pull the knees toward the chest to train the rectus abdominis.",["Sit on a flat bench, grip its edges beside or just behind your hips and lean your torso back slightly.","Extend your legs out in front of you with your feet off the floor.","Pull your knees toward your chest, bringing the torso slightly forward to meet them.","Extend the legs back out under control without letting your feet touch the floor.","Repeat for the desired number of repetitions."],["Keep your chest lifted and your back straight; do not round forward.","Control the eccentric; do not let gravity drop the legs.","Squeeze the abs at the top of each rep for a stronger contraction."],{"start":"images/flat/bench-leg-pull-in-start.webp","peak":"images/flat/bench-leg-pull-in-peak.webp"},"strength"],["bench-press","Barbell Bench Press","intermediate","barbell","chest","A compound pushing movement that targets the chest, shoulders, and triceps.",["Lie flat on a bench with your eyes under the bar.","Grip the bar slightly wider than shoulder-width.","Unrack the bar and lower it to your mid-chest.","Press the bar back up to full arm extension.","Repeat for the desired number of reps."],["Keep your feet flat on the floor.","Maintain a slight arch in your lower back.","Drive through your legs for stability."],{"start":"images/flat/bench-press-start.webp","peak":"images/flat/bench-press-peak.webp"},"strength"],["bench-pull","Bench Pull","intermediate","barbell","back","A rowing exercise performed lying face down on an elevated bench, eliminating body momentum to target the lats and rhomboids.",["Lie face down on an elevated bench with arms hanging straight down.","Grip a barbell or dumbbells below you.","Row the weight up to the underside of the bench.","Squeeze your shoulder blades at the top.","Lower under control and repeat."],["Keep your chest glued to the bench to prevent cheating.","Reach a full stretch at the bottom before each pull.","Drive your elbows up and back rather than curling the weight."],{"start":"images/flat/bench-pull-start.webp","peak":"images/flat/bench-pull-peak.webp"},"strength"],["bent-arm-barbell-pullover","Bent Arm Barbell Pullover","intermediate","barbell","back","A pullover variation performed with elbows bent, lowering a barbell behind the head to stretch the lats and chest.",["Lie on a bench holding a barbell above your chest with bent elbows.","Keep your elbows bent throughout the movement.","Lower the barbell behind your head in an arc.","Pull the barbell back over your chest using your lats.","Repeat for the desired number of reps."],["Keep your ribs down and avoid arching your lower back.","Limit the stretch to a range your shoulders can control.","Breathe in deeply as the bar lowers behind your head."],{"start":"images/flat/bent-arm-barbell-pullover-start.webp","peak":"images/flat/bent-arm-barbell-pullover-peak.webp"},"strength"],["bent-arm-ez-bar-pullover","Bent-Arm EZ-Bar Pullover","intermediate","ez_bar","back","A bent-arm pullover on a flat bench using an EZ-bar - wrist-friendlier than the straight barbell version while keeping the deep lat and pec stretch.",["Lie on a flat bench holding an EZ-bar with a narrow overhand grip on the inner bends.","Start with the bar above your chest, elbows bent to roughly 90 degrees.","Keep the elbow angle fixed and lower the bar back in an arc overhead until a deep stretch is felt in the lats and pecs.","Pull the bar back over the chest along the same arc, without straightening the elbows.","Repeat for the recommended number of repetitions."],["The elbow angle stays fixed - only the shoulder moves.","Bent elbows shorten the lever, so you can usually handle a little more weight than in a straight-arm pullover.","If the lower back arches, plant the feet more firmly and brace the abs."],{"start":"images/flat/bent-arm-ez-bar-pullover-start.webp","peak":"images/flat/bent-arm-ez-bar-pullover-peak.webp"},"strength"],["bent-knee-copenhagen-raises","Bent-Knee Copenhagen Raises","intermediate","flat_bench","core","A shorter-lever version of the Copenhagen plank raise. In a side plank with your top leg on a flat bench, you bend the knee of your lower leg and lift it up toward the bench, then lower it again. The inner thigh muscles and the obliques work as in the straight-leg version, with less load on the lower leg.",["Lie on your side next to a flat bench and place the inside of your top leg or foot on it, with the top knee slightly bent or straight.","Prop yourself up on the elbow of your lower arm, directly under your shoulder.","Lift your hips so that your body forms a straight line from your head to your top leg, and bend the knee of your lower leg under you.","Raise the bent lower knee up toward the bench, keeping your hips high.","Lower the knee slowly without letting your hips drop, and repeat for the planned repetitions.","Rest, then switch sides."],["Use this version to build up to the straight-leg Copenhagen raise; the bent knee shortens the lever and lowers the load.","Keep your hips high and your body in one line; dropping the hips takes the load off the inner thighs.","Move slowly and stop if you feel a sharp pull in the groin; the adductors need a gentle build-up."],{"start":"images/flat/bent-knee-copenhagen-raises-start.webp","peak":"images/flat/bent-knee-copenhagen-raises-peak.webp"},"strength"],["bent-over-db-row","Bent-Over Dumbbell Row","intermediate","dumbbell","back","A two-arm bent-over row with a dumbbell in each hand. The free movement of independent dumbbells lets the elbows track natural and adds a stability demand that a barbell row hides.",["Stand with feet hip-width, holding a dumbbell in each hand at the sides, palms facing in.","Hinge at the hips with a flat back until the torso is roughly 30-45 degrees from horizontal, dumbbells hanging directly below the shoulders.","Brace the core and pull both dumbbells up and slightly back, driving the elbows past the ribs.","Squeeze the upper back at the top, keeping the elbows tucked.","Lower under control to the starting position with the arms fully extended.","Repeat for the recommended number of repetitions."],["The torso angle stays fixed throughout - no rocking up to help the dumbbells.","Pull to the lower ribs/belly, not to the chest; that line keeps the lats loaded.","If the lower back rounds, hinge less and reset before the next set."],{"start":"images/flat/bent-over-db-row-start.webp","peak":"images/flat/bent-over-db-row-peak.webp"},"strength"],["bent-over-ez-bar-row","Bent-Over EZ-Bar Row","intermediate","ez_bar","back","A horizontal pulling movement with an EZ-bar for a wrist-friendly back rowing exercise.",["Hold an EZ-bar with an overhand grip, hinge at the hips to 45 degrees.","Pull the bar to your lower ribcage.","Lower under control.","Repeat."],["Keep your back flat throughout.","Initiate with the elbows, not the hands."],{"start":"images/flat/bent-over-ez-bar-row-start.webp","peak":"images/flat/bent-over-ez-bar-row-peak.webp"},"strength"],["bicep-curl","Dumbbell Bicep Curl","beginner","dumbbell","upper_arms","An isolation exercise targeting the biceps.",["Stand holding dumbbells at your sides, palms forward.","Curl the weights up toward your shoulders.","Squeeze at the top, then lower under control.","Repeat."],["Keep your elbows pinned to your sides.","Avoid swinging the weights."],{"start":"images/flat/bicep-curl-start.webp","peak":"images/flat/bicep-curl-peak.webp"},"strength"],["bicycle-crunch","Bicycle Crunch","beginner","bodyweight","core","A dynamic crunch variation targeting both the rectus abdominis and obliques.",["Lie on your back with hands behind your head and legs raised.","Bring one knee toward your chest while rotating your torso to meet it with the opposite elbow.","Extend that leg while bringing the other knee in.","Continue alternating in a pedaling motion.","Repeat."],["Avoid pulling on your neck with your hands.","Lead the rotation with your shoulder, not your elbow.","Move slowly and deliberately rather than racing through reps."],{"start":"images/flat/bicycle-crunch-start.webp","peak":"images/flat/bicycle-crunch-peak.webp"},"strength"],["bird-dog","Bird-Dog","beginner","bodyweight","core","A core stability exercise extending opposite arm and leg to challenge the erector spinae and deep core.",["Start on all fours with a neutral spine.","Extend your right arm forward and left leg back simultaneously.","Hold for a moment, then return.","Repeat on the other side.","Alternate."],["Move slowly and with control.","Keep hips level throughout."],{"start":"images/flat/bird-dog-start.webp","peak":"images/flat/bird-dog-peak.webp"},"strength"],["bird-dog-hold","Bird Dog Hold","intermediate","bodyweight","core","A static core hold balancing on all fours with one arm and the opposite leg extended, training spinal stability.",["Start on all fours with hands under shoulders and knees under hips.","Extend one arm forward and the opposite leg back.","Keep your core tight and body level.","Hold the position without rotating your torso.","Hold for time. Complete on one side, then switch."],["Reach long through your fingertips and heel in opposite directions.","Push the floor away with your supporting hand to stay stable.","Breathe steadily instead of holding your breath."],{"main":"images/flat/bird-dog-hold-main.webp"},"strength"],["boat-pose","Boat Pose","intermediate","bodyweight","core","A seated balance on the sit bones with the legs lifted and the chest tall, holding a V shape that loads the hip flexors and the whole front of the trunk.",["Sit on the floor with the knees bent and the feet flat, hands resting behind the thighs.","Lean back until you balance just behind the sit bones and lift the chest so the spine stays long.","Lift the shins until they are parallel to the floor, then straighten the legs as far as the back stays flat.","Reach the arms forward beside the legs and hold the position for the prescribed time.","Lower the feet under control to finish."],["Keep the chest lifted; the moment the back rounds, bend the knees again.","Hold behind the thighs if the hamstrings limit you more than the core does.","Breathe steadily instead of bracing against a held breath."],{"main":"images/flat/boat-pose-main.webp"},"strength"],["bodyweight-calf-raise","Bodyweight Calf Raise","beginner","bodyweight","lower_legs","A beginner-friendly calf raise using body weight only on flat ground, strengthening the gastrocnemius and soleus.",["Stand with feet hip-width apart on a flat surface.","Push up onto the balls of your feet as high as possible.","Squeeze your calves at the top.","Lower your heels back to the floor under control.","Repeat for the desired number of reps."],["Use light fingertip support for balance if needed.","Control the lowering phase instead of dropping your heels quickly.","Keep your ankles from rolling outward as you rise."],{"start":"images/flat/bodyweight-calf-raise-start.webp","peak":"images/flat/bodyweight-calf-raise-peak.webp"},"strength"],["bodyweight-good-morning","Bodyweight Good Morning","beginner","bodyweight","back","A bodyweight hip hinge with hands behind the head, strengthening the hamstrings and spinal erectors.",["Stand with feet hip-width apart and hands behind your head.","Keep a slight bend in your knees and brace your core.","Hinge at the hips and lower your torso toward parallel.","Drive your hips forward to return to standing.","Repeat for the desired number of reps."],["Push your hips back as if closing a door behind you.","Keep your spine neutral from head to tailbone throughout.","Stop the descent when your hamstrings reach their stretch limit."],{"start":"images/flat/bodyweight-good-morning-start.webp","peak":"images/flat/bodyweight-good-morning-peak.webp"},"strength"],["bodyweight-lateral-raise","Bodyweight Lateral Raise","beginner","bodyweight","shoulders","A shoulder isolation movement performed without equipment to develop lateral deltoid width.",["Stand upright with arms hanging at your sides.","Raise both arms out to the sides with a slight elbow bend until parallel with the floor.","Pause briefly at the top.","Lower slowly back to the starting position.","Repeat for the desired reps."],["Lead with your elbows, not your hands.","Avoid shrugging your shoulders at the top.","Control the descent to maximize time under tension."],{"start":"images/flat/bodyweight-lateral-raise-start.webp","peak":"images/flat/bodyweight-lateral-raise-peak.webp"},"strength"],["bodyweight-overhead-press","Bodyweight Overhead Press","beginner","bodyweight","shoulders","An unloaded standing overhead press: the arms press up from the shoulders until they are straight overhead, rehearsing the pressing pattern for the shoulders and triceps without any equipment.",["Stand tall with your feet hip-width apart and your hands in loose fists at shoulder height, palms facing forward and elbows under the wrists.","Brace your core and squeeze your glutes so your ribs stay down.","Press both arms straight up until the elbows are fully extended and the upper arms are beside your ears.","Lower your hands back to shoulder height under control.","Repeat for the desired number of reps."],["Finish with your hands directly over your shoulders, not in front of your face.","Do not lean back or arch your lower back to get the arms higher.","Once the pattern feels smooth, hold light dumbbells or a band to add load."],{"start":"images/flat/bodyweight-overhead-press-start.webp","peak":"images/flat/bodyweight-overhead-press-peak.webp"},"strength"],["bodyweight-reverse-lunge","Bodyweight Reverse Lunge","beginner","bodyweight","upper_legs","A lunge variation using only body weight, stepping backward for better knee stability than a forward lunge.",["Stand tall with your feet hip-width apart.","Step one leg back and lower your knee toward the floor.","Lower until your front thigh is parallel to the floor.","Push through your front heel to return to standing.","Repeat on both sides."],["No weight needed -- focus on balance and a controlled descent.","Keep your torso upright instead of leaning forward.","Step back far enough that your front knee stays behind your toes."],{"start":"images/flat/bodyweight-reverse-lunge-start.webp","peak":"images/flat/bodyweight-reverse-lunge-peak.webp"},"strength"],["bodyweight-squat","Bodyweight Squat","beginner","bodyweight","upper_legs","A foundational lower-body exercise squatting with body weight only, developing the quadriceps, glutes, and basic movement mechanics.",["Stand with feet shoulder-width apart and arms extended forward.","Sit back and down by bending your hips and knees.","Lower until your thighs are parallel to the floor.","Drive through your heels to return to standing.","Repeat for the desired number of reps."],["Keep your weight spread across your whole foot.","Track your knees in line with your toes.","Keep your chest up to avoid rounding the upper back."],{"start":"images/flat/bodyweight-squat-start.webp","peak":"images/flat/bodyweight-squat-peak.webp"},"strength"],["bow-pose","Bow Pose","intermediate","bodyweight","back","A prone backbend in which the hands hold the ankles and the legs press away, lifting the chest and thighs off the floor and loading the whole back line.",["Lie face down with the arms beside the body and the forehead resting on the mat.","Bend the knees and take hold of the outside of both ankles.","Press the shins back into the hands so the chest and thighs lift away from the floor.","Hold the lifted position for the prescribed time, keeping the neck long and the gaze forward.","Release the ankles and lower down under control."],["Drive the lift from the legs pressing into the hands, not from pulling with the arms.","Keep the knees roughly hip-width apart rather than letting them splay.","If the shoulders feel pinched, lift less and keep the chest open instead."],{"main":"images/flat/bow-pose-main.webp"},"strength"],["box-jump","Box Jump","intermediate","plyo_box","upper_legs","A plyometric jump from a quarter-squat onto a stable box, training lower-body power.",["Stand a foot in front of a sturdy box with feet shoulder-width.","Drop into a quarter-squat and swing the arms back.","Drive the arms up and explode off the floor onto the box.","Land softly with both feet flat and knees bent.","Step down - do not jump down - and reset."],["Always step down - repeated drop-landings stress the Achilles.","Land softly with the whole foot, knees tracking over the toes.","Pick a box height you can clear cleanly without piking the hips."],{"start":"images/flat/box-jump-start.webp","peak":"images/flat/box-jump-peak.webp"},"plyometrics"],["box-squat","Box Squat","intermediate","bodyweight","upper_legs","A squat performed to a box or bench, which fixes the depth and teaches sitting back into the hips.",["Stand in front of a box or bench, feet shoulder-width apart, with your arms extended forward for balance.","Push your hips back and bend your knees, sitting back toward the box rather than straight down.","Touch the box lightly with your glutes without collapsing onto it.","Drive through your feet to stand back up, squeezing your glutes at the top.","Repeat for the desired number of reps."],["Use a box height that lets your thighs reach about parallel to the floor and lower it as mobility improves.","Keep your weight through the middle of your feet - do not rock onto your toes.","Touch and go: fully relaxing onto the box loses core tension and stresses the spine."],{"start":"images/flat/box-squat-start.webp","peak":"images/flat/box-squat-peak.webp"},"strength"],["bulgarian-split-squat","Bulgarian Split Squat","intermediate","dumbbell","upper_legs","A single-leg squat variation with the rear foot elevated.",["Stand in front of a bench, place one foot behind you on the bench.","Hold dumbbells at your sides.","Lower your body until your front thigh is parallel to the floor.","Push through your front heel to stand back up.","Repeat on both sides."],["Keep most of your weight on the front leg.","Track your front knee over your toes without letting it cave inward.","Square your hips forward and avoid rotating toward the bench."],{"start":"images/flat/bulgarian-split-squat-start.webp","peak":"images/flat/bulgarian-split-squat-peak.webp"},"strength"],["burpees","Burpees","intermediate","bodyweight","full_body","A full-body conditioning movement combining a squat, plank, push-up, and jump.",["Stand with feet shoulder-width apart.","Squat down and place the hands on the floor in front of you.","Jump or step the feet back into a plank, then perform a push-up.","Jump or step the feet forward to the hands.","Stand up and jump explosively, reaching the arms overhead."],["Keep the back flat in the plank - do not let the hips sag.","Land softly from the jump.","Scale by stepping the feet back instead of jumping."],{"main":"images/flat/burpees-main.webp"},"cardio"],["butterfly-stretch","Butterfly Stretch","beginner","bodyweight","upper_legs","A seated stretch for the inner thighs, pressing the soles of the feet together with the knees dropped out.",["Sit tall and press the soles of your feet together.","Let your knees drop out toward the floor.","Hold your feet and sit up tall.","Hold for 20 to 30 seconds, breathing steadily."],["Gently press the knees down with your elbows for more stretch.","Bring your heels closer to your body to increase intensity."],{"main":"images/flat/butterfly-stretch-main.webp"},"stretching"],["cable-bent-over-row","Cable Bent-Over Row","intermediate","cable","back","A cable rowing variation providing constant tension throughout the movement.",["Attach a straight or V-bar to a low cable pulley.","Hinge at the hips with knees slightly bent.","Pull the handle toward your lower chest.","Squeeze your shoulder blades at the top.","Lower with control and repeat."],["Hold the hinge position steady instead of standing up as you pull.","Keep your back flat from head to hips throughout.","Resist the cable's pull on the way back to full stretch."],{"start":"images/flat/cable-bent-over-row-start.webp","peak":"images/flat/cable-bent-over-row-peak.webp"},"strength"],["cable-chest-press","Cable Chest Press","intermediate","cable","chest","A standing chest press on the cable machine, providing constant tension while the staggered stance demands core stability.",["Set the cables to chest height and face away from the machine.","Grip a handle in each hand and step forward into a staggered stance.","Press the handles forward until your arms are extended.","Squeeze your chest at the top.","Return under control and repeat."],["Press both handles evenly to avoid twisting your torso.","Brace your core against the backward pull of the stack.","Step forward enough that the cables stay taut throughout each rep."],{"start":"images/flat/cable-chest-press-start.webp","peak":"images/flat/cable-chest-press-peak.webp"},"strength"],["cable-crunch","Cable Crunch","intermediate","cable","core","A kneeling abdominal exercise flexing the spine against cable resistance, allowing progressive loading of the rectus abdominis.",["Kneel in front of a cable machine with a rope attachment at the top.","Hold the rope near your forehead with elbows bent.","Crunch down by flexing your spine and bringing your elbows to your thighs.","Squeeze your abs hard at the bottom.","Return to the start position and repeat."],["Avoid pulling the rope down with your arms.","Keep your hips fixed so movement comes from the spine.","Exhale fully as you crunch down."],{"start":"images/flat/cable-crunch-start.webp","peak":"images/flat/cable-crunch-peak.webp"},"strength"],["cable-curl","Cable Curl","beginner","cable","upper_arms","A bicep curl using cable resistance for constant tension.",["Stand facing a low cable pulley with a straight bar or EZ-bar attachment.","Grip the bar with an underhand grip, elbows at your sides.","Curl the bar up toward your shoulders.","Lower with control.","Repeat."],["Keep your elbows from drifting forward as you curl.","Straighten your arms fully at the bottom of each rep.","Avoid leaning back to help lift the weight."],{"start":"images/flat/cable-curl-start.webp","peak":"images/flat/cable-curl-peak.webp"},"strength"],["cable-external-rotation","Cable External Rotation","intermediate","cable","shoulders","A cable exercise rotating the forearm outward with the elbow pinned at the side, strengthening the rotator cuff's external rotators with the rear delts assisting.",["Set a cable pulley to elbow height and grip the handle.","Stand side-on to the machine with your working elbow bent at 90 degrees.","Keep your elbow glued to your side and rotate your forearm outward.","Pause at the end of the movement.","Return under control. Complete reps on one side, then switch."],["Use a light weight to keep the rotation strict and controlled.","Keep your wrist straight and in line with your forearm.","Avoid shrugging your shoulder or twisting your torso during the movement."],{"start":"images/flat/cable-external-rotation-start.webp","peak":"images/flat/cable-external-rotation-peak.webp"},"strength"],["cable-fly","Cable Fly","intermediate","cable","chest","An isolation movement for the chest using cable resistance for constant tension.",["Stand between two cable columns with handles attached to high pulleys.","With a slight bend in your elbows, open your arms wide.","Bring your hands together in front of your chest in a hugging motion.","Slowly return to the starting position.","Repeat."],["Maintain the same elbow bend throughout; do not press the weight.","Step one foot forward for a stable, balanced stance.","Control the stretch; do not let the cables yank your arms back."],{"start":"images/flat/cable-fly-start.webp","peak":"images/flat/cable-fly-peak.webp"},"strength"],["cable-front-raise","Cable Front Raise","intermediate","cable","shoulders","An isolation exercise raising a cable handle to shoulder height, keeping constant tension on the front delt.",["Stand facing away from a low cable pulley with a handle attachment.","Hold the handle with arm extended at your thigh.","Raise your arm forward to shoulder height keeping it straight.","Pause at the top.","Lower under control and repeat."],["Avoid swinging or using momentum to lift the handle.","Keep your torso upright; do not lean back as the arm rises.","Brace your core and keep your wrist neutral throughout."],{"start":"images/flat/cable-front-raise-start.webp","peak":"images/flat/cable-front-raise-peak.webp"},"strength"],["cable-hammer-curl","Cable Hammer Curl","intermediate","cable","upper_arms","A cable curl using a rope attachment with a neutral grip to target the brachialis and brachioradialis with constant tension.",["Attach a rope to a low cable pulley and stand facing the machine.","Grip the rope with a neutral (hammer) grip, palms facing each other.","Curl the rope upward toward your shoulders, keeping elbows pinned at your sides.","Squeeze at the top, then lower slowly to full extension.","Repeat for the desired reps."],["Keep your elbows stationary throughout the movement.","Pull the rope ends apart slightly at the top to increase contraction.","Avoid swinging the torso."],{"start":"images/flat/cable-hammer-curl-start.webp","peak":"images/flat/cable-hammer-curl-peak.webp"},"strength"],["cable-kickback","Cable Glute Kickback","intermediate","cable","upper_legs","A cable isolation exercise for the glutes, extending the hip back against constant resistance.",["Attach an ankle cuff to a low cable pulley and fasten it around one ankle.","Stand facing the machine, holding the frame lightly for balance, and hinge slightly forward at the hips.","Kick the cuffed leg straight back, extending the hip fully while keeping the knee nearly straight.","Squeeze the glute at full hip extension, then return the foot slowly to the start.","Complete all reps on one side before switching."],["Lead with the heel to maximize glute activation over hamstrings.","Keep the hips square; avoid rotating the pelvis as the leg kicks back.","The movement comes entirely from the hip - keep the back and torso still."],{"start":"images/flat/cable-kickback-start.webp","peak":"images/flat/cable-kickback-peak.webp"},"strength"],["cable-lateral-raise","Cable Lateral Raise","intermediate","cable","shoulders","A unilateral lateral raise on the cable, providing constant tension on the side delt.",["Stand sideways to a low pulley and grip the handle with the hand farther from the machine.","Keep a soft bend in the elbow and let the cable run across the front of your body.","Raise the arm out to the side until parallel to the floor.","Lower under control. Complete reps per side, then switch.","Maintain tension - do not let the weight rest at the bottom."],["Lead with the elbow, not the hand.","Pause briefly at the top, do not swing.","Use a lighter load than for dumbbell - cable tension is constant."],{"start":"images/flat/cable-lateral-raise-start.webp","peak":"images/flat/cable-lateral-raise-peak.webp"},"strength"],["cable-overhead-tricep-extension","Cable Overhead Tricep Extension","intermediate","cable","upper_arms","A cable triceps exercise: facing away from the weight stack, you hold a rope behind your head and straighten your elbows to push it up and overhead. The overhead position stretches the long head of the triceps, and the cable keeps tension on the muscle through the whole movement.",["Attach a rope to the low pulley and select a light weight.","Take the rope in both hands, turn away from the stack and step forward into a staggered stance so the cable pulls you back.","Raise the rope overhead with your elbows bent and your upper arms close to your ears, so your hands are behind your head.","Brace your trunk and keep your upper arms still, then straighten your elbows to push the rope up until your arms are fully extended overhead.","Pause briefly at the top, then bend your elbows to lower the rope back behind your head under control.","Repeat for the planned repetitions."],["Keep the elbows pointing forward and the upper arms still; letting them flare out or drift turns the extension into a press.","Step far enough forward that the cable holds you steady, and avoid arching your lower back as the arms go overhead.","Use a weight you can control through the full stretch; heavy loads pull the elbows apart."],{"start":"images/flat/cable-overhead-tricep-extension-start.webp","peak":"images/flat/cable-overhead-tricep-extension-peak.webp"},"strength"],["cable-pallof-press","Cable Pallof Press","intermediate","cable","core","An anti-rotation core exercise in which a cable pulls you sideways while you press a handle straight out from your chest and refuse to let your torso turn.",["Set a cable at chest height and take the handle in both hands, standing side-on to the machine.","Step away until there is real tension on the cable, with your feet about shoulder-width apart and knees softly bent.","Bring the handle to the centre of your chest and brace your trunk and glutes.","Press the handle straight out in front of you until your arms are extended, resisting the pull that wants to rotate you toward the machine.","Hold the extended position for a moment, then bring the handle back to your chest under control.","Complete the desired reps, then turn around and repeat facing the other way."],["Nothing should rotate. If your shoulders turn toward the cable as you press, reduce the weight - the point is the rotation that does not happen.","The further you step from the machine, the longer the lever and the harder it gets, so you can change difficulty without touching the weight stack.","Keep your arms level with your chest and your shoulders down; letting the handle drift up turns it into a front raise."],{"start":"images/flat/cable-pallof-press-start.webp","peak":"images/flat/cable-pallof-press-peak.webp"},"strength"],["cable-pull-through","Cable Pull-Through","intermediate","cable","upper_legs","A cable-resisted hip hinge performed facing away from a low pulley, loading the glutes and hamstrings without placing a bar across the spine.",["Attach a rope to the low pulley and stand facing away from the machine with the rope between the legs.","Step forward until the cable is taut, then brace the trunk and soften the knees.","Push the hips back while keeping the spine neutral and the arms long.","Drive the hips forward and squeeze the glutes to stand tall.","Reverse into the next hinge without letting the weight stack slam down."],["Think hips back and hips through; the arms only hold the rope.","Keep the shins nearly vertical so the movement stays a hinge rather than a squat.","Finish tall without leaning backwards at lockout."],{"start":"images/flat/cable-pull-through-start.webp","peak":"images/flat/cable-pull-through-peak.webp"},"strength"],["cable-reverse-fly","Cable Reverse Fly","intermediate","cable","shoulders","A standing cable exercise for the rear deltoids: facing the space between two cable towers, you hold the opposite handles with the cables crossed in front of you and sweep your arms out and back until they are level with your shoulders. The cables keep tension on the back of the shoulders through the whole arc.",["Set both pulleys at about shoulder height and stand centred between the two cable towers.","Take the left handle in your right hand and the right handle in your left hand, so the cables cross in front of you.","Stand tall with your arms reaching forward at shoulder height and a slight bend in the elbows.","Sweep your arms out and back in a wide arc, leading with the elbows, until they are in line with your shoulders.","Squeeze your shoulder blades together briefly without arching your lower back.","Bring the handles back to the crossed start position slowly and repeat for the planned repetitions."],["Keep the elbows soft and fixed; bending and straightening them turns the fly into a row.","Keep your shoulders down and your neck relaxed so the rear deltoids do the work, not the upper trapezius.","Use a light weight and a slow return; the cables pull hardest at the end of the arc, so control that position."],{"start":"images/flat/cable-reverse-fly-start.webp","peak":"images/flat/cable-reverse-fly-peak.webp"},"strength"],["cable-tricep-kickback","Cable Tricep Kickback","intermediate","cable","upper_arms","An isolation movement performed hinged forward, extending the elbow against cable resistance to work the triceps.",["Attach a handle to a low cable and hinge forward at the hips.","Tuck your upper arm against your side with elbow bent 90 degrees.","Extend your elbow to push the handle back behind you.","Squeeze your triceps at the end of the movement.","Return under control. Complete reps on one side, then switch."],["Move only your forearm; keep the upper arm completely still.","Avoid rounding your back while holding the hinged position.","Use a light weight to reach full lockout without swinging."],{"start":"images/flat/cable-tricep-kickback-start.webp","peak":"images/flat/cable-tricep-kickback-peak.webp"},"strength"],["cable-upright-row","Cable Upright Row","intermediate","cable","shoulders","An upright row performed with a cable for constant tension on the lateral deltoids and traps.",["Stand in front of a cable machine and grip a straight bar or rope at thigh height.","Pull the bar up toward your chin, leading with your elbows.","Lower under control.","Repeat."],["Keep elbows higher than your wrists.","Avoid shrugging excessively."],{"start":"images/flat/cable-upright-row-start.webp","peak":"images/flat/cable-upright-row-peak.webp"},"strength"],["cable-wrist-curl","Cable Wrist Curl","intermediate","cable","lower_arms","An isolation exercise for the forearm flexors: seated on a flat bench with your forearms resting on your thighs, you hold a short bar attached to a low cable pulley in front of you and curl it up by flexing your wrists. The thighs keep the forearms still, so only the wrists move.",["Attach a short straight bar to a low cable pulley and sit on a flat bench facing the pulley, feet flat on the floor.","Take the bar with an underhand grip, palms facing up, hands about shoulder-width apart.","Rest your forearms on your thighs so that your wrists and hands reach just past your knees.","Let the cable pull your wrists down until you feel a stretch in your forearms.","Curl the bar up by flexing your wrists, keeping your forearms on your thighs.","Lower the bar under control and repeat for the planned repetitions."],["Move only at the wrists; keep your forearms pressed against your thighs.","Perform the reps slowly to avoid straining your wrists.","Pause briefly at the top of each rep for a stronger contraction."],{"start":"images/flat/cable-wrist-curl-start.webp","peak":"images/flat/cable-wrist-curl-peak.webp"},"strength"],["calf-raise-hold","Calf Raise Hold","beginner","bodyweight","lower_legs","An isometric calf exercise: you rise onto the balls of your feet with the knees straight and hold the top position. The gastrocnemius and the soleus stay under constant tension at the point where a calf raise is hardest, with no movement to hide behind.",["Stand tall with your feet about hip-width apart and your arms relaxed at your sides.","Push through the balls of your feet and rise onto your toes as high as you can.","Keep your knees straight and your weight over the middle of your feet, not rolling out to the little toes.","Stop at the top and hold the position, heels as high as possible.","Keep your hips level, your chest tall and your breathing slow while you hold for the planned time.","Lower your heels slowly to the floor and rest."],["Hold on to a wall or a rack with one hand if you wobble; the aim is the calf contraction, not the balance.","Do not let the heels sink during the hold; if they drop, end the set instead of bouncing back up.","Add a pair of dumbbells or a loaded backpack once you can hold bodyweight for a full minute."],{"main":"images/flat/calf-raise-hold-main.webp"},"strength"],["camel-pose","Camel Pose","intermediate","bodyweight","core","A kneeling backbend that opens the front of the hips, the abdomen and the chest while the hands support the position on the heels or the lower back.",["Kneel with the knees hip-width apart and the hips stacked over the knees.","Place the hands on the back of the pelvis with the fingers pointing down and lift the chest.","Press the hips forward and arch back, reaching for the heels if the position stays comfortable.","Hold the pose for the prescribed time, keeping the neck in line with the spine.","Bring the hands back to the pelvis and come up chest-first."],["Keep the hips over the knees; letting them travel back turns the pose into a collapse.","Tuck the toes under and rest the hands on raised heels if the full reach is too deep.","Come out slowly: lifting the head first is what usually makes people dizzy."],{"main":"images/flat/camel-pose-main.webp"},"stretching"],["captains-chair-knee-raise","Captain's Chair Knee Raise","beginner","bodyweight","core","A bodyweight core exercise performed on a captain's chair that targets the lower abs and hip flexors.",["Position yourself in the captain's chair with your back flat against the pad and forearms on the armrests.","Let your legs hang straight down.","Engage your core and raise your knees toward your chest.","Hold briefly at the top, then lower slowly to the starting position.","Repeat for the desired reps."],["Avoid swinging the legs for momentum.","Exhale as you raise your knees.","Keep your back pressed against the pad throughout."],{"start":"images/flat/captains-chair-knee-raise-start.webp","peak":"images/flat/captains-chair-knee-raise-peak.webp"},"strength"],["captains-chair-leg-raise","Captain's Chair Leg Raise","intermediate","bodyweight","core","A bodyweight core exercise on a captain's chair that targets the lower abs and hip flexors with straight legs for greater difficulty.",["Position yourself in the captain's chair with your back flat against the pad and forearms on the armrests.","Let your legs hang straight down.","Keeping your legs straight, raise them until parallel with the floor or higher.","Hold briefly at the top, then lower slowly.","Repeat for the desired reps."],["Keep your legs as straight as possible throughout.","Avoid swinging - control the movement with your core.","For less difficulty, bend the knees slightly."],{"start":"images/flat/captains-chair-leg-raise-start.webp","peak":"images/flat/captains-chair-leg-raise-peak.webp"},"strength"],["cat-cow","Cat-Cow","beginner","bodyweight","back","A kneeling flow that alternates between rounding the spine towards the ceiling and letting it sag while the chest opens, moving every segment of the back through its range.",["Start on all fours with the hands under the shoulders and the knees under the hips.","Exhale and round the spine towards the ceiling, tucking the tailbone and letting the head drop.","Inhale and reverse it: let the belly sink, lift the chest and tailbone, and look slightly forward.","Move between the two shapes slowly, one breath per position.","Finish in a neutral spine and sit back onto the heels."],["Let the breath set the tempo rather than rushing between the two positions.","Keep the hands pressing evenly so the shoulders do not collapse towards the floor.","Move the whole spine, including the neck, instead of hinging only at the lower back."],{"main":"images/flat/cat-cow-main.webp"},"stretching"],["cat-stretch","Cat Stretch","beginner","bodyweight","back","A kneeling stretch that rounds the spine upward to lengthen the back muscles.",["Start on all fours, hands under shoulders and knees under hips.","Round your spine up toward the ceiling.","Tuck your chin toward your chest.","Hold for 20 to 30 seconds, breathing steadily."],["Push the floor away with your hands to spread the shoulder blades.","Relax and keep breathing throughout."],{"main":"images/flat/cat-stretch-main.webp"},"stretching"],["chair-pose","Chair Pose","beginner","bodyweight","upper_legs","A standing hold with the hips sunk back and the arms overhead, so the quadriceps and the upper back work isometrically against bodyweight.",["Stand with the feet together or hip-width apart and the weight in the heels.","Bend the knees and send the hips back as if sitting down onto a chair.","Raise the arms overhead beside the ears, keeping the ribs from flaring.","Hold the position for the prescribed time with the chest lifted and the knees tracking over the toes.","Press through the heels to stand back up."],["Keep enough weight in the heels that you could lift the toes.","Take the arms slightly forward if raising them fully makes the lower back arch.","Sink lower for more quadriceps work, but only while the heels stay down."],{"main":"images/flat/chair-pose-main.webp"},"strength"],["cheat-curl","Cheat Curl","intermediate","barbell","upper_arms","A momentum-assisted bicep curl using slight hip drive on the way up and a slow, controlled lowering phase.",["Stand holding weight at thigh level with an underhand grip.","Use a slight hip drive to start the curl.","Curl the weight up toward your shoulders explosively.","Lower the weight slowly under control through the full range.","Repeat for the desired number of reps."],["Keep the hip drive small so your biceps still do most of the work.","Avoid leaning back excessively to protect your lower back.","Keep your elbows close to your torso throughout the curl."],{"start":"images/flat/cheat-curl-start.webp","peak":"images/flat/cheat-curl-peak.webp"},"strength"],["chest-press-machine","Machine Chest Press","beginner","chest_press_machine","chest","A machine-based pressing movement for the chest, ideal for beginners.",["Sit in the machine with your back flat against the pad.","Grip the handles at chest level.","Push the handles forward until your arms are fully extended.","Slowly return to the starting position.","Repeat."],["Adjust the seat so the handles line up with mid-chest.","Keep your shoulder blades pulled back against the pad as you press.","Press to full extension without forcefully locking your elbows."],{"start":"images/flat/chest-press-machine-start.webp","peak":"images/flat/chest-press-machine-peak.webp"},"strength"],["chest-supported-db-row","Chest-Supported Dumbbell Row","intermediate","dumbbell","back","A dumbbell row with chest support to eliminate lower back strain and isolate the back muscles.",["Lie face-down on an incline bench with dumbbells hanging beneath.","Row the dumbbells up to your sides.","Squeeze at the top, then lower.","Repeat."],["The chest support eliminates back fatigue.","Focus on squeezing the shoulder blades together."],{"start":"images/flat/chest-supported-db-row-start.webp","peak":"images/flat/chest-supported-db-row-peak.webp"},"strength"],["chest-supported-dumbbell-shrug","Chest Supported Dumbbell Shrug","intermediate","dumbbell","back","A shrug performed face-down on an incline bench, the chest support isolating the traps and removing momentum.",["Set an incline bench to about 30 degrees.","Lie face down on the bench holding dumbbells at arm's length.","Shrug your shoulders up and back toward your ears.","Squeeze your upper traps at the top.","Lower under control and repeat."],["Shrug up and back toward your ears rather than straight up.","Keep your chest pinned to the pad so you cannot use body english.","Pause and squeeze at the top before lowering under control."],{"start":"images/flat/chest-supported-dumbbell-shrug-start.webp","peak":"images/flat/chest-supported-dumbbell-shrug-peak.webp"},"strength"],["chest-supported-kettlebell-row","Chest-Supported Kettlebell Row","beginner","kettlebell","back","This exercise targets your back muscles, primarily the latissimus dorsi and rhomboids, by rowing a kettlebell in each hand towards your hips while your torso is supported on an incline bench.",["Lie face down on an incline bench, allowing your arms to hang freely with a kettlebell in each hand.","Brace your core and retract your shoulder blades.","Pull the kettlebells towards your hips, squeezing your shoulder blades together.","Pause briefly at the top, feeling the contraction in your back.","Slowly lower the kettlebells back to the starting position with control."],["Maintain a stable torso throughout the movement; avoid rocking.","Focus on initiating the pull with your back muscles, not just your arms.","Keep your elbows close to your body to emphasize the lats."],{"start":"images/flat/chest-supported-kettlebell-row-start.webp","peak":"images/flat/chest-supported-kettlebell-row-peak.webp"},"strength"],["chest-supported-machine-row","Chest-Supported Machine Row","beginner","seated_row_machine","back","A seated rowing machine exercise with a chest pad that supports the torso, so the lats and the muscles between the shoulder blades do the pulling and the lower back stays out of it. You pull the handles back by driving the elbows behind you, then let them return forward with control.",["Adjust the seat so the handles sit at lower-chest height, then sit with your chest against the pad and your feet planted.","Reach forward and take the handles with your arms extended and your shoulders relaxed.","Brace your trunk, then pull the handles back by driving your elbows behind you.","Squeeze your shoulder blades together at the end of the pull without lifting your chest off the pad.","Pause briefly, then extend your arms to return the handles forward under control.","Repeat for the planned repetitions, keeping your chest on the pad throughout."],["Pull with the elbows rather than the hands, so the lats and mid-back lead and the biceps assist.","Keep the chest on the pad and the shoulders down; shrugging or leaning back turns the row into an upper trapezius pull.","Let the shoulder blades spread forward at the start of each repetition to get a full stretch before the next pull."],{"start":"images/flat/chest-supported-machine-row-start.webp","peak":"images/flat/chest-supported-machine-row-peak.webp"},"strength"],["chest-supported-smith-machine-row","Chest-Supported Smith Machine Row","beginner","smith_machine","back","A row performed against an inclined pad inside the Smith machine, where the chest support removes the lower back from the movement and the guided bar keeps the pull in one line.",["Set an incline bench inside the Smith machine facing the bar, and set the bar low enough that your arms hang straight when you lean on the pad.","Stand astride the bench with your feet planted and your chest resting against the top of the pad.","Take an overhand grip a little wider than shoulder-width and unhook the bar with your arms extended.","Pull the bar up to your lower chest, leading with your elbows and squeezing the shoulder blades together at the top.","Lower the bar under control until your arms are straight again, and repeat for the desired number of repetitions."],["Keep your chest on the pad for every repetition. The moment you push off it to move the weight you have turned this back into a bent-over row and given up the reason for the setup.","Lead with the elbows and stop when they pass your torso. Pulling further only rolls the shoulders forward and the fixed bar path leaves nowhere for them to go.","Because your lower back is doing nothing here, this is the row to use on a day when a bent-over row is not an option -- match the weight to what your back can pull, not to what your legs could brace."],{"start":"images/flat/chest-supported-smith-machine-row-start.webp","peak":"images/flat/chest-supported-smith-machine-row-peak.webp"},"strength"],["childs-pose","Child's Pose","beginner","bodyweight","back","A kneeling rest stretch that lengthens the lats, lower back and shoulders with the arms reaching forward.",["Kneel and sit your hips back toward your heels.","Fold your torso forward over your thighs.","Reach both arms out long on the floor in front.","Hold for 20 to 30 seconds, breathing steadily."],["Spread your knees wider to rest your chest lower.","Relax and keep breathing throughout."],{"main":"images/flat/childs-pose-main.webp"},"stretching"],["chin-tuck-hold","Chin Tuck Hold","intermediate","bodyweight","full_body","A static neck drill that retracts the head straight back to strengthen the deep neck flexors and counter forward-head posture.",["Stand or sit tall with your shoulders relaxed.","Pull your chin straight back, creating a double chin.","Keep your head level without tilting.","Hold the position for the desired duration.","Release and repeat for multiple sets."],["Imagine sliding your head back over your spine, not nodding down.","Keep your gaze level and your breathing relaxed."],{"main":"images/flat/chin-tuck-hold-main.webp"},"strength"],["chin-ups","Chin-Ups","intermediate","pull_up_bar","back","A supinated-grip pull-up that strongly activates the biceps alongside the lats.",["Hang from a bar with a shoulder-width underhand grip.","Pull yourself up until chin is above the bar.","Lower under control.","Repeat."],["Keep the core tight throughout.","Avoid excessive swinging."],{"start":"images/flat/chin-ups-start.webp","peak":"images/flat/chin-ups-peak.webp"},"strength"],["clamshells","Clamshells","intermediate","bodyweight","upper_legs","A side-lying hip exercise opening the top knee against gravity to activate the gluteus medius.",["Lie on your side with knees bent and stacked on top of each other.","Keep your feet together and hips stacked.","Open your top knee toward the ceiling without rotating your hips.","Squeeze your outer glute at the top.","Lower under control. Complete reps on one side, then switch."],["Place a hand on your top hip to check for unwanted rolling.","Keep the movement small and controlled rather than forcing the knee high.","Rest your head on your lower arm to keep your spine neutral."],{"start":"images/flat/clamshells-start.webp","peak":"images/flat/clamshells-peak.webp"},"strength"],["clamshells-hold","Clamshell Hold","intermediate","bodyweight","upper_legs","The top position of the clamshell held for time: lying on one side with the knees bent and stacked, the upper knee lifted and the pelvis square, so the glute medius works isometrically instead of through repetitions.",["Lie on one side with the hips and knees bent about 45 and 90 degrees, heels together and knees stacked.","Stack the shoulders and hips vertically and brace the trunk so the pelvis cannot roll backwards.","Open the upper knee as far as it goes without the pelvis rotating, keeping the heels touching.","Hold that open position for the prescribed time, breathing normally.","Lower the knee under control and repeat on the other side."],["Stop the lift where the pelvis starts to roll back; the range is smaller than most people expect.","Keep the heels pressed together so the movement stays in the hip rather than the ankle.","Add a loop band above the knees only once the pelvis stays perfectly still."],{"main":"images/flat/clamshells-hold-main.webp"},"strength"],["clap-push-ups","Clap Push-Ups","advanced","bodyweight","chest","An explosive plyometric push-up developing chest power and fast-twitch muscle fibers.",["Begin in a standard push-up position.","Lower your chest to the floor.","Explosively push up so hands leave the ground.","Clap your hands together and land softly, returning to start.","Repeat."],["Land with soft elbows to absorb impact.","Ensure you have enough upper body strength before attempting."],{"start":"images/flat/clap-push-ups-start.webp","peak":"images/flat/clap-push-ups-peak.webp"},"strength"],["clean","Clean","intermediate","barbell","full_body","An Olympic lift pulling a barbell explosively from the floor to the front-rack position on the shoulders.",["Stand over a loaded barbell with feet hip-width apart.","Grip the bar just outside your knees with an overhand grip.","Drive explosively through your legs and extend your hips.","Pull yourself under the bar and catch it on your front deltoids.","Stand fully upright to complete the lift."],["Keep the bar close to your body as it travels up.","Finish your leg drive fully before pulling under the bar.","Catch with your elbows high so the bar rests on your shoulders."],{"start":"images/flat/clean-start.webp","peak":"images/flat/clean-peak.webp"},"olympic"],["clean-and-jerk","Clean and Jerk","intermediate","barbell","full_body","A two-part Olympic lift cleaning a barbell to the shoulders, then driving it overhead.",["Pull a loaded barbell from the floor to your shoulders as in a clean.","Stand fully with the bar racked on your front delts.","Dip slightly and drive the bar overhead explosively.","Drop into a partial squat under the bar as your arms lock out overhead, feet staying about hip-width apart.","Stand up fully and hold the bar steady overhead before lowering it."],["Stand fully and reset your position before starting the jerk.","Drive the bar up with your legs, not just your arms.","Lock your arms out as you drop under the bar, then stand and hold the finish briefly."],{"start":"images/flat/clean-and-jerk-start.webp","peak":"images/flat/clean-and-jerk-peak.webp"},"olympic"],["close-grip-barbell-curl","Close-Grip Barbell Curl","beginner","barbell","upper_arms","A standing barbell curl with a narrow grip, biasing the long head of the biceps and the brachialis.",["Stand holding a barbell with an underhand grip, hands closer than shoulder-width apart.","Start with the bar at the thighs, arms extended, elbows tucked to the sides.","Curl the bar up to the shoulders by flexing the elbows.","Squeeze the biceps at the top, then lower under control.","Repeat for the recommended number of repetitions."],["Keep the elbows pinned to the sides - do not let them drift forward.","If the narrow grip bothers your wrists, use an EZ-bar."],{"start":"images/flat/close-grip-barbell-curl-start.webp","peak":"images/flat/close-grip-barbell-curl-peak.webp"},"strength"],["close-grip-bench-press","Close-Grip Bench Press","intermediate","barbell","upper_arms","A bench press variation with a narrow grip that shifts the emphasis to the triceps.",["Lie on a flat bench and grip the barbell with hands shoulder-width apart.","Lower the bar to your lower chest keeping elbows close to your sides.","Press back up to full extension.","Repeat."],["Keep elbows tucked to maximize triceps activation.","Avoid too-narrow a grip to prevent wrist strain."],{"start":"images/flat/close-grip-bench-press-start.webp","peak":"images/flat/close-grip-bench-press-peak.webp"},"strength"],["close-grip-db-bench-press","Close-Grip Dumbbell Bench Press","intermediate","dumbbell","upper_arms","A dumbbell bench press with dumbbells held together to increase triceps involvement.",["Lie on a flat bench and hold two dumbbells together over your chest.","Lower them to your chest keeping elbows close.","Press back up.","Repeat."],["Press the dumbbells together throughout the movement.","Keep elbows tucked."],{"start":"images/flat/close-grip-db-bench-press-start.webp","peak":"images/flat/close-grip-db-bench-press-peak.webp"},"strength"],["close-grip-ez-bar-bench-press","Close-Grip EZ-Bar Bench Press","intermediate","ez_bar","upper_arms","A triceps-focused press using an EZ-bar with a narrow grip for wrist comfort.",["Lie on a flat bench and grip the inner curves of the EZ-bar.","Lower the bar to your chest with elbows tucked.","Press back up to full extension.","Repeat."],["The EZ-bar reduces wrist discomfort.","Keep the movement controlled."],{"start":"images/flat/close-grip-ez-bar-bench-press-start.webp","peak":"images/flat/close-grip-ez-bar-bench-press-peak.webp"},"strength"],["close-grip-ez-bar-curl","Close-Grip EZ-Bar Curl","beginner","ez_bar","upper_arms","An EZ-bar biceps curl with hands close together, biasing the long head of the biceps.",["Stand holding an EZ-bar with hands on the inner bends, palms up.","Keep the elbows tucked at the sides.","Curl the bar up to shoulder level, squeezing the biceps.","Lower under control to a full stretch.","Repeat for the prescribed reps."],["Keep the elbows pinned - do not let them flare forward.","Squeeze hard at the top.","Avoid swinging the torso for momentum."],{"start":"images/flat/close-grip-ez-bar-curl-start.webp","peak":"images/flat/close-grip-ez-bar-curl-peak.webp"},"strength"],["close-grip-incline-bench","Close-Grip Incline Bench Press","intermediate","barbell","upper_arms","An incline bench press with a close grip targeting the triceps and upper chest.",["Set bench to an incline. Grip the barbell with hands shoulder-width or closer.","Lower the bar to your upper chest.","Press back up.","Repeat."],["The incline increases the stretch on the long head of the triceps.","Tuck elbows to keep the focus on triceps."],{"start":"images/flat/close-grip-incline-bench-start.webp","peak":"images/flat/close-grip-incline-bench-peak.webp"},"strength"],["close-grip-lat-pulldown","Close Grip Lat Pulldown","intermediate","cable","back","A lat pulldown variation using a close, parallel-grip handle to emphasize the lower lats and biceps.",["Sit at a lat pulldown machine and secure your thighs under the pad.","Grip the close-grip handle with palms facing each other.","Pull the handle down to your upper chest.","Squeeze your lats at the bottom.","Return under control and repeat."],["Lean back only slightly, not excessively.","Avoid using momentum to pull the handle down.","Drive your elbows down and back, not just your hands."],{"start":"images/flat/close-grip-lat-pulldown-start.webp","peak":"images/flat/close-grip-lat-pulldown-peak.webp"},"strength"],["close-grip-pull-ups","Close-Grip Pull-Ups","intermediate","pull_up_bar","back","A pull-up with a narrow overhand grip that increases biceps and inner-back activation.",["Hang from a pull-up bar with hands shoulder-width or narrower, palms away.","Pull yourself up until chin clears the bar.","Lower under control.","Repeat."],["The narrow grip increases biceps involvement.","Avoid kipping for strength development."],{"start":"images/flat/close-grip-pull-ups-start.webp","peak":"images/flat/close-grip-pull-ups-peak.webp"},"strength"],["close-grip-push-ups","Close Grip Push Ups","intermediate","bodyweight","chest","A push-up variation with hands placed close together to emphasize the triceps.",["Assume a push-up position with hands directly under your shoulders.","Keep your elbows tucked close to your ribs.","Lower your chest toward the floor.","Press back up to the starting position.","Repeat for the desired number of reps."],["Keep your elbows tracking backward, not flared out.","Maintain a rigid plank position throughout.","Slow the descent for greater triceps activation."],{"start":"images/flat/close-grip-push-ups-start.webp","peak":"images/flat/close-grip-push-ups-peak.webp"},"strength"],["close-stance-leg-press","Close-Stance Leg Press","beginner","leg_press","upper_legs","A leg press with the feet set close together, increasing knee flexion and keeping the quadriceps prominent while the back remains supported against the pad.",["Set the seat and back pad so your lower back stays supported throughout the repetition.","Place your feet close together near the middle of the platform, with the toes and knees pointing along the same line.","Lower the sled by bending the knees and hips while keeping both feet flat and the knees tracking over the toes.","Press the platform away through the whole foot until the legs are extended without snapping the knees straight.","Return under control and repeat for the desired number of repetitions."],["Use only as narrow a stance as lets the knees track comfortably over the toes.","Keep the heels down and avoid letting the knees collapse inward as the sled descends.","Do not trade pelvic position for depth; stop before the lower back starts to round off the pad."],{"start":"images/flat/close-stance-leg-press-start.webp","peak":"images/flat/close-stance-leg-press-peak.webp"},"strength"],["cobra-stretch","Cobra Stretch","beginner","bodyweight","core","A prone backbend that stretches the abdominals and front of the torso by lifting the chest.",["Lie face down with your hands under your shoulders.","Press through your hands to lift your chest off the floor.","Keep your hips and legs on the floor, shoulders relaxed.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your elbows slightly bent - do not force full extension.","Draw your shoulders down away from your ears."],{"main":"images/flat/cobra-stretch-main.webp"},"stretching"],["cocoons","Cocoons","intermediate","bodyweight","core","A dynamic ab exercise combining a knee tuck and an upper-body crunch from a full-body extended position.",["Lie face-up on the floor with arms extended overhead and legs extended, hovering slightly off the floor.","Simultaneously tuck the knees toward the chest and sweep the arms forward into a crunch.","Try to touch the hands to the shins at the top.","Reverse the motion smoothly, re-extending arms and legs back to the hover.","Repeat for the recommended number of repetitions."],["Feet and hands never touch the floor between reps - that's the whole drill.","Exhale sharply at the top of the tuck."],{"start":"images/flat/cocoons-start.webp","peak":"images/flat/cocoons-peak.webp"},"strength"],["commando-pull-up","Commando Pull-Up","advanced","pull_up_bar","back","A pull-up variation done with a staggered grip: the hands sit one in front of the other on the bar and the body is turned sideways, so the head passes beside the bar on each repetition. It demands more from the lats, arms and trunk than a standard pull-up.",["Grip the bar with the hands one in front of the other, palms facing each other, and hang with the arms straight and the body turned sideways.","Brace the trunk and pull the shoulder blades down to start the movement.","Pull yourself up, driving the elbows down, until your head clears the bar on one side of it.","Pause briefly at the top with the chest close to the bar.","Lower under control to a full hang.","Take the head to the other side of the bar on the next repetition, or swap the hand positions each set."],["Keep the legs and trunk still; swinging turns the pull into a kip.","Alternate the sides evenly so both arms and lats do the same work.","Start with a few repetitions per set: the staggered grip is harder than a regular pull-up."],{"start":"images/flat/commando-pull-up-start.webp","peak":"images/flat/commando-pull-up-peak.webp"},"strength"],["concentration-curl","Concentration Curl","beginner","dumbbell","upper_arms","An isolation curl performed seated for peak bicep contraction.",["Sit on a bench with legs spread, holding a dumbbell in one hand.","Brace your elbow against the inside of your thigh.","Curl the dumbbell up toward your shoulder.","Lower with control.","Repeat on both sides."],["Keep your upper arm vertical and let only the forearm move.","Avoid swinging your torso to help the weight up.","Match the reps on each arm to avoid muscle imbalances."],{"start":"images/flat/concentration-curl-start.webp","peak":"images/flat/concentration-curl-peak.webp"},"strength"],["copenhagen-plank","Copenhagen Plank","advanced","flat_bench","core","A demanding side plank in which the top leg rests on a flat bench and the lower leg is held off the floor. The inner thigh muscles of the top leg and the obliques hold the body in a straight line, which makes it a classic exercise for the adductors and the trunk.",["Lie on your side next to a flat bench and place your top leg on it, with the inside of the foot or the lower part of the leg resting on the bench.","Prop yourself up on the elbow of your lower arm, directly under your shoulder.","Lift your hips so that your body forms a straight line from your head to your top foot, and let the lower leg hang or lift it toward the bench.","Keep your hips high and your trunk steady, and breathe evenly.","Hold for the planned time, then lower your hips back to the floor.","Rest, then switch sides."],["Start with the top knee on the bench and a short lever; move the foot of the top leg onto the bench only when the hold feels easy.","Press your forearm into the floor and keep your shoulder away from your ear.","Stop if you feel a sharp pull in the groin; the adductors need a gentle build-up."],{"main":"images/flat/copenhagen-plank-main.webp"},"strength"],["copenhagen-plank-raises","Copenhagen Plank Raises","advanced","flat_bench","core","A dynamic version of the Copenhagen plank: you hold a side plank with the top leg resting on a flat bench and lift the lower leg up to meet it, then lower it again. The inner thigh muscles of both legs and the obliques work together, and the movement is demanding for the adductors.",["Lie on your side next to a flat bench and place your top leg on it, with the knee or the inner foot resting on the bench.","Prop yourself up on the elbow of your lower arm, directly under the shoulder.","Lift your hips so that your body forms a straight line from your head to your top foot, with the lower leg hanging underneath.","Raise the lower leg up toward the bench until it nearly touches the top leg, keeping your hips high.","Lower the lower leg slowly without letting your hips drop, and repeat for the planned repetitions.","Rest, then switch sides."],["Start with the top knee on the bench and a short lever; move the foot of the top leg onto the bench only when the raises feel easy.","Keep your hips high and your body in one line; dropping the hips takes the load off the inner thighs.","Move slowly and stop if you feel a sharp pull in the groin; the adductors need a gentle build-up."],{"start":"images/flat/copenhagen-plank-raises-start.webp","peak":"images/flat/copenhagen-plank-raises-peak.webp"},"strength"],["cossack-squat","Cossack Squat","intermediate","bodyweight","upper_legs","A wide-stance lateral squat that sinks the body deep over one bent leg while the other stays straight, training single-leg strength, hip mobility, and adductor flexibility.",["Stand in a wide stance with toes turned slightly out.","Shift your weight to one side, bending that knee and sinking into a deep squat.","Keep the trailing leg straight with the heel down and toes up.","Sink as low as your mobility allows, keeping the chest tall.","Drive through the bent leg back to center, then repeat to the other side."],["Keep the working heel planted -- do not roll onto the toes.","Point the straight leg's toes up to keep tension in the adductors.","Hold a light weight at your chest for a counterbalance if needed."],{"start":"images/flat/cossack-squat-start.webp","peak":"images/flat/cossack-squat-peak.webp"},"strength"],["cow-face-pose","Cow Face Pose","beginner","bodyweight","shoulders","A seated pose with the knees stacked and the arms clasped behind the back, stretching the outer hips on one side and the shoulders in opposite directions.",["Sit on the floor and cross one knee directly over the other so the knees stack in the midline.","Walk the feet out towards the hips and settle both sit bones evenly on the floor.","Reach the arm on the top-knee side up and bend it behind the head, then reach the other arm up the back to clasp.","Hold the position for the prescribed time, keeping the chest open and the spine tall.","Release and repeat with the other leg and arm on top."],["Sit on a folded blanket if one sit bone lifts off the floor.","Hold a strap between the hands when the fingers do not meet; forcing the clasp rounds the back.","Keep the top elbow pointing up rather than letting it drift out to the side."],{"main":"images/flat/cow-face-pose-main.webp"},"stretching"],["crab-dips","Crab Dips","intermediate","bodyweight","upper_arms","A floor triceps exercise from the reverse tabletop position: with the hands behind the hips and the trunk lifted, the elbows bend and straighten to move the body up and down.",["Sit with the knees bent, the feet flat and the hands on the floor behind you, fingers pointing towards the heels.","Press into the hands and feet and lift the hips until the trunk is roughly level with the knees.","Bend the elbows straight back to lower the hips towards the floor without sitting down.","Push back up until the arms are straight, keeping the hips lifted.","Repeat for the desired number of repetitions and lower the hips to finish."],["Keep the elbows pointing back, not flaring out to the sides.","Hold the hips high the whole set; letting them drop turns it into a rest.","Walk the feet further away for a longer lever and more triceps work."],{"start":"images/flat/crab-dips-start.webp","peak":"images/flat/crab-dips-peak.webp"},"strength"],["crescent-lunge","Crescent Lunge","intermediate","bodyweight","upper_legs","A split-stance hold with the back heel lifted and the arms overhead, loading the front leg while the back hip stays long.",["Step one foot forward into a long stance with the back heel lifted and the toes pointing forward.","Bend the front knee to about ninety degrees so it stacks over the ankle.","Draw the back hip forward so both hip points face the front of the mat, then raise the arms overhead.","Hold the position for the prescribed time with the ribs down and the back leg straight.","Step the feet together and repeat on the other side."],["Widen the stance sideways a little if balance is the limiting factor.","Press the back heel towards the wall behind you to keep the rear leg working.","Lower the arms to the hips if reaching overhead pulls the lower back into an arch."],{"main":"images/flat/crescent-lunge-main.webp"},"strength"],["cross-body-crunch","Cross-Body Crunch","beginner","bodyweight","core","A floor oblique crunch that draws the opposite elbow and knee toward each other, hitting the obliques and rectus together.",["Lie face-up on the floor with knees bent and hands lightly behind the ears.","Crunch up and rotate, bringing the right elbow toward the left knee as the knee draws up.","Return to the starting position under control.","Repeat on the other side, alternating every rep."],["Twist from the ribcage, not the arms; the elbows follow the shoulders.","Lower back stays on the floor throughout."],{"start":"images/flat/cross-body-crunch-start.webp","peak":"images/flat/cross-body-crunch-peak.webp"},"strength"],["cross-body-hammer-curl","Cross Body Hammer Curl","intermediate","dumbbell","upper_arms","A neutral-grip curl bringing the dumbbell across the body toward the opposite shoulder, emphasizing the brachialis and forearms.",["Stand tall holding a dumbbell in each hand with a neutral grip.","Curl one dumbbell up across your body toward the opposite shoulder.","Keep your elbow stationary at your side.","Lower under control and repeat on the other side.","Continue alternating for the desired number of reps."],["Keep your elbow pinned at your side throughout the curl.","Avoid swinging your torso to lift the weight.","Lower under control rather than letting the dumbbell drop."],{"start":"images/flat/cross-body-hammer-curl-start.webp","peak":"images/flat/cross-body-hammer-curl-peak.webp"},"strength"],["cross-body-shoulder-stretch","Cross-Body Shoulder Stretch","beginner","bodyweight","shoulders","A standing stretch that targets the rear shoulder by drawing one arm horizontally across the chest.",["Stand tall and bring one straight arm across your chest.","Hook your other forearm under it.","Gently pull the arm closer to your chest.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep the stretching shoulder down, not shrugged.","Do not pull on the elbow joint itself."],{"main":"images/flat/cross-body-shoulder-stretch-main.webp"},"stretching"],["crow-pose","Crow Pose","advanced","bodyweight","upper_arms","An arm balance with the knees resting on the backs of the upper arms and the feet lifted, held by the shoulders, arms and trunk.",["Squat with the feet close together and place the palms shoulder-width apart on the floor in front of you.","Bend the elbows straight back and set the knees high onto the backs of the upper arms.","Shift the weight forward onto the hands until the feet float off the floor.","Hold the balance for the prescribed time, rounding the upper back and looking slightly forward.","Lower the feet under control."],["Look at the floor ahead of the hands, not back at the feet; the gaze drives the balance.","Place a cushion in front of you while you are learning to fall forward safely.","Grip the floor with the fingertips to stop the weight rolling into the wrists."],{"main":"images/flat/crow-pose-main.webp"},"strength"],["crunches","Crunches","beginner","bodyweight","core","A basic abdominal exercise focusing on the rectus abdominis.",["Lie on your back with knees bent and hands behind your head.","Curl your upper body toward your knees, lifting your shoulder blades off the floor.","Squeeze your abs at the top.","Lower with control.","Repeat."],["Avoid pulling on your neck with your hands.","Exhale as you curl up and inhale on the way down.","Keep your lower back pressed into the floor throughout."],{"start":"images/flat/crunches-start.webp","peak":"images/flat/crunches-peak.webp"},"strength"],["cycling","Cycling","beginner","bicycle","upper_legs","Riding a road bicycle, used as steady endurance cardio. Seated on the saddle with your hands on the handlebars, you pedal in smooth circles; the thighs drive each pedal stroke, while the glutes, hamstrings and calves complete it.",["Adjust the saddle so your knee is only slightly bent when the pedal is at the bottom of the stroke.","Sit on the saddle with your hands on the handlebars, elbows slightly bent and shoulders relaxed.","Place the balls of your feet over the pedal axles.","Push each pedal down and forward, then let it come up and over the top in a smooth circle.","Keep a steady cadence and choose a gear that lets you pedal without bouncing on the saddle.","Ride for the planned time or distance, easing the pace for the last few minutes to cool down."],["Keep your knees tracking in line with your feet; knees that fall in or out usually mean the saddle or cleats need adjusting.","A higher cadence in an easier gear is kinder to the knees than grinding a hard gear slowly.","Keep your upper body relaxed and your back long rather than rounded or rocking from side to side."],{"main":"images/flat/cycling-main.webp"},"cardio"],["dancer-pose","Dancer Pose","advanced","bodyweight","upper_legs","A standing balance on one leg where the free foot is held behind the body and pressed away, combining a backbend with a single-leg hold.",["Stand tall and shift the weight onto one foot, keeping that knee soft.","Bend the other knee and take hold of the inside of that ankle behind you.","Press the lifted foot back into the hand and reach the opposite arm forward as the chest lifts.","Hold the shape for the prescribed time with the standing hip level and the gaze steady.","Release the foot and repeat on the other side."],["Fix the eyes on one point ahead; a moving gaze is what usually breaks the balance.","Keep the lifted knee in line with the hip rather than letting it swing out sideways.","Use a strap around the lifted foot if the shoulder does not allow the direct grip."],{"main":"images/flat/dancer-pose-main.webp"},"strength"],["db-bench-press","Dumbbell Bench Press","intermediate","dumbbell","chest","A compound chest exercise using dumbbells, allowing a greater range of motion than the barbell bench press.",["Lie on a flat bench holding a dumbbell in each hand at chest level.","Press the dumbbells up until your arms are fully extended.","Lower them slowly back to the start.","Repeat."],["Keep wrists neutral throughout.","Squeeze your chest at the top of the movement."],{"start":"images/flat/db-bench-press-start.webp","peak":"images/flat/db-bench-press-peak.webp"},"strength"],["db-fly","Dumbbell Fly","beginner","dumbbell","chest","An isolation exercise that stretches and contracts the pectorals through a wide arc of motion.",["Lie flat on a bench with dumbbells held above your chest, palms facing each other.","With a slight bend in the elbows, lower the dumbbells out to the sides.","Return to the start by squeezing your chest.","Repeat."],["Keep a consistent bend in the elbows throughout.","Do not let the dumbbells go too low."],{"start":"images/flat/db-fly-start.webp","peak":"images/flat/db-fly-peak.webp"},"strength"],["db-goblet-squat","Dumbbell Goblet Squat","beginner","dumbbell","upper_legs","A beginner-friendly squat with one dumbbell held upright against the chest. The weight in front of you counterbalances your body, so it is easy to sit deep with an upright torso while the quadriceps and glutes do the work.",["Stand with your feet slightly wider than shoulder-width and your toes turned out a little.","Hold one dumbbell vertically at your chest, with both hands cupped under the top end and your elbows pointing down.","Brace your trunk and sit your hips back and down, keeping your chest tall and the dumbbell close to your body.","Lower until your thighs are at least parallel to the floor, with your knees tracking over your toes and your heels flat.","Pause briefly in the bottom position, then drive through your whole foot to stand back up.","Repeat for the planned repetitions without letting the dumbbell drift away from your chest."],["Keep your elbows inside your knees at the bottom; they can lightly press the knees out and help you sit deeper.","Let the dumbbell stay at the chest rather than sinking toward your stomach, or your back will round to compensate.","If your heels lift, raise them on a small plate or turn your toes out a little more until you can stay flat."],{"start":"images/flat/db-goblet-squat-start.webp","peak":"images/flat/db-goblet-squat-peak.webp"},"strength"],["db-kickstand-deadlift","Dumbbell Kickstand Deadlift","intermediate","dumbbell","back","A staggered-stance hip hinge with one dumbbell that loads the front leg while the back foot provides light balance support.",["Step one foot back so only the toes lightly touch the floor, and hinge at the hips with a flat back.","Hold a dumbbell in one hand, low beside the front foot.","Drive through the front heel and extend the hips to stand tall, the dumbbell at your side.","Keep most of your weight on the front foot throughout.","Hinge back down, lowering the dumbbell toward the floor with a flat back. Complete all reps, then switch sides."],["Keep the dumbbell close to the shin on the descent.","Stop when you feel a stretch in the front hamstring.","Complete all reps on one side before switching."],{"start":"images/flat/db-kickstand-deadlift-start.webp","peak":"images/flat/db-kickstand-deadlift-peak.webp"},"strength"],["db-lunge","Dumbbell Lunge","intermediate","dumbbell","upper_legs","A unilateral lower-body exercise with dumbbells targeting quads and glutes through a stepping motion.",["Stand holding dumbbells at your sides.","Step forward with one foot and lower your back knee toward the floor.","Push off the front foot to return.","Alternate legs.","Repeat."],["Keep your torso upright.","Front knee should track over your toes."],{"start":"images/flat/db-lunge-start.webp","peak":"images/flat/db-lunge-peak.webp"},"strength"],["db-overhead-carry","Dumbbell Overhead Carry","intermediate","dumbbell","shoulders","A loaded walk with a single dumbbell locked out overhead, demanding shoulder stability and an upright trunk over every step.",["Clean or press a dumbbell to a locked-out position directly above your shoulder.","Push the arm all the way up so the elbow is straight and the biceps is close to your ear.","Brace your ribs down rather than letting your lower back arch to hold the weight up.","Walk forward with controlled strides, keeping the dumbbell stacked over your shoulder and hip.","Keep your eyes forward - tipping your head back to watch the weight drags your posture with it.","Carry for the desired distance, lower under control, then repeat with the other arm."],["Match the distance on both arms so the asymmetric load does not become an asymmetric adaptation.","A locked elbow is not optional. A soft elbow puts the whole load on the muscle instead of the skeleton and the set ends early.","If your ribs flare and your back arches, the weight is too heavy for your current overhead position - fix the position before adding load."],{"main":"images/flat/db-overhead-carry-main.webp"},"strength"],["db-preacher-curl","Dumbbell Preacher Curl","beginner","dumbbell","upper_arms","A biceps isolation curl performed with a dumbbell in each hand and the upper arms supported on a preacher bench. The pad locks the elbows in place, so the biceps do the work with almost no swing.",["Adjust the seat so the armpits rest against the top of the pad and the upper arms lie flat along it.","Hold a dumbbell in each hand with an underhand grip and let the arms hang down along the pad.","Curl both dumbbells up toward the shoulders without lifting the elbows off the pad.","Squeeze the biceps briefly at the top.","Lower the dumbbells slowly until the arms are almost fully extended, then repeat."],["Stop just short of full extension at the bottom to keep tension on the biceps and protect the elbows.","Keep the chest against the pad; leaning back lets the shoulders take over.","Lower the weights slowly; do not let them drop."],{"start":"images/flat/db-preacher-curl-start.webp","peak":"images/flat/db-preacher-curl-peak.webp"},"strength"],["db-pullover","Dumbbell Pullover","intermediate","dumbbell","chest","A compound movement targeting the lats and chest with a stretching motion.",["Lie on a flat bench with a dumbbell held above your chest, arms extended.","Lower the dumbbell behind your head in an arc, keeping slight bend in elbows.","Stretch until you feel tension in your lats and chest.","Pull the dumbbell back to the starting position.","Repeat."],["Cup one end of the dumbbell with both hands for a secure grip.","Avoid excessive arching in your lower back during the stretch.","Lower only as far as your shoulder mobility comfortably allows."],{"start":"images/flat/db-pullover-start.webp","peak":"images/flat/db-pullover-peak.webp"},"strength"],["db-reverse-curl","Dumbbell Reverse Curl","beginner","dumbbell","upper_arms","A curl variation with a pronated grip targeting the brachialis and forearm extensors.",["Hold dumbbells with an overhand grip at your sides.","Curl them up to shoulder height.","Lower under control.","Repeat."],["Keep wrists neutral throughout.","Controlled movement is key."],{"start":"images/flat/db-reverse-curl-start.webp","peak":"images/flat/db-reverse-curl-peak.webp"},"strength"],["db-reverse-wrist-curl","Dumbbell Reverse Wrist Curl","beginner","dumbbell","lower_arms","A dumbbell wrist curl with palms down, training the forearm extensors.",["Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms down.","Let both wrists drop, lowering the dumbbells toward the floor.","Lift the backs of your hands toward the ceiling by extending your wrists.","Squeeze at the top, then lower under control.","Repeat for the desired number of reps."],["Use a much lighter load than for a regular wrist curl.","Move only at the wrist.","Squeeze the back of the forearm at the top."],{"start":"images/flat/db-reverse-wrist-curl-start.webp","peak":"images/flat/db-reverse-wrist-curl-peak.webp"},"strength"],["db-shrug","Dumbbell Shrug","beginner","dumbbell","shoulders","A dumbbell shrug targeting the upper trapezius for neck and upper back thickness.",["Stand holding dumbbells at your sides.","Shrug your shoulders straight up as high as possible.","Hold briefly, then lower.","Repeat."],["Do not roll your shoulders.","Focus on squeezing the traps at the top."],{"start":"images/flat/db-shrug-start.webp","peak":"images/flat/db-shrug-peak.webp"},"strength"],["db-skull-crusher","Dumbbell Skull Crusher","intermediate","dumbbell","upper_arms","A lying triceps extension with dumbbells allowing independent arm movement.",["Lie on a flat bench holding dumbbells over your chest.","Lower the dumbbells toward the sides of your head.","Extend your arms back up.","Repeat."],["Keep elbows pointing toward the ceiling.","Use a controlled tempo."],{"start":"images/flat/db-skull-crusher-start.webp","peak":"images/flat/db-skull-crusher-peak.webp"},"strength"],["db-somersault-squat","Dumbbell Somersault Squat","intermediate","dumbbell","upper_legs","A single-arm reaching squat with a dumbbell that adds rotation and shoulder mobility to a squat pattern.",["Stand with feet shoulder-width holding a dumbbell in one hand at the shoulder.","Squat down while reaching the dumbbell forward and across the body.","Reach the bottom of the squat with the dumbbell extended past the opposite knee.","Drive through the heels to stand up, returning the dumbbell to the shoulder.","Complete reps per side, then switch."],["Move slowly through the rotation to keep the spine controlled.","Use a light dumbbell - the long lever taxes the shoulder.","Push the knees out to keep the squat track stable."],{"start":"images/flat/db-somersault-squat-start.webp","peak":"images/flat/db-somersault-squat-peak.webp"},"strength"],["db-squat","Dumbbell Squat","beginner","dumbbell","upper_legs","A squat loaded with a dumbbell in each hand at the sides, accessible without a barbell.",["Stand with feet shoulder-width, a dumbbell in each hand at the sides.","Brace the core and keep the chest up.","Squat down by hinging at the hips and bending the knees.","Descend until the thighs are parallel or below.","Drive through the heels to stand back up."],["Keep the chest up and the back flat throughout.","Push the knees out in line with the toes.","Use straps if grip becomes the limiting factor."],{"start":"images/flat/db-squat-start.webp","peak":"images/flat/db-squat-peak.webp"},"strength"],["db-step-up-to-balance","Dumbbell Step-Up to Balance","intermediate","dumbbell","upper_legs","A loaded version of the step-up to balance: holding a dumbbell in each hand, you step onto a low platform, drive the free knee up in front of you and stand tall on the working leg before stepping back down. The quadriceps and glutes lift the body and the weights while the hips and ankle keep you steady.",["Stand facing a low, stable step or bench with a dumbbell in each hand, arms hanging at your sides.","Place one foot flat on top of the step.","Press through the whole of the front foot and straighten that leg to lift your body onto the step.","As you rise, drive the other knee up in front of you until the thigh is about hip height.","Stand tall on the working leg and hold the knee-up position for a moment without leaning back.","Lower the free foot back to the floor under control, then step the working leg down as well and repeat; switch legs after the planned repetitions."],["Keep the weights hanging at your sides and still; swinging them or pulling them up with your arms takes the work away from the legs.","Keep your trunk upright and your hips level during the balance hold rather than tilting toward the lifted knee.","Start with light weights and a low step; add load only when you can hold the balance position without wobbling."],{"start":"images/flat/db-step-up-to-balance-start.webp","peak":"images/flat/db-step-up-to-balance-peak.webp"},"strength"],["db-sumo-squat","Dumbbell Sumo Squat","beginner","dumbbell","upper_legs","A wide-stance squat holding one dumbbell vertically between the legs, biasing the inner thighs and glutes.",["Stand with feet wider than shoulder-width, toes turned out about 30 degrees.","Hold one dumbbell vertically by its top end with both hands, letting it hang between your legs.","Brace the core and keep the chest up.","Bend at the hips and knees to sit straight down into a deep squat.","Drive through the heels to return to standing.","Repeat for the desired number of reps."],["Track the knees over the toes - do not let them cave in.","Keep the torso as upright as the hip mobility allows.","Let the dumbbell hang straight down; it should not touch the floor at the bottom."],{"start":"images/flat/db-sumo-squat-start.webp","peak":"images/flat/db-sumo-squat-peak.webp"},"strength"],["db-svend-press","Dumbbell Svend Press","beginner","dumbbell","chest","A standing chest exercise pressing two dumbbells together in front of the body, where the inward squeeze keeps the pecs under constant tension.",["Stand and press two dumbbells together horizontally at chest height.","Maintain the inward squeeze on the dumbbells throughout.","Press the dumbbells forward until your arms are almost straight.","Pull them back to the chest under control.","Repeat for the prescribed reps."],["The squeeze on the dumbbells is what makes the exercise - do not let them separate.","Use a light load - pec activation is the goal, not load.","Keep the elbows slightly bent at the lockout."],{"start":"images/flat/db-svend-press-start.webp","peak":"images/flat/db-svend-press-peak.webp"},"strength"],["dead-bug","Dead Bug","beginner","bodyweight","core","A supine core exercise coordinating opposite limb extension to train deep core stability.",["Lie on your back with arms extended toward the ceiling and knees at 90 degrees.","Lower your right arm and left leg toward the floor while keeping the lower back pressed down.","Return to start.","Repeat on the other side.","Alternate."],["Press your lower back into the floor at all times.","Move slowly."],{"start":"images/flat/dead-bug-start.webp","peak":"images/flat/dead-bug-peak.webp"},"strength"],["dead-bug-hold","Dead Bug Hold","beginner","bodyweight","core","The extended position of the dead bug held for time: lying on the back with one arm overhead and the opposite leg straightened just above the floor, keeping the lower back flat against the ground.",["Lie on your back with the arms pointing at the ceiling and the hips and knees bent to 90 degrees.","Press the lower back into the floor and keep it there for the whole set.","Extend one arm overhead and straighten the opposite leg until both hover just above the floor.","Hold that extended position for the prescribed time without letting the ribs flare or the back arch.","Return to the start and repeat with the other arm and leg."],["If the lower back lifts off the floor, keep the leg higher rather than reaching for the ground.","Breathe out slowly during the hold; holding your breath is what usually breaks the brace.","Keep the extended arm beside the ear, not out to the side."],{"main":"images/flat/dead-bug-hold-main.webp"},"strength"],["dead-hang","Dead Hang","beginner","pull_up_bar","back","A static hang from a pull-up bar with arms fully extended, primarily challenging grip and forearm strength.",["Grip a pull-up bar with palms facing away, shoulder-width apart.","Hang with your arms fully extended and feet off the ground.","Relax your shoulders and let your body hang.","Keep your core lightly engaged.","Hold for the desired duration."],["Build up your hold time gradually across sessions.","Breathe steadily throughout the hold instead of holding your breath.","Land softly with bent knees when you release the bar."],{"main":"images/flat/dead-hang-main.webp"},"strength"],["deadlift","Barbell Deadlift","intermediate","barbell","back","A full-body compound lift that primarily targets the posterior chain.",["Stand with feet hip-width apart, bar over mid-foot.","Hinge at the hips and grip the bar.","Brace your core and lift by extending hips and knees.","Stand tall at the top, then lower under control.","Repeat."],["Keep the bar close to your body.","Do not round your lower back."],{"start":"images/flat/deadlift-start.webp","peak":"images/flat/deadlift-peak.webp"},"strength"],["decline-bench-press","Decline Bench Press","intermediate","dumbbell","chest","A compound chest press on a decline bench with a dumbbell in each hand, targeting the lower pectorals.",["Set the bench to a decline angle. Lie down and secure your feet.","Hold a dumbbell in each hand above your chest, then lower them to the sides of your lower chest.","Press the dumbbells back up to the start.","Repeat."],["Keep your back flat on the bench.","Use a spotter when working with heavier loads."],{"start":"images/flat/decline-bench-press-start.webp","peak":"images/flat/decline-bench-press-peak.webp"},"strength"],["decline-bench-press-barbell","Decline Barbell Bench Press","intermediate","barbell","chest","A barbell compound press on a decline bench emphasizing the lower chest.",["Set the bench to a decline angle. Lie down and secure your feet.","Grip the bar slightly wider than shoulder-width.","Lower the bar to your lower chest, then press back up.","Repeat."],["Control the descent.","Keep elbows at about 45 degrees to the torso."],{"start":"images/flat/decline-bench-press-barbell-start.webp","peak":"images/flat/decline-bench-press-barbell-peak.webp"},"strength"],["decline-bench-press-ez-bar","Decline EZ-Bar Bench Press","intermediate","ez_bar","chest","A decline press using an EZ-bar for a wrist-friendly grip targeting the lower chest.",["Set the bench to a decline. Secure your feet and grip the EZ-bar.","Lower the bar to your lower chest.","Press back up explosively.","Repeat."],["The angled grip reduces wrist strain.","Keep your core braced."],{"start":"images/flat/decline-bench-press-ez-bar-start.webp","peak":"images/flat/decline-bench-press-ez-bar-peak.webp"},"strength"],["decline-crunch","Decline Crunch","intermediate","bodyweight","core","A crunch performed on a decline bench, increasing the range of motion and resistance on the abs.",["Secure your feet at the top of a decline bench.","Lie back with hands crossed on your chest or behind your head.","Crunch up by flexing your spine toward your knees.","Squeeze your abs at the top.","Lower under control and repeat."],["Curl your spine up rather than pulling on your neck.","Exhale as you crunch and squeeze the abs at the top.","Lower slowly instead of dropping back to the bench."],{"start":"images/flat/decline-crunch-start.webp","peak":"images/flat/decline-crunch-peak.webp"},"strength"],["decline-db-fly","Decline Dumbbell Fly","intermediate","dumbbell","chest","An isolation fly movement performed on a decline bench to emphasize the lower chest.",["Lie on a decline bench holding dumbbells above your chest.","With a slight elbow bend, lower the dumbbells wide to each side.","Squeeze the chest to bring them back up.","Repeat."],["Do not fully lock out the elbows.","Focus on the stretch at the bottom."],{"start":"images/flat/decline-db-fly-start.webp","peak":"images/flat/decline-db-fly-peak.webp"},"strength"],["decline-push-up","Decline Push-Up","intermediate","bodyweight","chest","A bodyweight push-up with feet elevated to increase upper chest and shoulder activation.",["Place your feet on an elevated surface and hands on the ground.","Lower your chest to the floor in a controlled manner.","Push back up to the start.","Repeat."],["Keep your body in a straight line.","The higher the elevation, the more upper chest is targeted."],{"start":"images/flat/decline-push-up-start.webp","peak":"images/flat/decline-push-up-peak.webp"},"strength"],["deep-squat-hold","Deep Squat Hold","beginner","bodyweight","upper_legs","A static bottom-position squat held with the hips below the knees, the heels flat and the hands clasped in front of the chest. It builds endurance and mobility in the hips, knees and ankles.",["Stand with the feet slightly wider than the shoulders and the toes turned out.","Clasp the hands in front of the chest and sit the hips down between the heels.","Lower until the hips are below the knees while the heels stay flat on the floor.","Keep the chest up and press the elbows against the knees to push them out.","Hold the position, breathing steadily, then stand up."],["Keep the heels flat; if they lift, place a small plate or wedge under them.","Push the knees out in line with the toes and keep the spine long.","Build the hold time gradually, standing to reset between sets."],{"main":"images/flat/deep-squat-hold-main.webp"},"strength"],["deficit-deadlift","Deficit Deadlift","advanced","barbell","back","A deadlift performed standing on a low platform, extending the range of motion to build strength off the floor.",["Stand on a small platform with a loaded barbell over your midfoot.","Hinge down and grip the bar just outside your knees.","Drive through your legs to stand up while keeping the bar close.","Lock out your hips and knees at the top.","Lower under control and repeat."],["Keep your back flat; the extra depth makes rounding more likely.","Use less weight than your conventional deadlift to maintain positioning.","Take the slack out of the bar before initiating the pull."],{"start":"images/flat/deficit-deadlift-start.webp","peak":"images/flat/deficit-deadlift-peak.webp"},"strength"],["deficit-push-ups","Deficit Push Ups","advanced","bodyweight","chest","A push-up variation with hands on raised supports, lowering the chest below hand level for a greater range of motion.",["Place your hands on two elevated surfaces like parallettes or blocks.","Assume a plank position with hands under your shoulders.","Lower your chest below the level of your hands.","Press back up to extend your arms.","Repeat for the desired number of reps."],["Avoid letting your hips sag during the deep stretch.","Work within a pain-free depth and increase it gradually.","Keep your elbows tracking back rather than flaring wide."],{"start":"images/flat/deficit-push-ups-start.webp","peak":"images/flat/deficit-push-ups-peak.webp"},"strength"],["diamond-push-ups","Diamond Push Ups","intermediate","bodyweight","chest","A close-hand push-up with thumbs and index fingers forming a diamond, shifting the emphasis onto the triceps.",["Assume a push-up position with hands close together forming a diamond.","Keep your elbows tucked close to your sides.","Lower your chest toward your hands.","Press back up to extend your arms.","Repeat for the desired number of reps."],["Keep your elbows tracking back along your sides, not flared out.","Hold your body in a rigid straight line from head to heels.","Lower with control until your chest reaches your hands."],{"start":"images/flat/diamond-push-ups-start.webp","peak":"images/flat/diamond-push-ups-peak.webp"},"strength"],["dips","Chest Dips","intermediate","dip_station","chest","A compound bodyweight exercise targeting the lower chest and triceps.",["Grip parallel dip bars and lift yourself to the top position with arms locked.","Lean your torso forward slightly.","Lower your body by bending your elbows until shoulders are below elbows.","Press back up to the starting position.","Repeat."],["Keep your shoulders pulled down away from your ears.","Bend your knees and cross your ankles to minimize swinging.","Stop the descent if you feel pinching in your shoulders."],{"start":"images/flat/dips-start.webp","peak":"images/flat/dips-peak.webp"},"strength"],["dolphin-pose","Dolphin Pose","intermediate","bodyweight","shoulders","An inverted V held on the forearms: the hips lift towards the ceiling while the shoulders take the load, which makes it the standard preparation for forearm inversions.",["Kneel and place the forearms on the floor shoulder-width apart with the elbows under the shoulders.","Tuck the toes and lift the hips up and back until the body forms an inverted V.","Press the forearms down and draw the shoulders away from the ears; let the heels stay high.","Hold the position for the prescribed time, keeping the neck relaxed between the arms.","Lower the knees to the floor to come out."],["Keep the elbows from sliding apart; a strap around the upper arms holds the width.","Bend the knees generously so the spine stays long instead of chasing straight legs.","Walk the feet slightly closer to the elbows to take more weight into the shoulders."],{"main":"images/flat/dolphin-pose-main.webp"},"strength"],["donkey-calf-raise","Donkey Calf Raise","intermediate","bodyweight","lower_legs","A bent-over calf raise that maximizes calf stretch by hinging at the hips.",["Bend at the hips and place your hands on the floor in front of you, hips high and legs nearly straight.","Set your feet hip-width apart with your weight on the balls of the feet.","Lower your heels as far as they go (below the edge if you stand on a raised platform) for a full stretch.","Drive up onto the toes as high as possible, squeezing the calves.","Lower under control to a deep stretch."],["Pause briefly at the top to maximize the contraction.","Use a slow eccentric for full stretch.","Add a partner or weight on the lower back for resistance."],{"start":"images/flat/donkey-calf-raise-start.webp","peak":"images/flat/donkey-calf-raise-peak.webp"},"strength"],["doorway-chest-stretch","Doorway Chest Stretch","beginner","bodyweight","chest","An open-arm stretch that lengthens the chest and front shoulders by drawing the arms back.",["Stand tall and raise your arms into a goalpost position.","Bend your elbows ninety degrees, forearms vertical.","Draw your elbows back and squeeze your shoulder blades.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your ribs down and avoid arching your back.","Stretch to mild tension, never to pain."],{"main":"images/flat/doorway-chest-stretch-main.webp"},"stretching"],["double-db-kickstand-deadlift","Double Dumbbell Kickstand Deadlift","intermediate","dumbbell","back","A staggered-stance hip hinge with two dumbbells that distributes load primarily through the front leg while the back foot lightly grounds for balance.",["Step one foot back so only the toes touch the floor, and hinge at the hips with a flat back.","Hold a dumbbell in each hand, low on either side of the front shin.","Drive through the front heel and extend the hips to stand tall, the dumbbells at your sides.","Keep most of your weight on the front foot throughout.","Hinge back down, lowering both dumbbells toward the floor with a flat back. Switch sides after all reps."],["Keep the dumbbells close to the legs throughout the movement.","Stop when you feel a stretch in the front hamstring.","Complete all reps on one side before switching."],{"start":"images/flat/double-db-kickstand-deadlift-start.webp","peak":"images/flat/double-db-kickstand-deadlift-peak.webp"},"strength"],["double-db-overhead-carry","Double Dumbbell Overhead Carry","intermediate","dumbbell","shoulders","A loaded walk with a dumbbell locked out above each shoulder, doubling the overhead load and removing the free arm that would otherwise help you balance.",["Clean or press a dumbbell to lockout above each shoulder.","Straighten both elbows fully and keep reaching up into the weights so the shoulders stay active, without letting the dumbbells sink down onto them.","Brace hard and keep your ribs down - with both arms overhead the temptation to arch is much stronger.","Walk forward with short, deliberate strides, keeping both dumbbells stacked over your shoulders.","Keep breathing shallowly and steadily instead of holding your breath for the whole carry.","Carry for the desired distance, then lower both weights under control."],["Start lighter than your single-arm carry weight per hand. Two arms overhead is not twice as easy, it is twice as much to stabilise.","Have a plan for bailing out before you start, and carry where you can drop the weights safely.","Short distances done well beat long ones done bent. Stop the set when your ribs start to flare, not when your shoulders give out."],{"main":"images/flat/double-db-overhead-carry-main.webp"},"strength"],["double-kettlebell-bicep-curl","Double Kettlebell Bicep Curl","beginner","kettlebell","upper_arms","A standing biceps curl with one kettlebell in each hand, held by the handle. The offset mass at the bottom of the bell adds a mild grip and stability challenge.",["Stand holding a kettlebell in each hand by the handle, palms facing forward.","Keep the elbows tucked to the sides and the bells hanging at arm length.","Curl both kettlebells up toward the shoulders by flexing the elbows.","Squeeze the biceps at the top, then lower under control to the starting position.","Repeat for the recommended number of repetitions."],["Do not let the bells swing - control the eccentric.","Elbows stay pinned to the sides; no shoulder flexion.","Grip hard throughout; the bell wants to pull the wrist into extension."],{"start":"images/flat/double-kettlebell-bicep-curl-start.webp","peak":"images/flat/double-kettlebell-bicep-curl-peak.webp"},"strength"],["double-kettlebell-clean","Double Kettlebell Clean","advanced","kettlebell","shoulders","An explosive hip hinge that racks two kettlebells to the shoulders simultaneously, the foundation for double-KB pressing and jerking.",["Stand with two kettlebells on the floor between your feet, handles angled slightly inward.","Hinge at the hips, grip the handles, and hike the kettlebells back between the legs.","Explosively extend the hips to drive the kettlebells up along the body.","As they reach chest height, spear your hands through the handles to catch them at the rack position on the shoulders.","Lower back to the hang by hinging at the hips and guiding the bells between the legs.","Repeat for the recommended number of repetitions."],["Spear the hands through - don't let the kettlebells flip over and bang the wrists.","Drive with the hips; the arms only guide the path."],{"start":"images/flat/double-kettlebell-clean-start.webp","peak":"images/flat/double-kettlebell-clean-peak.webp"},"strength"],["double-kettlebell-clean-and-press","Double Kettlebell Clean and Press","advanced","kettlebell","shoulders","A full-body power exercise that cleans two kettlebells from the floor to the racked position at the shoulders and then presses both overhead to lockout in one continuous sequence.",["Stand with two kettlebells on the floor between your feet, feet about hip-width apart, and hinge at the hips to grip one handle in each hand.","Drive through your legs and extend your hips explosively to pull both kettlebells up, then rotate your elbows under and catch the bells in the racked position at the front of your shoulders.","Brace your core and press both kettlebells overhead until your arms are fully locked out.","Lower the kettlebells back to the racked position, then down to the floor under control.","Repeat for the desired number of reps."],["Keep the kettlebells close to your body during the clean and punch your hands around and through the handles as you catch them, so the bells settle on your forearms instead of banging into them.","Use a slight dip-drive from the legs and hips to start the press, then finish with the shoulders - keep your core tight so you do not lean back under the load.","At lockout keep your wrists straight and the kettlebells stacked over your elbows and shoulders, with your head returning to a neutral position between the bells."],{"start":"images/flat/double-kettlebell-clean-and-press-start.webp","peak":"images/flat/double-kettlebell-clean-and-press-peak.webp"},"strength"],["double-kettlebell-dead-clean","Double Kettlebell Dead Clean","intermediate","kettlebell","full_body","An explosive kettlebell movement cleaning two bells from the floor to the rack position, with each rep starting from a dead stop.",["Set two kettlebells on the floor between your feet.","Hinge down and grip both handles.","Drive explosively through your legs and hips.","Pull the kettlebells up and rotate them to the rack position.","Lower them back to the floor and repeat."],["Guide the bells close to your body as they travel up.","Keep your wrists straight as the bells settle into the rack.","Reset a tight hinge position before every rep."],{"start":"images/flat/double-kettlebell-dead-clean-start.webp","peak":"images/flat/double-kettlebell-dead-clean-peak.webp"},"olympic"],["double-kettlebell-dead-split-snatch","Double Kettlebell Dead Split Snatch","intermediate","kettlebell","full_body","An Olympic-style kettlebell lift snatching two bells from the floor to overhead, caught in a split stance.",["Set two kettlebells on the floor between your feet.","Hinge down and grip both handles firmly.","Explosively pull the kettlebells overhead in one motion.","Drop into a split stance to catch them at lockout.","Recover by stepping feet back together."],["Punch up through the handles to achieve a stable overhead lockout.","Keep your front knee tracking over your foot in the split.","Stay tall through your torso as you drop under the bells."],{"start":"images/flat/double-kettlebell-dead-split-snatch-start.webp","peak":"images/flat/double-kettlebell-dead-split-snatch-peak.webp"},"olympic"],["double-kettlebell-jerk","Double Kettlebell Jerk","advanced","kettlebell","shoulders","An overhead lift using a double dip-drive to launch two kettlebells from the rack to lockout, the hallmark lift of kettlebell sport.",["Start with two kettlebells racked on the shoulders, elbows resting on the hips.","Perform a short dip at the knees, then explosively extend the legs to drive the kettlebells up.","As the bells rise, perform a second dip under them by bending the knees again.","Catch the kettlebells overhead with arms locked out, then stand fully upright.","Lower them back to the rack under control and repeat."],["The jerk is two dips, not one - the second dip is what lets you lock out with light arms.","Breathe on every rep, exhaling on each dip and drive, instead of holding your breath through the set."],{"start":"images/flat/double-kettlebell-jerk-start.webp","peak":"images/flat/double-kettlebell-jerk-peak.webp"},"strength"],["double-kettlebell-overhead-carry","Double Kettlebell Overhead Carry","advanced","kettlebell","shoulders","A loaded walk with a kettlebell locked out above each shoulder - the hardest of the carries to keep still, combining the offset mass of the bells with double the overhead load.",["Clean two kettlebells to the rack, then press or push press both to lockout overhead.","Straighten both elbows and settle each bell behind and above its wrist, with your wrists straight.","Pull your ribs down and brace hard before the first step; with both bells overhead there is nothing to counterbalance with.","Walk forward with short, controlled strides, keeping both bells stacked over your shoulders.","Keep looking straight ahead and breathe steadily through the carry.","Cover the desired distance, then lower both bells to the rack and down under control."],["Earn this one. Be comfortable with the single-bell overhead carry on both sides before loading two.","Only do it where you can safely drop both bells, and know which way you will step if you have to.","Distance should be short and posture perfect. The moment your back arches or a wrist folds, the set is finished."],{"main":"images/flat/double-kettlebell-overhead-carry-main.webp"},"strength"],["double-kettlebell-overhead-press","Double Kettlebell Overhead Press","intermediate","kettlebell","shoulders","A strict overhead press with two kettlebells from the rack position, demanding shoulder strength and a braced core.",["Clean two kettlebells to the rack position at your shoulders.","Stand tall with feet hip-width apart.","Press both kettlebells straight overhead.","Lock out your arms at the top.","Lower back to the rack position and repeat."],["Squeeze your glutes and brace your abs before each press.","Keep your forearms vertical as you drive the bells up.","Avoid flaring your ribs or arching your lower back at lockout."],{"start":"images/flat/double-kettlebell-overhead-press-start.webp","peak":"images/flat/double-kettlebell-overhead-press-peak.webp"},"strength"],["double-kettlebell-push-press","Double Kettlebell Push Press","intermediate","kettlebell","shoulders","A push press with two kettlebells in the rack. The leg drive (single dip) lets you launch heavier loads overhead than a strict press - the middle tier between strict OHP and full jerk.",["Stand with two kettlebells racked at the shoulders, elbows down and tucked.","Feet shoulder-width, core braced.","Dip the knees slightly while keeping the torso vertical.","Explosively extend the legs and press both bells overhead in one motion.","Lock out with the bells over the mid-foot.","Lower back to the rack under control.","Repeat for the recommended number of repetitions."],["Only ONE dip - if you re-bend the knees under the bell, that is a jerk.","Drive from the legs, the arms finish.","The torso stays vertical throughout; no lean."],{"start":"images/flat/double-kettlebell-push-press-start.webp","peak":"images/flat/double-kettlebell-push-press-peak.webp"},"strength"],["double-kettlebell-rear-delt-row","Double Kettlebell Rear Delt Row","intermediate","kettlebell","shoulders","A bent-over row with a kettlebell in each hand and the elbows driven out wide of the torso, which shifts the work off the lats and onto the posterior deltoids and upper back.",["Stand a kettlebell just outside each foot with your feet about hip-width apart.","Hinge at the hips with a flat back until your torso is close to parallel with the floor, letting your knees bend slightly.","Take both handles with an overhand grip and let your arms hang straight down from your shoulders.","Row both bells up by driving your elbows out to the sides, away from your ribs rather than back along them.","Stop when your upper arms are roughly in line with your shoulders, and squeeze your shoulder blades together.","Lower the bells under control until your arms hang straight again, and repeat for the desired reps."],["The wide elbow is the whole exercise. Let it drift in against your ribs and you are doing an ordinary double kettlebell row, training your lats instead of your rear delts.","Use less weight than you would for a normal row. The flared elbow is a long lever and the rear delts are a far smaller engine than the lats.","Hold the hinge angle steady. Standing up as you pull hands the work to the traps and lower back and shortens the range where the rear delts actually work."],{"start":"images/flat/double-kettlebell-rear-delt-row-start.webp","peak":"images/flat/double-kettlebell-rear-delt-row-peak.webp"},"strength"],["double-kettlebell-row","Double Kettlebell Row","intermediate","kettlebell","back","A bent-over rowing exercise pulling two kettlebells to the hips, strengthening the lats and upper back.",["Hold a kettlebell in each hand and hinge forward at the hips.","Let your arms hang straight down from your shoulders.","Row both kettlebells to your hips by driving elbows back.","Squeeze your shoulder blades at the top.","Lower under control and repeat."],["Hold your hinge angle steady; avoid standing up as you pull.","Keep your neck neutral by gazing at the floor ahead.","Brace your core to protect your lower back throughout."],{"start":"images/flat/double-kettlebell-row-start.webp","peak":"images/flat/double-kettlebell-row-peak.webp"},"strength"],["double-kettlebell-split-jerk","Double Kettlebell Split Jerk","intermediate","kettlebell","full_body","An explosive overhead lift driving two kettlebells from the rack to lockout, caught in a split stance.",["Clean two kettlebells to the rack position at your shoulders.","Dip slightly by bending your knees.","Drive the kettlebells overhead explosively.","Split your legs to catch them with locked arms.","Recover by stepping feet back together."],["Keep your heels down during the dip to maintain power.","Time the split so your arms lock as your feet land.","Drive with your legs; your arms mainly guide the bells."],{"start":"images/flat/double-kettlebell-split-jerk-start.webp","peak":"images/flat/double-kettlebell-split-jerk-peak.webp"},"olympic"],["double-kettlebell-swing-snatch","Double Kettlebell Swing Snatch","intermediate","kettlebell","full_body","A ballistic kettlebell exercise swinging two bells from between the legs to an overhead lockout in one motion.",["Stand with feet shoulder-width apart holding two kettlebells.","Hinge at the hips to swing the bells between your legs.","Explosively drive your hips forward to swing the bells up.","Punch through to catch both kettlebells overhead with locked arms.","Lower under control and repeat."],["Keep your arms relaxed and let your hips generate the power.","Let the bells roll smoothly around your wrists rather than flipping over.","Maintain a flat back during every backswing."],{"start":"images/flat/double-kettlebell-swing-snatch-start.webp","peak":"images/flat/double-kettlebell-swing-snatch-peak.webp"},"olympic"],["downward-dog","Downward-Facing Dog","beginner","bodyweight","full_body","An inverted-V stretch that lengthens the hamstrings, calves, shoulders and back at once.",["Start on all fours with hands slightly ahead of your shoulders.","Tuck your toes and lift your hips up and back.","Straighten your legs and press your heels toward the floor.","Hold for 20 to 30 seconds, breathing steadily."],["Bend your knees if your lower back rounds.","Press the floor away to lengthen your spine."],{"main":"images/flat/downward-dog-main.webp"},"stretching"],["downward-dog-knee-tuck","Downward Dog Knee Tuck","intermediate","bodyweight","core","A moving core drill held in downward dog: the hips stay high while one knee is drawn in under the chest and sent back to the start, alternating sides. The shoulders support the whole set, so the trunk works without the low-hip position of a plank.",["Set up in downward dog with the hands shoulder-width apart and the hips high.","Press the floor away and brace the trunk so the lower back stays long.","Draw one knee in towards the chest, rounding the upper back slightly as it comes in.","Extend the leg back to the starting position under control.","Repeat with the other leg and keep alternating for the desired number of repetitions."],["Keep the hips high; letting them drop turns this into a mountain climber.","Draw the knee in with the abdominals rather than by hopping off the standing foot.","Push the shoulders away from the ears so the upper body does not sink between the arms."],{"start":"images/flat/downward-dog-knee-tuck-start.webp","peak":"images/flat/downward-dog-knee-tuck-peak.webp"},"strength"],["downward-dog-pedal","Downward Dog Pedal","beginner","bodyweight","lower_legs","A warm-up performed in downward dog: the knees bend one at a time so each heel presses towards the floor in turn, taking the calf and the back of the ankle through a moving stretch instead of a static hold.",["Set up in downward dog with the hands shoulder-width apart and the hips high.","Bend one knee and let that heel lift while the opposite heel presses down towards the floor.","Switch sides smoothly, as if pedalling, keeping the hips high throughout.","Keep the hands pressing evenly so the shoulders stay stable.","Continue alternating for the desired number of repetitions or time."],["Keep the hips high; the point is the calves, not a deeper fold.","Press the whole hand into the floor so the wrists do not take all the load.","Move slowly enough to feel each side lengthen rather than bouncing."],{"start":"images/flat/downward-dog-pedal-start.webp","peak":"images/flat/downward-dog-pedal-peak.webp"},"stretching"],["downward-dog-to-knee-drive","Downward Dog to Knee Drive","intermediate","bodyweight","core","From three-legged dog the lifted leg folds forward so the knee travels towards the elbow or the nose, then extends back up. The shoulders hold the position while the trunk does the folding, one side at a time.",["Set up in downward dog and lift one leg behind you into three-legged dog.","Press both hands down and shift the weight slightly forward.","Round the upper back and drive that knee forward towards the elbow or the nose.","Extend the leg back up to three-legged dog under control.","Finish the repetitions on that side and repeat on the other."],["Let the upper back round as the knee comes in; a flat back stops the knee short.","Keep the shoulders over the wrists as you shift forward rather than collapsing past them.","Lift the leg only as high as the hips stay level on the way back out."],{"start":"images/flat/downward-dog-to-knee-drive-start.webp","peak":"images/flat/downward-dog-to-knee-drive-peak.webp"},"strength"],["downward-dog-to-low-lunge","Downward Dog to Low Lunge","beginner","bodyweight","upper_legs","The standard step-through: from downward dog one foot travels forward between the hands into a low lunge, then returns. It opens the hip flexor of the trailing leg and rehearses the transition used throughout flow practice.",["Start in downward dog with the hands shoulder-width apart.","Shift the weight forward and step one foot up between the hands.","Lower the back knee to the floor and sink the hips into a low lunge.","Press back through the hands, lift the back knee and step the front foot back to downward dog.","Repeat on the other side and keep alternating."],["Step the foot all the way to the hands rather than landing short and shuffling.","Pad the back knee with a folded mat if the floor is hard.","Keep the front knee above the ankle when the hips sink."],{"start":"images/flat/downward-dog-to-low-lunge-start.webp","peak":"images/flat/downward-dog-to-low-lunge-peak.webp"},"stretching"],["downward-dog-to-plank","Downward Dog to Plank","intermediate","bodyweight","shoulders","A moving transition between downward dog and a high plank: the hips travel from high to level and back, so the shoulders and trunk work through a full range instead of holding one position.",["Set up in downward dog with the hips high and the hands shoulder-width apart.","Shift the weight forward and lower the hips until the body forms a straight line in a high plank.","Hold the plank for a moment with the ribs down and the glutes engaged.","Press the floor away and lift the hips back up into downward dog.","Continue alternating for the desired number of repetitions."],["Move the hips, not the hands; the palms stay in the same place the whole set.","Keep the shoulders pushing away from the ears in both positions.","Slow the transition down if the lower back sags on the way into the plank."],{"start":"images/flat/downward-dog-to-plank-start.webp","peak":"images/flat/downward-dog-to-plank-peak.webp"},"strength"],["downward-dog-to-upward-dog","Downward Dog to Upward Dog","intermediate","bodyweight","shoulders","The vinyasa transition: the body travels from downward dog forward into upward dog and back, alternating between a shoulder-loaded inverted V and an open-chested backbend.",["Start in downward dog with the hips high and the hands shoulder-width apart.","Shift forward through plank and lower slightly, then press the chest through into upward dog with the thighs off the floor.","Draw the shoulders back and down and keep the neck long.","Tuck the toes, press the floor away and lift the hips back into downward dog.","Continue moving between the two positions for the desired number of repetitions."],["Move the hips, not the hands; the palms stay planted the whole set.","Press the tops of the feet down in upward dog so the thighs actually lift.","Slow down through the middle of the transition rather than swinging between the ends."],{"start":"images/flat/downward-dog-to-upward-dog-start.webp","peak":"images/flat/downward-dog-to-upward-dog-peak.webp"},"strength"],["drag-curl","Drag Curl","intermediate","barbell","upper_arms","A barbell curl where the elbows travel backward and the bar drags up the torso, eliminating front-delt assistance and emphasizing the long head of the biceps.",["Stand holding a barbell with an underhand grip, hands shoulder-width apart.","Start with the bar at the thighs and elbows at the sides.","Curl the bar by sliding (dragging) it straight up along your body.","As the bar rises, let the elbows travel backward so the bar stays in contact with your torso.","Stop when the bar reaches mid-chest; the biceps will be fully shortened.","Lower under control along the same path and repeat."],["Use significantly less weight than a standard curl - the altered mechanics make it much harder.","The bar should never move away from the body."],{"start":"images/flat/drag-curl-start.webp","peak":"images/flat/drag-curl-peak.webp"},"strength"],["dragon-flag","Dragon Flag","advanced","bodyweight","core","A demanding core hold performed on a bench: gripping behind your head, you raise your entire body into a rigid straight line supported only by your upper back.",["Lie on a bench and grip it firmly behind your head.","Raise your body up so only your upper back stays on the bench.","Keep your body rigid in a straight line.","Lower your body under control until nearly horizontal.","Raise back up and repeat."],["Keep your body rigid from shoulders to toes and move only at the shoulders.","Lower as slowly as you can - the eccentric is the exercise.","Start with tucked or single-leg progressions before the full flag."],{"start":"images/flat/dragon-flag-start.webp","peak":"images/flat/dragon-flag-peak.webp"},"strength"],["dumbbell-bench-pull","Dumbbell Bench Pull","intermediate","dumbbell","back","A prone rowing movement on a bench for strict upper back work.",["Lie face down on an incline bench holding dumbbells.","Let your arms hang straight down.","Pull the dumbbells up toward your chest, squeezing your shoulder blades.","Lower with control.","Repeat."],["Keep your chest glued to the bench throughout the pull.","Drive your elbows up and back rather than curling the weight.","Let your shoulder blades protract fully at the bottom for full range."],{"start":"images/flat/dumbbell-bench-pull-start.webp","peak":"images/flat/dumbbell-bench-pull-peak.webp"},"strength"],["dumbbell-calf-raise","Dumbbell Calf Raise","intermediate","dumbbell","lower_legs","A weighted calf raise holding dumbbells at the sides, done on the floor or on an elevated edge for a fuller stretch.",["Stand holding a dumbbell in each hand at your sides.","Set your feet flat on the floor, or place the balls of your feet on a raised surface with heels hanging off for a deeper stretch.","Press through the balls of your feet to raise your heels as high as possible.","Squeeze your calves at the top of the movement.","Lower your heels back to the floor (or below the platform) to stretch the calves.","Repeat for the desired number of reps."],["Avoid bouncing out of the bottom stretch position.","Keep your legs straight but not locked throughout.","Prevent your ankles from rolling outward as you rise."],{"start":"images/flat/dumbbell-calf-raise-start.webp","peak":"images/flat/dumbbell-calf-raise-peak.webp"},"strength"],["dumbbell-clean-and-press","Dumbbell Clean and Press","intermediate","dumbbell","full_body","A full-body power exercise in which two dumbbells are cleaned to the shoulders and then pressed overhead in one flowing sequence. It builds explosive hip power and strong shoulders and triceps.",["Stand with the feet hip-width apart and a dumbbell in each hand, hanging at your sides.","Hinge at the hips and bend the knees slightly to lower the dumbbells to just below the knees.","Explosively extend the hips and knees and shrug to pull the dumbbells up to the shoulders, catching them with the elbows forward.","Dip slightly at the knees and drive the dumbbells straight overhead until the arms are locked out.","Lower the dumbbells back to the shoulders, then to your sides, under control.","Repeat for the desired number of repetitions."],["Let the legs and hips produce the power; the arms only guide the dumbbells.","Keep the dumbbells close to the body on the way up.","Finish each press with the ribs down and the glutes tight."],{"start":"images/flat/dumbbell-clean-and-press-start.webp","peak":"images/flat/dumbbell-clean-and-press-peak.webp"},"olympic"],["dumbbell-curl-and-press","Dumbbell Curl and Press","intermediate","dumbbell","shoulders","A standing compound movement that links a dumbbell curl to an overhead press: the weights are curled to the shoulders and then pressed straight overhead before being lowered. It works the biceps and shoulders in one smooth repetition.",["Stand tall with the feet hip-width apart, holding a dumbbell in each hand at your sides with the palms facing forward.","Curl both dumbbells up to the shoulders, keeping the elbows close to the body.","Press the dumbbells overhead until the arms are fully extended.","Lower the dumbbells back to the shoulders under control.","Lower them to your sides with a controlled reverse curl, then repeat."],["Brace the abdominals and keep the ribs down so the press does not turn into a back bend.","Do not swing the weights up with the legs; use a load you can curl strictly.","Press in a slight arc so the dumbbells finish directly over the shoulders."],{"start":"images/flat/dumbbell-curl-and-press-start.webp","peak":"images/flat/dumbbell-curl-and-press-peak.webp"},"strength"],["dumbbell-deadlift","Dumbbell Deadlift","intermediate","dumbbell","back","A deadlift variation using a pair of dumbbells, training the glutes, hamstrings, and lower back.",["Stand with feet hip-width apart, hinge at the hips with a flat back and hold the dumbbells low, at shin height.","Brace your core and keep the dumbbells close to your legs.","Drive through your heels and extend your hips to stand up tall.","Extend your hips fully at the top without hyperextending your lower back.","Hinge back down, lowering the dumbbells along your legs to your shins.","Repeat for the desired number of reps."],["Brace your core before each rep to keep your spine stable.","Balance your weight over midfoot rather than your toes.","Keep your neck in line with your spine rather than looking up."],{"start":"images/flat/dumbbell-deadlift-start.webp","peak":"images/flat/dumbbell-deadlift-peak.webp"},"strength"],["dumbbell-face-pull","Dumbbell Face Pull","intermediate","dumbbell","back","A rear-delt and upper-back exercise performed by pulling dumbbells toward the face with a wide elbow path.",["Stand or sit holding a dumbbell in each hand with arms extended forward.","Bend your elbows and pull the dumbbells toward your face.","Flare your elbows out wide to shoulder height.","Squeeze your rear delts and upper back at the peak.","Lower the dumbbells back under control.","Repeat for the desired number of reps."],["Lead with your elbows, not your hands.","Keep your upper arms roughly parallel to the floor.","Use a lighter weight to prioritize form over load."],{"start":"images/flat/dumbbell-face-pull-start.webp","peak":"images/flat/dumbbell-face-pull-peak.webp"},"strength"],["dumbbell-farmers-walk","Dumbbell Farmer's Walk","beginner","dumbbell","full_body","This full-body exercise involves walking while holding heavy dumbbells, effectively building grip strength, core stability, and overall muscular endurance.",["Stand tall with a dumbbell in each hand, arms extended at your sides.","Retract your shoulder blades and brace your core, maintaining a neutral spine.","Walk slowly and deliberately for a set distance or duration, taking short, controlled steps.","Keep your chest up and avoid leaning to one side as you walk.","Focus on maintaining a strong, stable posture throughout the movement."],["Use the heaviest dumbbells you can control without compromising form.","Breathe deeply and rhythmically to maintain core tension.","Imagine you are balancing a glass of water on your head."],{"main":"images/flat/dumbbell-farmers-walk-main.webp"},"strength"],["dumbbell-floor-press","Dumbbell Floor Press","intermediate","dumbbell","chest","A dumbbell press performed lying on the floor, restricting the range of motion for joint-friendly pressing.",["Lie on the floor with a dumbbell in each hand at chest level.","Press the dumbbells upward until arms are extended.","Lower under control until elbows touch the floor.","Repeat."],["The floor limits shoulder strain at the bottom.","Keep wrists stacked over elbows."],{"start":"images/flat/dumbbell-floor-press-start.webp","peak":"images/flat/dumbbell-floor-press-peak.webp"},"strength"],["dumbbell-front-raise","Dumbbell Front Raise","beginner","dumbbell","shoulders","An isolation exercise targeting the anterior deltoid through a forward raise motion.",["Stand with dumbbells at your sides, palms facing your thighs.","Raise one or both dumbbells forward to shoulder height.","Lower under control.","Repeat."],["Avoid using momentum.","Slight elbow bend reduces joint stress."],{"start":"images/flat/dumbbell-front-raise-start.webp","peak":"images/flat/dumbbell-front-raise-peak.webp"},"strength"],["dumbbell-front-squat","Dumbbell Front Squat","intermediate","dumbbell","upper_legs","A squat holding dumbbells racked at the shoulders, keeping the torso upright and emphasizing the quads.",["Hold a dumbbell in each hand resting on top of your shoulders.","Keep your elbows high and torso upright.","Lower your hips by bending knees until thighs are parallel to the floor.","Drive through your heels to stand back up.","Maintain a neutral spine throughout.","Repeat for the desired number of reps."],["Keep your elbows high so the dumbbells stay racked on your shoulders.","Sit down between your hips rather than folding forward.","Drive through the whole foot and keep your heels down."],{"start":"images/flat/dumbbell-front-squat-start.webp","peak":"images/flat/dumbbell-front-squat-peak.webp"},"strength"],["dumbbell-hip-thrust","Dumbbell Hip Thrust","beginner","dumbbell","upper_legs","The Dumbbell Hip Thrust is a highly effective compound exercise for building strong glutes and hamstrings, performed by thrusting the hips upwards with a dumbbell across the pelvis.",["Sit on the floor with your upper back against a bench, knees bent, feet flat, and a dumbbell across your hips.","Brace your core and drive through your heels, lifting your hips off the floor until your body forms a straight line from shoulders to knees.","Squeeze your glutes powerfully at the top of the movement, ensuring full hip extension.","Slowly lower your hips back down to the starting position with control, maintaining tension.","Repeat for the desired number of repetitions."],["Keep your chin tucked towards your chest to maintain a neutral spine throughout the movement.","Focus on driving through your heels to maximize glute activation.","Control the eccentric (lowering) phase to enhance muscle growth.","Use a pad or towel under the dumbbell for comfort."],{"start":"images/flat/dumbbell-hip-thrust-start.webp","peak":"images/flat/dumbbell-hip-thrust-peak.webp"},"strength"],["dumbbell-pistol-squat","Dumbbell Pistol Squat","advanced","dumbbell","upper_legs","The Dumbbell Pistol Squat is an advanced single-leg squat variation that builds significant lower body strength, balance, and mobility, primarily targeting the quadriceps and glutes.",["Stand tall, holding a dumbbell in each hand with your arms hanging at your sides.","Lift one leg straight out in front of you, keeping it extended throughout the movement.","Lower your body by bending the knee of your standing leg, keeping your chest up and back straight.","Descend until your glutes are close to your heel or your thigh is parallel to the floor, maintaining balance.","Push through your heel to return to the starting position, extending your standing leg fully.","Complete all reps on one side, then switch legs and repeat for the other side per set."],["Start with bodyweight pistol squats to master the movement pattern before adding dumbbells.","Let the dumbbells hang straight down at your sides and keep your chest up to stay balanced over the working foot.","Focus on controlling the eccentric (lowering) phase to improve stability and strength.","Elevate your heel slightly on a small plate if ankle mobility is a limiting factor."],{"start":"images/flat/dumbbell-pistol-squat-start.webp","peak":"images/flat/dumbbell-pistol-squat-peak.webp"},"strength"],["dumbbell-push-press","Dumbbell Push Press","intermediate","dumbbell","shoulders","A compound overhead press that uses a leg drive to initiate momentum and develop shoulder and triceps power.",["Stand holding dumbbells at shoulder height with palms facing forward.","Slightly bend your knees into a quarter squat.","Drive through your legs to generate momentum, then press the dumbbells overhead.","Lock out your arms at the top.","Lower the dumbbells back to shoulder height with control."],["Use a shallow dip - this is not a full squat.","Drive the heels into the floor to initiate the press.","Keep your core braced to protect the lower back."],{"start":"images/flat/dumbbell-push-press-start.webp","peak":"images/flat/dumbbell-push-press-peak.webp"},"strength"],["dumbbell-reverse-fly","Dumbbell Reverse Fly","intermediate","dumbbell","shoulders","A hinged isolation exercise raising dumbbells out to the sides, targeting the rear deltoids and upper back.",["Hinge forward at the hips holding dumbbells with arms hanging down.","Keep your back flat and knees slightly bent.","Raise the dumbbells out to the sides until level with your shoulders.","Squeeze your shoulder blades together at the top.","Lower the dumbbells back with control.","Repeat for the desired number of reps."],["Use a light weight so the rear delts do the work, not momentum.","Squeeze your shoulder blades together at the top.","Keep a soft, fixed bend in your elbows throughout."],{"start":"images/flat/dumbbell-reverse-fly-start.webp","peak":"images/flat/dumbbell-reverse-fly-peak.webp"},"strength"],["dumbbell-romanian-deadlift","Dumbbell Romanian Deadlift","intermediate","dumbbell","back","A hip-hinge movement with dumbbells and soft knees, loading the hamstrings and glutes through a controlled stretch.",["Stand holding dumbbells in front of your thighs with a soft knee bend.","Hinge at the hips and push your glutes back.","Lower the dumbbells along your legs until you feel a hamstring stretch.","Keep your back flat and shoulders pulled back.","Drive your hips forward to return to standing.","Repeat for the desired number of reps."],["Keep your knee angle constant; the movement is a hinge, not a squat.","Tuck your chin slightly to keep your spine in one straight line.","Squeeze your glutes at the top without leaning backward."],{"start":"images/flat/dumbbell-romanian-deadlift-start.webp","peak":"images/flat/dumbbell-romanian-deadlift-peak.webp"},"strength"],["dumbbell-shoulder-press","Dumbbell Shoulder Press","intermediate","dumbbell","shoulders","An overhead press with dumbbells performed seated or standing, building the front and side delts.",["Sit or stand holding dumbbells at shoulder height, palms facing forward.","Press both dumbbells overhead until arms are fully extended.","Keep your core braced and avoid arching your lower back.","Lower the dumbbells under control back to shoulder height.","Do not let the dumbbells drift behind your head.","Repeat for the desired number of reps."],["Stack your wrists directly over your elbows throughout the press.","Exhale as you press up and inhale as you lower.","Keep your elbows slightly in front of your shoulders rather than flared wide."],{"start":"images/flat/dumbbell-shoulder-press-start.webp","peak":"images/flat/dumbbell-shoulder-press-peak.webp"},"strength"],["dumbbell-side-bend","Dumbbell Side Bend","beginner","dumbbell","core","A standing oblique isolation exercise using a dumbbell to develop lateral core strength and stability.",["Stand upright holding a dumbbell in one hand at your side.","Keep the opposite hand on your hip or behind your head.","Bend laterally toward the dumbbell side, lowering it along your thigh.","Return to upright, then bend to the opposite side using only your obliques.","Complete all reps per side."],["Avoid leaning forward or backward - move strictly sideways.","Use a controlled tempo in both directions.","Keep the weight close to your leg throughout."],{"start":"images/flat/dumbbell-side-bend-start.webp","peak":"images/flat/dumbbell-side-bend-peak.webp"},"strength"],["dumbbell-snatch","Dumbbell Snatch","intermediate","dumbbell","full_body","An explosive single-arm lift driving a dumbbell from the floor to overhead in one fluid motion.",["Stand with feet shoulder-width apart, dumbbell on the floor between your feet.","Hinge and grip the dumbbell with one hand.","Explosively extend hips, knees, and ankles to pull the dumbbell upward.","Punch the dumbbell overhead in one fluid motion.","Lock out your arm and stabilize at the top.","Complete reps on one side, then switch."],["Extend your hips and knees fully before pulling with your arm.","Punch the dumbbell up to a stable overhead lockout.","Keep the dumbbell close to your body as it rises."],{"start":"images/flat/dumbbell-snatch-start.webp","peak":"images/flat/dumbbell-snatch-peak.webp"},"olympic"],["dumbbell-split-squat","Dumbbell Split Squat","intermediate","dumbbell","upper_legs","A split-stance squat holding dumbbells at the sides, training the quads and glutes one leg at a time.",["Stand in a split stance holding dumbbells at your sides.","Keep your torso upright and core braced.","Lower your back knee toward the floor by bending both knees.","Stop when your front thigh is parallel to the floor.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],["Keep most of your weight on your front leg.","Lower your back knee straight down toward the floor.","Track your front knee over your toes without letting it cave inward."],{"start":"images/flat/dumbbell-split-squat-start.webp","peak":"images/flat/dumbbell-split-squat-peak.webp"},"strength"],["dumbbell-tricep-extension","Dumbbell Tricep Extension","beginner","dumbbell","upper_arms","An overhead triceps extension with a dumbbell in each hand, both arms working together.",["Stand holding a dumbbell in each hand with your arms extended overhead.","Lower the dumbbells behind your head by bending your elbows.","Extend your arms back to the starting position.","Keep your elbows close to your head.","Repeat for the planned number of reps."],["Move only your forearms, keeping the upper arms still.","Brace your core to avoid arching your lower back.","Choose a weight light enough to reach a full stretch."],{"start":"images/flat/dumbbell-tricep-extension-start.webp","peak":"images/flat/dumbbell-tricep-extension-peak.webp"},"strength"],["dumbbell-upright-row","Dumbbell Upright Row","intermediate","dumbbell","shoulders","A compound pulling movement with dumbbells that targets the lateral deltoids and upper trapezius.",["Stand holding two dumbbells in front of your thighs, palms facing your body.","Pull the dumbbells straight up along your body, leading with your elbows.","Raise until the dumbbells reach chin height and elbows are above the wrists.","Pause briefly, then lower with control.","Repeat for the desired reps."],["Keep the dumbbells close to your body throughout.","Lead with your elbows, not your hands.","Avoid pulling with a very narrow grip to reduce shoulder impingement risk."],{"start":"images/flat/dumbbell-upright-row-start.webp","peak":"images/flat/dumbbell-upright-row-peak.webp"},"strength"],["dumbbell-windmill","Dumbbell Windmill","intermediate","dumbbell","full_body","This full-body exercise builds core stability, shoulder strength, and hip mobility by rotating the torso while holding a dumbbell overhead, primarily targeting the obliques and lateral deltoids.",["Stand with feet shoulder-width apart, holding a dumbbell overhead in one hand, arm locked.","Turn your feet slightly away from the dumbbell side, keeping the arm straight and eyes on the weight.","Hinge at your hips, pushing them out to the side of the dumbbell, and slowly lower your torso towards the floor.","Keep your back straight and the dumbbell arm vertical as you reach your free hand towards your foot or the floor.","Reverse the motion by driving through your hips and obliques to return to the starting position.","Complete all reps on one side, then switch and repeat for the other side."],["Maintain a tight core throughout the movement to protect your spine and enhance stability.","Keep your eyes fixed on the dumbbell overhead to help maintain balance and a straight arm.","Focus on hinging at the hips, not rounding your back, to engage the hamstrings and glutes.","Start with a light weight to master the form before progressing to heavier loads."],{"start":"images/flat/dumbbell-windmill-start.webp","peak":"images/flat/dumbbell-windmill-peak.webp"},"strength"],["dumbbell-wrist-curl","Dumbbell Wrist Curl","beginner","dumbbell","lower_arms","A dumbbell wrist curl that isolates the forearm flexors and trains both arms independently.",["Sit on a bench with the forearm resting on the thigh, palm up.","Hold a dumbbell with the wrist hanging off the knee.","Let the dumbbell roll down to the fingertips.","Curl the dumbbell up by flexing the wrist.","Lower under control. Complete reps per side."],["Move only at the wrist - keep the forearm still.","Roll the dumbbell to the fingertips for full range.","Train both arms with the same load and reps."],{"start":"images/flat/dumbbell-wrist-curl-start.webp","peak":"images/flat/dumbbell-wrist-curl-peak.webp"},"strength"],["eagle-pose","Eagle Pose","intermediate","bodyweight","upper_legs","A standing balance with one leg wrapped over the other and the arms twined in front of the chest, holding a narrow, compact shape on a single bent leg.",["Stand tall, bend both knees slightly and shift the weight onto one foot.","Cross the other thigh over the standing thigh and hook the foot behind the calf if it reaches.","Cross the opposite arm underneath, wind the forearms and bring the palms towards each other.","Sit down a little into the standing leg and hold for the prescribed time with the elbows lifted.","Unwind and repeat on the other side."],["Let the crossed foot rest on a block or the floor if hooking it behind the calf is not available.","Lift the elbows to shoulder height to keep the upper back working rather than collapsing.","Sink lower on the standing leg only while the knee tracks over the middle of the foot."],{"main":"images/flat/eagle-pose-main.webp"},"strength"],["easy-pose","Easy Pose","beginner","bodyweight","upper_legs","A simple cross-legged seat used for breathing and meditation: the pelvis stays upright, the spine is tall and the hips settle without strain.",["Sit on the floor and cross the shins comfortably, each foot under the opposite knee.","Sit up on a folded blanket or cushion until the knees rest below the level of the hips.","Stack the ribs over the pelvis and let the hands rest on the thighs.","Hold the seat for the prescribed time, breathing slowly and evenly.","Switch which shin is in front on the next round so both sides get equal time."],["If the knees float high, raise the seat rather than forcing them down.","Let the chin stay level so the neck follows the line of the spine.","Support the knees on cushions when a long sit gets uncomfortable."],{"main":"images/flat/easy-pose-main.webp"},"stretching"],["elliptical-trainer","Elliptical Trainer","beginner","elliptical","full_body","A low-impact cardio machine movement in which the feet trace a continuous oval on the foot plates while the moving handles push and pull, working the legs and upper body together.",["Step onto the foot plates one at a time, holding the fixed centre post until you are steady, then take a moving handle in each hand.","Start the pedals turning forward, keeping your whole foot down on the plate rather than lifting your heel.","Push one handle away as the opposite foot travels forward, and pull the other back, so the arms and legs work in opposition.","Stand tall with your hips over the pedals and your core braced instead of hanging back on the handles.","Set the resistance and ramp so you can hold a smooth stride, and continue for the desired time or distance."],["Drive the handles rather than letting the legs push them for you - the arm work is most of what makes the elliptical a full-body machine.","Keep your heels down on the plates. Riding on the toes cramps the calves and cuts the glutes out of the stride.","Pedalling backwards for part of the session shifts the emphasis toward the hamstrings and glutes and breaks up a long steady effort."],{"main":"images/flat/elliptical-trainer-main.webp"},"cardio"],["extended-side-angle","Extended Side Angle Pose","intermediate","bodyweight","upper_legs","A wide-stance standing pose with the front knee bent and the torso extended over the front thigh, so one long line runs from the back heel to the top hand.",["Stand wide with the front foot turned out and the back foot angled slightly in.","Bend the front knee until it stacks over the ankle and keep the back leg straight.","Rest the front forearm on the thigh, or the hand on the floor or a block, and reach the top arm over the ear.","Hold the position for the prescribed time, turning the chest towards the ceiling.","Straighten the front leg to come up and repeat on the other side."],["Press the outer edge of the back foot down; the pose loses its base as soon as that heel lifts.","Keep the front knee pointing at the middle toes rather than drifting inwards.","Take the forearm on the thigh instead of the hand on the floor to keep the chest open."],{"main":"images/flat/extended-side-angle-main.webp"},"strength"],["ez-bar-bench-press","EZ-Bar Bench Press","intermediate","ez_bar","chest","A flat-bench chest press performed with an EZ bar, whose angled grips are easier on the wrists while still loading the pectorals, front delts, and triceps.",["Lie flat on a bench with your feet planted on the floor, gripping the EZ bar's angled bends over your chest.","Unrack the bar and hold it over your lower chest with your arms extended.","Lower the bar under control toward your lower chest.","Press the bar back up to full arm extension.","Repeat for the desired number of reps."],["Keep your feet flat on the floor and maintain a slight arch in your lower back for a stable base.","The EZ bar's angled grip is easier on the wrists than a straight barbell.","Lower the bar to your lower chest and keep your elbows tucked at roughly 45 degrees to protect the shoulders."],{"start":"images/flat/ez-bar-bench-press-start.webp","peak":"images/flat/ez-bar-bench-press-peak.webp"},"strength"],["ez-bar-curl","EZ-Bar Curl","beginner","ez_bar","upper_arms","An isolation exercise targeting the biceps using an EZ-bar, which reduces wrist strain compared to a straight barbell.",["Stand holding an EZ-bar with an underhand grip on the angled portions.","Curl the bar up toward your shoulders, keeping your elbows pinned.","Squeeze at the top, then lower under control.","Repeat."],["Use the inner or outer grip to vary emphasis.","Keep your wrists neutral on the angled grips."],{"start":"images/flat/ez-bar-curl-start.webp","peak":"images/flat/ez-bar-curl-peak.webp"},"strength"],["ez-bar-front-raise","EZ-Bar Front Raise","beginner","ez_bar","shoulders","A two-handed front raise with an EZ-bar. The angled grip is easier on the wrists than a straight bar while still letting both hands drive the same load.",["Stand holding an EZ-bar with an overhand grip on the inner bends, arms hanging in front of the thighs.","Keep the elbows slightly bent and fixed throughout.","Raise the bar in a smooth arc up to shoulder height.","Pause briefly at the top, then lower under control.","Repeat for the recommended number of repetitions."],["Raise and lower the bar along the same smooth arc, without swinging it away from the body.","Do not swing the torso; keep the core braced and the knees slightly soft.","Stop at shoulder height - going higher shifts tension off the front delts."],{"start":"images/flat/ez-bar-front-raise-start.webp","peak":"images/flat/ez-bar-front-raise-peak.webp"},"strength"],["ez-bar-lying-tricep-extension","EZ-Bar Lying Triceps Extension","intermediate","ez_bar","upper_arms","A lying triceps extension performed with an EZ bar to isolate the triceps through a full range of motion.",["Lie on a flat bench holding an EZ bar over your chest with a narrow grip.","Lower the bar toward your forehead by bending at the elbows.","Extend your arms back to the start.","Repeat."],["Keep your upper arms vertical throughout so the triceps do the work.","The EZ bar's angled grip is easier on the wrists than a straight bar.","Lower slowly to protect the elbows."],{"start":"images/flat/ez-bar-lying-tricep-extension-start.webp","peak":"images/flat/ez-bar-lying-tricep-extension-peak.webp"},"strength"],["ez-bar-overhead-extension","EZ-Bar Overhead Tricep Extension","intermediate","ez_bar","upper_arms","Overhead tricep extension with an EZ-bar - the angled grip is easier on the wrists than a straight bar while keeping the long head under a deep stretch.",["Stand or sit holding an EZ-bar overhead with an overhand grip on the inner bends.","Arms fully extended, bar above the head.","Bend only the elbows to lower the bar behind the head in an arc.","Keep the upper arms vertical and close to the head; only the forearms move.","Extend the elbows to return the bar overhead.","Repeat for the recommended number of repetitions."],["If the elbows flare out, drop the load - flared elbows mean shoulders are assisting.","The deeper the stretch at the bottom, the better the long-head hypertrophy stimulus.","A seated version is easier on the lower back."],{"start":"images/flat/ez-bar-overhead-extension-start.webp","peak":"images/flat/ez-bar-overhead-extension-peak.webp"},"strength"],["ez-bar-pullover","EZ Bar Pullover","intermediate","ez_bar","back","This compound exercise targets the lats and pectorals by extending the arms overhead with an EZ bar, promoting upper body strength and hypertrophy.",["Lie supine on a flat bench with your head slightly off the end, holding an EZ bar with a pronated grip.","Extend the bar straight above your chest, keeping a slight bend in your elbows.","Slowly lower the bar in an arc behind your head, feeling a stretch in your lats and chest.","Pull the bar back to the starting position using your lats and pectorals.","Maintain control throughout the movement, avoiding momentum."],["Keep your core braced to prevent arching your lower back excessively.","Focus on a deep stretch at the bottom of the movement.","Use a spotter for heavier loads to ensure safety.","Control the eccentric (lowering) phase for maximum muscle engagement."],{"start":"images/flat/ez-bar-pullover-start.webp","peak":"images/flat/ez-bar-pullover-peak.webp"},"strength"],["ez-bar-reverse-curl","EZ-Bar Reverse Curl","beginner","ez_bar","upper_arms","A reverse curl with an EZ-bar targeting the brachialis and forearm extensors with a comfortable grip.",["Hold an EZ-bar with an overhand grip.","Curl the bar up toward your shoulders.","Lower under control.","Repeat."],["Keep elbows close to your torso.","The EZ-bar reduces wrist strain."],{"start":"images/flat/ez-bar-reverse-curl-start.webp","peak":"images/flat/ez-bar-reverse-curl-peak.webp"},"strength"],["ez-bar-reverse-grip-row","EZ Bar Reverse Grip Row","intermediate","ez_bar","back","This compound pulling exercise targets the latissimus dorsi and biceps, effectively building back thickness and arm strength with an underhand grip.",["Stand with feet shoulder-width apart, holding an EZ bar with an underhand, shoulder-width grip.","Hinge at your hips, keeping a slight bend in your knees and your back straight, until your torso is nearly parallel to the floor.","Let the bar hang directly below your shoulders with arms fully extended.","Pull the bar towards your lower abdomen, squeezing your shoulder blades together and driving your elbows up.","Control the eccentric phase, slowly lowering the bar back to the starting position with full arm extension."],["Maintain a neutral spine throughout the movement to protect your lower back.","Focus on initiating the pull with your lats, not just your biceps.","Avoid shrugging your shoulders; keep them depressed and retracted.","Use a full range of motion, extending your arms completely at the bottom."],{"start":"images/flat/ez-bar-reverse-grip-row-start.webp","peak":"images/flat/ez-bar-reverse-grip-row-peak.webp"},"strength"],["ez-bar-romanian-deadlift","EZ-Bar Romanian Deadlift","beginner","ez_bar","upper_legs","A Romanian deadlift using an EZ-bar. The angled grip is easier on the wrists and suits lighter hinge work or elbow-sensitive lifters.",["Stand holding an EZ-bar at mid-thigh with an overhand grip on the inner bends.","Feet hip-width, soft bend in the knees, chest up, lats engaged.","Push the hips back while letting the bar slide down the front of the legs.","Go until you feel a deep hamstring stretch without rounding the lower back.","Drive the hips forward to return to standing, keeping the bar close to the body.","Repeat for the recommended number of repetitions."],["The movement is a hip hinge, not a squat - knees barely bend.","The EZ-bar is shorter than a barbell; grip the inner bends for a neutral-ish wrist.","Stop at the bottom of your clean ROM - no round-back stretch."],{"start":"images/flat/ez-bar-romanian-deadlift-start.webp","peak":"images/flat/ez-bar-romanian-deadlift-peak.webp"},"strength"],["ez-bar-shrug","EZ-Bar Shrug","beginner","ez_bar","shoulders","A shrug using an EZ-bar for a comfortable grip while loading the trapezius.",["Stand holding an EZ-bar in front of you.","Shrug your shoulders straight up.","Hold at the top, then lower.","Repeat."],["Avoid rolling the shoulders in circles.","Use a full range of motion."],{"start":"images/flat/ez-bar-shrug-start.webp","peak":"images/flat/ez-bar-shrug-peak.webp"},"strength"],["ez-bar-spider-curl","EZ Bar Spider Curl","intermediate","ez_bar","upper_arms","A chest-supported curl over an incline bench with an EZ bar, isolating the biceps with strict form.",["Lie chest down on an incline bench holding an EZ bar with underhand grip.","Let your arms hang straight down from your shoulders.","Curl the bar up toward your shoulders.","Squeeze your biceps at the top of the movement.","Lower the bar back down with control.","Repeat for the desired number of reps."],["Let your arms hang straight down and keep the upper arms fixed.","Curl with the biceps only - the bench removes any excuse to swing.","Lower to a full stretch before starting the next rep."],{"start":"images/flat/ez-bar-spider-curl-start.webp","peak":"images/flat/ez-bar-spider-curl-peak.webp"},"strength"],["ez-bar-upright-row","EZ-Bar Upright Row","intermediate","ez_bar","shoulders","An upright row variation using an EZ-bar for more comfortable wrist positioning.",["Stand holding an EZ-bar with a shoulder-width grip on the angled portions.","Pull the bar straight up along your body toward your chin.","Lead with your elbows, keeping them above your hands.","Lower with control.","Repeat."],["Pull only as high as your shoulders allow without pinching.","Keep the bar close to your body throughout the movement.","Avoid swinging or using your legs to lift the weight."],{"start":"images/flat/ez-bar-upright-row-start.webp","peak":"images/flat/ez-bar-upright-row-peak.webp"},"strength"],["ez-bar-wrist-curl","EZ-Bar Wrist Curl","beginner","ez_bar","lower_arms","A wrist curl with the EZ-bar, friendlier on the wrists than a straight bar.",["Sit on a bench with forearms resting on the thighs, palms up.","Grip an EZ-bar on the inner bends with hands shoulder-width.","Let the bar roll down to the fingertips.","Curl the bar up by flexing the wrists.","Lower under control."],["The EZ-bar's angle is gentler on the wrists than a straight bar.","Move only at the wrist - keep the forearms still.","Roll the bar to the fingertips for full range."],{"start":"images/flat/ez-bar-wrist-curl-start.webp","peak":"images/flat/ez-bar-wrist-curl-peak.webp"},"strength"],["face-pull","Cable Face Pull","beginner","cable","shoulders","A cable exercise targeting the rear deltoids and external rotators.",["Attach a rope to a high cable pulley.","Pull the rope toward your face, separating the ends.","Squeeze your rear deltoids and external rotators.","Return to the starting position with control.","Repeat."],["Keep your elbows high, roughly in line with your shoulders.","Choose a light weight and prioritize control over load.","Avoid leaning back or shrugging your shoulders as you pull."],{"start":"images/flat/face-pull-start.webp","peak":"images/flat/face-pull-peak.webp"},"strength"],["fire-hydrant","Fire Hydrant","beginner","bodyweight","upper_legs","A bodyweight glute exercise performed on hands and knees: one knee is lifted out to the side, like a dog at a fire hydrant, while the hips and spine stay square to the floor. It targets the gluteus medius and the other hip abductors with no equipment.",["Set up on hands and knees with the hands under the shoulders, the knees under the hips and the back flat.","Brace the trunk so the hips stay level and square to the floor.","Keeping the knee bent at about 90 degrees, lift one knee out to the side until the thigh is roughly parallel to the floor.","Pause briefly at the top without rotating the pelvis or leaning away from the working side.","Lower the knee back to the starting position under control.","Complete the repetitions on one side, then switch legs."],["Move only at the hip; if the lower back twists or the torso tips, the range is too big.","Keep the knee bent at the same angle for the whole set.","Press the supporting hand and knee into the floor so the standing side does not sag."],{"start":"images/flat/fire-hydrant-start.webp","peak":"images/flat/fire-hydrant-peak.webp"},"strength"],["fish-pose","Fish Pose","intermediate","bodyweight","chest","A supine backbend supported on the forearms with the chest lifted and the head tilted back, opening the front of the chest and the throat.",["Lie on your back with the legs straight and the arms alongside the body, palms down under the hips.","Press the forearms into the floor and lift the chest towards the ceiling.","Let the crown of the head rest lightly on the floor without putting weight through the neck.","Hold the position for the prescribed time, breathing into the upper chest.","Lift the head, then lower the back down."],["Carry the weight in the forearms, not the head; the neck only guides the position.","Place a block lengthwise under the upper back if the floor version pinches.","Keep the legs active and the thighs rolling slightly inwards."],{"main":"images/flat/fish-pose-main.webp"},"stretching"],["flexed-arm-hang","Flexed Arm Hang","intermediate","pull_up_bar","back","A static pull-up hold in which the chin is kept above a bar with the elbows bent. It builds endurance and strength in the arms, lats and grip and is a classic stepping stone to the pull-up.",["Grip a pull-up bar with the palms facing away, a little wider than shoulder-width, or facing you for an easier version.","Pull yourself up, or step up on a box, until the chin is above the bar.","Keep the elbows bent and pointing down, with the shoulders pulled away from the ears.","Hold the position without swinging, keeping the legs together and the trunk tight.","Lower slowly to a full hang when the chin begins to drop."],["Keep the chin clearly above the bar; once it drops below, the hold is over.","Squeeze the bar and pull the shoulder blades down and back.","Step up to the top position rather than jumping if you cannot yet pull up."],{"main":"images/flat/flexed-arm-hang-main.webp"},"strength"],["floor-ez-bar-press","Floor EZ-Bar Press","intermediate","ez_bar","chest","A floor press variation using an EZ-bar for a more comfortable wrist and elbow position.",["Lie on the floor holding an EZ-bar over your chest.","Lower the bar until your elbows touch the floor.","Press back up to full extension.","Repeat."],["The EZ-bar reduces wrist strain vs. a straight bar.","Keep your feet flat on the floor."],{"start":"images/flat/floor-ez-bar-press-start.webp","peak":"images/flat/floor-ez-bar-press-peak.webp"},"strength"],["floor-kettlebell-pullover","Floor Kettlebell Pullover","beginner","kettlebell","back","A pullover done lying on the floor with a kettlebell held by the handle or by the horns. The floor limits the range of motion compared to the bench version, which reduces shoulder strain and makes it a good home-gym or prehab option.",["Lie face-up on the floor with knees bent and feet flat.","Hold a kettlebell by the handle with both hands above your chest, arms almost straight (slight elbow bend).","Keeping the elbow angle fixed, lower the bell overhead in an arc until the upper arms touch the floor.","Pull the bell back above the chest along the same arc.","Repeat for the recommended number of repetitions."],["The floor caps the ROM; if it feels too short, use a bench version.","Grip the handle firmly and squeeze the lats at the top.","Keep the lower back flat against the floor throughout."],{"start":"images/flat/floor-kettlebell-pullover-start.webp","peak":"images/flat/floor-kettlebell-pullover-peak.webp"},"strength"],["floor-press","Floor Press","intermediate","barbell","chest","A barbell pressing movement performed on the floor, limiting range of motion and taking the lower body out of the equation.",["Lie on the floor and position yourself under a barbell in a rack.","Unrack the bar and lower it to your chest until your upper arms touch the floor.","Press back up to lockout.","Repeat."],["Elbows touching the floor provides a natural stopping point.","Useful for addressing lockout weakness."],{"start":"images/flat/floor-press-start.webp","peak":"images/flat/floor-press-peak.webp"},"strength"],["flutter-kicks","Flutter Kicks","intermediate","bodyweight","core","A supine core drill alternating small up-and-down leg kicks while the lower back stays pressed to the floor.",["Lie flat on your back with your legs extended.","Place your hands under your glutes for support.","Lift both legs a few inches off the floor.","Alternate kicking your legs up and down in a small range.","Keep your core braced and lower back pressed down.","Continue for the desired duration or reps."],["Press your lower back into the floor for the whole set.","Keep the kicks small and steady rather than big and wild.","Raise your legs higher if you feel your lower back arching."],{"start":"images/flat/flutter-kicks-start.webp","peak":"images/flat/flutter-kicks-peak.webp"},"strength"],["frog-stretch","Frog Stretch","beginner","bodyweight","upper_legs","A floor stretch for the inner thighs and groin: on your hands and knees, you slide the knees wide apart with the feet turned out and rock your hips back toward your heels. The wide knees open the adductors while the hips stay low.",["Start on your hands and knees on the floor, with your wrists under your shoulders.","Slide your knees out to the sides as far as is comfortable and turn your feet out, keeping your shins in line with your knees.","Lower onto your forearms and keep your back straight, not rounded.","Rock your hips back toward your heels until you feel a strong stretch along your inner thighs.","Hold the position and breathe slowly, keeping your hips level.","Come out by sliding the knees together and sitting back before you stand."],["Put a folded towel or mat under your knees if the floor is hard.","Go only as wide as you can keep your hips level; letting the pelvis tilt takes the stretch out of the inner thighs.","Rock back slowly and ease out of the position if you feel any pinching at the front of the hips."],{"main":"images/flat/frog-stretch-main.webp"},"stretching"],["front-lever","Front Lever","advanced","pull_up_bar","back","An advanced static hold under the bar with the body horizontal and chest facing upward, requiring straight-arm pulling strength through the lats and core.",["Grip the bar with an overhand grip and hang.","Tuck your knees to your chest and pull your straight arms down toward your hips, leaning back until your torso is horizontal and your chest faces up.","Extend your body horizontally with arms straight and chest facing the ceiling.","Keep your body rigid and parallel to the floor.","Hold for the desired duration, then tuck and lower under control."],["Progress through tuck and straddle holds before attempting the full extension.","Squeeze your core and glutes to prevent the hips from dropping.","Keep the shoulders actively depressed away from the ears throughout the hold."],{"main":"images/flat/front-lever-main.webp"},"strength"],["front-squat","Front Squat","intermediate","barbell","upper_legs","A barbell squat with the bar held in front on the deltoids, emphasizing quads and core.",["Clean or rack the bar to your front deltoids with elbows high.","Squat down keeping torso upright until thighs are parallel.","Drive back up.","Repeat."],["Maintain high elbows to keep the bar stable.","A more upright torso increases quad activation."],{"start":"images/flat/front-squat-start.webp","peak":"images/flat/front-squat-peak.webp"},"strength"],["garland-pose","Garland Pose","beginner","bodyweight","upper_legs","A deep bodyweight squat held with the heels down and the elbows pressing the knees open, used to open the hips, ankles and lower back.",["Stand with the feet a little wider than the hips and the toes turned slightly out.","Squat down as low as the ankles allow, keeping the heels on the floor.","Bring the palms together at the chest and press the elbows against the inner knees.","Hold the position for the prescribed time with the chest lifted and the spine long.","Press through the feet to stand back up."],["Roll a towel under the heels if they lift; forcing them down rounds the lower back instead.","Widen the stance to make room for the pelvis rather than squeezing into a narrow squat.","Press the knees and elbows against each other lightly to keep the chest from collapsing."],{"main":"images/flat/garland-pose-main.webp"},"stretching"],["glute-bridge","Glute Bridge","beginner","bodyweight","upper_legs","A bodyweight glute activation exercise performed lying on the floor.",["Lie on your back with knees bent and feet flat on the floor.","Drive your hips up by squeezing your glutes.","Hold briefly at the top with hips fully extended.","Lower your hips back down with control.","Repeat."],["Push through your heels rather than your toes.","Avoid arching your lower back at the top.","Don't let your knees cave inward as you lift."],{"start":"images/flat/glute-bridge-start.webp","peak":"images/flat/glute-bridge-peak.webp"},"strength"],["glute-bridge-hold","Glute Bridge Hold","beginner","bodyweight","upper_legs","The top of the glute bridge held for time: hips fully extended with the shoulders, hips and knees in one line, so the glutes stay under tension instead of cycling through reps.",["Lie on your back with the knees bent and the feet flat, about hip-width apart and close enough to brush your fingertips with your heels.","Push through the heels and lift the hips until the body forms a straight line from the knees to the shoulders.","Squeeze the glutes and tuck the ribs down so the lower back does not take over.","Hold the top position for the prescribed time, keeping the weight in the heels.","Lower the hips under control to finish the set."],["Push the knees slightly outwards during the hold to keep the glutes engaged.","Stop lifting once the knees, hips and shoulders form a straight line; going higher usually means arching the back.","For extra load, rest a dumbbell or a plate across the hips before the lift."],{"main":"images/flat/glute-bridge-hold-main.webp"},"strength"],["glute-kickback","Glute Kickback","beginner","bodyweight","upper_legs","A bodyweight glute isolation exercise performed on all fours to develop gluteus maximus strength and shape.",["Begin on all fours with hands under shoulders and knees under hips.","Keeping the knee bent at 90 degrees, drive one heel toward the ceiling.","Squeeze the glute at the top of the movement.","Lower the leg back to the starting position with control.","Complete all reps, then switch sides."],["Keep your hips square to the floor - avoid rotating.","Focus on squeezing the glute, not just lifting the leg.","Add a resistance band or cable for progressive overload."],{"start":"images/flat/glute-kickback-start.webp","peak":"images/flat/glute-kickback-peak.webp"},"strength"],["glute-kickback-hold","Glute Kickback Hold","beginner","bodyweight","upper_legs","The end position of the glute kickback held for time: on all fours with one leg extended back at hip height, the pelvis level and the glute holding the leg in place.",["Start on all fours with the hands under the shoulders and the knees under the hips.","Brace the trunk and keep the pelvis level; do not let the working side rotate upwards.","Extend one leg back and up until the thigh is in line with the torso.","Hold that position for the prescribed time, keeping the neck long and the lower back flat.","Lower the leg under control and repeat on the other side."],["Squeeze the glute rather than kicking higher; the height is limited by the pelvis staying square.","Keep the supporting shoulder pushed away from the ear so the upper body does not sag.","A bent knee keeps the tension on the glute, a straight leg shifts more of it to the hamstring."],{"main":"images/flat/glute-kickback-hold-main.webp"},"strength"],["goblet-squat","Goblet Squat","beginner","kettlebell","upper_legs","A beginner-friendly squat with a kettlebell held at chest height for improved posture and depth.",["Hold a kettlebell at chest height with both hands.","Squat down keeping the weight close to your chest.","Drive back up.","Repeat."],["The goblet position naturally encourages an upright torso.","Push knees out at the bottom."],{"start":"images/flat/goblet-squat-start.webp","peak":"images/flat/goblet-squat-peak.webp"},"strength"],["good-morning","Good Morning","intermediate","barbell","upper_legs","A hip-hinge movement with a barbell on the back for posterior chain development.",["Stand with a barbell across your upper back.","Hinge at the hips, pushing them back while keeping your back flat.","Lower your torso until it's nearly parallel to the floor.","Drive your hips forward to return to standing.","Repeat."],["Start with a light bar and master the hinge first.","Keep a soft bend in your knees throughout.","Stop the descent if your lower back starts to round."],{"start":"images/flat/good-morning-start.webp","peak":"images/flat/good-morning-peak.webp"},"strength"],["hack-squat","Hack Squat","intermediate","hack_squat","upper_legs","A compound lower-body machine exercise on the hack squat sled, targeting the quadriceps through a guided squat pattern.",["Load the hack squat machine and step on, positioning your back and shoulders against the pads.","Place your feet shoulder-width on the platform with toes turned out slightly.","Unlock the safety handles and lower the sled by bending at the knees and hips.","Descend until your thighs are at least parallel to the platform.","Drive through your heels to extend the legs and push the sled back to the start.","Re-engage the safety handles after your final rep."],["Keep your lower back pressed against the pad throughout the movement.","Placing the feet higher on the platform shifts emphasis to the glutes and hamstrings.","Control the descent; do not bounce out of the bottom position."],{"start":"images/flat/hack-squat-start.webp","peak":"images/flat/hack-squat-peak.webp"},"strength"],["hack-squat-calf-raise","Hack Squat Calf Raise","intermediate","hack_squat","lower_legs","A calf raise performed in the hack squat machine, loading the calves heavily without balancing a bar.",["Load yourself into a hack squat machine with shoulders under the pads.","Place the balls of your feet on the platform with heels hanging off.","Keep your legs straight with a slight knee bend.","Press through the balls of your feet to raise your heels.","Lower your heels back below the platform for a stretch.","Repeat for the desired number of reps."],["Rise as high onto the balls of your feet as possible.","Pause in the bottom stretch instead of bouncing out of it.","Keep your knees straight but not locked to keep tension on the calves."],{"start":"images/flat/hack-squat-calf-raise-start.webp","peak":"images/flat/hack-squat-calf-raise-peak.webp"},"strength"],["half-kneeling-hip-flexor-rock","Half-Kneeling Hip Flexor Rock","beginner","bodyweight","upper_legs","The dynamic version of the kneeling hip-flexor stretch: from a half-kneeling stance the hips rock forward into the stretch and back out of it, repeated instead of held.",["Kneel on one knee with the other foot flat on the floor in front of you.","Tuck the tailbone slightly and brace the trunk so the lower back stays neutral.","Rock the hips forward until you feel the front of the back thigh lengthen.","Rock back out of the position under control and repeat rhythmically.","Switch sides and repeat for the same number of repetitions."],["Keep the movement in the hips; if the lower back arches, shorten the range.","Squeeze the glute of the kneeling leg during the forward rock.","Pad the down knee with a folded mat if the floor is hard."],{"start":"images/flat/half-kneeling-hip-flexor-rock-start.webp","peak":"images/flat/half-kneeling-hip-flexor-rock-peak.webp"},"stretching"],["half-moon-pose","Half Moon Pose","advanced","bodyweight","core","A standing side balance on one leg and one hand, with the top leg lifted to hip height and the chest turned open towards the ceiling.",["From a wide standing stance, bend the front knee and place the bottom hand on the floor or a block ahead of the front foot.","Shift the weight forward and lift the back leg until it is parallel to the floor.","Straighten the standing leg and stack the top hip over the bottom one, reaching the top arm to the ceiling.","Hold the balance for the prescribed time with the lifted foot flexed.","Lower the back foot down and repeat on the other side."],["Use a block under the bottom hand; reaching the floor is not the point of the pose.","Press the lifted heel towards the wall behind you to keep the leg switched on.","Look at the floor instead of up if the balance keeps breaking."],{"main":"images/flat/half-moon-pose-main.webp"},"strength"],["hammer-curl","Dumbbell Hammer Curl","beginner","dumbbell","upper_arms","A bicep curl variation with a neutral grip targeting the brachioradialis.",["Stand holding dumbbells at your sides with palms facing each other.","Curl the weights up while keeping your palms facing inward.","Squeeze at the top, then lower under control.","Repeat."],["Keep your elbows pinned to your sides throughout.","Keep your wrists straight and rigid throughout the curl.","Avoid leaning back or swinging the weights up."],{"start":"images/flat/hammer-curl-start.webp","peak":"images/flat/hammer-curl-peak.webp"},"strength"],["handstand-hold","Handstand Hold","advanced","bodyweight","shoulders","A freestanding static hold balanced upside down on the hands with the body stacked in a straight line. It builds shoulder strength, wrist and trunk stability and balance.",["Place the hands about shoulder-width apart on the floor and kick up into an inverted position, one leg after the other.","Press tall through the shoulders and keep the arms locked.","Squeeze the glutes and abdominals so the body forms one straight line from the hands to the toes.","Keep the gaze between the hands and hold the position, making small corrections with the fingers.","Come down under control, one leg at a time, or step out of the hold."],["Practise against a wall until you can hold the line without leaning on it.","Push the floor away so the shoulders stay elevated, and pull the ribs in to avoid arching the back.","Warm up the wrists before holding."],{"main":"images/flat/handstand-hold-main.webp"},"strength"],["handstand-push-ups","Handstand Push Ups","advanced","bodyweight","shoulders","An inverted press in a freestanding handstand on parallettes, lowering the head between the handles and pressing back up to straight arms.",["Set two parallettes shoulder-width apart and kick up into a freestanding handstand on them.","Brace your core and keep your body straight, legs together.","Bend your elbows to lower your head between the handles.","Go down until your head is about level with the handles.","Press through the handles back to straight arms, keeping your balance.","Repeat for the desired number of reps."],["Lower under control instead of dropping into the bottom position.","Keep the ribs down and the body stacked over the hands so the back does not arch.","Learn it against a wall and through pike push-ups before going freestanding."],{"start":"images/flat/handstand-push-ups-start.webp","peak":"images/flat/handstand-push-ups-peak.webp"},"strength"],["hang-clean","Hang Clean","intermediate","barbell","full_body","A clean variation starting with the barbell at the thighs, training explosive triple extension and a fast catch.",["Stand holding a barbell with a shoulder-width grip at your thighs.","Hinge at the hips to lower the bar just above your knees.","Explosively extend your hips, knees, and ankles.","Shrug your shoulders and pull the bar up.","Pull yourself under the bar and catch it on your front shoulders in a full squat.","Stand up tall, then return to the hang position."],["Hinge to just above the knees before exploding upward.","Shrug and pull the bar up close to your body.","Catch the bar on your shoulders as you sit into the squat."],{"start":"images/flat/hang-clean-start.webp","peak":"images/flat/hang-clean-peak.webp"},"olympic"],["hang-power-clean","Hang Power Clean","intermediate","barbell","full_body","A clean from the hang caught in a partial squat, building explosive power without dropping into a full squat.",["Stand with feet hip-width apart holding a barbell at your thighs.","Hinge at the hips to lower the bar to just above the knees.","Drive through your hips and legs explosively.","Pull the bar up and catch it on your front shoulders in a partial squat.","Stand tall with the bar racked on your shoulders.","Lower the bar back to the hang position."],["Drive through your hips and legs before the arms pull.","Receive the bar with your thighs above parallel.","Keep your back flat as you hinge to the start position."],{"start":"images/flat/hang-power-clean-start.webp","peak":"images/flat/hang-power-clean-peak.webp"},"olympic"],["hang-snatch","Hang Snatch","intermediate","barbell","full_body","An Olympic lift in which a barbell is pulled from the hang position, just above the knees, to overhead in one explosive movement and caught in a squat. It builds power through the hips, back and shoulders.",["Stand with a wide snatch grip on a barbell held at the thighs and the feet about hip-width apart.","Hinge at the hips to lower the bar to just above the knees, keeping the back flat and the shoulders over the bar.","Explosively extend the hips, knees and ankles, shrugging as the bar rises.","Pull yourself under the bar and catch it overhead with locked arms in a squat.","Stand up fully with the bar overhead and stable.","Lower the bar under control back to the thighs and reset."],["Keep the bar close to the body throughout the pull.","Finish the pull with full extension before dropping under the bar.","Learn the movement with a light bar or a dowel; the wide overhead catch needs good shoulder and hip mobility."],{"start":"images/flat/hang-snatch-start.webp","peak":"images/flat/hang-snatch-peak.webp"},"olympic"],["hanging-knee-raise","Hanging Knee Raise","beginner","pull_up_bar","core","A hanging core exercise on a pull-up bar that targets the lower abs and hip flexors with bent knees.",["Hang from a pull-up bar with an overhand grip, arms fully extended.","Engage your core and raise your knees toward your chest.","Hold briefly at the top.","Lower your legs slowly back to the starting position.","Repeat for the desired reps."],["Avoid swinging - initiate the movement from your core.","Exhale as you raise your knees.","Progress to straight-leg raises when this feels easy."],{"start":"images/flat/hanging-knee-raise-start.webp","peak":"images/flat/hanging-knee-raise-peak.webp"},"strength"],["hanging-l-sit","Hanging L-Sit","advanced","pull_up_bar","core","A static core hold hanging from a bar with the legs extended straight in front of the body at hip height, forming an L shape. It demands strong abdominals, hip flexors and grip.",["Hang from a pull-up bar with an overhand grip, arms straight and the shoulders pulled down.","Brace the abdominals and lift the straight legs until they are parallel to the floor.","Keep the knees locked and the toes pointed, with the legs together.","Hold the position without swinging, breathing steadily.","Lower the legs under control to a dead hang."],["If the legs drop below parallel, bend the knees (a tuck hold) and build up from there.","Keep the shoulders active; do not hang passively from the joints.","Squeeze the legs together and point the toes to keep the line tight."],{"main":"images/flat/hanging-l-sit-main.webp"},"strength"],["hanging-leg-raise","Hanging Leg Raise","intermediate","pull_up_bar","core","An advanced core exercise performed hanging from a bar.",["Hang from a pull-up bar with an overhand grip.","Raise your legs in front of you until they are parallel to the floor.","Hold briefly, then lower with control.","Avoid swinging.","Repeat."],["Curl your pelvis up at the top to fully engage your abs.","Keep your shoulders engaged rather than hanging passively.","Bend your knees to make the movement easier if needed."],{"start":"images/flat/hanging-leg-raise-start.webp","peak":"images/flat/hanging-leg-raise-peak.webp"},"strength"],["hanging-pike","Hanging Pike","advanced","pull_up_bar","core","A strict hanging leg raise taken to the bar - legs stay straight and the feet rise all the way to the hands.",["Hang from a pull-up bar with a shoulder-width overhand grip.","Engage the lats and brace the core to create a hollow body.","Keeping the legs perfectly straight, lift them in a smooth arc up to the bar.","Aim to touch the toes to the bar between the hands.","Lower the legs slowly back to the hanging position and repeat."],["No swinging - every rep starts from a dead hang with a braced trunk.","If full range is too hard, raise only to horizontal and build up."],{"start":"images/flat/hanging-pike-start.webp","peak":"images/flat/hanging-pike-peak.webp"},"strength"],["hanging-tuck-hold","Hanging Tuck Hold","intermediate","pull_up_bar","core","A static core hold hanging from a bar with the knees pulled up toward the chest. It trains the abdominals and hip flexors and is a step toward the hanging L-sit.",["Hang from a pull-up bar with an overhand grip and the arms straight.","Brace the abdominals and pull the knees up toward the chest, rounding the lower back slightly.","Keep the knees together and the thighs at or above hip height.","Hold the tucked position without swinging and breathe steadily.","Lower the legs under control to a full hang."],["Curl the pelvis up rather than just lifting the knees; the abdominals should do the work.","Keep the shoulders pulled away from the ears.","End the set when the knees start to drop or the body starts to swing."],{"main":"images/flat/hanging-tuck-hold-main.webp"},"strength"],["happy-baby","Happy Baby Pose","beginner","bodyweight","upper_legs","A supine hip opener in which the knees are drawn towards the armpits and the feet are held from the outside, releasing the inner thighs and lower back.",["Lie on your back and draw both knees towards the chest.","Take hold of the outside edges of the feet, or the shins if the feet are out of reach.","Open the knees wider than the ribs and stack the ankles above the knees, soles facing up.","Press the feet gently into the hands and hold for the prescribed time with the lower back on the floor.","Release the feet and lower the legs."],["Keep the tailbone heavy on the floor rather than rolling onto the upper back.","Hold the shins or use a strap around the feet if the grip forces the shoulders off the mat.","Rock gently side to side to massage the lower back if it feels tight."],{"main":"images/flat/happy-baby-main.webp"},"stretching"],["head-to-knee-pose","Head-to-Knee Pose","beginner","bodyweight","upper_legs","A seated one-legged fold: one leg stays straight while the other foot rests against the inner thigh, so the hamstring of the straight leg lengthens one side at a time.",["Sit with one leg straight in front of you and the other knee bent out to the side, that foot at the inner thigh.","Turn the chest towards the straight leg so the navel lines up with the thigh.","Hinge from the hips and reach forward along the straight leg with a long spine.","Hold the fold for the prescribed time, breathing into the back of the leg.","Come up with a flat back and repeat on the other side."],["Sit on a folded blanket so the pelvis can tip forward instead of the back rounding.","Keep the toes of the straight leg pointing up rather than rolling out.","Use a strap around the foot when the hands do not reach it comfortably."],{"main":"images/flat/head-to-knee-pose-main.webp"},"stretching"],["heel-elevated-squat","Heel-Elevated Squat","intermediate","barbell","upper_legs","A squat variation with heels raised on plates or a wedge to shift emphasis onto the quadriceps and improve depth.",["Place weight plates or a wedge under your heels, feet shoulder-width apart.","Hold a barbell across your upper back or hold dumbbells at your sides.","Brace your core and descend into a squat, keeping your torso upright.","Squat until thighs are parallel to the floor or lower.","Drive through your feet to return to the starting position."],["The elevated heels allow a more upright torso and greater knee travel.","Keep your knees tracking over your toes throughout.","Start with a small heel elevation and increase as mobility improves."],{"start":"images/flat/heel-elevated-squat-start.webp","peak":"images/flat/heel-elevated-squat-peak.webp"},"strength"],["heel-flicks","Heel Flicks","beginner","bodyweight","full_body","A running warm-up drill that alternates the heels towards the glutes, raising the cadence while dynamically flexing the knees and preparing the hamstrings.",["Stand tall with the feet under the hips and the arms bent as for running.","Begin jogging lightly in place.","Flick one heel up towards the same-side glute without driving the knee forward.","Switch feet quickly and continue alternating at an even rhythm.","Stay light on the forefeet and keep the torso upright for the full interval."],["Aim for quick relaxed contacts rather than forcing the heel into the glute.","Keep the knees pointing down instead of lifting them like high knees.","Start slowly and increase cadence only after the rhythm feels smooth."],{"main":"images/flat/heel-flicks-main.webp"},"cardio"],["heel-to-toe-walk","Heel-to-Toe Walk","beginner","bodyweight","lower_legs","A balance and coordination drill walked along an imaginary line, placing the heel of each step directly against the toes of the other foot so the base of support narrows to almost nothing.",["Pick a straight line on the floor and stand on it with your arms out to your sides at shoulder height.","Step forward and place your heel directly in front of - and touching - the toes of the standing foot.","Shift your weight onto the front foot under control, pausing for a moment before the next step.","Bring the back foot through and place it heel to toe again, staying on the line rather than stepping around it.","Look ahead at a fixed point instead of down at your feet, and use your arms to correct any wobble.","Walk the desired number of steps, then turn around and walk back."],["Go slowly. Rushing turns it into ordinary walking on a narrow line and removes the balance demand entirely.","If you cannot hold the line, walk beside a wall and touch it only when you need it - that is a regression, not a failure.","Make it harder by folding your arms across your chest, and harder again by doing it with your eyes closed near a wall."],{"main":"images/flat/heel-to-toe-walk-main.webp"},"strength"],["heel-touches","Heel Touches","intermediate","bodyweight","core","A lying core exercise in which you crunch slightly to one side and reach the hand toward the heel, then alternate sides. It trains the obliques and the upper abdominals with the lower back kept on the floor.",["Lie on your back with the knees bent and the feet flat on the floor, about hip-width apart.","Lift the head and shoulders slightly off the floor and reach the arms down along your sides.","Crunch to one side and reach that hand toward the heel on the same side.","Return to the center and reach toward the opposite heel.","Keep alternating sides in a smooth rhythm while the lower back stays on the floor.","Continue for the desired number of repetitions."],["Keep the neck long and the chin off the chest; lead with the ribcage, not the head.","Keep each reach small and controlled; the shoulder blades only just clear the floor.","Keep the feet planted and the lower back pressed into the floor throughout."],{"start":"images/flat/heel-touches-start.webp","peak":"images/flat/heel-touches-peak.webp"},"strength"],["hero-pose","Hero Pose","beginner","bodyweight","upper_legs","A kneeling seat with the hips settling between the heels, which lengthens the quadriceps and the front of the ankles while the spine stays tall.",["Kneel with the knees together and the feet slightly wider than the hips, tops of the feet flat.","Sit the hips back and down between the heels, using a block or cushion if the floor is out of reach.","Stack the ribs over the pelvis and rest the hands on the thighs.","Hold the seat for the prescribed time, keeping the weight even on both sit bones.","Come out by pressing into the hands and straightening one leg at a time."],["Sit on a block whenever the knees complain; the height is a normal part of the pose.","Roll a towel under the ankles if the front of them feels strained.","Keep the feet pointing straight back rather than flaring out to the sides."],{"main":"images/flat/hero-pose-main.webp"},"stretching"],["hex-bar-deadlift","Hex Bar Deadlift","intermediate","trap_bar","back","A deadlift standing inside a hex (trap) bar, keeping the load centered for a more upright, back-friendly pull.",["Stand inside a loaded trap bar with feet shoulder-width apart.","Hinge at the hips and knees to grip the handles.","Brace your core and set your back flat.","Drive through your heels and extend hips and knees to stand up.","Lock out at the top with shoulders pulled back.","Lower the bar back to the floor under control."],["Keep your chest up and back flat as you set your grip.","Push the floor away rather than yanking the bar with your back.","Stand fully upright at the top without leaning back."],{"start":"images/flat/hex-bar-deadlift-start.webp","peak":"images/flat/hex-bar-deadlift-peak.webp"},"strength"],["high-foot-leg-press","High-Foot Leg Press","beginner","leg_press","upper_legs","A leg press with the feet placed high on the platform, shifting more of the movement toward hip extension and the gluteus maximus while the back stays supported.",["Set the back pad and seat so your lower back stays supported and your knees can bend without your pelvis rolling under.","Place both feet high on the platform at about shoulder width, with the toes tracking in the same direction as the knees.","Lower the sled by bending the hips and knees until you reach a comfortable depth without the lower back lifting from the pad.","Press through the whole foot and extend the hips and knees without locking the knees aggressively.","Lower the sled under control and repeat for the desired number of repetitions."],["Keep the pelvis heavy against the pad; a high foot position does not justify rounding the lower back at the bottom.","Keep the heels and the whole foot planted rather than letting the toes carry the sled.","Use a depth that preserves pelvic position instead of chasing a deeper range with a tucked pelvis."],{"start":"images/flat/high-foot-leg-press-start.webp","peak":"images/flat/high-foot-leg-press-peak.webp"},"strength"],["high-knees","High Knees","beginner","bodyweight","full_body","A bodyweight cardio drill where the knees are driven up to hip height in rapid alternation.",["Stand tall with feet hip-width apart.","Drive one knee up toward the chest while pumping the opposite arm.","Quickly switch legs, mirroring the arm action.","Continue alternating at a fast pace.","Continue for the prescribed work interval."],["Drive the knees up to at least hip height.","Stay light on the balls of the feet.","Keep the torso upright - do not lean back."],{"main":"images/flat/high-knees-main.webp"},"cardio"],["high-plank","High Plank","beginner","bodyweight","core","A plank variation with arms fully extended in a push-up position.",["Start in a push-up position with arms fully extended.","Keep your body in a straight line from head to heels.","Brace your core and hold the position.","Breathe steadily throughout."],["Stack your shoulders directly above your wrists.","Squeeze your glutes to keep your hips from sagging.","Push the floor away to avoid sinking between your shoulder blades."],{"main":"images/flat/high-plank-main.webp"},"strength"],["hip-abduction","Machine Hip Abduction","beginner","hip_abduction_machine","upper_legs","A machine exercise targeting the outer hip muscles.",["Sit in the hip abduction machine with pads against your outer thighs.","Push your legs apart against the resistance.","Hold briefly at the widest point.","Return to the starting position with control.","Repeat."],["Sit tall and keep your back against the pad.","Don't let the weight stack slam down between reps.","Choose a resistance that allows a full range of motion."],{"start":"images/flat/hip-abduction-start.webp","peak":"images/flat/hip-abduction-peak.webp"},"strength"],["hip-adduction","Hip Adduction","intermediate","hip_adduction_machine","upper_legs","A machine exercise pressing the legs together against resistance, isolating and strengthening the inner-thigh adductors.",["Sit on the hip adduction machine with your back against the pad.","Place your legs against the pads with the machine set to a comfortable stretch.","Squeeze your legs together until the pads meet in the middle.","Hold the squeeze briefly in the fully closed position.","Let your legs open back out under control to the start.","Repeat for the desired number of reps."],["Choose a start width that stretches without straining your groin.","Move through the whole range at an even, controlled speed.","Do not let the weight stack slam down as your legs open back out."],{"start":"images/flat/hip-adduction-start.webp","peak":"images/flat/hip-adduction-peak.webp"},"strength"],["hip-thrust","Barbell Hip Thrust","intermediate","barbell","upper_legs","A compound glute exercise using a barbell across the hips.",["Sit on the floor with your upper back against a bench, barbell across your hips.","Drive your hips up until your thighs are parallel to the floor.","Squeeze your glutes at the top.","Lower your hips back down with control.","Repeat."],["Tuck your chin and keep your ribs down at the top.","Finish with your shins vertical, driving through your heels.","Reach full hip extension without arching your lower back."],{"start":"images/flat/hip-thrust-start.webp","peak":"images/flat/hip-thrust-peak.webp"},"strength"],["hollow-body-hold","Hollow Body Hold","intermediate","bodyweight","core","An isometric core hold borrowed from gymnastics, training total-body tension with the spine in a slight C-shape.",["Lie on your back with arms extended overhead and legs straight.","Press the lower back firmly into the floor.","Lift the shoulders, head, and legs slightly off the floor.","Hold the position with arms and legs extended, body in a shallow banana shape.","Hold for the prescribed time."],["Keep the lower back glued to the floor - if it lifts, raise the legs higher.","Tuck the chin slightly to engage the upper abs.","Bend the knees to scale if the position breaks."],{"main":"images/flat/hollow-body-hold-main.webp"},"strength"],["horizontal-leg-press","Horizontal Leg Press","beginner","leg_press","upper_legs","A machine leg press performed horizontally, targeting quads, glutes, and hamstrings.",["Sit in a horizontal leg press with your back against the pad and your feet shoulder-width apart on the footplate.","Press through your feet to straighten your legs, stopping just short of locking the knees.","Bend your knees under control until they come toward your chest.","Repeat."],["Do not let your lower back lift off the seat.","Avoid locking out the knees completely."],{"start":"images/flat/horizontal-leg-press-start.webp","peak":"images/flat/horizontal-leg-press-peak.webp"},"strength"],["human-flag","Human Flag","advanced","pull_up_bar","core","An advanced calisthenics isometric hold with the body horizontal on a vertical pole, parallel to the ground.",["Stand close to a sturdy vertical pole.","Grip the pole high with the top hand (overhand) and lower with the bottom hand (underhand).","Kick the legs up and out while pressing the bottom arm hard against the pole.","Extend the body horizontally so it forms a straight line parallel to the ground.","Hold the position with the body rigid for the target time.","Lower under control."],["Build up to the full flag with tucked and straddle progressions first.","The bottom arm pushes; the top arm pulls - they balance the lever.","Engage the lats, obliques, and glutes hard to stay rigid."],{"main":"images/flat/human-flag-main.webp"},"strength"],["hyperextension-hold-bench","Hyperextension Bench Hold","beginner","bodyweight","back","An isometric hold on a hyperextension bench: you lift your torso until your body forms one straight line from the heels to the head and hold it there. The erector spinae and the glutes stay under tension without the swinging of the dynamic back extension.",["Adjust the bench so that the pad sits just below your hip bones and your heels are hooked firmly behind the roller or pad.","Cross your arms over your chest and lower your torso toward the floor with a straight back.","Raise your torso until your body is in one straight line from your head to your heels.","Stop in that line and hold, with your glutes squeezed and your neck in line with your spine.","Keep your breathing slow and do not arch your lower back past the straight line while you hold for the planned time.","Lower your torso under control and rest."],["Stop at a straight line; leaning back past it hands the work to your lower back joints instead of the muscles.","Squeeze the glutes during the whole hold, so that the hips stay extended and the lower back is not doing the job alone.","Hold a weight plate against your chest only after you can hold bodyweight for a full minute."],{"main":"images/flat/hyperextension-hold-bench-main.webp"},"strength"],["inchworm","Inchworm","beginner","bodyweight","full_body","A bodyweight warm-up and mobility drill: from a standing forward fold you walk your hands out along the floor until your body is in a low plank, with the elbows bent as at the bottom of a push-up, then walk them back toward your feet. It stretches the hamstrings and calves while the shoulders, chest and trunk hold the low plank.",["Stand tall with your feet about hip-width apart.","Hinge forward at the hips and place your hands on the floor in front of your feet, bending the knees slightly if you need to.","Walk your hands forward one at a time, keeping your legs as straight as you comfortably can, until your body is in a straight line close to the floor.","Bend your elbows so your chest hovers just above the floor, as at the bottom of a push-up, and pause briefly with your trunk braced.","Walk your hands back toward your feet in small steps, raising your hips, until you are back in the forward fold.","Stand up, or go straight into the next repetition."],["Keep the knees as straight as you can so the hamstrings and calves get the stretch; a slight bend is fine if your hands do not reach the floor.","Brace the trunk in the low plank so the hips do not sag or pike up. For an easier version, stop in a straight-arm plank and skip the lowering.","Take small, controlled steps; walking out too far, too fast makes you collapse onto the floor."],{"start":"images/flat/inchworm-start.webp","peak":"images/flat/inchworm-peak.webp"},"strength"],["incline-bench-ez-bar-press","Incline EZ-Bar Bench Press","intermediate","ez_bar","chest","An incline press with an EZ-bar targeting the upper chest with a joint-friendly grip.",["Set bench to 30-45 degrees. Grip the EZ-bar with hands on the angled sections.","Lower the bar to your upper chest.","Press back up to full extension.","Repeat."],["The incline shifts emphasis to the upper pectorals.","Control the descent to avoid shoulder strain."],{"start":"images/flat/incline-bench-ez-bar-press-start.webp","peak":"images/flat/incline-bench-ez-bar-press-peak.webp"},"strength"],["incline-bench-press","Incline Barbell Bench Press","intermediate","barbell","chest","A barbell pressing movement on an incline bench targeting the upper chest.",["Lie on an incline bench set to 30-45 degrees.","Grip the bar slightly wider than shoulder-width and unrack.","Lower the bar to your upper chest.","Press the bar back up to full extension.","Repeat."],["Keep your shoulder blades pinched together against the bench.","Lower the bar without bouncing it off your chest.","Keep your feet planted and your glutes on the bench."],{"start":"images/flat/incline-bench-press-start.webp","peak":"images/flat/incline-bench-press-peak.webp"},"strength"],["incline-db-curl","Incline Dumbbell Curl","intermediate","dumbbell","upper_arms","A bicep curl on an incline bench for a deeper stretch of the long head.",["Sit on an incline bench set to 45 degrees, holding dumbbells at your sides.","Let your arms hang straight down with palms forward.","Curl the dumbbells up toward your shoulders.","Lower with control to full extension.","Repeat."],["Keep your head and shoulders against the bench throughout.","Don't let your elbows drift forward as you curl.","Avoid shrugging your shoulders forward as you lift the weight."],{"start":"images/flat/incline-db-curl-start.webp","peak":"images/flat/incline-db-curl-peak.webp"},"strength"],["incline-db-press","Incline Dumbbell Press","intermediate","dumbbell","chest","An incline pressing movement emphasizing the upper chest.",["Set bench to 30-degree incline and sit back with dumbbells at shoulder level.","Press dumbbells up and together until arms are fully extended.","Lower dumbbells back to shoulder level with control.","Repeat."],["Keep your wrists stacked directly over your elbows.","Press up without banging the dumbbells together at the top.","Keep your shoulder blades pulled back against the bench."],{"start":"images/flat/incline-db-press-start.webp","peak":"images/flat/incline-db-press-peak.webp"},"strength"],["incline-dumbbell-fly","Incline Dumbbell Fly","intermediate","dumbbell","chest","An incline isolation exercise opening dumbbells in a wide arc, stretching and targeting the upper chest.",["Lie back on an incline bench holding dumbbells above your chest.","Press the dumbbells up with palms facing each other.","Maintain a slight bend in your elbows throughout.","Lower the dumbbells in a wide arc until you feel a chest stretch.","Squeeze your chest to bring the dumbbells back together.","Repeat for the desired number of reps."],["Keep a fixed slight bend in your elbows throughout.","Lower only as far as a comfortable chest stretch allows.","Squeeze your chest to bring the dumbbells back together."],{"start":"images/flat/incline-dumbbell-fly-start.webp","peak":"images/flat/incline-dumbbell-fly-peak.webp"},"strength"],["incline-hammer-curl","Incline Hammer Curl","intermediate","dumbbell","upper_arms","A hammer curl performed on an incline bench for increased stretch and biceps long-head activation.",["Sit on an incline bench holding dumbbells with a neutral grip.","Allow arms to hang straight.","Curl the dumbbells up in a hammer motion.","Lower slowly.","Repeat."],["The incline provides a greater stretch.","Avoid swinging."],{"start":"images/flat/incline-hammer-curl-start.webp","peak":"images/flat/incline-hammer-curl-peak.webp"},"strength"],["incline-plank-hold","Incline Plank Hold","beginner","flat_bench","core","An easier version of the plank: with your forearms resting on a flat bench and your feet on the floor, you hold your body in a straight line from head to heels. The raised hands reduce the load on the shoulders and make it a good starting point for the full plank.",["Place your forearms on a flat bench, with your elbows directly under your shoulders.","Step your feet back until your body forms a straight line from head to heels.","Squeeze your glutes and pull your belly button toward your spine to keep your hips level.","Keep your neck long and look at a point on the bench slightly ahead of your hands.","Hold the position for the planned time while breathing steadily.","Step your feet in to finish."],["Do not let your hips sag toward the bench or pike up; your body should stay in one straight line.","Press your forearms into the bench and push the bench away to keep your shoulder blades wide.","Step your feet further back to make it harder, or closer to make it easier; make sure the bench cannot slide."],{"main":"images/flat/incline-plank-hold-main.webp"},"strength"],["incline-push-ups","Incline Push-Up","beginner","bodyweight","chest","A beginner-friendly push-up variation with hands elevated on a bench or step.",["Place your hands on a bench or elevated surface, shoulder-width apart.","Extend your legs behind you into a plank position.","Lower your chest toward the bench by bending your elbows.","Push back up to the starting position.","Repeat."],["Check that the elevated surface is stable before starting.","Keep your elbows tucked rather than flared out wide.","Progress to a lower surface as you get stronger."],{"start":"images/flat/incline-push-ups-start.webp","peak":"images/flat/incline-push-ups-peak.webp"},"strength"],["incline-treadmill-walk","Incline Treadmill Walk","beginner","treadmill","full_body","A steady uphill walk on an inclined treadmill belt, keeping one foot in contact with the belt throughout so the glutes and hamstrings work hard with almost no impact.",["Start the belt at a slow walking speed and step on, then raise the incline to your target gradient.","Walk with a long, deliberate stride, rolling from heel to toe and pushing the belt away behind you with each step.","Stand tall and lean from the ankles with the hill rather than folding forward at the waist.","Keep at least one foot on the belt at all times - walk the hill, do not break into a jog.","Let your arms swing naturally, or rest them lightly on the rails for balance without carrying your weight on them.","Hold the gradient for the desired time, then lower the incline and walk level for a few minutes to finish."],["Pick a speed you can still walk at. As soon as you need a flight phase to keep up, drop the speed or the incline - it is a walk, not a run.","Hanging your bodyweight off the handrails removes most of the work the hill is there to create; touch them for balance only.","The steep grade is what moves the effort from the quads into the glutes and hamstrings, so raise the incline before you raise the speed."],{"main":"images/flat/incline-treadmill-walk-main.webp"},"cardio"],["inverted-row","Inverted Row","intermediate","barbell","back","A horizontal bodyweight pulling exercise performed under a fixed bar, pulling the chest to the bar while keeping the body rigid.",["Set a barbell in a rack at about waist height.","Lie underneath and grip the bar slightly wider than shoulder-width with an overhand grip.","Hang with arms extended, heels on the floor, body straight from head to ankles.","Pull your chest to the bar, squeezing the shoulder blades together.","Lower yourself under control until arms are fully extended.","Repeat."],["Keep the core braced - no hip sag.","To make it harder, elevate your feet; to make it easier, walk your feet in toward the bar.","Pause briefly at the top with the chest against the bar."],{"start":"images/flat/inverted-row-start.webp","peak":"images/flat/inverted-row-peak.webp"},"strength"],["isometric-neck-side","Isometric Neck Lateral Flexion","beginner","bodyweight","shoulders","A static side-neck drill using the hand as resistance against the head, training the sternocleidomastoid and scalene without hardware.",["Sit or stand tall. Place the palm of one hand against the side of the head, above the ear.","Press the head into the hand while resisting equally with the hand - the head does not move.","Hold the isometric contraction for 5 to 10 seconds.","Release slowly, then repeat on the same side for the set.","Switch sides and repeat."],["Match the pressure; this is 50% effort, not a wrestling match.","Keep the jaw relaxed and the shoulders down."],{"main":"images/flat/isometric-neck-side-main.webp"},"strength"],["isometric-split-squat","Isometric Split Squat","intermediate","bodyweight","upper_legs","A held version of the split squat: you stand in a long lunge stance and stay in the bottom position with your front thigh near parallel to the floor. The continuous tension builds strength and control in the quadriceps and glutes of the front leg.",["Stand with one foot well forward and the other foot back, about a long stride apart, with your hands on your hips.","Keep your torso upright and lower straight down by bending both knees.","Lower until your front thigh is close to parallel with the floor and your back knee hovers just above the ground.","Keep your front heel flat and your front knee tracking over your toes.","Hold this position for the planned time, keeping your trunk tall and your weight spread through the front foot.","Press up to the top, then repeat on the other leg."],["Keep the back knee just off the floor so the front leg keeps working the whole time.","Do not let the front knee cave inward; push it gently over the middle toes.","Hold a lighter position higher up if the bottom is too intense; the quads should burn, not the knee joint."],{"main":"images/flat/isometric-split-squat-main.webp"},"strength"],["jackknife-sit-up","Jackknife Sit-Up","intermediate","bodyweight","core","A full-body crunch performed lying on the floor, lifting both legs and torso simultaneously to touch hands to feet.",["Lie face-up on the floor with arms extended overhead and legs extended straight.","Simultaneously lift the torso and the straight legs off the floor.","Reach the hands up toward the feet as the feet rise - meet above the hips.","Lower the torso and legs back to the floor under control.","Repeat for the recommended number of repetitions."],["Arms and legs move at the same speed - avoid a kick-first cheat.","If the lower back arches on the return, slow down and don't fully touch the floor."],{"start":"images/flat/jackknife-sit-up-start.webp","peak":"images/flat/jackknife-sit-up-peak.webp"},"strength"],["jefferson-curl","Jefferson Curl","intermediate","dumbbell","back","A loaded spinal-flexion drill: standing tall with a light weight, you round the spine one vertebra at a time and restack it, building segmental control and hamstring/spinal-erector flexibility under load.",["Stand tall holding a light dumbbell with straight arms, feet roughly hip-width.","Tuck your chin and begin rounding the spine from the top, one vertebra at a time.","Curl down slowly, letting the weight hang and keeping the legs mostly straight.","Reach the bottom with the back fully rounded and a stretch through the hamstrings.","Reverse it, restacking the spine from the bottom up back to standing."],["Use a very light weight -- this is a controlled mobility drill, not a heavy lift.","Round segment by segment; do not hinge at the hips like a stiff-leg deadlift.","Move slowly and never bounce at the bottom."],{"start":"images/flat/jefferson-curl-start.webp","peak":"images/flat/jefferson-curl-peak.webp"},"strength"],["jump-rope","Jump Rope","beginner","jump_rope","full_body","A classic cardio drill that trains calves, ankles, and timing with a rope and rhythmic hops.",["Hold a jump rope handle in each hand with the rope behind you.","Swing the rope overhead and forward in a smooth arc.","Hop just high enough for the rope to pass under your feet.","Land softly on the balls of the feet, knees slightly bent.","Keep a steady rhythm for the prescribed interval."],["Use the wrists to spin the rope, not the shoulders.","Hop low - only an inch or two off the floor.","Stay tall with elbows close to the sides."],{"main":"images/flat/jump-rope-main.webp"},"cardio"],["jump-squat","Jump Squat","beginner","bodyweight","upper_legs","A plyometric bodyweight squat where you explode upward into a vertical jump.",["Stand with feet shoulder-width apart.","Drop into a quarter-squat with the arms back.","Explode upward, swinging the arms up and jumping as high as you can.","Land softly back into a quarter-squat to absorb impact.","Repeat without pausing for the prescribed reps."],["Land softly with bent knees to absorb impact.","Drive the arms up to add height to the jump.","Keep the chest up - do not let the torso collapse."],{"start":"images/flat/jump-squat-start.webp","peak":"images/flat/jump-squat-peak.webp"},"plyometrics"],["jumping-jacks","Jumping Jacks","beginner","bodyweight","full_body","This classic full-body dynamic exercise elevates heart rate and targets the calves, shoulders, quads, and glutes, making it an excellent warm-up or conditioning movement.",["Stand tall with feet together and arms at your sides.","Simultaneously jump your feet out wide and raise your arms overhead.","Ensure your arms meet or nearly meet above your head.","Jump your feet back together while lowering your arms to your sides.","Maintain a continuous, rhythmic motion."],["Land softly on the balls of your feet to absorb impact.","Keep your core engaged throughout the movement.","Control your breathing; inhale as you jump out, exhale as you jump in.","Increase speed for a greater cardiovascular challenge."],{"start":"images/flat/jumping-jacks-start.webp","peak":"images/flat/jumping-jacks-peak.webp"},"cardio"],["kb-step-up-to-balance","Kettlebell Step-Up to Balance","intermediate","kettlebell","upper_legs","A loaded version of the step-up to balance: holding a kettlebell in each hand, you step onto a low platform, drive the free knee up in front of you and stand tall on the working leg before stepping back down. The quadriceps and glutes lift the body and the weights while the hips and ankle keep you steady.",["Stand facing a low, stable step or bench with a kettlebell in each hand, arms hanging at your sides.","Place one foot flat on top of the step.","Press through the whole of the front foot and straighten that leg to lift your body onto the step.","As you rise, drive the other knee up in front of you until the thigh is about hip height.","Stand tall on the working leg and hold the knee-up position for a moment without leaning back.","Lower the free foot back to the floor under control, then step the working leg down as well and repeat; switch legs after the planned repetitions."],["Keep the weights hanging at your sides and still; swinging them or pulling them up with your arms takes the work away from the legs.","Keep your trunk upright and your hips level during the balance hold rather than tilting toward the lifted knee.","Start with light weights and a low step; add load only when you can hold the balance position without wobbling."],{"start":"images/flat/kb-step-up-to-balance-start.webp","peak":"images/flat/kb-step-up-to-balance-peak.webp"},"strength"],["kettlebell-bottoms-up-hold","Kettlebell Bottoms-Up Hold","advanced","kettlebell","shoulders","A one-arm hold in which the kettlebell is held upside down by the handle at shoulder height, with the bell above your hand. Keeping the bell level demands a very firm grip and constant work from the forearm and the shoulder, which makes this a strong test of wrist and shoulder stability.",["Clean a kettlebell to your shoulder and flip it so that the bell points up and the handle sits in your fist.","Stand with your feet about shoulder-width apart and your free arm relaxed at your side.","Keep your forearm vertical and your elbow close to your ribs, with the bell directly above your hand.","Grip the handle firmly and keep your wrist straight, as if you were balancing a cup.","Hold the bell steady for the planned time, breathing slowly and keeping your shoulder down.","Lower the kettlebell with control, turn it the right way up and switch arms."],["Start with a very light bell; a weight that feels easy when held the normal way can be hard to keep level.","Keep the shoulder down and the wrist stacked over the forearm; if the bell tips, reset the position before it falls.","Stand in a clear space, away from people and furniture, in case the bell tips."],{"main":"images/flat/kettlebell-bottoms-up-hold-main.webp"},"strength"],["kettlebell-bulgarian-split-squat","Kettlebell Bulgarian Split Squat","intermediate","kettlebell","upper_legs","This unilateral squat variation builds lower body strength, muscle, and stability by elevating the rear foot and holding a kettlebell in each hand, primarily targeting the quadriceps and glutes.",["Stand facing away from a bench, placing one foot on it behind you, laces down. Hold a kettlebell in each hand at your sides.","Maintain an upright torso and engage your core.","Lower your body by bending both knees, allowing your front knee to track over your toes.","Descend until your front thigh is parallel to the floor or slightly below, keeping your rear knee close to the ground.","Drive through your front heel to return to the starting position, extending your hips and knees.","Complete all reps per side before switching."],["Ensure your front foot is far enough from the bench to allow a full range of motion without discomfort.","Keep your torso upright throughout the movement to maximize glute and quad engagement.","Control the eccentric (lowering) phase to build strength and stability.","With only one kettlebell, hold it in the hand opposite the front leg for an extra balance challenge."],{"start":"images/flat/kettlebell-bulgarian-split-squat-start.webp","peak":"images/flat/kettlebell-bulgarian-split-squat-peak.webp"},"strength"],["kettlebell-close-grip-floor-press","Kettlebell Close-Grip Floor Press","intermediate","kettlebell","upper_arms","A floor press performed with a single kettlebell gripped close together with both hands. The narrow grip and the floor stop on the elbows shift emphasis off the chest and onto the triceps, with no shoulder hyperextension.",["Lie on your back on the floor with the knees bent and feet flat.","Hold a single kettlebell by the handle with both hands, close together, the bell resting on the chest with elbows tucked tight to the ribs.","Brace the core and press the kettlebell straight up until the arms are fully extended.","Lower under control until the upper arms touch the floor and pause briefly.","Press back up to lockout.","Repeat for the recommended number of repetitions."],["Keep the elbows tucked at roughly 30-45 degrees from the torso - wide elbows turn it into a chest press.","The brief pause when the elbows touch the floor kills the bounce and forces a clean concentric.","Pick a bell you can control with two hands; the narrow grip is unforgiving if it tips."],{"start":"images/flat/kettlebell-close-grip-floor-press-start.webp","peak":"images/flat/kettlebell-close-grip-floor-press-peak.webp"},"strength"],["kettlebell-concentration-curl","Kettlebell Concentration Curl","beginner","kettlebell","upper_arms","A seated single-arm bicep isolation move: the elbow braces against the inner thigh while curling a kettlebell, keeping the upper arm still so the bicep does all the work.",["Sit on a bench with your feet wide, holding a kettlebell in one hand.","Brace the back of your upper arm against the inside of your thigh, letting the kettlebell hang.","Curl the kettlebell up toward your shoulder, keeping the elbow pinned against your leg.","Squeeze the bicep at the top, then lower slowly under control.","Finish all reps on one side, then switch arms."],["Keep the upper arm braced and still -- only the forearm moves.","Rotate the wrist slightly as you curl for a stronger peak contraction.","Use a lighter weight than a standard curl -- strict form matters more here."],{"start":"images/flat/kettlebell-concentration-curl-start.webp","peak":"images/flat/kettlebell-concentration-curl-peak.webp"},"strength"],["kettlebell-curl","Kettlebell Curl","beginner","kettlebell","upper_arms","A biceps curl with one kettlebell held by the handle in both hands. The kettlebell hangs in front of your thighs and you curl it up toward your chest, keeping the elbows close to your sides; sharing the load between two hands makes it an easy way to start training the biceps.",["Stand with your feet about shoulder-width apart and hold the kettlebell by its handle with both hands, so it hangs in front of your thighs.","Keep your elbows close to your sides, your chest tall and your shoulders relaxed.","Bend your elbows and curl the kettlebell up toward your chest without letting your upper arms swing forward.","Squeeze your biceps at the top, with the kettlebell close to your chest.","Lower the kettlebell slowly until your arms are straight again, keeping control of the swing of the bell.","Repeat for the planned repetitions."],["Hold the handle firmly with both hands and keep your wrists straight, so the kettlebell does not roll or tilt.","Do not lean back or swing your hips to lift the kettlebell; if you have to, the weight is too heavy.","Take about twice as long to lower the kettlebell as to lift it, so the biceps work through the whole descent."],{"start":"images/flat/kettlebell-curl-start.webp","peak":"images/flat/kettlebell-curl-peak.webp"},"strength"],["kettlebell-curl-iso-hold","Kettlebell Curl Iso Hold","beginner","kettlebell","upper_arms","An isometric version of the kettlebell curl: you curl a kettlebell held by the handle in both hands until your forearms are level with the floor and hold it there. The biceps and the brachialis stay under constant tension at the point where the lift is hardest.",["Stand with your feet about shoulder-width apart and hold the kettlebell by its handle with both hands, so it hangs in front of your thighs.","Keep your elbows close to your sides and your shoulders relaxed.","Curl the kettlebell up until your forearms are level with the floor and the elbows are bent to about 90 degrees.","Stop there and hold the kettlebell steady, hanging in front of your body.","Keep your upper arms still, your chest tall and your breathing slow while you hold for the planned time.","Lower the kettlebell under control and rest."],["Keep the kettlebell steady; swaying or letting it drop toward your thighs takes the load off the biceps.","Do not lean back to hold the weight; your trunk stays upright and your elbows stay close to your sides.","Choose a lighter kettlebell than for the curl itself, since the hold is hard at the halfway point."],{"main":"images/flat/kettlebell-curl-iso-hold-main.webp"},"strength"],["kettlebell-deadlift","Kettlebell Deadlift","intermediate","kettlebell","back","A foundational hip-hinge pull lifting a kettlebell from the floor, training the glutes, hamstrings, and lower back.",["Stand with feet shoulder-width apart and kettlebell between your feet.","Hinge at the hips and bend your knees to grip the handle.","Brace your core and set your back flat.","Drive through your heels to stand up with the kettlebell.","Lock out at the top with shoulders pulled back.","Lower the kettlebell back to the floor with control."],["Keep the kettlebell close to your shins as you lift.","Think of pushing the floor away rather than lifting with your back.","Look at a spot on the floor ahead to keep your neck neutral."],{"start":"images/flat/kettlebell-deadlift-start.webp","peak":"images/flat/kettlebell-deadlift-peak.webp"},"strength"],["kettlebell-farmers-walk","Kettlebell Farmer's Walk","intermediate","kettlebell","full_body","A loaded carry with heavy kettlebells at the sides, building grip strength and full-body stability.",["Stand between two heavy kettlebells.","Hinge and grip the handles firmly with a neutral grip.","Stand tall with shoulders back and core braced.","Walk forward with short, controlled steps.","Maintain an upright posture throughout the walk.","Set the weights down at the end of the distance."],["Keep your shoulders level and avoid leaning to either side.","Breathe steadily rather than holding your breath under load.","If your grip fails, set the weights down away from your feet."],{"main":"images/flat/kettlebell-farmers-walk-main.webp"},"strength"],["kettlebell-floor-press","Kettlebell Floor Press","intermediate","kettlebell","chest","A two-arm chest press performed lying on the floor with a kettlebell in each hand. The floor caps the ROM (triceps hit the floor before full stretch), making it shoulder-friendly and a great home option.",["Lie on your back on the floor with knees bent, feet flat.","Hold a kettlebell in each hand at the chest, bells resting on the outer forearms.","Press both kettlebells straight up until the arms are fully extended.","Lower under control until the triceps touch the floor - do not bounce.","Repeat for the recommended number of repetitions."],["Elbows stay about 45 degrees from the torso; do not flare.","The grip matters: keep the bells stable against the outside of the forearms.","The floor limits ROM by design - this is the feature, not the bug."],{"start":"images/flat/kettlebell-floor-press-start.webp","peak":"images/flat/kettlebell-floor-press-peak.webp"},"strength"],["kettlebell-goblet-lunge","Kettlebell Goblet Lunge","beginner","kettlebell","upper_legs","This unilateral compound exercise strengthens the quadriceps, glutes, and hamstrings by performing a lunge while holding a kettlebell in the goblet position, improving lower body strength and stability.",["Stand tall holding a kettlebell by its horns at chest height, elbows tucked, in the goblet position.","Take a controlled step forward with one leg, lowering your hips until both knees are bent at approximately 90 degrees.","Ensure your front knee is stacked over your ankle and your rear knee hovers just above the floor.","Drive through your front heel to return to the starting position, maintaining balance and core tension.","Complete all repetitions on one side before switching, or alternate legs per set."],["Keep your chest upright and core braced throughout the movement to protect your spine and maintain stability.","Focus on a controlled descent and a powerful drive up, engaging your glutes and quads.","Avoid letting your front knee collapse inward; keep it aligned with your toes."],{"start":"images/flat/kettlebell-goblet-lunge-start.webp","peak":"images/flat/kettlebell-goblet-lunge-peak.webp"},"strength"],["kettlebell-halo","Kettlebell Halo","beginner","kettlebell","shoulders","A shoulder-mobility drill where a kettlebell is circled around the head. Warms up the rotator cuff, thoracic spine, and shoulder girdle with minimal load.",["Stand tall, core braced, holding a light kettlebell by the horns (upside down) at chest height.","Raise the bell to one side of your head and pass it around the back in a smooth circle.","Bring it back to the starting position in front of your face.","Reverse direction every few reps.","Repeat for the recommended number of repetitions or time."],["Light weight only - this is mobility, not strength.","Keep the head stationary; the bell goes around, not the head.","If the bell drifts wide, shrink the circle - tight orbit, close to the skull."],{"start":"images/flat/kettlebell-halo-start.webp","peak":"images/flat/kettlebell-halo-peak.webp"},"strength"],["kettlebell-hammer-curl","Kettlebell Hammer Curl","beginner","kettlebell","upper_arms","A neutral-grip curl with a kettlebell in each hand, gripping the handles with the bells hanging below the hands. The offset mass and neutral grip bias the brachialis and brachioradialis.",["Stand holding a kettlebell in each hand, gripping the handles in a neutral position (palms facing the body).","Let the bells hang below your hands.","Keep the elbows tucked to the sides and curl both bells up toward the shoulders.","Squeeze at the top, then lower under control.","Repeat for the planned number of reps."],["Control the offset mass - the bells want to rotate at the bottom of the ROM.","Elbows stay still; only the forearms move.","Light load - this biases brachialis, not peak bicep size."],{"start":"images/flat/kettlebell-hammer-curl-start.webp","peak":"images/flat/kettlebell-hammer-curl-peak.webp"},"strength"],["kettlebell-hip-thrust","Kettlebell Hip Thrust","beginner","kettlebell","upper_legs","This exercise effectively targets the gluteus maximus and hamstrings, using a kettlebell to add resistance for powerful hip extension and glute development.",["Sit on the floor with your upper back against a bench, knees bent, and feet flat.","Place a kettlebell across your hips, holding it securely with both hands.","Drive through your heels, lifting your hips off the floor until your body forms a straight line from shoulders to knees.","Squeeze your glutes forcefully at the top of the movement.","Slowly lower your hips back down to the starting position with control."],["Keep your chin tucked towards your chest to maintain a neutral spine.","Focus on pushing through your heels to maximize glute activation.","Ensure your knees track in line with your toes throughout the movement.","Control the eccentric phase, resisting the weight as you lower your hips."],{"start":"images/flat/kettlebell-hip-thrust-start.webp","peak":"images/flat/kettlebell-hip-thrust-peak.webp"},"strength"],["kettlebell-kickstand-deadlift","Kettlebell Kickstand Deadlift","intermediate","kettlebell","back","A staggered-stance hip hinge with one kettlebell that loads the front leg while the back foot lightly stabilizes.",["Set a kettlebell on the floor beside the front foot and step the other foot back so only its toes touch the floor.","Hinge at the hips with a flat back and grip the kettlebell handle with one hand.","Drive through the front heel and extend the hips to stand tall, the kettlebell at your side.","Keep most of your weight on the front foot throughout.","Hinge back down, lowering the kettlebell toward the floor with a flat back. Switch sides after all reps."],["Keep the kettlebell close to the shin on the descent.","Stop at the point of hamstring stretch in the front leg.","Complete all reps on one side before switching."],{"start":"images/flat/kettlebell-kickstand-deadlift-start.webp","peak":"images/flat/kettlebell-kickstand-deadlift-peak.webp"},"strength"],["kettlebell-lunge-press","Kettlebell Lunge Press","intermediate","kettlebell","full_body","A combination exercise pressing a kettlebell overhead with one arm while lunging, training legs, shoulders, and core.",["Hold a kettlebell at shoulder height with one arm.","Step forward into a lunge with the opposite leg.","As you lunge, press the kettlebell overhead.","Lock out the arm at the top of the press.","Step back to standing while lowering the kettlebell.","Complete reps on one side, then switch."],["Brace your core to resist leaning toward the loaded side.","Keep your front knee tracking in line with your toes.","Avoid arching your back as you lock out overhead."],{"start":"images/flat/kettlebell-lunge-press-start.webp","peak":"images/flat/kettlebell-lunge-press-peak.webp"},"strength"],["kettlebell-offset-reverse-lunge-and-press","Kettlebell Offset Reverse Lunge and Press","intermediate","kettlebell","full_body","A reverse lunge with a single kettlebell pressed overhead, the offset load challenging balance and core stability.",["Hold a kettlebell at shoulder height on one side.","Step backward into a reverse lunge with the opposite leg.","As you reach the bottom of the lunge, press the kettlebell overhead.","Drive through your front heel to return to standing.","Lower the kettlebell back to shoulder height.","Complete reps on one side, then switch."],["Keep your hips square as you step back into the lunge.","Brace your trunk to resist bending toward the loaded side.","Lower your back knee with control instead of dropping into the bottom."],{"start":"images/flat/kettlebell-offset-reverse-lunge-and-press-start.webp","peak":"images/flat/kettlebell-offset-reverse-lunge-and-press-peak.webp"},"strength"],["kettlebell-overhead-carry","Kettlebell Overhead Carry","intermediate","kettlebell","shoulders","A loaded walk with a single kettlebell locked out overhead, where the bell hangs behind the wrist and pulls the arm backwards, making it harder to hold still than a dumbbell.",["Clean and press a kettlebell to lockout, letting the bell settle on the back of your forearm.","Straighten the elbow fully and turn the arm so the bell sits behind and above your wrist rather than off to the side.","Keep the shoulder active: push the weight up toward the ceiling and let the shoulder blade rotate up with it rather than forcing it down.","Brace your trunk and walk forward with even strides, keeping the bell stacked over your shoulder and hip.","Keep your wrist straight; letting it bend back is what makes an overhead bell feel unstable.","Carry for the desired distance, lower under control, then repeat on the other side."],["Go lighter than you would with a dumbbell. The offset mass makes the same weight noticeably harder to keep still.","A bent wrist is the usual failure point. If it keeps collapsing, drop the weight rather than fighting it for the whole distance.","Do both sides for the same distance - the unilateral load is the point of the exercise."],{"main":"images/flat/kettlebell-overhead-carry-main.webp"},"strength"],["kettlebell-overhead-hold","Kettlebell Overhead Hold","intermediate","kettlebell","shoulders","A one-arm isometric hold with the kettlebell locked out overhead. The shoulder, the upper back and the trunk work together to keep the bell steady over your head, which trains shoulder stability and the finish position of the press.",["Clean or press a kettlebell up so that your arm is straight overhead with the bell resting against the back of your forearm.","Stand with your feet about shoulder-width apart and your free arm relaxed at your side.","Lock out your elbow and push your hand up toward the ceiling so that your upper arm stays next to your ear.","Squeeze your glutes and brace your core so that your ribs do not flare and your lower back stays neutral.","Hold the bell steady over your shoulder for the planned time, breathing slowly.","Lower the kettlebell back to the rack position with control and switch arms."],["Keep the wrist straight and the bell over your shoulder joint; if it drifts forward, your shoulder will tire quickly.","Do not lean away from the bell; stay tall and let your trunk muscles hold you upright.","Start with a light kettlebell, since holding it overhead for time is a lot harder than pressing it once."],{"main":"images/flat/kettlebell-overhead-hold-main.webp"},"strength"],["kettlebell-overhead-tricep-extension","Kettlebell Overhead Tricep Extension","intermediate","kettlebell","upper_arms","An overhead tricep extension holding a kettlebell by the horns with both hands. The offset load pulls the bell behind the head for a deep long-head stretch.",["Stand or sit holding a kettlebell by the horns (upside down) with both hands overhead.","Arms fully extended, bell above the head.","Bend only the elbows to lower the bell behind the head in a controlled arc.","Keep the upper arms vertical and close to the head; only the forearms move.","Extend the elbows to return the bell overhead.","Repeat for the recommended number of repetitions."],["Grip the horns firmly - the bell wants to rotate at the bottom.","Elbows stay narrow; if they flare, drop the load.","A seated version on a bench with a back rest is easier on the lumbar."],{"start":"images/flat/kettlebell-overhead-tricep-extension-start.webp","peak":"images/flat/kettlebell-overhead-tricep-extension-peak.webp"},"strength"],["kettlebell-pistol-squat","Kettlebell Pistol Squat","advanced","kettlebell","upper_legs","An advanced single-leg squat performed holding a kettlebell at the chest for counterbalance.",["Hold a kettlebell at your chest with both hands.","Stand on one leg with the other leg extended forward.","Lower your hips down into a one-legged squat.","Keep your raised leg off the floor throughout.","Drive through your standing heel to return to standing.","Complete reps on one side, then switch."],["Keep your standing heel rooted to the floor throughout.","Descend slowly to stay in control at the bottom.","Push the kettlebell slightly forward to counterbalance as you sit back."],{"start":"images/flat/kettlebell-pistol-squat-start.webp","peak":"images/flat/kettlebell-pistol-squat-peak.webp"},"strength"],["kettlebell-pullover","Kettlebell Pullover","intermediate","kettlebell","back","A pullover on a flat bench with a kettlebell held by the horns. The deep overhead stretch hits the lats, long-head triceps, and serratus.",["Lie on a flat bench holding a kettlebell by the horns with both hands above the chest, arms nearly straight (slight elbow bend).","Keeping the elbow angle fixed, lower the bell overhead in an arc until the upper arms are in line with the torso.","Pull the bell back above the chest along the same arc.","Repeat for the recommended number of repetitions."],["Keep the lower back pressed into the bench - do not arch to steal ROM.","Grip the horns hard; the bell will try to flip over at the bottom.","Go only as deep as your shoulder mobility allows without pain."],{"start":"images/flat/kettlebell-pullover-start.webp","peak":"images/flat/kettlebell-pullover-peak.webp"},"strength"],["kettlebell-rack-hold","Kettlebell Rack Hold","beginner","kettlebell","shoulders","A one-arm hold with the kettlebell resting in the rack position, against your chest and the back of your forearm at the shoulder. The shoulder, the upper back and the trunk work to carry the bell comfortably, which is the starting position of the press, the squat and many other kettlebell lifts.",["Clean a kettlebell to your shoulder so that the bell rests against the back of your forearm and your upper arm, with the handle in your palm.","Stand with your feet about shoulder-width apart and your free arm relaxed at your side.","Keep your elbow close to your ribs and your wrist straight, so that the bell sits on your chest and shoulder, not on your wrist.","Stand tall, squeeze your glutes and brace your core without leaning away from the bell.","Hold the position for the planned time, breathing slowly.","Lower the kettlebell to the floor with control and switch arms."],["Let the bell rest on your forearm and chest rather than gripping it hard, so that your forearm does not tire first.","Keep the elbow tucked and the wrist straight; a bent wrist is the most common cause of a sore forearm.","Do not lean back or shift your hips sideways to counter the weight; stay tall."],{"main":"images/flat/kettlebell-rack-hold-main.webp"},"strength"],["kettlebell-reverse-lunge","Kettlebell Reverse Lunge","beginner","kettlebell","upper_legs","This compound unilateral exercise builds lower body strength and stability, primarily targeting the glutes and quads while engaging hamstrings, glute medius, and obliques.",["Stand tall holding a kettlebell by the horns at your chest, elbows tucked in (goblet hold).","Step one leg straight back, lowering your hips until both knees are bent at approximately 90 degrees.","Keep your front shin vertical and your chest upright, ensuring your back knee hovers just above the floor.","Drive through your front heel to return to the starting position.","Complete all reps per side before switching to the other side."],["Maintain a stable core throughout the movement to protect your spine.","Focus on a controlled descent and a powerful ascent.","Keep your front foot flat and distribute weight evenly through the heel and midfoot.","Avoid letting your front knee collapse inward; keep it tracking over your toes."],{"start":"images/flat/kettlebell-reverse-lunge-start.webp","peak":"images/flat/kettlebell-reverse-lunge-peak.webp"},"strength"],["kettlebell-reverse-wrist-curl","Kettlebell Reverse Wrist Curl","beginner","kettlebell","lower_arms","A reverse wrist curl holding one kettlebell by the handle with both hands, training the forearm extensors.",["Sit on a bench with your forearms on your thighs, palms down.","Hold one kettlebell by the handle with both hands, with the wrists hanging off the knees.","Let the wrists drop, lowering the kettlebell.","Lift the backs of the hands by extending the wrists.","Lower under control and repeat for the planned reps."],["Use a very light kettlebell - extensors fatigue quickly.","Move only at the wrists.","Hold the handle, not the bell."],{"start":"images/flat/kettlebell-reverse-wrist-curl-start.webp","peak":"images/flat/kettlebell-reverse-wrist-curl-peak.webp"},"strength"],["kettlebell-rotational-lunge","Kettlebell Rotational Lunge","intermediate","kettlebell","upper_legs","A reverse lunge holding a kettlebell at the chest, adding a torso rotation toward the front leg to work the legs and obliques together.",["Hold a kettlebell with both hands at your chest.","Step back into a lunge, lowering until both knees are bent.","Rotate your torso toward the front leg.","Move the kettlebell to that side at chest to shoulder height, arms almost straight.","Rotate back to the center and push through the front foot to return to standing.","Complete reps on one side, then switch."],["Keep the front knee over the ankle as you lower into the lunge.","Rotate from your torso and hips, not your knees.","Keep your chest tall as you rotate."],{"start":"images/flat/kettlebell-rotational-lunge-start.webp","peak":"images/flat/kettlebell-rotational-lunge-peak.webp"},"strength"],["kettlebell-russian-twist","Kettlebell Russian Twist","intermediate","kettlebell","core","A seated rotational core exercise twisting a kettlebell from side to side with the feet lifted.",["Sit on the floor with your knees bent and feet lifted off the ground.","Hold a kettlebell with both hands in front of your chest.","Lean back slightly to engage your core.","Rotate your torso to one side, bringing the kettlebell next to your hip.","Rotate to the opposite side in a controlled motion.","Repeat for the desired number of reps."],["Rotate your whole torso, not just your arms.","Keep your spine tall instead of slumping as you twist.","Keep your legs still as your torso moves side to side."],{"start":"images/flat/kettlebell-russian-twist-start.webp","peak":"images/flat/kettlebell-russian-twist-peak.webp"},"strength"],["kettlebell-shrug","Kettlebell Shrug","beginner","kettlebell","back","This isolation exercise targets the upper trapezius muscles by elevating the shoulders, enhancing shoulder stability and neck strength.",["Stand tall with feet hip-width apart, holding a kettlebell in each hand with palms facing your body.","Keep your arms straight and shoulders relaxed.","Elevate your shoulders straight up towards your ears, squeezing your traps at the top.","Hold the contraction briefly.","Slowly lower your shoulders back to the starting position with control.","Repeat for the desired number of repetitions."],["Focus on moving only your shoulders, keeping your arms straight throughout the movement.","Avoid rolling your shoulders; move them straight up and down.","Maintain a neutral spine and engaged core to prevent lower back strain.","Use a weight that allows for full range of motion and controlled execution."],{"start":"images/flat/kettlebell-shrug-start.webp","peak":"images/flat/kettlebell-shrug-peak.webp"},"strength"],["kettlebell-single-leg-deadlift","Kettlebell Single Leg Deadlift","intermediate","kettlebell","back","A single-leg hip hinge holding a kettlebell, training the hamstrings and glutes while challenging balance.",["Hold a kettlebell in one hand and stand on the opposite leg.","Hinge at the hip and lower the kettlebell toward the floor.","Extend your free leg straight back for balance.","Lower until your torso is parallel to the floor.","Drive through your standing heel to return to standing.","Complete reps on one side, then switch."],["Keep your hips square to the floor as you hinge.","Keep a soft bend in your standing knee.","Fix your eyes on one spot to steady your balance."],{"start":"images/flat/kettlebell-single-leg-deadlift-start.webp","peak":"images/flat/kettlebell-single-leg-deadlift-peak.webp"},"strength"],["kettlebell-skull-crusher","Kettlebell Skull Crusher","intermediate","kettlebell","upper_arms","A skull crusher lying on the floor, holding a kettlebell by the horns with both hands. The offset mass hangs below the wrists, adding a grip and control challenge.",["Lie on your back on the floor with your knees bent and feet flat, holding a kettlebell by the horns with both hands, arms extended above the chest.","Bend the elbows to lower the bell in a controlled arc past your forehead to behind your head, until it nearly touches the floor.","Keep the upper arms still, angled slightly back toward your head; only the forearms move.","Extend the elbows to press the bell back up.","Repeat for the recommended number of repetitions."],["Grip the horns firmly - the bell tries to rotate forward at the bottom.","Elbows stay narrow - if they flare, the load is too heavy.","Angle the upper arms slightly back toward the head to keep tension on the triceps at lockout."],{"start":"images/flat/kettlebell-skull-crusher-start.webp","peak":"images/flat/kettlebell-skull-crusher-peak.webp"},"strength"],["kettlebell-squat","Kettlebell Squat","beginner","kettlebell","upper_legs","A squat variation holding a kettlebell with both hands hanging low between the legs, adding load to a standard bodyweight squat pattern.",["Stand with feet shoulder-width apart, holding a kettlebell with both hands in front of you.","Let the kettlebell hang naturally between your legs as you brace your core.","Bend your hips and knees to squat down, keeping the kettlebell close to your body.","Drive through your feet to stand back up to the starting position.","Repeat for the desired number of reps."],["Keep your chest up and back flat throughout the movement.","Let the kettlebell act as a counterbalance to help you sit deeper into the squat.","Push your knees out in line with your toes as you descend."],{"start":"images/flat/kettlebell-squat-start.webp","peak":"images/flat/kettlebell-squat-peak.webp"},"strength"],["kettlebell-sumo-deadlift","Kettlebell Sumo Deadlift","beginner","kettlebell","upper_legs","A wide-stance deadlift with a single kettlebell between the feet. The wide stance and close-to-body load make this a quad-and-glute-dominant pattern that is easy to learn.",["Stand in a wide stance with toes pointed slightly out, a kettlebell on the floor between the feet.","Hinge down with a flat back, knees tracking over the toes, and grip the handle with both hands.","Drive through the floor and extend the hips and knees together to stand up.","Squeeze the glutes at the top.","Lower the bell under control back to the floor by pushing the hips back.","Repeat for the recommended number of repetitions."],["Knees track out over the toes - do not let them cave in.","Shoulders stay above the hips at the bottom; if the shoulders drop, narrow the stance.","Keep the bell close to the body throughout the lift."],{"start":"images/flat/kettlebell-sumo-deadlift-start.webp","peak":"images/flat/kettlebell-sumo-deadlift-peak.webp"},"strength"],["kettlebell-sumo-high-pull","Kettlebell Sumo High Pull","intermediate","kettlebell","shoulders","A wide-stance kettlebell pull from the floor to chin height, combining a hinge with an upright row for explosive upper-trap development.",["Stand with feet wider than shoulder-width, toes slightly turned out, a kettlebell on the floor between the feet.","Hinge down and grip the handle with both hands.","Drive through the feet and extend the hips explosively to pull the kettlebell up.","As it rises, pull the elbows up and out until the handle reaches chin height.","Lower the kettlebell back between the legs under control.","Repeat for the recommended number of repetitions."],["Drive with the hips first; the arms finish the movement.","Keep the elbows higher than the hands at the top - think wide and high, not narrow."],{"start":"images/flat/kettlebell-sumo-high-pull-start.webp","peak":"images/flat/kettlebell-sumo-high-pull-peak.webp"},"strength"],["kettlebell-svend-press","Kettlebell Svend Press","beginner","kettlebell","chest","A standing chest exercise pressing one kettlebell forward from the chest, held by the handle with both hands; squeezing the hands together on the handle keeps the pecs under tension.",["Stand holding one kettlebell by the handle with both hands at chest height, the bell hanging below your hands.","Squeeze your hands together on the handle to tense the chest.","Press the kettlebell forward until your arms are almost straight.","Pull it back to the chest under control.","Repeat for the prescribed reps."],["Keep pushing the hands toward each other on the handle throughout; without that squeeze it turns into a front-shoulder raise.","Use a light kettlebell - the long lever of straight arms dictates the load.","Keep the elbows slightly bent at the lockout."],{"start":"images/flat/kettlebell-svend-press-start.webp","peak":"images/flat/kettlebell-svend-press-peak.webp"},"strength"],["kettlebell-swing","Kettlebell Swing","intermediate","kettlebell","upper_legs","An explosive hip-hinge movement using a kettlebell for power and conditioning.",["Stand with feet shoulder-width apart, kettlebell on the floor in front.","Hinge at the hips, grip the kettlebell, and hike it back between your legs.","Explosively drive your hips forward to swing the kettlebell to chest height.","Let the kettlebell swing back between your legs.","Repeat in a fluid motion."],["Power the swing with your hips, not your arms or shoulders.","Treat it as a hinge, not a squat, with minimal knee bend.","Finish each rep standing tall with glutes squeezed and core tight."],{"start":"images/flat/kettlebell-swing-start.webp","peak":"images/flat/kettlebell-swing-peak.webp"},"strength"],["kettlebell-swing-clean","Kettlebell Swing Clean","intermediate","kettlebell","full_body","A hip-driven clean swinging the kettlebell from between the legs up to the shoulder rack position.",["Stand with feet shoulder-width apart, kettlebell between your feet.","Hinge at the hips and grip the handle with one hand.","Swing the kettlebell back between your legs.","Drive your hips forward to pull the kettlebell up to your shoulder.","Catch the kettlebell in the rack position on your shoulder.","Complete reps on one side, then switch."],["Keep the kettlebell close to your body on the way up.","Let the kettlebell roll around your wrist rather than flipping over it.","Relax your grip slightly at the top for a soft catch."],{"start":"images/flat/kettlebell-swing-clean-start.webp","peak":"images/flat/kettlebell-swing-clean-peak.webp"},"olympic"],["kettlebell-tibialis-raise","Kettlebell Tibialis Raise","intermediate","kettlebell","lower_legs","A shin exercise performed seated on a bench with a kettlebell hanging from the front of one foot. Lifting the toes toward the shin against the weight strengthens the muscles at the front of the lower leg.",["Sit at the end of a flat bench with one leg extended and the heel resting on the floor.","Hang a kettlebell by its handle from the front of the foot, over the toes.","Pull the toes up toward the shin as far as is comfortable while the heel stays on the floor.","Hold briefly at the top.","Lower the foot slowly until the toes point toward the floor.","Complete the repetitions, then switch legs."],["Keep the movement at the ankle; the knee and thigh stay still.","Start with a light kettlebell and increase gradually; the shin muscles tire quickly.","Lower slowly rather than letting the weight drop."],{"start":"images/flat/kettlebell-tibialis-raise-start.webp","peak":"images/flat/kettlebell-tibialis-raise-peak.webp"},"strength"],["kettlebell-turkish-get-ups","Kettlebell Turkish Get Ups","intermediate","kettlebell","full_body","A full-body kettlebell exercise that moves from lying to standing while holding the weight locked out overhead, training total-body strength, stability, and mobility.",["Lie on your back holding a kettlebell pressed overhead in one hand.","Bend the knee on the same side and plant the foot flat.","Roll up onto your opposite elbow, then to your hand.","Drive your hips up and sweep your straight leg back into a lunge.","Stand up fully while keeping the kettlebell locked out overhead.","Reverse the sequence to return to the start."],["Keep your eyes on the kettlebell until you are standing, then look forward.","Move slowly through each step - the get-up is a sequence, not one motion."],{"start":"images/flat/kettlebell-turkish-get-ups-start.webp","peak":"images/flat/kettlebell-turkish-get-ups-peak.webp"},"strength"],["kettlebell-windmills","Kettlebell Windmills","intermediate","kettlebell","full_body","A kettlebell exercise hinging sideways under a locked-out overhead weight, training oblique strength and shoulder stability.",["Stand holding a kettlebell locked out overhead in one hand.","Turn your feet about 45 degrees away from the working arm.","Keeping the kettlebell up, hinge at the hips sideways.","Reach your opposite hand down toward your foot.","Drive your hips back to stand up tall.","Complete reps on one side, then switch."],["Keep your eyes on the kettlebell throughout the movement.","Push your hips out to the side instead of rounding your spine.","Start light until the hinge pattern feels stable and controlled."],{"start":"images/flat/kettlebell-windmills-start.webp","peak":"images/flat/kettlebell-windmills-peak.webp"},"strength"],["kettlebell-wrist-curl","Kettlebell Wrist Curl","beginner","kettlebell","lower_arms","A wrist curl with a kettlebell in each hand, with the offset weight adding extra grip challenge.",["Sit on a bench with your forearms on your thighs, palms up.","Hold a kettlebell by the handle in each hand, with the wrists hanging off the knees.","Let the kettlebells rotate down toward the fingertips.","Curl them up by flexing the wrists, controlling the offset weight.","Lower under control and repeat for the planned reps."],["Hold the handles, not the bells, so the offset weight loads the grip.","Move only at the wrists.","Use a lighter load than you would for a dumbbell."],{"start":"images/flat/kettlebell-wrist-curl-start.webp","peak":"images/flat/kettlebell-wrist-curl-peak.webp"},"strength"],["knee-push-ups","Knee Push Ups","beginner","bodyweight","chest","A beginner-friendly push-up variation performed from the knees, reducing bodyweight load while building chest and triceps strength.",["Start in a push-up position with your knees on the floor.","Place your hands shoulder-width apart on the ground.","Keep your body in a straight line from knees to shoulders.","Lower your chest toward the floor by bending your elbows.","Press through your hands to return to the starting position.","Repeat for the desired number of reps."],["Squeeze your glutes to keep your hips from sagging.","Keep your elbows at roughly a 45-degree angle from your torso.","Lower with control instead of dropping your chest quickly."],{"start":"images/flat/knee-push-ups-start.webp","peak":"images/flat/knee-push-ups-peak.webp"},"strength"],["knee-to-chest-stretch","Knee-to-Chest Stretch","beginner","bodyweight","upper_legs","A lying stretch that releases the glutes and lower back by hugging one knee into the chest.",["Lie on your back with both legs straight.","Pull one knee in and hug it to your chest with both hands.","Keep the other leg relaxed on the floor.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep your head and shoulders relaxed on the floor.","Relax and keep breathing throughout."],{"main":"images/flat/knee-to-chest-stretch-main.webp"},"stretching"],["kneeling-cable-row","Kneeling Cable Row","beginner","cable","back","A cable row performed from a tall kneeling position, eliminating hip drive and keeping tension on the upper back throughout.",["Set a cable pulley to about chest height and attach a rope or double-D handle.","Kneel upright facing the stack far enough back that the weight stack doesn't bottom out.","Grab the handle with both hands and hold it out in front at chest height.","Row the handle to the sternum by driving the elbows back and squeezing the shoulder blades together.","Return under control to the stretched starting position.","Repeat for the recommended number of repetitions."],["Stay tall - no leaning back to finish the rep.","The tall-kneeling stance forces the core to resist rotation on every pull."],{"start":"images/flat/kneeling-cable-row-start.webp","peak":"images/flat/kneeling-cable-row-peak.webp"},"strength"],["kneeling-hip-flexor-stretch","Kneeling Hip Flexor Stretch","beginner","bodyweight","upper_legs","A half-kneeling stretch that opens the hip flexors of the rear leg by pressing the hips forward.",["Kneel on one knee with the other foot flat in front.","Keep your torso upright and core gently braced.","Press your hips forward until the front of the rear hip stretches.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Squeeze the glute of the kneeling leg to protect the lower back.","Avoid arching your lower back."],{"main":"images/flat/kneeling-hip-flexor-stretch-main.webp"},"stretching"],["kneeling-wrist-stretch","Kneeling Wrist Stretch","beginner","bodyweight","lower_arms","A kneeling stretch for the forearm flexors and wrists, with palms down and fingers pointing back.",["Kneel on all fours and place your palms flat on the floor.","Turn your hands so the fingers point back toward your knees.","Keep your palms down and rock your weight back gently.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your palms flat as you lean back.","Stretch to mild tension, never to pain."],{"main":"images/flat/kneeling-wrist-stretch-main.webp"},"stretching"],["l-sit","L Sit","advanced","dip_station","full_body","An advanced static hold with legs extended parallel to the floor, demanding hip flexor and core strength.",["Sit on the floor or press up on parallel bars with arms straight.","Lock your elbows and depress your shoulders.","Lift your legs straight out in front of you parallel to the floor.","Form an L shape with your body.","Hold the position for the prescribed duration.","Lower your legs with control to exit."],["Bend your knees into a tuck position if the full hold is too hard.","Point your toes and squeeze your quads to keep legs straight.","Breathe steadily during the hold rather than holding your breath."],{"main":"images/flat/l-sit-main.webp"},"strength"],["landmine-press","Landmine Press","intermediate","barbell","shoulders","A two-handed shoulder press using one end of a barbell anchored in a landmine attachment, allowing a natural arc that is easier on the shoulder joint.",["Load one end of a barbell into a landmine attachment and load the other end with a plate.","Stand in a staggered or square stance and cup the sleeve end of the barbell in both hands at chest height.","Brace your core and press the bar forward and upward along its natural arc.","Fully extend your arms without locking the elbows, then lower the bar back under control.","Keep both hands on the bar throughout and repeat for the desired number of reps."],["Keep your torso upright and avoid leaning excessively into the press.","The angled path makes it more shoulder-friendly than a strict overhead press.","Use a push-press leg drive for heavier loads."],{"start":"images/flat/landmine-press-start.webp","peak":"images/flat/landmine-press-peak.webp"},"strength"],["landmine-single-arm-overhead-hold","Landmine Single-Arm Overhead Hold","intermediate","barbell","shoulders","A one-arm isometric hold at the top of the landmine press: you press the end of the barbell overhead and stay locked out. The shoulder, the chest and the serratus keep the bar steady while the trunk resists the sideways pull of the angled bar.",["Set one end of a barbell in a landmine post or in a corner and stand facing the free end in a staggered stance, feet about shoulder-width apart.","Hold the end of the bar with one hand at the shoulder and keep your other hand on your hip.","Press the bar up and forward until your arm is straight and your hand is above and slightly in front of your shoulder.","Lock out your elbow and push your shoulder blade around your ribs without shrugging.","Hold the bar steady for the planned time, with your trunk braced so that you do not lean to the side.","Lower the bar to your shoulder under control and switch arms."],["Keep the ribs down and the glutes squeezed so that you do not arch your lower back as you hold.","Push the shoulder away from your ear at the top; do not let it shrug up toward your neck.","Use a lighter load than for the press; holding for time is harder than a single repetition."],{"main":"images/flat/landmine-single-arm-overhead-hold-main.webp"},"strength"],["lat-pulldown","Lat Pulldown","beginner","cable","back","A cable machine exercise targeting the latissimus dorsi.",["Sit at the lat pulldown machine with thighs secured under the pads.","Grip the wide bar with an overhand grip.","Pull the bar down to your upper chest, squeezing your lats.","Slowly return the bar to the starting position.","Repeat."],["Drive your elbows down and back rather than pulling with your hands.","Avoid leaning far back or using momentum to move the weight.","Keep your chest lifted and shoulders down away from your ears."],{"start":"images/flat/lat-pulldown-start.webp","peak":"images/flat/lat-pulldown-peak.webp"},"strength"],["lateral-leg-swing","Lateral Leg Swing","beginner","bodyweight","upper_legs","A dynamic hip-mobility drill in which one leg swings across the body and out to the side while the standing leg and trunk remain controlled.",["Stand tall and brace the trunk, using a stable support if needed.","Shift the weight onto one leg and lift the other foot slightly from the floor.","Swing the free leg across the front of the body.","Reverse the motion and swing it out to the side through a comfortable range.","Continue smoothly, then change legs."],["Keep the pelvis facing forward instead of rotating with the swinging leg.","Use a range you can control without leaning the torso.","Let the movement grow gradually rather than forcing the first repetition."],{"start":"images/flat/lateral-leg-swing-start.webp","peak":"images/flat/lateral-leg-swing-peak.webp"},"stretching"],["lateral-raise","Dumbbell Lateral Raise","beginner","dumbbell","shoulders","An isolation movement targeting the lateral deltoid for shoulder width.",["Stand holding dumbbells at your sides.","Raise the dumbbells out to the sides until arms are parallel to the floor.","Lower under control.","Repeat."],["Slight bend in the elbows.","Lead with your elbows, not your hands."],{"start":"images/flat/lateral-raise-start.webp","peak":"images/flat/lateral-raise-peak.webp"},"strength"],["lean-back-90-90-hold","Lean-Back 90/90 Hold","beginner","bodyweight","upper_legs","A gentler version of the 90/90 hip hold: from the same 90/90 leg position, you lean your trunk back and support it on your hands behind you. Leaning back takes some load off the hips while keeping the front leg turned out and the back leg turned in.",["Sit on the floor with your front leg bent in front of you to about 90 degrees and your back leg out to the side, also bent to about 90 degrees.","Place your hands on the floor behind your hips, fingers pointing back or to the side.","Lean your trunk back onto your hands, keeping your arms straight and your chest open.","Let both knees settle toward the floor without forcing them.","Hold the position, breathing slowly, feeling a mild stretch in the outer hip of the front leg and the front of the hip of the back leg.","Hold for the planned time, then switch the legs and hold on the other side."],["Use this version when the upright 90/90 is too intense; lean further back on your hands to ease the stretch.","Keep your shoulders down and away from your ears rather than hanging on your arms.","Move slowly into the position and keep it pain-free, especially at the knees."],{"main":"images/flat/lean-back-90-90-hold-main.webp"},"stretching"],["leg-curl","Lying Leg Curl","beginner","leg_curl","upper_legs","An isolation exercise for the hamstrings using a leg curl machine.",["Lie face down on the leg curl machine with ankles under the pad.","Curl your heels toward your glutes.","Squeeze your hamstrings at the top.","Lower with control.","Repeat."],["Keep your hips pressed into the bench throughout the set.","Avoid jerking the weight up with your lower back.","Use a full range of motion without letting the stack slam down."],{"start":"images/flat/leg-curl-start.webp","peak":"images/flat/leg-curl-peak.webp"},"strength"],["leg-extension","Leg Extension","beginner","leg_extension","upper_legs","An isolation exercise for the quadriceps using a machine.",["Sit in the leg extension machine with ankles behind the pad.","Extend your legs until they are straight.","Squeeze your quads at the top.","Lower with control.","Repeat."],["Adjust the seat so your knees align with the machine's pivot point.","Keep your back pressed against the pad throughout.","Avoid swinging the weight up with momentum."],{"start":"images/flat/leg-extension-start.webp","peak":"images/flat/leg-extension-peak.webp"},"strength"],["leg-press","Leg Press","beginner","leg_press","upper_legs","A machine-based compound movement for the quads and glutes.",["Sit in the leg press machine with feet shoulder-width apart on the platform.","Release the safety catches and lower the platform by bending your knees.","Push the platform back up until legs are nearly straight.","Do not lock your knees at the top.","Repeat."],["Keep your lower back and hips pressed into the seat.","Lower only as far as you can without your hips tucking under.","Drive evenly through your whole foot, not just your toes."],{"start":"images/flat/leg-press-start.webp","peak":"images/flat/leg-press-peak.webp"},"strength"],["leg-swing-front-to-back","Front-to-Back Leg Swing","beginner","bodyweight","upper_legs","A dynamic hip-mobility drill that swings one straight or softly bent leg forwards and backwards while the standing side stabilises the pelvis.",["Stand tall beside a stable support and shift the weight onto the inside leg.","Brace the trunk and lift the outside foot slightly from the floor.","Swing the free leg forwards through a comfortable range.","Let it travel back behind the body without arching the lower back.","Continue smoothly, then repeat with the other leg."],["Keep the torso tall and let the movement come from the hip.","Use a small range first and increase it as the hip warms up.","Keep the standing foot planted and the pelvis facing forward."],{"start":"images/flat/leg-swing-front-to-back-start.webp","peak":"images/flat/leg-swing-front-to-back-peak.webp"},"stretching"],["legs-up-the-wall","Legs-Up-the-Wall Pose","beginner","bodyweight","upper_legs","A restorative position with the hips close to a wall and the legs resting vertically against it, used for recovery rather than for effort.",["Sit sideways next to a wall with one hip touching it.","Swing the legs up the wall as you lie back, so the hips end close to the base of the wall.","Let the legs rest against the wall with the feet relaxed and the arms open at the sides.","Stay for the prescribed time, breathing slowly.","Bend the knees and roll to one side to come out."],["Slide the hips a few centimetres away from the wall if the hamstrings feel pulled.","Place a folded blanket under the pelvis for a gentler, more supported version.","Keep the legs passive; this position is meant to cost no effort."],{"main":"images/flat/legs-up-the-wall-main.webp"},"stretching"],["lizard-stretch","Lizard Stretch","beginner","bodyweight","upper_legs","A deep lunge stretch that opens the hip flexors, groin and glutes with the forearms lowered toward the floor.",["Step one foot forward into a deep lunge, foot placed wide.","Lower both forearms toward the floor inside the front foot.","Extend the back leg straight and let the hips sink.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Rest on your hands instead of forearms for an easier version.","Stretch to mild tension, never to pain."],{"main":"images/flat/lizard-stretch-main.webp"},"stretching"],["locust-pose","Locust Pose","beginner","bodyweight","back","A prone hold in which the chest, arms and legs lift away from the floor, so the whole back line works isometrically without any load.",["Lie face down with the arms alongside the body and the forehead on the mat.","Lengthen the back of the neck and reach the fingertips towards the feet.","Lift the chest, arms and both legs off the floor at the same time.","Hold the lifted position for the prescribed time, keeping the gaze down.","Lower everything down together and rest."],["Lift with the length of the spine rather than cranking the head up.","Keep the legs about hip-width apart and the knees straight.","Start with the legs only, then add the chest, if the full lift is too much."],{"main":"images/flat/locust-pose-main.webp"},"strength"],["low-lunge","Low Lunge","beginner","bodyweight","upper_legs","A kneeling split-stance stretch: the back knee rests on the floor while the hips sink forward, lengthening the hip flexor of the rear leg.",["From kneeling, step one foot forward so the knee stacks over the ankle.","Lower the back knee to the floor and untuck that foot.","Tuck the tailbone slightly and press the hips forward until you feel the front of the back thigh lengthen.","Lift the chest, raise the arms if it feels good, and hold for the prescribed time.","Step back and repeat on the other side."],["Pad the back knee with a folded mat if the floor is hard.","Squeeze the back glute to deepen the stretch without arching the lower back.","Keep the front knee above the ankle rather than letting it slide forward."],{"main":"images/flat/low-lunge-main.webp"},"stretching"],["low-lunge-to-half-split","Low Lunge to Half Split","beginner","bodyweight","upper_legs","A moving hamstring and hip-flexor sequence: from a low lunge the hips shift back over the rear knee and the front leg straightens into a half split, then the hips travel forward into the lunge again.",["Start in a low lunge with the back knee on the floor and the front knee over the ankle.","Press the hands into the floor or onto blocks either side of the front foot.","Shift the hips back over the back knee and straighten the front leg, flexing that foot.","Hold the half split briefly, then glide the hips forward into the low lunge again.","Repeat for the desired number of repetitions and change sides."],["Keep the back of the front leg long: bend the knee slightly rather than rounding the spine to reach.","Move the hips, not the front foot; the foot stays where it started.","Pad the back knee and use blocks under the hands if the floor is out of reach."],{"start":"images/flat/low-lunge-to-half-split-start.webp","peak":"images/flat/low-lunge-to-half-split-peak.webp"},"stretching"],["lunge","Lunge","intermediate","bodyweight","upper_legs","A bodyweight forward lunge stepping into a long stride, training the quads, glutes, and balance one leg at a time.",["Stand tall with your feet hip-width apart.","Step forward with one leg into a long stride.","Lower your back knee toward the floor until both knees form 90-degree angles.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],["Take a stride long enough for both knees to reach about 90 degrees.","Keep your torso upright and eyes forward.","Push through the front heel to return in one strong motion."],{"start":"images/flat/lunge-start.webp","peak":"images/flat/lunge-peak.webp"},"strength"],["lying-leg-raise","Lying Leg Raise","beginner","bodyweight","core","A floor-based core exercise that targets the lower abs and hip flexors by raising straight legs from a supine position.",["Lie flat on your back with legs straight and hands under your lower back or gripping a stable surface behind your head.","Keeping your legs together and core braced, raise them to vertical (or as high as flexibility allows).","Pause briefly at the top.","Lower your legs slowly toward the floor without letting them touch.","Repeat for the desired reps."],["Press your lower back into the floor throughout to protect the lumbar spine.","Avoid swinging - control the descent to maximize tension.","Bend the knees slightly if hamstring flexibility is a limiting factor."],{"start":"images/flat/lying-leg-raise-start.webp","peak":"images/flat/lying-leg-raise-peak.webp"},"strength"],["lying-quad-stretch","Lying Quad Stretch","beginner","bodyweight","upper_legs","A floor stretch for the front of the thigh: lying on your side, you bend the top knee and pull the heel toward your glute with your hand. Lying down takes balance out of the stretch, so you can relax and let the quadriceps lengthen.",["Lie on your side with your legs straight and your head resting on your lower arm.","Bend your top knee and take hold of that foot or ankle with your top hand.","Gently pull your heel toward your glute, keeping your knees close together.","Tuck your pelvis slightly so your lower back does not arch.","Hold the stretch for the planned time while breathing slowly.","Release the foot, roll to the other side and repeat."],["Keep the knees side by side; letting the top knee drift forward turns it into a hip stretch.","Do not pull the heel hard; ease into a stretch you feel in the front of the thigh, not in the knee.","If you cannot reach the foot, loop a towel or strap around the ankle and pull on that."],{"main":"images/flat/lying-quad-stretch-main.webp"},"stretching"],["lying-tricep-extension","Lying Tricep Extension","intermediate","dumbbell","upper_arms","A lying triceps isolation exercise: one dumbbell held in both hands is lowered behind the head by bending the elbows, then pressed back up.",["Lie flat on a bench and hold one dumbbell in both hands straight above your chest.","Keep your upper arms close to vertical, elbows pointing up toward the ceiling.","Lower the dumbbell behind your head by bending your elbows.","Extend your arms back to the starting position.","Squeeze your triceps at the top.","Repeat for the desired number of reps."],["Keep your elbows pointing up and tucked in rather than flaring out to the sides.","Move only at the elbows, not the shoulders.","Lower the weight under control rather than dropping it."],{"start":"images/flat/lying-tricep-extension-start.webp","peak":"images/flat/lying-tricep-extension-peak.webp"},"strength"],["machine-back-extension","Machine Back Extension","beginner","back_extension_machine","back","A seated machine isolation exercise for the lower back: with the hips and legs held in place, the torso is driven backwards against a padded lever to extend the spine against a weight stack.",["Sit in the back extension machine with your feet flat on the foot platform and the roller pad set behind your upper back, just below the shoulder blades.","Grip the handles at your sides and let your torso come forward into a slight flexion - this is the starting position.","Push back against the pad by extending your spine until your torso is leaning back and your lower back is fully contracted.","Pause briefly at full extension, then return to the starting position under control, resisting the weight stack on the way back.","Repeat for the desired number of reps."],["Set the pad across your upper back just below the shoulder blades - too high and it presses on your neck, too low and you lose range of motion.","Extend with your lower back rather than throwing your head and shoulders backwards, and keep both directions slow.","Stop at a neutral, fully extended trunk instead of forcing the spine past it, and start light - the lower back responds better to controlled reps than to heavy loads."],{"start":"images/flat/machine-back-extension-start.webp","peak":"images/flat/machine-back-extension-peak.webp"},"strength"],["machine-bicep-curl","Machine Bicep Curl","beginner","bicep_curl_machine","upper_arms","A machine-based bicep curl for isolated arm training.",["Sit in the machine and adjust the pad to your arm length.","Grip the handles with an underhand grip.","Curl the handles toward your shoulders.","Lower with control.","Repeat."],["Keep your upper arms pressed into the pad throughout the set.","Avoid shrugging your shoulders as you curl.","Extend your arms fully at the bottom without bouncing."],{"start":"images/flat/machine-bicep-curl-start.webp","peak":"images/flat/machine-bicep-curl-peak.webp"},"strength"],["machine-calf-raise","Machine Calf Raise","beginner","standing_calf_raise_machine","lower_legs","A standing machine exercise isolating the calves through a full stretch and rise onto the toes.",["Stand in the calf raise machine with the balls of your feet on the platform.","Position the shoulder pads firmly.","Lower your heels below the platform for a full stretch.","Push through the balls of your feet to rise onto your toes.","Squeeze your calves at the top.","Lower with control and repeat."],["Keep your knees straight but not locked throughout the movement.","Pause briefly in the stretched position instead of bouncing.","Avoid cutting the range of motion short as fatigue sets in."],{"start":"images/flat/machine-calf-raise-start.webp","peak":"images/flat/machine-calf-raise-peak.webp"},"strength"],["machine-chest-fly","Machine Chest Fly","beginner","chest_fly_machine","chest","A chest isolation exercise performed on a machine that arcs the handles together in front of the body.",["Sit in the chest fly machine and adjust the seat so the handles align with your chest.","Grip the handles with a slight bend in your elbows.","Bring the handles together in front of your chest in a smooth arc.","Squeeze your pectorals at the point of peak contraction.","Return under control to the starting position without slamming the weight.","Repeat for the desired number of reps."],["Keep a slight, fixed bend in your elbows throughout.","Focus on squeezing the chest rather than pushing with the arms.","Control the return instead of letting the weight stack slam."],{"start":"images/flat/machine-chest-fly-start.webp","peak":"images/flat/machine-chest-fly-peak.webp"},"strength"],["machine-preacher-curl","Machine Preacher Curl","beginner","preacher_curl_machine","upper_arms","A preacher curl performed on a plate-loaded or selectorized machine, locking the elbows on a pad and providing a fixed strength curve.",["Sit at a preacher curl machine and adjust the seat so your armpits sit at the top of the pad.","Place the upper arms flat on the pad and grip the handles.","Start with the arms extended - but not locked - at the bottom.","Curl the handles up by flexing the elbows; squeeze hard at the top.","Lower slowly back to the starting position and repeat."],["Do not let the elbows lift off the pad at the top.","Stop just short of full extension at the bottom to protect the elbow tendons."],{"start":"images/flat/machine-preacher-curl-start.webp","peak":"images/flat/machine-preacher-curl-peak.webp"},"strength"],["machine-reverse-fly","Machine Reverse Fly","beginner","reverse_fly_machine","shoulders","A seated machine exercise for the rear deltoids, also known as the reverse pec deck: facing the pad, you sweep the two handles out and back in a wide arc against the weight stack. The pad keeps the torso still, so the work stays on the back of the shoulders and the muscles between the shoulder blades.",["Adjust the seat so the handles are at shoulder height, then sit facing the machine with your chest against the pad.","Grip the handles with your arms reaching forward and a slight bend in the elbows.","Keep your shoulders down and away from your ears and brace your trunk.","Sweep the handles out and back in a wide arc, leading with the elbows, until your arms are roughly in line with your shoulders.","Squeeze your shoulder blades together briefly without leaning back off the pad.","Return the handles forward slowly and repeat for the planned repetitions."],["Lead with the elbows rather than pulling with the hands, so the rear deltoids do the work and not the biceps.","Keep the chest on the pad and the neck relaxed; leaning back or shrugging moves the load to the upper trapezius.","Choose a weight you can lower under control; a lighter load with a slow return works the rear deltoids better than a heavy swing."],{"start":"images/flat/machine-reverse-fly-start.webp","peak":"images/flat/machine-reverse-fly-peak.webp"},"strength"],["machine-seated-crunch","Machine Seated Crunch","beginner","ab_crunch_machine","core","An abdominal isolation exercise performed on a seated machine that flexes the spine against resistance.",["Sit in the abdominal crunch machine and grip the handles.","Position the chest pad against your upper body.","Contract your abs to crunch your torso forward and down.","Squeeze at the bottom of the movement.","Return to the starting position with control.","Repeat for the desired number of reps."],["Initiate the movement with your abs, not your arms.","Exhale as you crunch forward.","Avoid using momentum by rocking your body."],{"start":"images/flat/machine-seated-crunch-start.webp","peak":"images/flat/machine-seated-crunch-peak.webp"},"strength"],["machine-shoulder-press","Machine Shoulder Press","beginner","shoulder_press_machine","shoulders","A machine-based overhead pressing movement for the shoulders.",["Sit in the machine with your back against the pad.","Grip the handles at shoulder level.","Press the handles overhead until arms are fully extended.","Lower with control to the starting position.","Repeat."],["Keep your lower back pressed into the pad without overarching.","Keep your wrists stacked directly over your elbows as you press."],{"start":"images/flat/machine-shoulder-press-start.webp","peak":"images/flat/machine-shoulder-press-peak.webp"},"strength"],["machine-triceps-extension","Machine Triceps Extension","beginner","tricep_extension_machine","upper_arms","A seated machine isolation exercise in which the upper arms stay supported on a pad while the elbows extend against two handles, loading the triceps along a fixed path without help from the shoulders or torso.",["Sit in the tricep extension machine with your back against the seat pad and your upper arms resting flat on the arm pad in front of your chest.","Take a handle in each hand with your elbows bent and your hands up near shoulder height.","Keeping your upper arms pressed into the pad, extend your elbows to drive the handles down and away until your arms are straight.","Squeeze your triceps at full extension, then bend your elbows to return to the start under control.","Repeat for the desired number of reps."],["Set the seat height so your upper arms lie flat on the pad and your elbows line up with the machine's pivot - that alignment is what keeps the work on the triceps.","Keep your upper arms glued to the pad; letting them lift turns the movement into a press and takes the triceps out of it.","Straighten your arms fully without snapping the elbows, and resist on the way back instead of letting the weight stack drop."],{"start":"images/flat/machine-triceps-extension-start.webp","peak":"images/flat/machine-triceps-extension-peak.webp"},"strength"],["medicine-ball-side-throw","Medicine Ball Side Throw","beginner","medicine_ball","core","A rotational power exercise: standing side-on with a medicine ball held at your hip, you turn your hips and torso and throw the ball out to the side with both hands. The obliques and the rest of the trunk turn the body, and the hips start the rotation.",["Stand with your feet a little wider than shoulder-width, holding a medicine ball with both hands in front of your torso.","Turn your torso and the ball toward your back hip, bending your knees slightly and keeping your chest up.","Start the throw by turning your back hip forward and pivoting on the ball of your back foot.","Let your torso and arms follow, throwing the ball out to the side with both hands.","Finish facing the direction of the throw with your arms extended.","Retrieve the ball, reset, and repeat for the planned repetitions, then switch sides."],["Start the throw from the hips, not the arms; the trunk and arms should follow the hip turn.","Throw explosively, but keep your back neutral as you rotate rather than bending sideways.","Use a ball light enough to throw fast; a heavy ball slows the rotation and turns it into a push."],{"start":"images/flat/medicine-ball-side-throw-start.webp","peak":"images/flat/medicine-ball-side-throw-peak.webp"},"strength"],["medicine-ball-slam","Medicine Ball Slam","beginner","slam_ball","core","An explosive full-body exercise where a soft slam ball is lifted overhead and driven into the floor with maximum force.",["Stand with feet shoulder-width apart, holding a slam ball in front of your hips.","Lift the ball overhead by extending the hips and reaching tall.","Forcefully slam the ball into the floor between your feet, crunching through the core.","Catch the ball on the bounce or pick it up from the floor.","Repeat for the recommended number of repetitions."],["Use a dead-bounce slam ball, not a traditional medicine ball - regular balls will bounce back into your face.","Finish with the whole body - it is a full swing, not just an arm throw."],{"start":"images/flat/medicine-ball-slam-start.webp","peak":"images/flat/medicine-ball-slam-peak.webp"},"strength"],["mountain-climbers","Mountain Climbers","beginner","bodyweight","core","A dynamic bodyweight exercise combining core work with cardio.",["Start in a high plank position.","Drive one knee toward your chest.","Quickly switch legs, driving the other knee forward.","Continue alternating at a brisk pace.","Repeat."],["Keep your hips level and low rather than piking upward.","Keep your shoulders stacked directly over your wrists.","Maintain a steady breathing rhythm as the pace increases."],{"start":"images/flat/mountain-climbers-start.webp","peak":"images/flat/mountain-climbers-peak.webp"},"cardio"],["mountain-pose","Mountain Pose","beginner","bodyweight","full_body","The basic standing posture: feet grounded, legs active, spine tall and shoulders relaxed. It is the reference alignment every other standing pose is measured against.",["Stand with the feet hip-width apart and spread the weight evenly across both feet.","Engage the thighs lightly and let the tailbone drop so the pelvis is neutral.","Stack the ribs over the pelvis and the head over the ribs, arms relaxed by the sides.","Hold the posture for the prescribed time, breathing evenly.","Notice where the weight sits and rebalance it towards the middle of each foot."],["Lift and spread the toes once, then set them down; it resets the arch of the foot.","Keep the knees soft rather than locked back.","Let the shoulders roll back and down without pinning the shoulder blades together."],{"main":"images/flat/mountain-pose-main.webp"},"stretching"],["muscle-snatch","Muscle Snatch","intermediate","barbell","full_body","A snatch variation pulling the barbell overhead without dropping under it, building pulling power and lockout strength.",["Stand with feet hip-width apart and grip the bar wide with a hook grip.","Pull the bar explosively from the floor, keeping it close to your body.","Shrug hard and pull the bar overhead without dipping under.","Lock out the bar overhead with straight arms.","Lower the bar under control to the starting position.","Repeat for the desired number of reps."],["Shrug hard and keep pulling the bar up high.","Stay tall; do not dip under the bar to catch it.","Keep the bar close to your body throughout the pull."],{"start":"images/flat/muscle-snatch-start.webp","peak":"images/flat/muscle-snatch-peak.webp"},"olympic"],["muscle-ups","Muscle Ups","advanced","pull_up_bar","back","An advanced bar movement combining an explosive pull-up with a dip transition to finish above the bar.",["Hang from a pull-up bar with a false grip.","Pull yourself up explosively toward the bar.","As your chest reaches the bar, rotate your elbows over and transition into a dip.","Press your body up until your arms are fully extended above the bar.","Lower back down with control through the same path.","Repeat for the desired number of reps."],["Use a false grip so your wrists are already over the bar for the transition.","Pull explosively toward your sternum, not just your chin.","Drill the transition on low rings or with bands before full reps."],{"start":"images/flat/muscle-ups-start.webp","peak":"images/flat/muscle-ups-peak.webp"},"strength"],["neck-side-stretch","Neck Side Stretch","beginner","bodyweight","back","A gentle stretch that lengthens the upper trapezius and side of the neck by tilting the ear toward the shoulder.",["Sit or stand tall with your shoulders relaxed.","Tilt your head so one ear drops toward that shoulder.","Rest that hand lightly over your head for gentle weight.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Let the weight of your hand do the work - do not pull hard.","Keep the opposite shoulder pressed down."],{"main":"images/flat/neck-side-stretch-main.webp"},"stretching"],["negative-pull-ups","Negative Pull Ups","beginner","pull_up_bar","back","A pull-up regression emphasizing the slow lowering phase, building back and grip strength toward a full pull-up.",["Use a box or jump to position yourself at the top of a pull-up.","Grip the bar with hands shoulder-width apart.","Hold your chin above the bar briefly.","Lower yourself slowly over 3-5 seconds with control.","Fully extend your arms at the bottom.","Reset and repeat for the desired number of reps."],["Fight for control during the final third of the descent.","Keep your shoulder blades engaged instead of hanging passively.","Stop the set once you can no longer lower slowly."],{"start":"images/flat/negative-pull-ups-start.webp","peak":"images/flat/negative-pull-ups-peak.webp"},"strength"],["neutral-grip-pull-ups","Neutral Grip Pull Ups","intermediate","pull_up_bar","back","A pull-up variation on parallel handles with palms facing each other, recruiting the lats with strong brachialis assistance.",["Grip parallel bars with palms facing each other.","Hang with your arms fully extended.","Pull yourself up until your chin clears the bar.","Squeeze your lats at the top of the movement.","Lower yourself with control to the starting position.","Repeat for the desired number of reps."],["Initiate each rep by pulling your shoulder blades down and back.","Drive your elbows down toward your ribs as you pull.","Avoid kipping or swinging your legs for momentum."],{"start":"images/flat/neutral-grip-pull-ups-start.webp","peak":"images/flat/neutral-grip-pull-ups-peak.webp"},"strength"],["nordic-hamstring-curl","Nordic Hamstring Curl","advanced","glute_ham_developer","upper_legs","A knee-flexion exercise lowering the torso forward from a kneeling position, working the hamstrings eccentrically.",["Kneel on a pad with your ankles anchored under a fixed support.","Keep your torso upright and your hips extended.","Slowly lower your body forward by resisting with your hamstrings.","Catch yourself with your hands just before hitting the floor.","Push back up and pull yourself to the starting position.","Repeat for the desired number of reps."],["Lower as slowly as possible - the eccentric is the point.","Keep your hips extended; do not fold at the waist.","Catch yourself with your hands and push off lightly while building strength."],{"start":"images/flat/nordic-hamstring-curl-start.webp","peak":"images/flat/nordic-hamstring-curl-peak.webp"},"strength"],["ohp","Barbell Overhead Press","intermediate","barbell","shoulders","A compound overhead pressing movement targeting the shoulders and triceps.",["Stand with feet shoulder-width apart, bar at collarbone level.","Brace your core and press the bar overhead.","Lock out at the top with the bar over your mid-foot.","Lower the bar back to collarbone height.","Repeat."],["Do not lean back excessively.","Squeeze your glutes for stability."],{"start":"images/flat/ohp-start.webp","peak":"images/flat/ohp-peak.webp"},"strength"],["one-arm-dumbbell-preacher-curl","One Arm Dumbbell Preacher Curl","intermediate","dumbbell","upper_arms","A unilateral biceps curl performed seated at a preacher bench with the upper arm supported on the pad. Training one arm at a time keeps the elbow fixed and isolates the biceps.",["Sit at a preacher bench and rest the back of one upper arm flat on the pad.","Hold a dumbbell in that hand with the palm facing up and the arm almost fully extended.","Curl the dumbbell toward the shoulder without lifting the elbow off the pad.","Squeeze the biceps at the top of the movement.","Lower the dumbbell slowly until the arm is almost straight.","Complete the repetitions, then switch arms."],["Stop just short of lockout at the bottom to keep tension on the biceps and spare the elbow.","Keep the shoulder relaxed and the chest against the pad.","Lower the weight more slowly than you lift it."],{"start":"images/flat/one-arm-dumbbell-preacher-curl-start.webp","peak":"images/flat/one-arm-dumbbell-preacher-curl-peak.webp"},"strength"],["one-arm-dumbbell-push-press","One-Arm Dumbbell Push Press","intermediate","dumbbell","shoulders","A unilateral push press using a single dumbbell. Leg drive lets you punch heavier loads overhead than a strict one-arm press, and the asymmetric load forces strong anti-lateral-flexion bracing.",["Stand holding a dumbbell at one shoulder, palm facing inward (neutral).","Feet shoulder-width, core braced, free arm out to the side for balance.","Dip by bending the knees slightly, keeping the torso vertical.","Explosively extend the legs and press the dumbbell overhead in one motion.","Lock out overhead, then lower back to the shoulder under control.","Complete all reps on one side, then switch."],["Drive from the legs - the arm finishes, it does not start.","The torso must stay upright and square; do not side-bend away from the load.","Lighter weight and cleaner leg drive beat heavy with a leaning torso."],{"start":"images/flat/one-arm-dumbbell-push-press-start.webp","peak":"images/flat/one-arm-dumbbell-push-press-peak.webp"},"strength"],["one-arm-dumbbell-shoulder-press","One Arm Dumbbell Shoulder Press","intermediate","dumbbell","shoulders","A standing overhead press performed with a single dumbbell. Working one side at a time loads the shoulder and triceps and makes the trunk resist leaning toward the empty hand.",["Stand with the feet hip-width apart and hold a dumbbell at one shoulder with the palm facing forward.","Brace the abdominals and keep the free arm relaxed at your side.","Press the dumbbell straight overhead until the arm is fully extended.","Pause briefly at the top with the upper arm next to the ear.","Lower the dumbbell back to the shoulder under control.","Complete the repetitions on one arm, then switch sides."],["Keep the ribs down and the glutes tight; do not lean sideways to push the weight up.","Press in a straight line close to the head, not out in front.","Start lighter than you would with two dumbbells; the trunk has to stabilise the load."],{"start":"images/flat/one-arm-dumbbell-shoulder-press-start.webp","peak":"images/flat/one-arm-dumbbell-shoulder-press-peak.webp"},"strength"],["one-arm-dumbbell-swing","One-Arm Dumbbell Swing","intermediate","dumbbell","full_body","This dynamic exercise builds explosive power in the glutes and hamstrings through a powerful hip hinge, engaging the core and shoulders for a full-body workout.",["Stand with feet shoulder-width apart, a dumbbell on the floor slightly in front of you.","Hinge at your hips, keeping a flat back, and grasp the dumbbell with one hand.","Hike the dumbbell back between your legs, then explosively drive your hips forward.","Swing the dumbbell up to chest height, keeping your arm relaxed and straight.","Allow the dumbbell to swing back down, hinging at the hips as it descends.","Repeat for desired reps per side, maintaining control."],["Focus on driving with your hips, not pulling with your arm.","Keep your core braced throughout the movement for stability.","Maintain a neutral spine; avoid rounding your back.","Control the eccentric phase as the dumbbell swings down."],{"start":"images/flat/one-arm-dumbbell-swing-start.webp","peak":"images/flat/one-arm-dumbbell-swing-peak.webp"},"strength"],["one-arm-kettlebell-bicep-curl","One Arm Kettlebell Bicep Curl","intermediate","kettlebell","upper_arms","A unilateral kettlebell exercise isolating the biceps, with the offset load adding forearm and grip demand.",["Stand tall holding a kettlebell in one hand.","Keep your elbow pinned to your side.","Curl the kettlebell toward your shoulder by flexing your bicep.","Squeeze at the top of the movement.","Lower the kettlebell with control.","Complete reps on one side, then switch."],["Keep your wrist straight as the offset weight shifts through the curl.","Brace your core to resist leaning away from the working side.","Avoid swinging the kettlebell up with your hips."],{"start":"images/flat/one-arm-kettlebell-bicep-curl-start.webp","peak":"images/flat/one-arm-kettlebell-bicep-curl-peak.webp"},"strength"],["one-arm-kettlebell-bottoms-up-press","One-Arm Kettlebell Bottoms-Up Press","advanced","kettlebell","shoulders","A strict overhead press with the kettlebell held upside-down - bell on top, handle at the palm. The inverted load demands heavy grip, perfect shoulder stability, and ruthless bar-path discipline.",["Clean a light kettlebell to the rack position, then tilt it so the bell points up and the handle is at the palm.","Grip the handle hard; wrist absolutely straight and vertical.","Brace the core and press the bell straight up without letting it tip.","Lock out overhead with the bell still perfectly upright.","Lower slowly back to the rack position keeping the bell vertical the entire descent.","Complete all reps on one side, then switch."],["If the bell tips, the set is over - do not fight it down.","Start with a very light weight; this is a skill and stability lift, not a heavy press.","Grip hard throughout - any loosening and the bell falls."],{"start":"images/flat/one-arm-kettlebell-bottoms-up-press-start.webp","peak":"images/flat/one-arm-kettlebell-bottoms-up-press-peak.webp"},"strength"],["one-arm-kettlebell-floor-glute-bridge-press","One Arm Kettlebell Floor Glute Bridge Press","intermediate","kettlebell","chest","A combined glute bridge and single-arm floor press, training the glutes and chest in one movement.",["Lie on your back with knees bent and feet flat on the floor.","Hold a kettlebell in one hand at your shoulder.","Drive your hips up into a glute bridge.","Press the kettlebell straight up toward the ceiling.","Lower the kettlebell and your hips with control.","Complete reps on one side, then switch."],["Hold the bridge steady at the top while pressing.","Keep your wrist straight and stacked under the kettlebell.","Extend your free arm along the floor for extra stability."],{"start":"images/flat/one-arm-kettlebell-floor-glute-bridge-press-start.webp","peak":"images/flat/one-arm-kettlebell-floor-glute-bridge-press-peak.webp"},"strength"],["one-arm-kettlebell-floor-press","One Arm Kettlebell Floor Press","intermediate","kettlebell","chest","A unilateral kettlebell press performed lying on the floor, where the limited range reduces shoulder strain.",["Lie flat on the floor with knees bent.","Hold a kettlebell at your shoulder with one hand.","Press the kettlebell straight up until your arm is fully extended.","Lower the kettlebell until your upper arm touches the floor.","Keep your core braced throughout.","Complete reps on one side, then switch."],["Keep your forearm vertical throughout the press.","Tuck your elbow to roughly 45 degrees from your torso.","Let your upper arm touch down gently rather than bouncing off the floor."],{"start":"images/flat/one-arm-kettlebell-floor-press-start.webp","peak":"images/flat/one-arm-kettlebell-floor-press-peak.webp"},"strength"],["one-arm-kettlebell-front-squat","One Arm Kettlebell Front Squat","intermediate","kettlebell","upper_legs","A unilateral front squat with one kettlebell racked at the shoulder, challenging the legs and core against the offset load.",["Hold a kettlebell in the racked position at one shoulder.","Stand with feet shoulder-width apart.","Squat down by bending your knees and hips.","Keep your chest up and torso upright throughout.","Drive through your heels to stand back up.","Complete reps on one side, then switch."],["Keep the rack position tight against your chest and forearm.","Resist twisting or leaning toward the loaded side.","Spread the floor with your feet to keep your knees tracking outward."],{"start":"images/flat/one-arm-kettlebell-front-squat-start.webp","peak":"images/flat/one-arm-kettlebell-front-squat-peak.webp"},"strength"],["one-arm-kettlebell-push-press","One Arm Kettlebell Push Press","intermediate","kettlebell","shoulders","An explosive single-arm overhead press using leg drive to launch the kettlebell, allowing heavier loads than a strict press.",["Hold a kettlebell in the racked position at one shoulder.","Stand with feet shoulder-width apart.","Dip by bending your knees slightly.","Drive explosively through your legs and press the kettlebell overhead.","Lock out your arm at the top.","Lower the kettlebell to your shoulder with control.","Complete reps on one side, then switch."],["Keep your torso upright during the dip, not tipping forward.","Time the press so your arm extends as your legs finish driving.","Keep the dip shallow and quick rather than a half squat."],{"start":"images/flat/one-arm-kettlebell-push-press-start.webp","peak":"images/flat/one-arm-kettlebell-push-press-peak.webp"},"strength"],["one-arm-kettlebell-row","One Arm Kettlebell Row","intermediate","kettlebell","back","A unilateral rowing exercise with bench support, building the lats and mid-back one side at a time.",["Place one hand and knee on a bench for support.","Hold a kettlebell in the opposite hand with your arm extended.","Pull the kettlebell toward your hip by driving your elbow back.","Squeeze your back at the top of the movement.","Lower the kettlebell with control.","Complete reps on one side, then switch."],["Keep your torso square to the floor throughout the set.","Pull with your back muscles rather than just your arm.","Keep your neck neutral, eyes on the floor just ahead."],{"start":"images/flat/one-arm-kettlebell-row-start.webp","peak":"images/flat/one-arm-kettlebell-row-peak.webp"},"strength"],["one-arm-kettlebell-shoulder-press","One Arm Kettlebell Shoulder Press","intermediate","kettlebell","shoulders","A strict single-arm overhead press from the rack position, training the shoulders while the core resists side-bending.",["Hold a kettlebell in the racked position at one shoulder.","Stand tall with feet hip-width apart.","Press the kettlebell straight overhead until your arm is locked out.","Keep your core tight throughout.","Lower the kettlebell back to the rack position with control.","Complete reps on one side, then switch."],["Avoid leaning away from the kettlebell as it travels overhead.","Finish with your biceps close to your ear at lockout.","Squeeze your glutes to keep your ribs from flaring."],{"start":"images/flat/one-arm-kettlebell-shoulder-press-start.webp","peak":"images/flat/one-arm-kettlebell-shoulder-press-peak.webp"},"strength"],["one-arm-kettlebell-swing","One Arm Kettlebell Swing","intermediate","kettlebell","full_body","A single-arm variation of the kettlebell swing, adding grip and anti-rotation demands to the explosive hip hinge.",["Stand with feet shoulder-width apart and a kettlebell on the floor in front of you.","Hinge at the hips and grip the kettlebell with one hand.","Hike the kettlebell back between your legs.","Drive your hips forward to swing the kettlebell to chest height.","Let gravity bring the kettlebell back between your legs.","Complete reps on one side, then switch."],["Keep your shoulders square as the offset load tries to rotate you.","Power the movement with your hips, not by lifting with your arm.","Hinge with a flat back rather than squatting the swing."],{"start":"images/flat/one-arm-kettlebell-swing-start.webp","peak":"images/flat/one-arm-kettlebell-swing-peak.webp"},"strength"],["one-arm-kettlebell-tricep-kickback","One-Arm Kettlebell Tricep Kickback","beginner","kettlebell","upper_arms","A unilateral tricep isolation done with a kettlebell instead of a dumbbell. Hinge over, pin the upper arm to the side parallel to the floor, and extend the elbow back. The offset bell mass adds rotational tension at the bottom of every rep.",["Hinge forward at the hips with a flat back, knees softly bent.","Hold a kettlebell by the handle in one hand, palm facing the body.","Pin the upper arm to the side so it is parallel to the floor; the forearm hangs straight down.","Extend the elbow back to straighten the arm fully behind you, keeping the upper arm motionless.","Squeeze the tricep at lockout, then return under control to the starting position.","Complete all reps on one side, then switch hands."],["The upper arm does not move - only the forearm. Any shoulder swing is a cheat.","Lock the bell briefly at full extension; the bottom of the bell wants to dip the wrist.","Use a lighter bell than you would for a dumbbell kickback - the offset load is harder to stabilize."],{"start":"images/flat/one-arm-kettlebell-tricep-kickback-start.webp","peak":"images/flat/one-arm-kettlebell-tricep-kickback-peak.webp"},"strength"],["one-arm-landmine-press","One-Arm Landmine Press","intermediate","barbell","shoulders","A unilateral overhead press variation using a landmine setup that follows a natural arc, reducing shoulder impingement risk while building pressing strength.",["Anchor one end of a barbell in a landmine attachment and load the free end.","Kneel on one knee or stand and grip the sleeve end at shoulder height with one hand.","Press the bar upward and forward along its arc until the arm is fully extended.","Lower the bar back to shoulder height under control.","Complete all reps before switching sides."],["Engage your core to prevent the torso from rotating toward the working arm.","The arc motion is more joint-friendly than a vertical overhead press.","Kneeling on the knee on the same side as the pressing arm, with the other foot planted in front, increases the core's anti-rotation demand."],{"start":"images/flat/one-arm-landmine-press-start.webp","peak":"images/flat/one-arm-landmine-press-peak.webp"},"strength"],["one-arm-lat-pulldown","One-Arm Lat Pulldown","intermediate","cable","back","A unilateral cable pulldown that targets the latissimus dorsi with a single-arm handle, allowing a greater range of motion and bilateral strength imbalances to be addressed.",["Attach a single-handle to the cable pulldown station and sit with your thighs secured under the pad.","Reach up and grasp the handle with one hand, arm fully extended.","Pull the handle down toward your shoulder, driving your elbow toward your hip.","Pause briefly at full contraction, then return to the starting position with control.","Complete all reps on one side before switching."],["Lean slightly away from the cable to increase lat stretch at the top.","Focus on pulling with your elbow, not your hand, to keep the lat engaged.","Control the eccentric to maximize lat tension throughout the range."],{"start":"images/flat/one-arm-lat-pulldown-start.webp","peak":"images/flat/one-arm-lat-pulldown-peak.webp"},"strength"],["one-arm-seated-cable-row","One-Arm Seated Cable Row","intermediate","cable","back","A unilateral seated cable row that trains the lats and upper back while the torso stays square and the working shoulder blade moves through a controlled reach and pull.",["Sit at the cable row station and hold one handle with the working arm extended.","Plant the feet, sit tall and brace the trunk without leaning back.","Pull the handle towards the lower ribs while drawing the shoulder blade back.","Pause briefly without rotating the torso or shrugging the shoulder.","Extend the arm under control, finish the set and repeat on the other side."],["Keep both shoulders facing forward throughout the repetition.","Drive the elbow back close to the body rather than curling the handle.","Let the shoulder blade reach forward at the start without rounding the lower back."],{"start":"images/flat/one-arm-seated-cable-row-start.webp","peak":"images/flat/one-arm-seated-cable-row-peak.webp"},"strength"],["one-arm-single-leg-dumbbell-romanian-deadlift","One-Arm Single-Leg Dumbbell Romanian Deadlift","advanced","dumbbell","upper_legs","A single-leg RDL holding a dumbbell in one hand - usually the hand opposite the working leg (contralateral). Loads the hamstrings and glutes of the standing leg while demanding heavy anti-rotation from the core.",["Stand on one leg holding a dumbbell in the opposite hand.","Free arm out to the side for balance, free leg hovering just off the floor.","Hinge at the standing hip, pushing it back while the free leg extends behind to counterbalance.","Keep the hips square to the floor - do not open them to the side.","Lower the dumbbell toward the foot of the standing leg, feeling a deep hamstring stretch.","Drive the hip forward to return to standing under control.","Complete all reps on one side, then switch."],["Start lighter than you think - balance and anti-rotation demands are the limit, not hamstring strength.","If you rotate open, pause and reset; a shorter clean ROM beats a full ROM with rotation.","Eyes on a fixed spot on the floor a few feet in front helps balance."],{"start":"images/flat/one-arm-single-leg-dumbbell-romanian-deadlift-start.webp","peak":"images/flat/one-arm-single-leg-dumbbell-romanian-deadlift-peak.webp"},"strength"],["one-arm-single-leg-kettlebell-romanian-deadlift","One-Arm Single-Leg Kettlebell Romanian Deadlift","advanced","kettlebell","upper_legs","The kettlebell version of the one-arm single-leg RDL. The offset mass of the kettlebell and the lower hanging centre make this a subtly different challenge to the dumbbell variant - excellent for posterior-chain strength and balance under asymmetric load.",["Stand on one leg holding a kettlebell in the opposite hand by the handle.","Free arm out to the side for balance, free leg hovering behind.","Hinge at the standing hip, pushing it back while the free leg extends to counterbalance.","Keep hips square to the floor; the kettlebell tracks straight down the shin.","Feel a deep hamstring stretch on the standing leg at the bottom.","Drive the hip forward to return to standing.","Complete all reps on one side, then switch."],["The kettlebell hangs lower than a dumbbell - shorten the ROM slightly to keep the back flat.","If the bell swings, you are moving too fast. Slow the eccentric.","Build up from the two-arm (dumbbell) single-leg RDL first."],{"start":"images/flat/one-arm-single-leg-kettlebell-romanian-deadlift-start.webp","peak":"images/flat/one-arm-single-leg-kettlebell-romanian-deadlift-peak.webp"},"strength"],["overhead-squat","Overhead Squat","intermediate","barbell","upper_legs","A squat with a barbell locked out overhead in a wide snatch grip, demanding mobility, stability, and a strong core.",["Hold a barbell overhead with a wide snatch grip and arms locked out.","Stand with feet slightly wider than shoulder-width.","Squat down by pushing your hips back and bending your knees.","Keep the bar directly over the middle of your feet.","Drive through your heels to stand back up.","Repeat for the desired number of reps."],["Keep your armpits facing forward to lock the bar in place.","Keep the bar over mid-foot with a more upright torso than a back squat.","Work on shoulder and ankle mobility before adding load."],{"start":"images/flat/overhead-squat-start.webp","peak":"images/flat/overhead-squat-peak.webp"},"strength"],["overhead-tricep-extension","Overhead Tricep Extension","beginner","dumbbell","upper_arms","An isolation exercise for the triceps emphasizing the long head.",["Stand or sit holding a dumbbell overhead with both hands.","Lower the dumbbell behind your head by bending your elbows.","Extend your arms back to the starting position.","Keep your elbows close to your head throughout.","Repeat."],["Keep your ribs down and avoid arching your lower back.","Lower until you feel a deep stretch in your triceps.","Check your grip is secure before lowering the dumbbell behind your head."],{"start":"images/flat/overhead-tricep-extension-start.webp","peak":"images/flat/overhead-tricep-extension-peak.webp"},"strength"],["overhead-triceps-stretch","Overhead Triceps Stretch","beginner","bodyweight","upper_arms","A standing stretch that lengthens the triceps and lat by reaching the hand down the upper back.",["Raise one arm overhead and bend the elbow.","Let your hand drop down behind your head.","Use the other hand to press the bent elbow back.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep your head upright, do not push it forward.","Relax and keep breathing throughout."],{"main":"images/flat/overhead-triceps-stretch-main.webp"},"stretching"],["pause-deadlift","Pause Deadlift","advanced","barbell","back","A deadlift variation with a deliberate pause just above the knees, building strength and position through the upper half of the pull.",["Set up for a conventional deadlift.","Pull the bar off the floor and pause when it passes your knees.","Hold for 2-3 seconds, then complete the lift.","Lower under control.","Repeat."],["The pause removes momentum and builds strength and control from the knees to lockout.","Keep your back flat during the pause."],{"start":"images/flat/pause-deadlift-start.webp","peak":"images/flat/pause-deadlift-peak.webp"},"strength"],["pause-pull-up","Pause Pull-Up","advanced","pull_up_bar","back","A pull-up variation that adds a brief isometric hold at the top of the movement, with the chin over the bar, before lowering back down.",["Hang from a pull-up bar with an overhand grip, arms fully extended.","Pull yourself up until your chin clears the bar.","Pause and hold that top position for a moment.","Lower yourself back down under control to a full hang.","Repeat for the desired number of reps."],["The pause removes momentum, so the pull is harder than a regular pull-up -- expect fewer reps.","Keep your shoulders engaged during the hold instead of relaxing into the bar.","Lower slowly instead of dropping straight into the next rep."],{"start":"images/flat/pause-pull-up-start.webp","peak":"images/flat/pause-pull-up-peak.webp"},"strength"],["pause-squat","Pause Squat","intermediate","barbell","upper_legs","A barbell squat variation with a deliberate pause at the bottom, eliminating the stretch reflex to build strength from a dead stop.",["Unrack a barbell and rest it across your upper back.","Stand with feet shoulder-width apart.","Squat down until your thighs are parallel to the floor.","Hold the bottom position for 2-3 seconds.","Drive through your heels to stand back up.","Repeat for the desired number of reps."],["Stay braced and tight during the pause rather than relaxing.","Avoid collapsing forward or rocking as you hold the bottom.","Use lighter loads than your regular squat to maintain crisp form."],{"start":"images/flat/pause-squat-start.webp","peak":"images/flat/pause-squat-peak.webp"},"strength"],["paused-bench-press","Paused Bench Press","advanced","barbell","chest","A bench press variation pausing the bar on the chest, removing momentum to build strict pressing strength.",["Lie on a flat bench and grip the barbell slightly wider than shoulder-width.","Unrack the bar and lower it to your chest.","Pause on your chest for 1-2 seconds.","Press the bar back up until your arms are fully extended.","Control the descent on every rep.","Repeat for the desired number of reps."],["Stay tight during the pause instead of letting the bar sink.","Keep your shoulder blades pinched and your feet planted throughout.","Touch the bar to the same spot on your chest every rep."],{"start":"images/flat/paused-bench-press-start.webp","peak":"images/flat/paused-bench-press-peak.webp"},"strength"],["paused-incline-bench-press","Paused Incline Bench Press","advanced","barbell","chest","An incline bench press with a pause on the upper chest, emphasizing strict control and upper-pec strength.",["Lie on an incline bench and grip the barbell slightly wider than shoulder-width.","Unrack the bar and lower it to your upper chest.","Pause on your chest for 1-2 seconds.","Press the bar back up until your arms are fully extended.","Keep your shoulder blades retracted throughout.","Repeat for the desired number of reps."],["Keep your wrists stacked over your elbows during the pause.","Maintain full-body tension while the bar rests on your chest.","Avoid bouncing the bar off your chest after the pause."],{"start":"images/flat/paused-incline-bench-press-start.webp","peak":"images/flat/paused-incline-bench-press-peak.webp"},"strength"],["paused-ohp","Paused Overhead Press","advanced","barbell","shoulders","An overhead press variation that pauses the bar at the shoulders, removing momentum to build strict pressing strength and overhead stability.",["Set up with a barbell racked at shoulder height, feet shoulder-width apart, and the core braced.","Press the bar straight overhead until the elbows are fully locked out.","Lower the bar under control back down to the front of the shoulders.","Hold a full one-second pause at the shoulders, keeping tension and eliminating any bounce.","Press back up from the dead stop without using leg drive."],["Keep the pause strict -- no rebounding the bar off the shoulders.","Brace hard and keep the bar path vertical over the mid-foot.","Use a weight you can control through the dead-stop start."],{"start":"images/flat/paused-ohp-start.webp","peak":"images/flat/paused-ohp-peak.webp"},"strength"],["pec-deck","Pec Deck","beginner","pec_deck","chest","A chest isolation machine with swinging handles that targets the pectorals through horizontal adduction.",["Sit in the pec deck machine and grip the handles with your arms out to the sides, elbows slightly bent.","Adjust the seat so the handles align with mid-chest height.","Squeeze the handles together in front of your chest.","Hold the contraction briefly at the center.","Return under control to the starting position.","Repeat for the desired number of reps."],["Keep your shoulders down and back against the seat.","Avoid letting the handles fly back past a comfortable stretch.","Focus on squeezing your chest rather than pressing with your arms."],{"start":"images/flat/pec-deck-start.webp","peak":"images/flat/pec-deck-peak.webp"},"strength"],["pendlay-row","Pendlay Row","intermediate","barbell","back","A strict barbell row performed from a dead stop on the floor between reps, torso parallel to the ground. Popularized by coach Glenn Pendlay.",["Load a barbell and set it on the floor.","Hinge at the hips until your torso is parallel to the ground, knees slightly bent.","Grip the bar slightly wider than shoulder-width with an overhand grip.","Explosively pull the bar to your lower chest.","Lower the bar back to the floor under control and pause before the next rep.","Repeat."],["Dead-stop each rep on the floor - no touch-and-go.","Keep your torso locked at roughly 90 degrees; do not use body english.","Drive the elbows up and back, not out to the sides."],{"start":"images/flat/pendlay-row-start.webp","peak":"images/flat/pendlay-row-peak.webp"},"strength"],["pigeon-stretch","Pigeon Stretch","beginner","bodyweight","upper_legs","A seated floor stretch that targets the glutes and outer hip with the front shin folded across the body.",["From all fours, bring one knee forward and lay the shin across in front.","Extend the other leg straight back, top of the foot down.","Sink your hips toward the floor and keep them square.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Place a cushion under the hip if it does not reach the floor.","Walk your hands forward to deepen the stretch."],{"main":"images/flat/pigeon-stretch-main.webp"},"stretching"],["pike-push-ups","Pike Push Ups","intermediate","bodyweight","shoulders","A push-up performed with hips high in a pike position, pressing at a steep angle to load the shoulders.",["Start in a downward dog position with hips high and hands shoulder-width apart.","Walk your feet closer to your hands.","Bend your elbows and lower your head toward the floor.","Keep your hips high throughout.","Press back up until your arms are fully extended.","Repeat for the desired number of reps."],["The higher your hips, the more the shoulders work.","Lower your head toward a spot slightly ahead of your hands.","Walk your feet closer to your hands to progress toward handstand push-ups."],{"start":"images/flat/pike-push-ups-start.webp","peak":"images/flat/pike-push-ups-peak.webp"},"strength"],["pilates-kneeling-side-kick","Pilates Kneeling Side Kick","intermediate","bodyweight","upper_legs","A Pilates mat exercise: kneeling on one knee with one hand on the floor for support and the other on the hip, the top leg lifts out to the side up to hip height and lowers again while the trunk holds still.",["Kneel on one knee and place the same-side hand on the floor under the shoulder, the other hand on the hip.","Extend the top leg out to the side, the foot a little below hip height.","Keeping the trunk perfectly still, lift the leg up to hip height.","Lower it back down under control without letting the pelvis tip or the lower back arch.","Repeat for the desired number of repetitions and change sides."],["The trunk is the exercise: if it rocks with the leg, make the lift smaller.","Keep the supporting shoulder pushed away from the ear.","Move at a controlled tempo instead of throwing the leg."],{"start":"images/flat/pilates-kneeling-side-kick-start.webp","peak":"images/flat/pilates-kneeling-side-kick-peak.webp"},"strength"],["pilates-leg-pull-back","Pilates Leg Pull Back","intermediate","bodyweight","core","A reverse plank with alternating leg lifts: the hips stay high while one leg at a time is raised, so the glutes and the back of the trunk work against the shifting support.",["Sit with the legs straight and the hands on the floor behind the hips, fingers pointing forward.","Press into the hands and heels and lift the hips into a reverse plank.","Keeping the hips level and high, lift one straight leg as far as the pelvis stays still.","Lower the leg under control and repeat with the other one.","Finish the set and lower the hips to the floor."],["Stop the leg lift where the hips start to drop; height is not the point.","Keep the chest open and the shoulders away from the ears.","Bend the knees slightly if the straight-leg version pulls at the hamstrings."],{"start":"images/flat/pilates-leg-pull-back-start.webp","peak":"images/flat/pilates-leg-pull-back-peak.webp"},"strength"],["pilates-leg-pull-front","Pilates Leg Pull Front","intermediate","bodyweight","core","A high plank with alternating leg lifts: the shoulders stay stacked over the wrists while one leg at a time lifts, adding an anti-rotation demand to the plank.",["Set up in a high plank with the hands under the shoulders and the body in one line.","Brace the trunk and squeeze the glutes so the hips cannot rotate.","Lift one straight leg a few centimetres above hip height without letting the pelvis tilt.","Lower it under control and repeat with the other leg.","Keep alternating for the desired number of repetitions."],["Lift the leg from the glute rather than by arching the lower back.","Keep the weight even in both hands; the tendency is to lean away from the lifted side.","Reduce the lift height until the hips stay perfectly level."],{"start":"images/flat/pilates-leg-pull-front-start.webp","peak":"images/flat/pilates-leg-pull-front-peak.webp"},"strength"],["pilates-roll-down","Pilates Roll Down","beginner","bodyweight","back","A standing articulation of the spine: the head leads a vertebra-by-vertebra roll towards the floor and back up, mobilising the whole back while the legs stay steady.",["Stand tall with the feet hip-width apart and the arms hanging at the sides.","Drop the chin to the chest and start rolling down one vertebra at a time.","Let the arms and head hang heavy once the spine is fully rolled down.","Roll back up the same way, stacking the vertebrae one by one, head last.","Repeat for the desired number of repetitions."],["Keep the knees soft so the movement comes from the spine, not the hamstrings.","Move slowly enough to feel each segment; speed defeats the purpose.","Keep the weight in the middle of the feet as you roll down."],{"start":"images/flat/pilates-roll-down-start.webp","peak":"images/flat/pilates-roll-down-peak.webp"},"stretching"],["pilates-roll-over","Pilates Roll Over","advanced","bodyweight","core","A controlled inversion from the mat: with the arms pressing down, the straight legs travel overhead until the toes reach towards the floor, then the spine rolls back down one segment at a time.",["Lie on your back with the legs straight and the arms pressed into the mat beside you.","Lift both legs to vertical without letting the lower back arch.","Press the arms down and take the legs overhead until they are parallel to the floor behind you.","Open the legs slightly, flex the feet, and roll the spine down one vertebra at a time.","Return the legs to vertical and repeat for the desired number of repetitions."],["Drive the movement with the abdominals, not by throwing the legs.","Keep the weight off the neck: the roll stops at the shoulder blades.","Skip this exercise if you have neck complaints, and build it up with smaller curls first."],{"start":"images/flat/pilates-roll-over-start.webp","peak":"images/flat/pilates-roll-over-peak.webp"},"strength"],["pilates-saw","Pilates Saw","intermediate","bodyweight","back","A seated twist and reach: sitting tall with the legs wide, the torso rotates and then folds over the opposite leg so the reaching hand passes the little toe like a saw.",["Sit tall with the legs straight and slightly wider than the hips, arms out to the sides.","Rotate the torso to one side, keeping both sit bones on the floor.","Fold forward over that leg and reach the opposite hand past the little toe.","Roll back up through the spine and return to the centre.","Repeat to the other side and continue alternating."],["Anchor both sit bones; lifting one of them turns the twist into a lean.","Rotate first, then fold - the order is what makes the exercise work.","Sit on a folded blanket if the pelvis cannot stay upright."],{"start":"images/flat/pilates-saw-start.webp","peak":"images/flat/pilates-saw-peak.webp"},"stretching"],["pilates-side-bend","Pilates Side Bend","intermediate","bodyweight","core","A lateral trunk exercise from a side-supported position: the hips lift and the top arm reaches overhead, bending the body sideways over the supporting arm.",["Sit on one hip with the legs bent to the side and the supporting hand on the floor under the shoulder.","Press into the hand and the lower leg to lift the hips off the floor.","Reach the top arm overhead so the body forms a long arc from the hand to the feet.","Lower the hips under control back towards the mat.","Complete the repetitions and change sides."],["Push the floor away so the supporting shoulder stays stacked and stable.","Reach the top arm long rather than collapsing sideways.","Keep the movement smooth; the lift and the lower take the same time."],{"start":"images/flat/pilates-side-bend-start.webp","peak":"images/flat/pilates-side-bend-peak.webp"},"strength"],["pilates-spine-stretch-forward","Pilates Spine Stretch Forward","intermediate","bodyweight","back","A seated articulation: sitting tall with the legs apart, the spine curls forward segment by segment over the legs and then restacks vertebra by vertebra.",["Sit tall with the legs straight and slightly wider than the hips, feet flexed.","Reach the arms forward at shoulder height.","Drop the chin and curl the spine forward one vertebra at a time, reaching past the toes.","Restack the spine from the base upwards until you are sitting tall again.","Repeat for the desired number of repetitions."],["Keep the pelvis upright: the curl comes from the spine, not from tipping the hips.","Press the heels away throughout so the legs stay active.","Sit on a folded blanket if sitting upright already rounds the lower back."],{"start":"images/flat/pilates-spine-stretch-forward-start.webp","peak":"images/flat/pilates-spine-stretch-forward-peak.webp"},"stretching"],["pilates-spine-twist","Pilates Spine Twist","intermediate","bodyweight","core","A seated rotation with the legs together and the arms wide: the trunk turns to each side in a controlled pulse while the pelvis and legs stay completely still.",["Sit tall with the legs straight and together, feet flexed, arms out to the sides at shoulder height.","Grow tall through the spine and press both sit bones into the floor.","Rotate the trunk to one side as far as the hips stay square, then return to the centre.","Rotate to the other side in the same way.","Keep alternating for the desired number of repetitions."],["The legs are the anchor: if one foot slides forward, the pelvis has moved.","Lengthen upwards before each rotation instead of sinking into it.","Turn the head with the trunk rather than leading with it."],{"start":"images/flat/pilates-spine-twist-start.webp","peak":"images/flat/pilates-spine-twist-peak.webp"},"stretching"],["pistol-squat","Pistol Squat","advanced","bodyweight","upper_legs","A single-leg squat performed with the non-working leg extended forward, demanding strength and balance.",["Stand on one leg with the other extended forward, arms out for balance.","Hinge at the hips and bend the standing knee, keeping the chest up.","Descend slowly until the back of the thigh touches the calf.","Drive through the standing heel to return to standing.","Complete reps per side, then switch legs."],["Hold a light counterweight at the chest if balance is hard.","Build the strength with box-assisted pistols first.","Keep the working heel flat on the floor."],{"start":"images/flat/pistol-squat-start.webp","peak":"images/flat/pistol-squat-peak.webp"},"strength"],["planche","Planche","advanced","bodyweight","chest","An advanced calisthenics hold requiring exceptional upper body and core strength to hold the body parallel to the ground.",["Begin in a push-up position with your hands turned outward on the floor, or on parallettes.","Lean forward until your center of mass is over your hands.","Lift your feet off the ground keeping the body horizontal.","Hold the position.","Return to the floor with control."],["Progress through tuck, straddle, and full planche.","Build wrist and shoulder strength before attempting."],{"main":"images/flat/planche-main.webp"},"strength"],["planche-lean-floor","Planche Lean","intermediate","bodyweight","chest","A floor progression toward the planche: from a high plank position, you lean your shoulders forward past your hands and hold, so that more of your bodyweight loads the shoulders and chest. It builds the straight-arm strength needed for the full planche.",["Start in a high plank with your hands on the floor, a little below your hips and turned out slightly.","Lock your elbows and protract your shoulder blades so your upper back is slightly rounded and strong.","Lean your body forward until your shoulders are well in front of your hands.","Keep your whole body in a straight line, with your glutes squeezed and your core braced.","Hold the lean for the planned time while breathing steadily.","Shift back to the neutral plank to finish."],["Keep your arms straight; bending the elbows turns the hold into a push-up.","Push the floor away so your shoulder blades stay wide rather than sinking between the shoulders.","Lean only as far as you can keep the hold for several seconds; increase the lean gradually over weeks."],{"main":"images/flat/planche-lean-floor-main.webp"},"strength"],["plank","Plank","beginner","bodyweight","core","An isometric core exercise that strengthens the entire midsection.",["Place your forearms on the floor with elbows under your shoulders.","Extend your legs back and rise onto your toes.","Keep your body in a straight line from head to heels.","Brace your core and squeeze your glutes.","Hold the position for the desired duration.","Lower your knees to exit the hold."],["Do not let your hips sag or pike up.","Squeeze your glutes and quads."],{"main":"images/flat/plank-main.webp"},"strength"],["plank-knee-tuck","Plank Knee Tuck","intermediate","bodyweight","core","A moving core drill performed from a high plank: the body holds its straight line while one knee is drawn in under the chest and sent back, alternating sides. Slower and more controlled than a mountain climber, it trains the abdominals and hip flexors while the shoulders and trunk stay braced.",["Set up in a high plank with the hands under the shoulders and the body in a straight line from head to heels.","Press the floor away and brace the trunk so the hips neither sag nor pike.","Draw one knee in towards the chest without letting the hips rise.","Extend the leg back to the starting position under control.","Repeat with the other leg and keep alternating for the desired number of repetitions."],["Keep the hips level with the shoulders; letting them lift turns this into a pike.","Pull the knee in with the abdominals rather than by hopping off the supporting foot.","Keep the shoulders stacked over the wrists and push the floor away so the upper body does not sink."],{"start":"images/flat/plank-knee-tuck-start.webp","peak":"images/flat/plank-knee-tuck-peak.webp"},"strength"],["plate-loaded-donkey-calf-raise","Plate-Loaded Donkey Calf Raise","beginner","donkey_calf_raise_machine","lower_legs","A donkey calf raise on a plate-loaded machine, with a pad across the hips and the torso hinged forward so the calves are stretched at the bottom of every repetition.",["Load the plate horns and step onto the platform with the balls of your feet on the edge and your heels hanging free.","Bend forward at the hips and settle the pad across your hips, then rest your forearms on the support in front of you.","Keep your knees straight and your back flat, with your torso close to parallel to the floor.","Push through the balls of your feet and raise your heels as high as you can, pausing briefly at the top.","Lower your heels below the platform until you feel a strong calf stretch, and repeat for the desired number of repetitions."],["The forward hinge is the exercise. Standing up straight turns this into an ordinary standing calf raise and gives away the extra stretch you came for.","Keep the knees straight throughout. Bending them shifts the work from the gastrocnemius to the soleus, which is the seated calf raise, not this one.","Let the heels drop all the way below the platform edge. The bottom of the range is where this machine earns its place, and cutting it short wastes the setup."],{"start":"images/flat/plate-loaded-donkey-calf-raise-start.webp","peak":"images/flat/plate-loaded-donkey-calf-raise-peak.webp"},"strength"],["plate-loaded-glute-drive","Plate-Loaded Glute Drive","beginner","hip_thrust_machine","upper_legs","A machine hip thrust performed on a plate-loaded glute drive, where the built-in back pad and foot platform set the position so the hips can extend against the load without setting up a bench.",["Load the plate horns evenly and sit into the machine with your upper back against the pad and your feet flat on the platform.","Pull the hip pad or lap bar across your hips and adjust it so it sits on the crease of the hips, not on your stomach.","Set your feet so that your shins will be roughly vertical when your hips are at the top, and take hold of the handles.","Drive your hips up by squeezing the glutes until your thighs are level with your torso, and hold briefly at the top.","Lower under control until your hips are just short of the bottom of the range, and repeat for the desired number of repetitions."],["Get the pad on the hip crease. Sitting it up on the stomach is the only genuinely uncomfortable thing this machine does, and it is fixed by moving the pad, not by adding padding.","Finish with the hips, not the lower back. If the ribs flare at the top you have run out of hip extension and started arching, which is where the machine stops training the glutes.","This is the hip thrust to reach for when the bench and barbell are taken -- the back pad and platform are part of the frame, so there is no setup to get wrong."],{"start":"images/flat/plate-loaded-glute-drive-start.webp","peak":"images/flat/plate-loaded-glute-drive-peak.webp"},"strength"],["plate-loaded-lateral-raise","Plate-Loaded Lateral Raise","beginner","plate_loaded_lateral_raise_machine","shoulders","A seated lateral raise on a plate-loaded machine, where pads bear against the upper arms so the side deltoids lift the load without the hands gripping it.",["Set the seat height so that the pivot of the arm pads lines up with the point of your shoulders when you sit down.","Load the plate horns evenly on both sides and sit with your back flat against the pad.","Place the outside of your upper arms against the pads with your elbows bent and your arms hanging down.","Push out and up against the pads until your upper arms are roughly level with your shoulders.","Lower under control until your arms are back at your sides, and repeat for the desired number of repetitions."],["Set the seat first. If the pivot sits below your shoulder the pads drive your arm across your body instead of out to the side, and the side deltoid stops being the muscle doing the work.","Push with the arm, not the hand. The handles are there to stop your arms sliding off the pads -- gripping hard pulls the biceps and forearms into a raise that should be all deltoid.","Stop at shoulder height. Going higher hands the last part of the rep to the traps, and the machine will happily let you."],{"start":"images/flat/plate-loaded-lateral-raise-start.webp","peak":"images/flat/plate-loaded-lateral-raise-peak.webp"},"strength"],["plate-loaded-seated-dip-machine","Plate-Loaded Seated Dip Machine","intermediate","plate_loaded_dip_machine","upper_arms","A plate-loaded version of the seated dip machine: you sit with your back against the pad and press two lever arms down by your sides against weight plates loaded on a sleeve behind you. It trains the triceps along the same pressing path as the selectorized dip machine, with the resistance set by the plates you load.",["Load the plates evenly on the sleeve and adjust the seat so the handles are at about shoulder height when you are seated.","Sit upright with your back against the pad and grip the handles at your sides with your elbows bent.","Keep your shoulders down and your chest up, then press the handles down by straightening your elbows.","Squeeze your triceps at the bottom, with your arms straight but not locked out hard.","Let the handles rise back up under control until your elbows are bent to about 90 degrees.","Repeat for the planned repetitions, then return the lever to its safety stop before you stand up."],["Start light and add plates gradually; if the handles stop short of full extension the load is too heavy.","Keep the elbows close to your sides and your back against the pad so the work stays on the triceps.","Do not let the shoulders roll forward or shrug as the handles rise; stop where the stretch in the chest and shoulders is comfortable."],{"start":"images/flat/plate-loaded-seated-dip-machine-start.webp","peak":"images/flat/plate-loaded-seated-dip-machine-peak.webp"},"strength"],["plate-loaded-shrug","Plate-Loaded Shrug","beginner","shrug_machine","back","A standing shrug on a plate-loaded machine, lifting handles that hang at your sides so the traps work without a bar in front of or behind the legs.",["Load the plate horns evenly and stand on the machine platform, facing away from the frame.","Take a handle in each hand with your arms hanging straight down at your sides and your shoulders relaxed.","Stand tall with your chest up, your chin level and your knees soft.","Shrug your shoulders straight up toward your ears as high as they will go, and hold for a moment at the top.","Lower under control until your shoulders are fully down, and repeat for the desired number of repetitions."],["Shrug straight up. Rolling the shoulders adds travel but no extra trap work, and it takes the shoulder joint through a loaded circle for nothing.","Keep the arms straight and passive. Bending the elbows turns the movement into a short upright row and takes the load off the traps.","The handles hanging at your sides are what this machine is for -- there is no bar to clear your thighs, so you can stand upright and use a full range without shortening the top."],{"start":"images/flat/plate-loaded-shrug-start.webp","peak":"images/flat/plate-loaded-shrug-peak.webp"},"strength"],["plate-pinch","Plate Pinch","intermediate","plates","lower_arms","A grip-training staple: pinch a weight plate by its rim and hold it for time, loading the thumb and finger flexors in sustained isometric work.",["Stand a weight plate on its edge on the floor.","Squat down and pinch the plate by its rim between the fingers and thumb of one hand - no handles, just pinch.","Stand up and hold the plate at the side for time, keeping the arm straight.","Set it back down under control.","Repeat on the other hand."],["Start with a 5 kg / 10 lb plate and build up; pinching two plates together smooth-side out is a harder variation.","Chalk on the hands makes a huge difference; sweaty pinches fail fast."],{"start":"images/flat/plate-pinch-start.webp","peak":"images/flat/plate-pinch-peak.webp"},"strength"],["plate-pullover","Plate Pullover","beginner","plates","back","A pullover holding a weight plate, working the lats, chest, and serratus.",["Lie flat on a bench holding a plate with both hands.","Press the plate over the chest with arms nearly straight.","Lower the plate back in an arc behind the head until you feel a stretch.","Pull the plate back over the chest along the same arc.","Repeat for the prescribed reps."],["Keep the elbows soft but locked at the same angle.","Stop at the bottom of your clean range - no excessive shoulder stretch.","Plant the feet firmly for stability."],{"start":"images/flat/plate-pullover-start.webp","peak":"images/flat/plate-pullover-peak.webp"},"strength"],["plow-pose","Plow Pose","intermediate","bodyweight","back","An inversion in which the legs pass overhead until the toes reach the floor behind the head, lengthening the whole back of the body.",["Lie on your back with the arms alongside the body, palms down.","Lift both legs overhead and support the lower back with the hands.","Lower the toes towards the floor behind the head, keeping the legs as straight as comfort allows.","Hold the position for the prescribed time, breathing steadily and keeping the head still.","Roll down one vertebra at a time with the hands supporting the back."],["Never turn the head while you are in the pose; the neck is loaded and must stay neutral.","Rest the toes on a chair or a stack of cushions if the floor is out of reach.","Skip this pose entirely if you have any neck complaints."],{"main":"images/flat/plow-pose-main.webp"},"stretching"],["plyo-lunge","Plyo Lunge","intermediate","bodyweight","upper_legs","An explosive split-stance jump that switches the legs in mid-air, alternating each rep.",["Start in a forward lunge with one foot ahead of the other.","Drop into a deep lunge with the back knee almost touching the floor.","Drive both feet off the floor, switching legs in mid-air.","Land softly in a lunge with the opposite leg forward.","Continue alternating without pausing."],["Land softly with bent knees to absorb impact.","Switch the leg position fully - do not just hop in place.","Keep the torso upright - do not pitch forward."],{"start":"images/flat/plyo-lunge-start.webp","peak":"images/flat/plyo-lunge-peak.webp"},"plyometrics"],["plyo-push-up","Plyo Push-Up","intermediate","bodyweight","chest","An explosive push-up where the hands leave the floor at the top, training upper-body power.",["Set up in a standard push-up position with hands shoulder-width.","Lower yourself with control until the chest nearly touches the floor.","Drive up explosively so the hands leave the floor.","Land softly with the elbows slightly bent.","Repeat without pausing for the prescribed reps."],["Keep the body in a straight line - no piking or sagging.","Land softly with bent elbows to absorb impact.","Drop to knees if you cannot clear the floor cleanly."],{"start":"images/flat/plyo-push-up-start.webp","peak":"images/flat/plyo-push-up-peak.webp"},"plyometrics"],["preacher-curl","Preacher Curl","beginner","ez_bar","upper_arms","A curl variation using a preacher bench to isolate the biceps.",["Sit at a preacher bench with your upper arms resting on the pad.","Hold an EZ-bar with an underhand grip.","Curl the bar up toward your shoulders.","Lower with control until arms are nearly straight.","Repeat."],["Avoid bouncing at the bottom to protect the biceps tendon.","Keep your wrists neutral rather than letting them bend back.","Don't shrug your shoulders as the bar rises."],{"start":"images/flat/preacher-curl-start.webp","peak":"images/flat/preacher-curl-peak.webp"},"strength"],["preacher-hammer-curl","Preacher Hammer Curl","intermediate","dumbbell","upper_arms","A biceps curl performed on a preacher bench with a neutral, hammer grip to emphasize the brachialis and forearms.",["Sit at a preacher bench with a dumbbell in each hand.","Rest your upper arms on the pad with palms facing each other.","Curl the dumbbells up while keeping your wrists neutral.","Squeeze your biceps at the top of the movement.","Lower the dumbbells with control.","Repeat for the desired number of reps."],["Keep your upper arms flat against the pad.","Avoid locking out the elbows completely at the bottom.","Control the lowering phase rather than dropping the weight."],{"start":"images/flat/preacher-hammer-curl-start.webp","peak":"images/flat/preacher-hammer-curl-peak.webp"},"strength"],["pseudo-planche-push-ups","Pseudo Planche Push Ups","advanced","bodyweight","chest","A push-up with hands turned back and shoulders leaned far past the wrists, mimicking planche loading.",["Start in a push-up position with your hands turned so fingers point back.","Lean your shoulders forward past your wrists.","Lower your chest toward the floor by bending your elbows.","Keep your body in a straight line.","Press back up while maintaining the forward lean.","Repeat for the desired number of reps."],["The further you lean forward, the harder each rep becomes.","Keep your elbows close to your body as you lower.","Keep your shoulder blades protracted and your body rigid."],{"start":"images/flat/pseudo-planche-push-ups-start.webp","peak":"images/flat/pseudo-planche-push-ups-peak.webp"},"strength"],["pull-up","Pull-Up","intermediate","pull_up_bar","back","A bodyweight compound pull targeting the lats and biceps.",["Hang from a bar with an overhand grip, slightly wider than shoulder-width.","Pull yourself up until your chin is over the bar.","Lower yourself under control to a dead hang.","Repeat."],["Avoid swinging or kipping.","Engage your lats by pulling your elbows down."],{"start":"images/flat/pull-up-start.webp","peak":"images/flat/pull-up-peak.webp"},"strength"],["puppy-pose","Puppy Pose","beginner","bodyweight","shoulders","A kneeling pose halfway between child's pose and downward dog: the hips stay over the knees while the chest melts towards the floor, opening the shoulders and the upper back.",["Kneel on all fours with the hips over the knees and the hands under the shoulders.","Walk the hands forward and lower the chest towards the floor, keeping the hips high.","Rest the forehead or the chin on the mat and let the armpits soften downwards.","Hold the position for the prescribed time, breathing into the upper back.","Walk the hands back and sit onto the heels to come out."],["Keep the hips stacked over the knees; sitting back turns this into child's pose.","Press the palms down and lift the elbows off the floor to keep the arms working.","Rest the forehead on a block if the chest does not reach comfortably."],{"main":"images/flat/puppy-pose-main.webp"},"stretching"],["push-jerk","Push Jerk","intermediate","barbell","full_body","An overhead lift using a leg dip and drive to launch the barbell overhead, caught in a quarter squat.",["Hold a barbell in the front rack position at your shoulders.","Stand with feet hip-width apart.","Dip by bending your knees slightly.","Drive explosively through your legs and press the bar overhead.","Drop into a quarter-squat under the bar and lock out your arms.","Stand up fully and lower the bar to repeat."],["Keep your torso upright during the dip.","Drive with your legs before pressing with your arms.","Lock your arms out as you drop under the bar."],{"start":"images/flat/push-jerk-start.webp","peak":"images/flat/push-jerk-peak.webp"},"olympic"],["push-press","Push Press","intermediate","barbell","shoulders","A barbell overhead press using leg drive to press heavier loads overhead.",["Stand with a barbell racked on your front deltoids.","Dip slightly at the knees.","Drive up with your legs and press the bar overhead.","Lock out fully.","Lower to the start.","Repeat."],["Use leg drive only to initiate - finish with the shoulders.","Keep the core braced throughout."],{"start":"images/flat/push-press-start.webp","peak":"images/flat/push-press-peak.webp"},"strength"],["push-up","Push-Up","beginner","bodyweight","chest","A fundamental bodyweight exercise for the chest, shoulders, and triceps.",["Start in a high plank position with hands shoulder-width apart.","Lower your body until your chest nearly touches the floor.","Push back up to the starting position.","Keep your body in a straight line throughout.","Repeat."],["Tuck your elbows toward your body rather than flaring them out wide.","Brace your core and squeeze your glutes to prevent sagging hips.","Keep your neck neutral by gazing slightly ahead of your hands."],{"start":"images/flat/push-up-start.webp","peak":"images/flat/push-up-peak.webp"},"strength"],["pyramid-pose","Pyramid Pose","intermediate","bodyweight","upper_legs","A standing forward fold over a straight front leg in a short split stance, which isolates the hamstring of the front leg while both hips stay square.",["Step one foot back about a leg's length and turn the back foot out slightly.","Square both hip points towards the front of the mat and keep both legs straight.","Hinge from the hips and fold over the front leg, bringing the hands to the floor, blocks or the shin.","Hold the fold for the prescribed time with the spine long rather than rounded.","Press into the feet to come up and repeat on the other side."],["Shorten the stance until both hips can face forward; length is worth less than square hips.","Use blocks under the hands so the chest can keep reaching towards the shin.","Micro-bend the front knee if the hamstring grips."],{"main":"images/flat/pyramid-pose-main.webp"},"stretching"],["rack-pull","Rack Pull","intermediate","barbell","back","A partial-range deadlift variation performed from pins set at knee height, emphasizing the upper back, traps, and lockout strength with heavier-than-deadlift loads.",["Set the safety pins in a power rack at knee height and place a loaded barbell on them.","Stand with feet hip-width apart and grip the bar just outside your legs.","Brace your core, retract your shoulder blades, and drive through your legs to lift the bar.","Lock out your hips and knees fully at the top.","Return the bar to the pins under control and reset before the next rep."],["Use a hip-hinge pattern - keep the bar close to your body throughout.","Rack pulls allow loads well above your full deadlift max to overload the lockout.","Focus on upper back tightness to prevent rounding at heavy weights."],{"start":"images/flat/rack-pull-start.webp","peak":"images/flat/rack-pull-peak.webp"},"strength"],["rear-delt-fly","Rear Delt Fly","beginner","dumbbell","shoulders","An isolation movement targeting the posterior deltoids and upper back.",["Hold dumbbells and hinge forward at the hips.","With a slight bend in elbows, raise the dumbbells out to the sides.","Squeeze your shoulder blades at the top.","Lower with control.","Repeat."],["Choose a light weight to keep the movement strict.","Avoid using momentum from the torso to swing the weights up.","Lead with your elbows rather than your hands."],{"start":"images/flat/rear-delt-fly-start.webp","peak":"images/flat/rear-delt-fly-peak.webp"},"strength"],["reclined-butterfly","Reclined Butterfly","beginner","bodyweight","upper_legs","A restful version of the butterfly stretch: lying back with the soles of your feet together and your knees dropped out to the sides, you open the inner thighs and hips under gravity. Resting your back and arms on the floor lets the legs relax into the stretch.",["Lie on your back with your knees bent and the soles of your feet flat on the floor.","Bring the soles of your feet together and let both knees fall out to the sides.","Rest your arms on the floor with your palms up, or place your hands on your belly.","Keep your lower back resting on the floor and your shoulders relaxed.","Breathe slowly and let your knees sink toward the floor for the planned time.","Bring your knees together with your hands to finish."],["Do not push the knees down with your hands; let gravity do the work so the inner thighs relax.","Slide your feet further from the hips to ease the stretch, or closer to deepen it.","Put a pillow or folded blanket under each knee if the stretch feels too strong."],{"main":"images/flat/reclined-butterfly-main.webp"},"stretching"],["renegade-row","Renegade Row","intermediate","dumbbell","back","A plank-based rowing exercise in which a dumbbell in each hand is rowed alternately toward the hip while the other hand stays planted. It trains the back and arms while the trunk resists rotation.",["Start in a high plank with a hand on each of two dumbbells, shoulder-width apart, and the feet set wide for stability.","Brace the trunk so the body forms a straight line from head to heels.","Row one dumbbell up toward the hip, driving the elbow back along the ribs.","Keep the hips square to the floor and do not let the body twist.","Lower the dumbbell to the floor under control.","Repeat on the other side and keep alternating."],["Use hexagonal dumbbells so they do not roll, and start light.","Set the feet wider to make it easier to keep the hips level.","Do not shrug or twist; pause briefly at the top of each row to prove control."],{"start":"images/flat/renegade-row-start.webp","peak":"images/flat/renegade-row-peak.webp"},"strength"],["reverse-crunches","Reverse Crunches","intermediate","bodyweight","core","An abdominal exercise curling the hips off the floor to emphasize the lower portion of the abs.",["Lie on your back with your arms at your sides.","Raise your legs with knees bent to 90 degrees.","Curl your hips off the floor by contracting your lower abs.","Bring your knees toward your chest.","Lower your hips with control.","Repeat for the desired number of reps."],["Curl your pelvis rather than swinging your legs for momentum.","Exhale as your hips lift to deepen the abdominal contraction.","Press your arms into the floor for added stability."],{"start":"images/flat/reverse-crunches-start.webp","peak":"images/flat/reverse-crunches-peak.webp"},"strength"],["reverse-curl","Reverse Curl","beginner","barbell","upper_arms","A barbell curl with an overhand grip targeting the brachialis and forearm extensors.",["Stand and hold a barbell with an overhand grip.","Curl the bar up toward your shoulders.","Lower under control.","Repeat."],["Keep wrists straight.","Move through a full range of motion."],{"start":"images/flat/reverse-curl-start.webp","peak":"images/flat/reverse-curl-peak.webp"},"strength"],["reverse-grip-bent-over-row","Reverse Grip Bent Over Row","intermediate","barbell","back","A barbell row performed with an underhand grip, shifting emphasis toward the lower lats and biceps.",["Stand with feet shoulder-width apart and grip a barbell underhand.","Hinge forward at the hips with a slight knee bend.","Let the bar hang with your arms extended.","Pull the bar to your lower abdomen by driving your elbows back.","Squeeze your back at the top.","Lower the bar with control.","Repeat for the desired number of reps."],["Keep your back flat and your core braced throughout.","Maintain a fixed torso angle instead of heaving upright as you pull.","Keep the bar close to your legs throughout the movement."],{"start":"images/flat/reverse-grip-bent-over-row-start.webp","peak":"images/flat/reverse-grip-bent-over-row-peak.webp"},"strength"],["reverse-grip-lat-pulldown","Reverse Grip Lat Pulldown","intermediate","cable","back","A lat pulldown variation using an underhand grip that increases biceps involvement.",["Attach a straight bar to a lat pulldown machine.","Grip the bar with an underhand grip, shoulder-width apart.","Sit and secure your thighs under the pad.","Pull the bar down to your upper chest.","Squeeze your lats and biceps at the bottom.","Return the bar to the starting position with control.","Repeat for the desired number of reps."],["Keep your chest up and avoid leaning back excessively.","Pull with your elbows, not just your hands.","Squeeze your lats at the bottom of the movement."],{"start":"images/flat/reverse-grip-lat-pulldown-start.webp","peak":"images/flat/reverse-grip-lat-pulldown-peak.webp"},"strength"],["reverse-lunge","Reverse Lunge","intermediate","dumbbell","upper_legs","A lunge variation stepping backward for better knee stability.",["Stand holding dumbbells at your sides.","Step one leg back and lower your knee toward the floor.","Lower until your front thigh is parallel to the floor.","Push through your front heel to return to standing.","Repeat on both sides."],["Keep the front knee tracking in line with your toes.","Stay upright through the torso rather than leaning forward.","Lower the back knee softly instead of dropping it to the floor."],{"start":"images/flat/reverse-lunge-start.webp","peak":"images/flat/reverse-lunge-peak.webp"},"strength"],["reverse-nordic-curl","Reverse Nordic Curl","intermediate","bodyweight","upper_legs","A bodyweight quadriceps exercise performed kneeling, leaning the torso backward under control while keeping the hips extended.",["Kneel on a pad with your knees hip-width apart, shins and the tops of your feet on the floor, and your torso upright.","Keep your hips extended and core braced.","Slowly lean your torso backward while keeping your body in a straight line.","Lower as far as you can control with your quadriceps.","Pull yourself back up to the starting position.","Repeat for the desired number of reps."],["Keep your hips extended throughout - don't let them fold.","Lower only as far as you can control.","Use a pad under the knees for comfort."],{"start":"images/flat/reverse-nordic-curl-start.webp","peak":"images/flat/reverse-nordic-curl-peak.webp"},"strength"],["reverse-plank","Reverse Plank","intermediate","bodyweight","core","An isometric hold with the body facing upward, training the glutes, spinal erectors, and shoulder stability.",["Sit on the floor with your legs extended in front of you.","Place your hands behind you with fingers pointing toward your feet.","Lift your hips off the floor to form a straight line from head to heels.","Squeeze your glutes and brace your core.","Hold the position for the desired duration.","Lower your hips with control to exit."],["Don't let your hips sag as the hold progresses.","Keep your gaze up to maintain a neutral neck.","Press evenly through your palms to reduce wrist strain."],{"main":"images/flat/reverse-plank-main.webp"},"strength"],["reverse-plank-dips","Reverse Plank Dips","intermediate","bodyweight","upper_arms","Triceps dips from a straight-leg reverse plank: the legs stay extended and the hips high while the elbows bend and straighten.",["Sit with the legs straight and the hands on the floor behind the hips, fingers pointing forward.","Press into the hands and heels and lift the hips into a straight-leg reverse plank.","Bend the elbows straight back and lower the hips a short way towards the floor.","Push back up until the arms lock out, keeping the hips high.","Repeat for the desired number of repetitions."],["Keep the hips lifted at the bottom; sitting down between reps removes the load.","Keep the elbows tracking straight back rather than flaring outwards.","Bend the knees if the straight-leg version is too demanding on the hamstrings."],{"start":"images/flat/reverse-plank-dips-start.webp","peak":"images/flat/reverse-plank-dips-peak.webp"},"strength"],["reverse-tabletop-hip-pulses","Reverse Tabletop Hip Pulses","intermediate","bodyweight","upper_legs","Glute pulses from the reverse tabletop position: the arms stay straight and only the hips drop and lift, which keeps the work in the glutes rather than the triceps.",["Sit with the knees bent, the feet flat and the hands on the floor behind you.","Press into the hands and feet and lift the hips until the trunk is level with the knees.","Keeping the elbows straight, lower the hips a few centimetres.","Squeeze the glutes to lift them back to level.","Pulse for the desired number of repetitions and lower down."],["Keep the arms locked: bending the elbows turns this into a dip.","Drive the lift from the heels and the glutes, not from the lower back.","Keep the chest open and the shoulders down away from the ears."],{"start":"images/flat/reverse-tabletop-hip-pulses-start.webp","peak":"images/flat/reverse-tabletop-hip-pulses-peak.webp"},"strength"],["reverse-tabletop-hold","Reverse Tabletop Hold","beginner","bodyweight","core","A static reverse tabletop: knees bent, hands under the shoulders behind the body, hips lifted level with the knees and held, so the glutes and the whole back of the trunk work isometrically.",["Sit with the knees bent, the feet flat and the hands on the floor behind you, fingers pointing towards the heels.","Press into the hands and feet and lift the hips until the trunk is level with the knees.","Open the chest, draw the shoulders away from the ears and look straight ahead.","Hold the position for the prescribed time with the hips high.","Lower the hips under control to finish."],["Push the floor away rather than hanging on the shoulders.","Keep the knees stacked over the ankles and pointing straight ahead.","Let the head follow the line of the spine instead of dropping it back."],{"main":"images/flat/reverse-tabletop-hold-main.webp"},"strength"],["revolved-chair-pose","Revolved Chair Pose","intermediate","bodyweight","core","Chair pose with a closed twist: the hips stay level and low while the chest rotates and one elbow hooks outside the opposite thigh.",["Set up in chair pose with the knees bent, the hips back and the palms together at the chest.","Keep the knees level with each other so the hips do not open into the twist.","Rotate the chest to one side and hook the opposite elbow outside that thigh.","Press the palms together and hold for the prescribed time, lengthening the spine on each inhale.","Come back to centre and repeat on the other side."],["Line the knees up before you twist; a knee sliding forward fakes most of the rotation.","Rotate from the mid-back rather than pulling with the arm against the leg.","Keep the weight in the heels so the position stays a squat, not a lean."],{"main":"images/flat/revolved-chair-pose-main.webp"},"strength"],["revolved-crescent-lunge","Revolved Crescent Lunge","intermediate","bodyweight","core","A high lunge with a closed twist: the back heel stays lifted, the hips face forward and the chest rotates over the front thigh.",["Step into a high lunge with the front knee over the ankle and the back heel lifted.","Bring the palms together at the chest and square both hips towards the front of the mat.","Rotate the chest towards the front leg and hook the opposite elbow outside the thigh.","Hold the twist for the prescribed time, pressing the back heel towards the wall behind you.","Unwind and repeat on the other side."],["Keep the back leg straight and long; it is what stops the twist collapsing into the hips.","Drop the back knee to the floor for an easier version with the same rotation.","Lengthen the spine first, then rotate - twisting a rounded back gets you nowhere."],{"main":"images/flat/revolved-crescent-lunge-main.webp"},"strength"],["ring-dead-hang","Ring Dead Hang","intermediate","rings","back","A passive hang from gymnastic rings. The free-rotating grip recruits more stabilisers in the hands, forearms, and shoulder girdle than a fixed bar.",["Grip a pair of gymnastic rings with a neutral grip, palms facing each other.","Hang with your arms fully extended and feet off the ground.","Let the rings rotate naturally; do not fight the grip.","Keep your shoulders engaged (no shrug to the ears) and core lightly braced.","Hold for the desired duration."],["Breathe steadily rather than holding your breath.","Build hold duration gradually as your grip strengthens.","Step down under control before your grip fails completely."],{"main":"images/flat/ring-dead-hang-main.webp"},"strength"],["ring-dips","Ring Dips","advanced","rings","chest","A challenging bodyweight dip performed on gymnastic rings, demanding greater stabilization than bar dips.",["Support yourself on the rings with arms locked out.","Lower your body by bending the elbows until upper arms are parallel to the ground.","Press back up to the starting position.","Repeat."],["Keep the rings close to your body.","Turn the rings out at the top for additional chest activation."],{"start":"images/flat/ring-dips-start.webp","peak":"images/flat/ring-dips-peak.webp"},"strength"],["ring-face-pull","Ring Face Pull","intermediate","rings","back","A face pull using gymnastic rings for adjustable resistance and improved shoulder health.",["Grip the rings and lean back so your body is at an angle.","Pull the rings toward your face, flaring elbows to the sides.","Hold briefly, then return.","Repeat."],["Adjust your body angle to control difficulty.","Externally rotate your arms at the top."],{"start":"images/flat/ring-face-pull-start.webp","peak":"images/flat/ring-face-pull-peak.webp"},"strength"],["ring-l-sit","Ring L-Sit","advanced","rings","core","A static L-sit performed in the support position on gymnastic rings: the arms are locked, the body is held off the floor and the legs reach straight forward. The unstable rings make it a demanding test of core, shoulder and arm strength.",["Set the rings at about hip height and grip them with the arms straight beside the body.","Press down on the rings and lift the body into the support position, with the shoulders pushed down and away from the ears.","Turn the rings out slightly, brace the abdominals and raise the straight legs until they are parallel to the floor.","Hold the position, keeping the rings steady and the knees locked.","Lower the legs, then the body, under control."],["Keep the arms locked and the shoulders pushed down; do not sag between the rings.","Build up from tucked holds, and from parallettes or a dip station, before moving to rings.","Point the toes and squeeze the legs together."],{"main":"images/flat/ring-l-sit-main.webp"},"strength"],["ring-muscle-up","Ring Muscle-Up","advanced","rings","back","An advanced calisthenics movement combining a pull-up and a dip on gymnastic rings.",["Hang from the rings with a false grip, palms facing each other.","Pull explosively, driving the chest up to the rings.","Transition the elbows over the rings as the chest rises.","Press to full arm extension at the top.","Lower under control through the transition back to the hang."],["A false grip is essential for the transition.","Drive the elbows down hard during the transition.","Build the strength with negatives and band-assisted reps first."],{"start":"images/flat/ring-muscle-up-start.webp","peak":"images/flat/ring-muscle-up-peak.webp"},"strength"],["ring-plank","Ring Plank","advanced","rings","core","A plank held with the hands in gymnastic rings and the feet on the floor. The rings move freely, so the shoulders and trunk have to work harder to keep the body in a straight line.",["Set the rings at about knee height and take hold of them with the arms straight under the shoulders.","Step the feet back into a plank, with the body in a straight line from head to heels.","Brace the abdominals and glutes and press the rings down and slightly out to keep them steady.","Hold the position without letting the hips sag or the rings drift apart.","Step the feet in and stand up to finish."],["Keep the rings directly under the shoulders; if they swing, place the feet wider.","Push the floor away through the rings so the shoulder blades stay wide.","Raise the rings to make the hold easier and lower them to make it harder."],{"main":"images/flat/ring-plank-main.webp"},"strength"],["ring-push-up","Ring Push-Up","intermediate","rings","chest","A push-up performed on gymnastic rings, increasing the demand on stabilizers in the chest, shoulders, and core.",["Set the rings just above floor height.","Grip the rings and assume a plank position with arms straight.","Lower the chest toward the rings, keeping the elbows close to the body.","Press back up to full arm extension.","Repeat for the prescribed reps."],["Keep the rings turned out at the top to engage the chest.","Brace the core - the rings will magnify any wobble.","Drop to knees to scale the difficulty."],{"start":"images/flat/ring-push-up-start.webp","peak":"images/flat/ring-push-up-peak.webp"},"strength"],["ring-row","Ring Row","beginner","rings","back","A bodyweight row on gymnastic rings, performed at an angle for back and biceps work.",["Set the rings at hip to chest height.","Grip the rings with palms facing each other, lean back at an angle with arms straight.","Brace the core and pull the chest toward the rings.","Squeeze the shoulder blades together at the top.","Lower under control to a full-arm extension."],["The lower the body angle, the harder the row.","Keep the body in a straight line - do not let the hips sag.","Pull the elbows back, not flared out, for more lat involvement."],{"start":"images/flat/ring-row-start.webp","peak":"images/flat/ring-row-peak.webp"},"strength"],["ring-support-hold","Ring Support Hold","intermediate","rings","chest","The basic gymnastic rings position: you hold yourself above the rings with your arms locked and your body tall. The unstable rings force the shoulders, chest and triceps to keep the arms steady, and it is the foundation for ring dips and many other ring skills.",["Hang the rings at about hip height and take one ring in each hand, with your thumbs wrapped around the ring.","Press up so that your arms are straight and your body is lifted off the floor above the rings.","Turn your palms slightly outward so the rings sit beside your hips, with your elbows locked.","Push down on the rings and keep your shoulders away from your ears, with your chest lifted.","Squeeze your glutes and keep your legs together, with your feet pointed.","Hold the position for the planned time, then lower down under control."],["Keep the rings close to your body and still; any wobble tells you which side needs more control.","Press the shoulders down and away from the ears instead of letting them shrug up.","Start with the rings low and your feet on the floor if you cannot hold the position with straight arms."],{"main":"images/flat/ring-support-hold-main.webp"},"strength"],["rings-inverted-row","Rings Inverted Row","intermediate","rings","back","A bodyweight row on gymnastic rings hung low, pulling the chest up to the rings from a straight, inclined body line; more challenging than a standing ring row.",["Set the rings just above hip height.","Lie under the rings and grip them with palms facing each other.","Walk the feet forward so the body forms a straight line.","Pull the chest toward the rings, squeezing the shoulder blades.","Lower under control to a full-arm extension."],["Keep the body in a straight line - heels through head.","Squeeze the glutes and core to prevent sagging.","Elevate the feet on a box for a harder version."],{"start":"images/flat/rings-inverted-row-start.webp","peak":"images/flat/rings-inverted-row-peak.webp"},"strength"],["romanian-deadlift","Romanian Deadlift","intermediate","barbell","upper_legs","A hip-hinge movement emphasizing the hamstrings and glutes.",["Stand holding a barbell at hip level with an overhand grip.","Hinge at the hips, pushing them back while keeping legs nearly straight.","Lower the bar along your legs until you feel a hamstring stretch.","Drive your hips forward to return to standing.","Repeat."],["Keep your spine neutral and avoid rounding the lower back.","Maintain the same slight knee bend for the entire rep.","Go only as deep as your hamstring flexibility allows."],{"start":"images/flat/romanian-deadlift-start.webp","peak":"images/flat/romanian-deadlift-peak.webp"},"strength"],["rope-climb","Rope Climb","advanced","climbing_rope","back","A total-body pulling exercise that climbs a vertical rope hand-over-hand, loading the lats, biceps, grip, and core isometrically.",["Grip the rope as high as you can with both hands.","Either wrap the rope around one foot (S-hook or J-hook) or pinch it between both feet.","Pull with your arms and bring your knees up, then clamp the rope with your feet and stand up on the foot lock.","Reach higher with one hand, then the other, release the feet, and clamp the rope again higher up.","Repeat until you reach the top of the rope.","Descend hand-under-hand with the feet controlling the speed - never slide."],["Learn the foot lock before attempting longer climbs; it doubles your work capacity.","Never drop from the top; controlled descent is part of the exercise."],{"main":"images/flat/rope-climb-main.webp"},"strength"],["rowing-machine","Rowing Machine","beginner","rower","full_body","A full-body cardio machine movement in which each stroke drives with the legs, swings the torso back and pulls the handle to the ribs, training the legs, back and arms in one continuous cycle.",["Sit on the rower, strap your feet into the footplates and take the handle with an overhand grip.","Slide forward into the catch: shins vertical, torso leaning slightly ahead of the hips, arms straight out toward the flywheel.","Drive through your legs first, pushing the seat back until your knees are almost straight.","Swing your torso back past vertical, then pull the handle in to your lower ribs with your elbows travelling past your sides.","Reverse the order on the recovery - arms away, torso forward, then bend the knees - and slide back to the catch for the next stroke.","Continue for the desired time, distance or number of strokes."],["Keep the order: legs, then body, then arms on the drive, and arms, body, legs on the recovery. Breaking the arms early wastes the strongest part of the stroke.","Row with a flat back and a braced core - rounding the lower back at the catch is what turns rowing into a back ache instead of conditioning.","Let the handle travel in a straight, level line to the lower ribs, and make the recovery about twice as slow as the drive rather than rushing back to the catch."],{"start":"images/flat/rowing-machine-start.webp","peak":"images/flat/rowing-machine-peak.webp"},"cardio"],["running","Running","beginner","bodyweight","full_body","Unaided running over ground, with a flight phase in every stride where neither foot is down - the impact and the effort that separates it from walking.",["Start from an easy jog and build into your pace over the first few minutes rather than setting off at target speed.","Land with your foot under your hips, not out in front, and keep the contact with the ground short and quiet.","Run tall through the hips with a slight forward lean from the ankles, not a fold at the waist.","Bend your elbows to about ninety degrees and drive your arms forward and back, keeping them off your chest.","Breathe rhythmically and keep your shoulders, jaw and hands loose.","Hold the pace for the desired time or distance, then jog and walk for a few minutes to finish."],["Build weekly distance gradually. Almost every running injury comes from adding volume faster than the tendons and bones adapt, not from a single hard run.","Most of your running should be easy enough to talk in. Running every session at a middling hard pace is the fastest way to plateau.","Shorten your stride and let your cadence rise if you feel yourself thudding - reaching for a longer stride puts the brakes on with every footfall."],{"main":"images/flat/running-main.webp"},"cardio"],["russian-twist","Russian Twist","beginner","bodyweight","core","A rotational core exercise targeting the obliques.",["Sit on the floor with knees bent, lean back slightly.","Hold your hands together or hold a weight at chest level.","Rotate your torso to one side, then the other.","Keep your core braced throughout.","Repeat."],["Rotate from the torso rather than just swinging the arms.","Keep your chest lifted and your spine long as you twist.","Move at a controlled tempo instead of racing through reps."],{"start":"images/flat/russian-twist-start.webp","peak":"images/flat/russian-twist-peak.webp"},"strength"],["sandbag-carry","Sandbag Carry","intermediate","sandbag","full_body","A loaded carry in which you hold a sandbag against your chest in a bear hug and walk with it. The awkward, shifting load makes your legs, trunk and arms work together and challenges your grip and posture over the whole walk.",["Stand over a sandbag, squat down and wrap both arms around it, with your hands or forearms locked together underneath it.","Lift the sandbag by standing up, and hold it tight against your chest.","Brace your trunk and keep your chest tall, with the bag high enough that it does not pull your shoulders forward.","Walk forward with short, controlled steps for the planned distance or time.","Keep squeezing the bag throughout the walk.","Lower the bag to the floor with a straight back by squatting down."],["Hold the bag high on your chest; if it slides down, your lower back takes the load.","Take short steps and keep your hips level rather than swaying with the bag.","Start with a lighter bag until you can walk the full distance with a tall posture."],{"main":"images/flat/sandbag-carry-main.webp"},"strength"],["savasana","Corpse Pose","beginner","bodyweight","full_body","The closing rest of a practice: lying flat on the back with the body completely passive, letting the effects of the session settle.",["Lie on your back with the legs a comfortable distance apart and the feet falling open.","Rest the arms slightly away from the body with the palms facing up.","Let the whole body soften into the floor, including the jaw, the eyes and the hands.","Stay for the prescribed time, breathing naturally without controlling the breath.","Bend the knees and roll to one side before sitting up slowly."],["Place a bolster under the knees if the lower back does not settle.","Cover yourself with a blanket; the body cools quickly once it stops moving.","This pose is meant to require no effort at all - resist the urge to adjust constantly."],{"main":"images/flat/savasana-main.webp"},"stretching"],["scapular-pull-ups","Scapular Pull Ups","beginner","pull_up_bar","back","A straight-arm hang exercise lifting the chest by depressing and retracting the shoulder blades, building pull-up strength.",["Hang from a pull-up bar with arms fully extended.","Keep your arms straight throughout the movement.","Depress and retract your shoulder blades to lift your chest.","Pause briefly at the top of the movement.","Return to a fully hanging position.","Repeat for the desired number of reps."],["Think of pulling your shoulder blades down into your back pockets.","Avoid swinging or kipping to keep the movement strict.","Focus on small, precise movement quality rather than maximum height."],{"start":"images/flat/scapular-pull-ups-start.webp","peak":"images/flat/scapular-pull-ups-peak.webp"},"strength"],["scissor-kicks","Scissor Kicks","intermediate","bodyweight","core","A core exercise performed lying on the back, alternating straight-leg crosses to target the lower abdominals and hip flexors.",["Lie flat on your back with your hands under your glutes.","Lift both legs a few inches off the floor.","Alternate crossing one leg over the other in a scissor motion.","Keep your lower back pressed into the floor.","Maintain a steady rhythm throughout.","Repeat for the desired number of reps."],["Press your lower back into the floor throughout.","Keep your legs straight and close to the ground.","Move with control rather than speed."],{"start":"images/flat/scissor-kicks-start.webp","peak":"images/flat/scissor-kicks-peak.webp"},"strength"],["seated-barbell-overhead-press","Seated Barbell Overhead Press","intermediate","barbell","shoulders","A strict seated overhead press with a barbell, removing hip drive and isolating the deltoids and triceps.",["Set an upright bench inside a rack with the pins at about shoulder height when seated.","Sit with your back flat against the pad and unrack the barbell at the front of the shoulders.","Press the bar overhead until the arms are fully extended, tucking the head through at the top.","Lower the bar back to the collarbones under control.","Repeat for the recommended number of repetitions."],["Keep the ribs down and glutes tight; do not lean back into a bench press.","Drive the bar straight up, not forward."],{"start":"images/flat/seated-barbell-overhead-press-start.webp","peak":"images/flat/seated-barbell-overhead-press-peak.webp"},"strength"],["seated-cable-row","Seated Cable Row","intermediate","cable","back","A back exercise performed on a cable row machine, pulling a handle toward the torso while seated.",["Sit at the cable row station and place your feet on the footrests.","Grip the handle and sit upright with a slight forward lean.","Drive your elbows back and pull the handle toward your lower abdomen.","Squeeze your shoulder blades together at the end of the pull.","Extend your arms under control back to the starting position.","Repeat for the desired number of reps."],["Keep your torso upright with minimal rocking.","Drive your elbows straight back, not out to the sides.","Squeeze your shoulder blades together at the end of the pull."],{"start":"images/flat/seated-cable-row-start.webp","peak":"images/flat/seated-cable-row-peak.webp"},"strength"],["seated-calf-raise","Seated Calf Raise","beginner","seated_calf_raise_machine","lower_legs","A machine calf raise performed seated to specifically target the soleus muscle.",["Sit at a calf raise machine with the pads resting on your thighs.","Lower your heels as far as possible.","Raise up onto your toes.","Lower under control.","Repeat."],["The bent knee slackens the gastrocnemius, so the soleus does more of the work.","Use a full range of motion."],{"start":"images/flat/seated-calf-raise-start.webp","peak":"images/flat/seated-calf-raise-peak.webp"},"strength"],["seated-db-press","Seated Dumbbell Shoulder Press","intermediate","dumbbell","shoulders","A seated pressing movement for the shoulders using dumbbells.",["Sit on a bench with back support, holding dumbbells at shoulder height.","Press the dumbbells overhead until arms are fully extended.","Lower the dumbbells back to shoulder level.","Repeat."],["Keep your lower back against the pad instead of arching excessively.","Avoid clanging the dumbbells together at the top.","Keep your forearms vertical under the dumbbells throughout the press."],{"start":"images/flat/seated-db-press-start.webp","peak":"images/flat/seated-db-press-peak.webp"},"strength"],["seated-dip-machine","Seated Dip Machine","beginner","dip_machine","upper_arms","A selectorized machine version of the dip: seated upright with your back against the pad, you press two lever arms down by your sides until your arms are straight. The movement follows the path of a bodyweight dip, but the load is the weight you select on the stack, and the seat takes your body weight.",["Select your weight on the stack and adjust the seat so the handles are at about shoulder height when you are seated.","Sit upright with your back against the pad and grip the handles at your sides with your elbows bent.","Keep your shoulders down and your chest up, then press the handles down by straightening your elbows.","Squeeze your triceps at the bottom, with your arms straight but not locked out hard.","Let the handles rise back up under control until your elbows are bent to about 90 degrees.","Repeat for the planned repetitions, keeping your back against the pad."],["Keep the elbows close to your sides so the work stays on the triceps.","Do not let the shoulders roll forward or shrug as the handles rise; stop where the stretch in the chest and shoulders is comfortable.","Keep your back against the pad; leaning forward shifts the work toward the chest."],{"start":"images/flat/seated-dip-machine-start.webp","peak":"images/flat/seated-dip-machine-peak.webp"},"strength"],["seated-dumbbell-curl","Seated Dumbbell Curl","beginner","dumbbell","upper_arms","A seated bicep curl with dumbbells, the upright seated position removing body momentum for stricter form.",["Sit on a bench with a dumbbell in each hand.","Let your arms hang at your sides with palms facing forward.","Curl both dumbbells toward your shoulders by flexing your biceps.","Squeeze at the top of the movement.","Lower the dumbbells with control.","Repeat for the desired number of reps."],["Keep your elbows pinned at your sides throughout.","Avoid leaning back to help lift the weight.","Straighten your arms fully at the bottom of each rep."],{"start":"images/flat/seated-dumbbell-curl-start.webp","peak":"images/flat/seated-dumbbell-curl-peak.webp"},"strength"],["seated-dumbbell-lateral-raise","Seated Dumbbell Lateral Raise","beginner","dumbbell","shoulders","A seated isolation exercise raising dumbbells out to the sides, targeting the side deltoids without leg drive.",["Sit on a bench with a dumbbell in each hand at your sides.","Keep your back upright and core braced.","Raise both dumbbells out to the sides until they reach shoulder height.","Keep a slight bend in your elbows.","Lower the dumbbells with control.","Repeat for the desired number of reps."],["Use a light weight to keep the raise strict.","Lead with your elbows rather than your hands.","Raise to shoulder height and lower with control."],{"start":"images/flat/seated-dumbbell-lateral-raise-start.webp","peak":"images/flat/seated-dumbbell-lateral-raise-peak.webp"},"strength"],["seated-dumbbell-tricep-extension","Seated Dumbbell Tricep Extension","beginner","dumbbell","upper_arms","A seated overhead extension lowering a dumbbell behind the head, stretching and working the triceps.",["Sit on a bench with a dumbbell held overhead in both hands.","Keep your upper arms vertical next to your ears.","Lower the dumbbell behind your head by bending your elbows.","Extend your arms to press the dumbbell back overhead.","Squeeze your triceps at the top.","Repeat for the desired number of reps."],["Keep your upper arms vertical next to your ears.","Move only your forearms, keeping the elbows still.","Brace your core to avoid arching your lower back."],{"start":"images/flat/seated-dumbbell-tricep-extension-start.webp","peak":"images/flat/seated-dumbbell-tricep-extension-peak.webp"},"strength"],["seated-forward-fold","Seated Forward Fold","beginner","bodyweight","upper_legs","A seated stretch that targets the hamstrings and lower back by reaching the torso over straight legs.",["Sit on the floor with both legs straight out in front.","Keep your back long and hinge forward from the hips.","Reach your hands toward your feet.","Hold for 20 to 30 seconds, breathing steadily."],["Lead with your chest, not your head, to keep the back long.","Stretch to mild tension, never to pain."],{"main":"images/flat/seated-forward-fold-main.webp"},"stretching"],["seated-leg-curl","Seated Leg Curl","beginner","leg_curl","upper_legs","A machine isolation exercise for the hamstrings performed in a seated position, providing consistent tension and reduced hip flexor involvement compared to the lying variant.",["Adjust the seat back and ankle pad so your knees align with the machine's pivot point.","Sit upright, place the backs of your ankles on top of the pad, and grip the handles.","Curl your lower legs down and back under the seat as far as the machine allows.","Pause at peak contraction, then return the weight slowly to the starting position.","Repeat for the desired reps."],["Keep your back firmly against the backrest throughout the movement.","Point toes slightly toward your shins at peak contraction to increase hamstring activation.","Control the eccentric phase - do not let the weight pull your legs back quickly."],{"start":"images/flat/seated-leg-curl-start.webp","peak":"images/flat/seated-leg-curl-peak.webp"},"strength"],["seated-smith-machine-shoulder-press","Seated Smith Machine Shoulder Press","beginner","smith_machine","shoulders","A seated overhead press on the Smith machine, using the fixed bar path to keep the focus on the deltoids.",["Position a bench inside a Smith machine.","Sit facing forward with the bar at shoulder height.","Grip the bar slightly wider than shoulder-width.","Unrack and press the bar straight up until your arms are extended.","Lower the bar back to shoulder height with control.","Repeat for the desired number of reps."],["Align the bench so the bar tracks just in front of your nose.","Brace your core to keep the lower back from over-arching.","Plant your feet firmly on the floor for a stable base."],{"start":"images/flat/seated-smith-machine-shoulder-press-start.webp","peak":"images/flat/seated-smith-machine-shoulder-press-peak.webp"},"strength"],["seated-spinal-twist","Seated Spinal Twist","beginner","bodyweight","back","A seated rotation that stretches the obliques, mid-back and glutes by twisting toward a bent knee.",["Sit with one leg straight and cross the other foot over it.","Brace the opposite elbow against the outside of the bent knee.","Rotate your torso toward the bent knee and look over your shoulder.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Sit tall and lengthen your spine before twisting.","Twist from the mid-back, not the lower back."],{"main":"images/flat/seated-spinal-twist-main.webp"},"stretching"],["seated-straddle-stretch","Seated Straddle Stretch","beginner","bodyweight","upper_legs","A wide-legged seated stretch for the inner thighs and hamstrings, folding the torso forward between the legs.",["Sit with your legs straight and spread wide in a V.","Keep your back long and hinge forward from the hips.","Walk your hands forward along the floor.","Hold for 20 to 30 seconds, breathing steadily."],["Keep your toes pointing up, not rolled in.","Ease into the stretch slowly - never bounce."],{"main":"images/flat/seated-straddle-stretch-main.webp"},"stretching"],["shrimp-squat","Shrimp Squat","advanced","bodyweight","upper_legs","An advanced single-leg squat in which you hold the rear foot behind you and lower until your back knee touches the floor. The working leg does all the lifting through a deep range, which makes it a demanding test of quad strength, hip control and balance.",["Stand on one leg, bend the other knee and hold that foot behind you with the same-side hand.","Hold your arms and chest steady and begin to bend the standing knee, sitting your hips down and slightly back.","Lower until the back knee lightly touches the floor behind the standing foot.","Keep your chest up and your standing heel on the floor throughout the descent.","Press through the whole standing foot and straighten that leg to return to standing without letting go of the rear foot.","Complete the planned repetitions, then repeat on the other leg."],["Touch the floor with the knee lightly and do not drop onto it; control the descent with the standing leg.","Lean the trunk forward a little to keep your balance; the front knee tracks over the toes and the heel stays down.","Learn the movement first by holding a support with your free hand or lowering onto a folded mat."],{"start":"images/flat/shrimp-squat-start.webp","peak":"images/flat/shrimp-squat-peak.webp"},"strength"],["shrug","Barbell Shrug","beginner","barbell","shoulders","An isolation movement for the upper trapezius.",["Stand holding a barbell at arm's length with an overhand grip.","Shrug your shoulders straight up toward your ears.","Hold briefly at the top.","Lower your shoulders back down with control.","Repeat."],["Avoid rolling the shoulders forward or backward at the top.","Keep your arms relaxed and let the traps do the work.","Keep your neck neutral instead of jutting the chin forward."],{"start":"images/flat/shrug-start.webp","peak":"images/flat/shrug-peak.webp"},"strength"],["side-lunge","Side Lunge","intermediate","bodyweight","upper_legs","A lateral lunge stepping wide to one side, training the quads, glutes, and inner thighs through a side-to-side pattern.",["Stand with feet hip-width apart and hands at your chest.","Step one leg wide to the side, keeping the other leg straight.","Bend the stepping knee and push your hips back into a lateral squat.","Keep your chest up and the working heel planted.","Drive through the bent leg to return to standing.","Complete reps on one side, then switch."],["Push your hips back as you bend the stepping knee.","Keep your trailing leg straight and both heels planted.","Keep your chest up rather than rounding forward."],{"start":"images/flat/side-lunge-start.webp","peak":"images/flat/side-lunge-peak.webp"},"strength"],["side-lying-hip-abduction","Side-Lying Hip Abduction","beginner","bodyweight","upper_legs","A bodyweight isolation exercise targeting the gluteus medius and hip abductors.",["Lie on your side with legs stacked.","Keep the bottom leg slightly bent.","Raise the top leg toward the ceiling.","Lower under control.","Repeat on both sides."],["Keep hips stacked throughout.","Avoid tilting the pelvis."],{"start":"images/flat/side-lying-hip-abduction-start.webp","peak":"images/flat/side-lying-hip-abduction-peak.webp"},"strength"],["side-lying-hip-abduction-hold","Side-Lying Hip Abduction Hold","beginner","bodyweight","upper_legs","The top of the side-lying leg raise held for time: lying on one side with the top leg lifted and slightly behind the body, loading the glute medius isometrically.",["Lie on one side with the legs stacked and straight, and support the head on the lower arm.","Brace the trunk so the torso stays square and does not roll backwards.","Lift the top leg to about 30 to 45 degrees, keeping the toes pointing forward.","Hold the leg there for the prescribed time, breathing normally.","Lower the leg under control and repeat on the other side."],["Turning the toes towards the ceiling shifts the work to the hip flexor; keep them facing forward.","Take the leg slightly behind the line of the body to bias the glute medius.","Rest the top hand on the floor in front of you if balance is the limiting factor."],{"main":"images/flat/side-lying-hip-abduction-hold-main.webp"},"strength"],["side-lying-hip-adduction","Side Lying Hip Adduction","intermediate","bodyweight","upper_legs","A side-lying exercise raising the bottom leg against gravity, training hip adduction with body weight alone.",["Lie on your side with your bottom leg straight.","Bend your top leg and place its foot flat in front of the bottom thigh.","Support your head with your bottom arm.","Lift the bottom leg upward toward the ceiling.","Lower the leg back down under control.","Complete reps on one side, then switch."],["Keep your hips stacked vertically to avoid rolling backward.","Keep the movement slow and deliberate through the short range of motion.","Pause briefly at the top of each lift."],{"start":"images/flat/side-lying-hip-adduction-start.webp","peak":"images/flat/side-lying-hip-adduction-peak.webp"},"strength"],["side-lying-hip-adduction-hold","Side-Lying Hip Adduction Hold","intermediate","bodyweight","upper_legs","The top of the side-lying inner-thigh raise held for time: lying on one side with the top leg crossed over and the bottom leg lifted off the floor by the adductors.",["Lie on one side with the bottom leg straight and the top leg crossed over it, foot flat on the floor.","Support the head on the lower arm and keep the hips stacked vertically.","Lift the bottom leg as high as it will go with the knee straight and the toes pointing forward.","Hold that lifted position for the prescribed time without rolling the hips back.","Lower the leg under control and repeat on the other side."],["The range is short; a few centimetres of lift with a still pelvis beats a big swing.","Keep the lifted leg in line with the torso rather than drifting forward.","Press the top foot lightly into the floor if you need to steady the position."],{"main":"images/flat/side-lying-hip-adduction-hold-main.webp"},"strength"],["side-lying-lateral-raise","Side-Lying Lateral Raise","beginner","dumbbell","shoulders","A dumbbell lateral deltoid isolation exercise performed lying on one side on a flat bench, providing constant tension and eliminating momentum from the standing position.",["Lie on your side on a flat bench with your bottom arm supporting your head or gripping the bench edge.","Hold a dumbbell in your top hand with your arm resting along your side.","Keeping your elbow slightly bent, raise the dumbbell upward until your arm is perpendicular to the floor.","Pause briefly at the top, then lower the dumbbell slowly back to your side.","Complete all reps on one side before switching."],["Keep your torso still - only the working arm should move.","The lying position removes momentum and isolates the lateral deltoid effectively.","Use a lighter weight than your standing lateral raise - the leverage is more challenging."],{"start":"images/flat/side-lying-lateral-raise-start.webp","peak":"images/flat/side-lying-lateral-raise-peak.webp"},"strength"],["side-plank","Side Plank","beginner","bodyweight","core","A lateral plank variation targeting the obliques and lateral core.",["Lie on your side with your forearm on the floor, elbow under your shoulder.","Lift your hips off the floor, forming a straight line from head to feet.","Hold the position, keeping your core tight.","Breathe steadily.","Repeat on both sides."],["Don't let your top shoulder roll forward during the hold.","Push the floor away through the forearm rather than sinking into the shoulder.","Keep your head in line with your spine."],{"main":"images/flat/side-plank-main.webp"},"strength"],["side-plank-leg-lift","Side Plank with Leg Lift","intermediate","bodyweight","core","A side plank with the top leg raising up, combining lateral core work with hip abduction.",["Lie on your side with the forearm on the floor, elbow under the shoulder.","Stack the feet and lift the hips into a side plank.","From this stable side plank, raise the top leg straight up toward the ceiling.","Lower the leg back down with control without dropping the hips.","Complete reps on one side, then switch."],["Keep the hips lifted the entire set - do not let them sag.","Lead the leg lift with the heel, not the toes.","Keep the body in one straight line from head to bottom foot."],{"start":"images/flat/side-plank-leg-lift-start.webp","peak":"images/flat/side-plank-leg-lift-peak.webp"},"strength"],["side-plank-leg-lift-hold","Side Plank Leg Lift Hold","intermediate","bodyweight","core","A side plank held with the top leg raised: the hips stay lifted and square while the top leg is abducted, adding a glute medius demand to the lateral trunk hold.",["Set up in a side plank on the forearm with the elbow under the shoulder and the feet stacked.","Lift the hips until the body forms a straight line from the ankles to the head.","Raise the top leg to roughly hip height, keeping the toes pointing forward.","Hold the position for the prescribed time, keeping the hips high and the supporting shoulder stacked over the elbow.","Lower the leg and the hips under control and repeat on the other side."],["Push the supporting shoulder away from the ear so the chest does not collapse towards the floor.","Stop the set when the hips start to drop, not when the leg gets tired.","Bend the bottom knee to the floor for an easier version that keeps the leg lift intact."],{"main":"images/flat/side-plank-leg-lift-hold-main.webp"},"strength"],["single-arm-chest-supported-dumbbell-row","Single-Arm Chest-Supported Dumbbell Row","intermediate","dumbbell","back","A unilateral row performed one arm at a time on a chest-supported incline bench, isolating each side of the back and reducing momentum.",["Lie face-down on an incline bench holding a dumbbell in one hand, arm hanging straight down.","Row the dumbbell up to your side, driving your elbow past your torso.","Squeeze your shoulder blade at the top, then lower under control.","Complete all reps on one side before switching arms."],["Working one side at a time lets you focus on a full contraction without the other arm compensating.","Keep your chest pressed into the bench throughout to avoid using momentum.","Match the rep count on both sides to avoid imbalances."],{"start":"images/flat/single-arm-chest-supported-dumbbell-row-start.webp","peak":"images/flat/single-arm-chest-supported-dumbbell-row-peak.webp"},"strength"],["single-arm-db-row","Single-Arm Dumbbell Row","intermediate","dumbbell","back","A unilateral back exercise using a dumbbell for balanced development.",["Place one knee and hand on a bench for support.","Hold a dumbbell in the other hand with arm extended.","Pull the dumbbell up toward your hip, squeezing your shoulder blade.","Lower the dumbbell with control.","Repeat on both sides."],["Avoid rotating the torso to hoist the weight higher.","Let your arm extend fully at the bottom for a complete stretch.","Keep your back flat from head to hips throughout the set."],{"start":"images/flat/single-arm-db-row-start.webp","peak":"images/flat/single-arm-db-row-peak.webp"},"strength"],["single-arm-dumbbell-bench-press","Single Arm Dumbbell Bench Press","intermediate","dumbbell","chest","A flat-bench press performed with one dumbbell at a time. The unilateral load trains the chest, shoulder and triceps while the trunk works to keep the body from rotating off the bench.",["Lie back on a flat bench with the feet planted on the floor and a dumbbell held at chest level in one hand.","Rest the free hand on your stomach or hold it out to the side for balance.","Press the dumbbell up over the chest until the arm is straight.","Pause briefly at the top without letting the body roll toward the pressing arm.","Lower the dumbbell slowly to the side of the chest.","Complete the repetitions on one side, then switch arms."],["Squeeze the glutes and keep the shoulder blades pinned to the bench to resist rotation.","Lower to the side of the chest, with the elbow about 45 degrees from the body.","Use a weight you can hold level without twisting; add load only when both sides match."],{"start":"images/flat/single-arm-dumbbell-bench-press-start.webp","peak":"images/flat/single-arm-dumbbell-bench-press-peak.webp"},"strength"],["single-arm-dumbbell-overhead-tricep-extension","Single-Arm Dumbbell Overhead Tricep Extension","beginner","dumbbell","upper_arms","A one-arm overhead tricep extension giving a long, unilateral stretch of the long head and training anti-side-bend core stability.",["Stand or sit holding a dumbbell in one hand overhead, arm fully extended.","The palm faces forward; the other hand can hold your waist or an upright for stability.","Bend the elbow to lower the dumbbell behind the head in a controlled arc.","Keep the upper arm vertical and close to the head throughout.","Extend the elbow to return the dumbbell overhead.","Complete all reps on one side, then switch."],["Only the forearm moves - the upper arm stays glued in place.","Don't let the torso lean to the side; this is also a core exercise."],{"start":"images/flat/single-arm-dumbbell-overhead-tricep-extension-start.webp","peak":"images/flat/single-arm-dumbbell-overhead-tricep-extension-peak.webp"},"strength"],["single-arm-hammer-curl","Single-Arm Hammer Curl","intermediate","dumbbell","upper_arms","A unilateral dumbbell curl with a neutral grip that keeps the working elbow close to the torso while the brachialis and brachioradialis flex the elbow.",["Stand with your feet about hip-width apart and hold one dumbbell at your side with the palm facing inward.","Brace your trunk and keep the working upper arm beside your ribs as the arm hangs straight.","Curl the dumbbell toward your shoulder without rotating the palm or swinging the torso.","Squeeze the elbow flexors at the top, then lower the dumbbell under control until the arm is straight.","Complete the repetitions on one side, then switch arms and repeat."],["Let the weaker arm set the repetitions and weight so both sides receive the same work.","Keep the wrist neutral and the shoulder quiet; the movement should come from bending the elbow.","Use a controlled lowering phase instead of dropping the dumbbell from the top."],{"start":"images/flat/single-arm-hammer-curl-start.webp","peak":"images/flat/single-arm-hammer-curl-peak.webp"},"strength"],["single-arm-machine-shoulder-press","Single-Arm Machine Shoulder Press","beginner","shoulder_press_machine","shoulders","A unilateral seated machine shoulder press that lets one arm press independently while the back stays supported and the machine controls the resistance path.",["Adjust the seat so the working handle starts around shoulder height and sit with your back firmly against the pad.","Grip one handle with the wrist straight and keep the free hand on the support or resting comfortably.","Press the handle upward without leaning away from the back pad or rotating the torso.","Lower the handle under control until the elbow is just below the starting line, then repeat.","Complete the repetitions on one side, adjust the seat if needed, and train the other side."],["Start with the weaker arm and let it set the weight and repetitions for both sides.","Keep the ribs down and the back against the pad instead of leaning away from the working arm.","Stop short of a painful shoulder position; the machine path should feel controlled from bottom to top."],{"start":"images/flat/single-arm-machine-shoulder-press-start.webp","peak":"images/flat/single-arm-machine-shoulder-press-peak.webp"},"strength"],["single-arm-plank","Single-Arm Plank","advanced","bodyweight","core","A harder plank in which one hand leaves the floor so you hold the position on a single arm. With one support gone, the trunk has to resist twisting, which works the obliques and deep abdominals far more than a standard plank.",["Set up in a high plank with your hands under your shoulders and your feet a little wider than hip-width.","Brace your trunk and squeeze your glutes to keep your body in one straight line.","Shift your weight onto one arm and lift the other hand off the floor, resting it on your hip or behind your back.","Keep your hips and shoulders level and square to the floor.","Hold for the planned time, then replace the hand and rest.","Repeat on the other arm."],["Place your feet wider than usual to give yourself a more stable base.","Stop the hips from twisting toward the lifted arm; the body should stay as flat as in a normal plank.","Progress by shortening the lift time first, then lengthen it as the trunk gets stronger."],{"main":"images/flat/single-arm-plank-main.webp"},"strength"],["single-arm-plate-loaded-lateral-raise","Single-Arm Plate-Loaded Lateral Raise","beginner","plate_loaded_lateral_raise_machine","shoulders","The plate-loaded machine lateral raise worked one arm at a time, so each side lifts its own load and the two can be trained to the same standard.",["Set the seat height so the pad pivot lines up with your shoulder, and load only the side you are about to work.","Sit with your back flat against the pad and place the outside of your working upper arm against its pad.","Hold the handle on the free side or rest that hand in your lap, and keep your torso square to the seat.","Push the working arm out and up against the pad until the upper arm is level with your shoulder, then lower it under control.","Complete all the repetitions on that side, then load and work the other side."],["Match the sides on the weaker arm, not the stronger one. Working one side at a time only tells you about an imbalance if you let the weaker side set the number.","Do not let the torso tip toward the working side. With load on one arm only, the machine no longer balances itself and leaning turns the raise into a side bend.","Start with the weaker arm so it sets the target, and give both sides the same rest."],{"start":"images/flat/single-arm-plate-loaded-lateral-raise-start.webp","peak":"images/flat/single-arm-plate-loaded-lateral-raise-peak.webp"},"strength"],["single-arm-tricep-pushdown","Single Arm Tricep Pushdown","intermediate","cable","upper_arms","A triceps isolation exercise performed one arm at a time on a cable machine with a single handle.",["Attach a single handle to a high cable pulley.","Grasp the handle with one hand and keep your elbow pinned to your side.","Press the handle down until your arm is fully extended.","Squeeze the triceps at the bottom.","Slowly return to the start position.","Complete reps on one side, then switch."],["Keep your elbow pinned to your side throughout.","Avoid leaning forward to add momentum.","Fully extend your arm at the bottom for a complete contraction."],{"start":"images/flat/single-arm-tricep-pushdown-start.webp","peak":"images/flat/single-arm-tricep-pushdown-peak.webp"},"strength"],["single-db-svend-press","Single Dumbbell Svend Press","beginner","dumbbell","chest","A standing chest press holding one dumbbell upright between the palms, where the inward squeeze rather than the load is what works the pecs.",["Stand tall and hold a single dumbbell upright in front of your sternum, the handle running vertically between your flat palms.","Squeeze your palms hard into the dumbbell so the chest takes the tension and the weight cannot slip.","Press the dumbbell straight forward until your arms are almost straight, keeping it at chest height the whole way out.","Pause briefly without letting the squeeze go, then draw the dumbbell back to your chest under control.","Repeat for the recommended number of repetitions."],["The squeeze on the dumbbell is what makes the exercise. If you are gripping the handle instead of crushing the weight between flat palms, the chest is not working.","Use a light dumbbell. Your palms hold it up on friction alone, so the grip sets the ceiling long before the chest does.","Keep the elbows slightly bent at the lockout and the dumbbell at sternum height throughout; letting it sag toward the hips takes the pecs out of it."],{"start":"images/flat/single-db-svend-press-start.webp","peak":"images/flat/single-db-svend-press-peak.webp"},"strength"],["single-leg-box-squat","Single-Leg Box Squat","intermediate","plyo_box","upper_legs","A single-leg squat in which you sit back onto a box and stand up again on the same leg, with the other leg held out in front of you. The box limits the depth and gives you a target to reach, so it is a controlled way to build toward the pistol squat.",["Stand in front of a sturdy box or bench that is about knee height, with your back to it.","Shift your weight onto one leg and lift the other leg out in front of you, with your arms stretched forward for balance.","Push your hips back and bend the standing knee, lowering yourself under control toward the box.","Sit lightly on the box without dropping onto it, keeping your chest up and the free leg off the floor.","Press through the whole standing foot and straighten that leg to stand up again.","Complete the planned repetitions, then repeat on the other leg."],["Choose a higher box to start; lower it as your strength and control improve.","Keep the knee of the standing leg tracking over your toes and your heel on the floor.","Touch the box with your hips rather than relaxing onto it, and use the arms as a counterweight."],{"start":"images/flat/single-leg-box-squat-start.webp","peak":"images/flat/single-leg-box-squat-peak.webp"},"strength"],["single-leg-calf-raise","Single Leg Calf Raise","beginner","bodyweight","lower_legs","A unilateral calf raise that loads one calf at a time, exposing strength imbalances side to side.",["Stand on one foot on the floor and lift the other foot off the ground, knee bent.","Keep the arms relaxed at your sides and brace your core to hold your balance.","Drive up onto the ball of the foot as high as possible.","Lower the heel back to the floor under control.","Complete all reps on one side, then switch."],["Pause at the top to maximize the contraction.","Lower slowly instead of dropping onto the heel.","Hold a dumbbell on the working side once bodyweight is too easy."],{"start":"images/flat/single-leg-calf-raise-start.webp","peak":"images/flat/single-leg-calf-raise-peak.webp"},"strength"],["single-leg-extension","Single Leg Extension","intermediate","leg_extension","upper_legs","A quadriceps isolation exercise performed on a leg extension machine, working one leg at a time.",["Sit on a leg extension machine and place one foot under the pad.","Rest the other foot on the floor or let it hang.","Extend the working leg until it is nearly straight.","Squeeze the quadriceps at the top.","Lower the leg back down under control.","Complete reps on one side, then switch."],["Squeeze the quadriceps hard at the top of the movement.","Lower the weight under control rather than letting it drop.","Keep your back flat against the pad."],{"start":"images/flat/single-leg-extension-start.webp","peak":"images/flat/single-leg-extension-peak.webp"},"strength"],["single-leg-glute-bridge","Single Leg Glute Bridge","intermediate","bodyweight","upper_legs","A unilateral glute bridge that loads one glute at a time and helps even out side-to-side imbalances.",["Lie on your back with one knee bent, foot flat, the other leg extended straight.","Brace the core and squeeze the glute on the working side.","Drive the hips up by pressing through the working heel.","Pause at the top with the body in a straight line from shoulders to knee.","Lower under control. Complete reps per side, then switch."],["Keep the extended leg in line with the working thigh.","Squeeze the glute hard at the top - do not push with the lower back.","Slow the lowering phase for more stimulus."],{"start":"images/flat/single-leg-glute-bridge-start.webp","peak":"images/flat/single-leg-glute-bridge-peak.webp"},"strength"],["single-leg-glute-bridge-hold","Single-Leg Glute Bridge Hold","intermediate","bodyweight","upper_legs","The top of the single-leg glute bridge held for time: hips extended and level while one leg is lifted, so one glute carries the whole position.",["Lie on your back with one knee bent and that foot flat, and lift the other leg so the thigh is roughly vertical.","Push through the heel of the planted foot and lift the hips until the body is straight from the knee to the shoulders.","Level the pelvis so the lifted side does not drop, and tuck the ribs down.","Hold the top position for the prescribed time, keeping the lifted knee still.","Lower the hips under control and repeat on the other side."],["Watch the pelvis rather than the height: a level hip at a lower position beats a high, twisted one.","Keep the planted heel close to the glute so the hamstring does not cramp.","Extend the free leg straight if the position feels easy, but only while the pelvis stays level."],{"main":"images/flat/single-leg-glute-bridge-hold-main.webp"},"strength"],["single-leg-hip-thrust","Single-Leg Hip Thrust","intermediate","flat_bench","upper_legs","A hip thrust done on one leg: with your upper back resting on a flat bench and one foot planted on the floor, you drive your hips up until your body is level, holding the other knee raised. Working one side at a time isolates the glute and shows up any difference between the legs.",["Sit on the floor with your back to a flat bench and rest your upper back against its edge, just below your shoulder blades.","Plant both feet flat on the floor with your knees bent, then lift one knee toward your chest and keep it there.","Keep your chin tucked toward your chest and your arms resting along the bench.","Drive through the heel of the planted foot and push your hips up until your body is level from your shoulders to your knee.","Squeeze your glute at the top without arching your lower back, then lower your hips under control.","Complete the planned repetitions, then switch legs."],["Keep the planted shin close to vertical at the top so the glute, rather than the hamstring, does most of the work.","Do not let your hips twist toward the lifted leg; keep your pelvis level throughout.","Anchor the bench against a wall so it cannot slide, and start with the two-leg hip thrust until the movement is smooth."],{"start":"images/flat/single-leg-hip-thrust-start.webp","peak":"images/flat/single-leg-hip-thrust-peak.webp"},"strength"],["single-leg-hip-thrust-hold","Single-Leg Hip Thrust Hold","intermediate","flat_bench","upper_legs","A held top position of the hip thrust on one leg: with your upper back on a bench and one foot on the floor, you lift your hips until your body is flat and keep the other knee raised. Holding it loads the glute of the working leg through the full contraction.",["Sit on the floor with your back to a flat bench and rest your upper back against its edge, just below your shoulder blades.","Plant both feet flat on the floor with your knees bent, then lift one knee toward your chest.","Keep the other foot planted under that knee and your chin tucked toward your chest.","Drive through the planted heel and push your hips up until your body is flat from shoulders to knee.","Keep your ribs down and hold the top position for the planned time.","Lower your hips under control and repeat on the other leg."],["Do not arch the lower back at the top; finish the lift by squeezing the glute rather than thrusting the ribs up.","Keep the working shin close to vertical so the glute, not the hamstring, does most of the effort.","Anchor the bench against a wall so it cannot slide as you push."],{"main":"images/flat/single-leg-hip-thrust-hold-main.webp"},"strength"],["single-leg-lying-leg-curl","Single Leg Lying Leg Curl","intermediate","leg_curl","upper_legs","A unilateral hamstring isolation on the lying leg curl machine, addressing strength imbalances between legs.",["Lie face down on a lying leg curl machine.","Position one ankle under the pad, keeping the other foot off the machine.","Curl the working leg by bringing your heel toward your glute.","Squeeze the hamstring at the top.","Lower the leg back down under control.","Complete reps on one side, then switch."],["Keep your hips pressed into the bench throughout the curl.","Avoid jerking the pad up with momentum.","Start with the weaker leg and match its reps on the other side."],{"start":"images/flat/single-leg-lying-leg-curl-start.webp","peak":"images/flat/single-leg-lying-leg-curl-peak.webp"},"strength"],["single-leg-press","Single Leg Press","intermediate","leg_press","upper_legs","A lower-body exercise performed on a leg press machine, pressing the platform with one leg at a time.",["Sit in a leg press machine with one foot placed on the platform.","Keep the other leg off the platform, resting to the side.","Release the safeties and lower the platform by bending your knee.","Stop when your knee is near a 90-degree angle.","Drive through the heel to press the platform back up.","Complete reps on one side, then switch."],["Keep your foot flat and centered on the platform.","Avoid letting your knee cave inward.","Don't lock out the knee forcefully at the top."],{"start":"images/flat/single-leg-press-start.webp","peak":"images/flat/single-leg-press-peak.webp"},"strength"],["single-leg-rdl-hold","Single Leg RDL Hold","intermediate","bodyweight","upper_legs","A balance hold at the bottom of a single-leg Romanian deadlift: standing on one leg, the torso is hinged forward and the other leg extends back in line with the body. It trains the hamstrings, glutes and trunk while challenging balance.",["Stand on one leg with a slight bend in the knee and the arms hanging in front of you.","Hinge at the hip, sending the free leg straight back as the torso tips forward.","Keep the back flat and the hips square to the floor.","Stop when the torso and the free leg are roughly parallel to the floor and hold the position.","Return to standing under control, then switch legs."],["Think of a seesaw: the torso and the free leg move together.","Keep the hips level; do not let the free hip rotate upward.","Fix your gaze on a point on the floor ahead to help your balance."],{"main":"images/flat/single-leg-rdl-hold-main.webp"},"strength"],["single-leg-romanian-deadlift","Single Leg Romanian Deadlift","intermediate","dumbbell","back","A single-leg hip hinge with dumbbells, training the hamstrings and glutes while challenging balance and hip stability.",["Stand on one leg holding a dumbbell in each hand in front of your thighs.","Keep a slight bend in the standing knee.","Hinge at the hip while extending the free leg behind you.","Lower the dumbbells along your standing leg until you feel a hamstring stretch.","Drive through the heel to return to upright.","Complete reps on one side, then switch."],["Keep your hips square to the floor as you hinge.","Fix your eyes on a spot ahead to help balance.","Reach the rear heel straight back rather than letting the leg swing wide."],{"start":"images/flat/single-leg-romanian-deadlift-start.webp","peak":"images/flat/single-leg-romanian-deadlift-peak.webp"},"strength"],["sit-ups","Sit-Ups","beginner","bodyweight","core","A classic abdominal exercise with a full range of motion.",["Lie on your back with knees bent and feet anchored.","Cross your arms over your chest or place hands behind your head.","Sit all the way up until your torso is upright.","Lower back down with control.","Repeat."],["Avoid pulling on your neck when your hands are behind your head.","Roll up through the spine rather than jerking with momentum.","Exhale on the way up to reinforce the abdominal contraction."],{"start":"images/flat/sit-ups-start.webp","peak":"images/flat/sit-ups-peak.webp"},"strength"],["six-inch-hold","Six Inch Hold","intermediate","bodyweight","core","A static core hold lying on the back with the head, shoulders and straight legs lifted about six inches off the floor. It trains the lower abdominals and hip flexors.",["Lie on your back with the legs straight and the arms resting along your sides.","Press the lower back into the floor and brace the abdominals.","Lift the head, shoulders and straight legs about six inches off the floor.","Hold the position while breathing steadily.","Lower slowly to rest."],["Keep the lower back flat; if it arches, raise the legs a little higher or bend the knees.","Keep the neck relaxed and the chin slightly tucked.","Build up with short holds and rest in between."],{"main":"images/flat/six-inch-hold-main.webp"},"strength"],["ski-erg","SkiErg","intermediate","ski_erg","full_body","A standing cardio exercise on a ski ergometer that combines a forceful double-pole pull with a small hip hinge to train full-body power and endurance.",["Stand facing the SkiErg with the handles overhead and the feet about hip-width apart.","Brace the trunk and drive the handles down by pulling with the lats while hinging slightly at the hips.","Finish with the hands beside the thighs and the knees softly bent.","Let the cords retract as you return the arms overhead and stand tall.","Repeat smoothly while keeping the heels planted and the torso controlled."],["Lead the pull with the lats instead of turning it into an arm-only movement.","Keep the hinge compact; do not collapse into a deep squat.","Allow the handles to return under control so the cords stay taut."],{"start":"images/flat/ski-erg-start.webp","peak":"images/flat/ski-erg-peak.webp"},"cardio"],["skull-crusher","Skull Crusher","intermediate","barbell","upper_arms","A lying triceps extension using a barbell to isolate the triceps through a full range of motion.",["Lie on a flat bench holding a barbell over your chest with a narrow grip.","Lower the bar toward your forehead by bending at the elbows.","Extend your arms back to the start.","Repeat."],["Keep upper arms vertical throughout.","Lower slowly to protect the elbows."],{"start":"images/flat/skull-crusher-start.webp","peak":"images/flat/skull-crusher-peak.webp"},"strength"],["sled-push","Sled Push","intermediate","sled","full_body","A conditioning and leg-strength exercise: leaning into the uprights of a loaded sled, you drive it across the floor with short, powerful steps. The legs and glutes push the load while the arms and trunk stay braced, and there is no weight on the spine.",["Load the sled and stand behind it, holding the uprights with your hands at about chest height.","Lean forward so your body forms a straight diagonal line from your head to your back heel, with your arms extended.","Brace your trunk and drive one knee forward, pushing the floor away with the ball of your back foot.","Keep taking short, powerful steps, driving each leg back hard to move the sled forward.","Keep your hips low and your back flat, and look a short distance ahead of the sled.","Push for the planned distance or time, then stop under control and rest before the next push."],["Stay low with your arms locked or slightly bent; standing up tall makes you lose drive and push the sled with your arms.","Push through the balls of the feet with short, quick steps rather than long strides.","Pick a load you can keep moving at a steady pace; if the sled stops, the load is too heavy for the set."],{"main":"images/flat/sled-push-main.webp"},"strength"],["sled-row","Sled Row","intermediate","sled","back","A loaded carry-and-pull performed by holding a sled's strap handles and rowing it toward you as you walk backwards, training the back through a continuous drag rather than discrete reps.",["Load a sled with two straps attached and take one strap handle in each hand.","Stand facing the sled with the arms extended and the torso leaned back slightly against the load.","Pull the sled toward you by driving the elbows back, and take a short step backwards as you do.","Extend the arms again, step back once more, and repeat the pull.","Continue for distance or time, keeping a steady pull-and-step rhythm."],["Keep the chest up and the back flat - let the legs carry you backwards rather than rounding over the sled.","Use a load you can move continuously; the point is a steady drag, not a maximal pull.","No straps? A rope looped around the sled works the same way."],{"start":"images/flat/sled-row-start.webp","peak":"images/flat/sled-row-peak.webp"},"strength"],["smith-machine-bench-press","Smith Machine Bench Press","beginner","smith_machine","chest","A bench press variation in the Smith machine, where the guided bar path adds stability for the chest.",["Lie on a flat bench set inside a Smith machine.","Grip the bar slightly wider than shoulder-width and unrack it.","Lower the bar under control to your mid-chest.","Pause briefly without bouncing.","Press the bar back up until your arms are fully extended.","Repeat for the desired number of reps."],["Align the bench so the bar lands at mid-chest, not the neck.","Keep your shoulder blades pulled back and down against the bench.","Keep your feet planted and your glutes on the bench."],{"start":"images/flat/smith-machine-bench-press-start.webp","peak":"images/flat/smith-machine-bench-press-peak.webp"},"strength"],["smith-machine-bent-over-row","Smith Machine Bent Over Row","beginner","smith_machine","back","A bent-over row in the Smith machine, with a fixed bar path that keeps the pull strict for the lats.",["Stand inside a Smith machine with feet shoulder-width apart.","Grip the bar with an overhand grip slightly wider than shoulders.","Hinge at the hips until your torso is roughly 45 degrees.","Pull the bar toward your lower chest by driving your elbows back.","Squeeze your shoulder blades at the top.","Lower the bar under control and repeat."],["Hold your hip hinge steady rather than rising as you fatigue.","Keep your neck neutral by looking at the floor slightly ahead.","Brace your core to protect the lower back throughout."],{"start":"images/flat/smith-machine-bent-over-row-start.webp","peak":"images/flat/smith-machine-bent-over-row-peak.webp"},"strength"],["smith-machine-bulgarian-split","Smith Machine Bulgarian Split Squat","intermediate","smith_machine","upper_legs","A Bulgarian split squat performed in a Smith machine for added stability and load control.",["Set up a bench behind the Smith machine. Rest the bar on your traps.","Place the rear foot on the bench and front foot forward.","Lower your back knee toward the floor.","Push through the front heel to return.","Repeat on both sides."],["The Smith machine guides the bar path.","Focus on keeping front knee tracking over toes."],{"start":"images/flat/smith-machine-bulgarian-split-start.webp","peak":"images/flat/smith-machine-bulgarian-split-peak.webp"},"strength"],["smith-machine-calf-raise","Smith Machine Calf Raise","beginner","smith_machine","lower_legs","A standing calf raise in the Smith machine with the bar held behind the thighs at arm's length, the guided bar keeping the movement steady.",["Stand in the Smith machine with your back to the bar, set just below hip height.","Reach back and grip the bar behind your thighs with both hands, arms straight.","Unrack the bar and raise up onto the balls of your feet.","Squeeze your calves hard at the top.","Lower your heels to the floor under control (below the edge if you stand on a low platform).","Repeat for the desired number of reps."],["Avoid bouncing out of the bottom stretch position.","Keep your knees straight but not forcefully locked.","Use a slow tempo through the full range rather than pumping short reps."],{"start":"images/flat/smith-machine-calf-raise-start.webp","peak":"images/flat/smith-machine-calf-raise-peak.webp"},"strength"],["smith-machine-decline-bench-press","Smith Machine Decline Bench Press","beginner","smith_machine","chest","A bench press on a decline bench under the Smith machine, where the head-down angle and the guided bar path put the work on the lower chest.",["Set a decline bench in the machine so the bar lines up with your lower chest when you lie down, and hook your legs under the pads.","Lie back with your head at the low end, take an overhand grip slightly wider than your shoulders and unrack the bar.","Lower the bar under control until it touches your lower chest, keeping your elbows at roughly forty-five degrees from your torso.","Press the bar back up until your arms are extended, without locking the elbows out hard.","Repeat for the desired number of repetitions, then rack the bar before releasing your legs."],["Line the bench up before you load it. The bar only moves in one plane, so if the bench is a few centimetres out the bar will meet your throat or your stomach instead of your lower chest.","Secure your legs under the pads first. Head-down and unsecured, you slide toward the low end of the bench on the first hard rep.","Come down and sit up slowly between sets. Long sets with the head below the heart make people light-headed, and this variation is where it happens."],{"start":"images/flat/smith-machine-decline-bench-press-start.webp","peak":"images/flat/smith-machine-decline-bench-press-peak.webp"},"strength"],["smith-machine-front-squat","Smith Machine Front Squat","beginner","smith_machine","upper_legs","A squat on the Smith machine with the bar racked across the front of the shoulders, where the fixed path and the upright torso keep the work on the quads.",["Set the bar at upper-chest height and step under it so it rests across the front of your shoulders, against your collarbones.","Cross your arms over the bar or take an open front-rack grip, and drive your elbows up until your upper arms are close to parallel with the floor.","Unrack the bar and stand with your feet about shoulder-width apart and slightly forward of it.","Sit straight down, keeping your elbows high and your torso upright, until your thighs are at least parallel to the floor.","Drive through the middle of your feet to stand back up, and repeat for the desired number of repetitions."],["High elbows are the whole exercise. As soon as they drop, the bar rolls off your shoulders onto your hands and the rack position collapses.","Set the safety stops just below your deepest squat position before you unrack anything -- on a front squat the fastest way out of a failed rep is to let the bar go.","Standing slightly ahead of the bar lets you keep your torso vertical. Under a fixed path, a stance directly beneath the bar forces you to lean and pushes the bar off the front rack."],{"start":"images/flat/smith-machine-front-squat-start.webp","peak":"images/flat/smith-machine-front-squat-peak.webp"},"strength"],["smith-machine-good-morning","Smith Machine Good Morning","beginner","smith_machine","upper_legs","A hip hinge with the Smith machine bar resting on the upper back, bending forward at the hips against a fixed bar path to load the hamstrings and the spinal erectors.",["Set the bar at upper-back height, step under it and settle it across your traps, then unrack it with your feet about hip-width apart.","Soften your knees slightly and keep them there -- this is a hinge, not a squat.","Push your hips straight back and let your torso tip forward, keeping your back flat and your head in line with your spine.","Stop when you feel a strong stretch in your hamstrings, with your torso somewhere near parallel to the floor.","Drive your hips forward to stand back up, squeezing the glutes at the top, and repeat for the desired reps."],["Use much less weight than you would for a squat. The bar is a long way from your hips at the bottom, and that lever, not the number on the bar, is what the exercise costs you.","Hips back, not chest down. If your torso drops without your hips travelling backwards you are bending your spine instead of hinging at the hip.","Let the range of motion end where your back would start to round. Depth on a good morning is set by your hamstrings, and the machine will happily take you past that point."],{"start":"images/flat/smith-machine-good-morning-start.webp","peak":"images/flat/smith-machine-good-morning-peak.webp"},"strength"],["smith-machine-hip-thrust","Smith Machine Hip Thrust","beginner","smith_machine","upper_legs","A hip thrust with the bar running in the Smith machine guides, so the load travels in a fixed vertical line across the hips while the shoulders stay supported on a bench.",["Set a flat bench inside the Smith machine, parallel to the bar and positioned so the bar will sit over your hip crease.","Set the bar low enough that you can get under it while seated on the floor, then sit with your upper back against the bench.","Slide your hips under the bar so it sits over your hip crease, pad it if you need to, and unhook it with your feet flat and about hip-width apart.","Drive through your heels and extend your hips until your thighs and torso form a straight line, squeezing the glutes at the top.","Lower your hips under control until they are just off the floor, and repeat for the desired number of repetitions."],["Line the bench up before you load the bar. The bar can only move straight up and down, so if the bench is out of place the bar lands on your stomach or your thighs and there is no adjusting mid-set.","Set the safety stops where the bar sits at the bottom of your range. Getting out from under a loaded Smith bar on the floor is awkward, and the stops make it a non-event.","Look at a point in front of you rather than at the ceiling. Keeping the chin tucked stops the movement turning into a lower-back arch at lockout."],{"start":"images/flat/smith-machine-hip-thrust-start.webp","peak":"images/flat/smith-machine-hip-thrust-peak.webp"},"strength"],["smith-machine-incline-bench-press","Smith Machine Incline Bench Press","beginner","smith_machine","chest","An incline press in the Smith machine, guiding the bar to target the upper chest and front delts.",["Set an incline bench at 30-45 degrees inside a Smith machine.","Lie back and grip the bar slightly wider than shoulder-width.","Unrack and lower the bar to your upper chest.","Pause briefly at the bottom.","Press the bar back up until your arms are extended.","Repeat for the desired number of reps."],["Position the bench so the bar lands on the upper chest, not the throat.","Stack your wrists directly above your elbows.","Avoid driving your head forward off the bench as you press."],{"start":"images/flat/smith-machine-incline-bench-press-start.webp","peak":"images/flat/smith-machine-incline-bench-press-peak.webp"},"strength"],["smith-machine-rdl","Smith Machine Romanian Deadlift","beginner","smith_machine","upper_legs","A Romanian deadlift performed on a Smith machine, fixing the bar path so you can focus on the hip hinge and posterior-chain stretch.",["Set the Smith machine bar at mid-thigh height and stand facing it, feet hip-width, close enough that the bar touches your thighs.","Unrack the bar with an overhand grip just outside the hips.","Push the hips back while letting the bar slide down the front of the legs.","Go until you feel a deep hamstring stretch, with a flat back and a soft knee bend.","Drive the hips forward to return to standing, keeping the bar close to the body.","Repeat for the recommended number of repetitions."],["The bar is locked to a straight path - use that to groove the hinge pattern.","Do not round the lower back at the bottom; stop at the end of your hamstring range."],{"start":"images/flat/smith-machine-rdl-start.webp","peak":"images/flat/smith-machine-rdl-peak.webp"},"strength"],["smith-machine-reverse-grip-bent-over-row","Smith Machine Reverse Grip Bent Over Row","beginner","smith_machine","back","An underhand-grip row performed in the Smith machine, biasing the lower lats and biceps on a guided bar path.",["Stand inside a Smith machine and grip the bar with an underhand grip.","Hinge forward at the hips until your torso is about 45 degrees.","Keep your back flat and core braced.","Pull the bar toward your lower abdomen.","Squeeze your lats and shoulder blades at the top.","Lower the bar under control and repeat."],["Keep your wrists straight under the underhand grip.","Drive your elbows back close to your sides.","Avoid rising out of the hinge to cheat the bar up."],{"start":"images/flat/smith-machine-reverse-grip-bent-over-row-start.webp","peak":"images/flat/smith-machine-reverse-grip-bent-over-row-peak.webp"},"strength"],["smith-machine-reverse-lunge","Smith Machine Reverse Lunge","intermediate","smith_machine","upper_legs","A reverse lunge under a Smith machine bar, stepping one foot back into the lunge and returning it to standing each repetition while the guided bar holds the load steady.",["Set the bar so it sits across your upper traps when you stand, then unrack it with your feet under your hips.","Step one foot straight back and lower the rear knee toward the floor, keeping the front shin vertical and most of your weight on the front foot.","Stop when the rear knee is just short of the floor and the front thigh is roughly parallel to it.","Push through the front heel and bring the rear foot back to standing under the bar.","Complete all the repetitions on one side, then switch legs, or alternate legs on every repetition."],["Step back far enough. A short step puts the front knee well past the toes, which the fixed bar path will not let you correct once you are loaded.","The stepping foot does the travelling; the front foot does not move at all. If it shifts between reps, your step is too long or too short.","The rack removes the balance, not the load -- keep the trunk braced and stand up out of the bottom rather than leaning back into the bar."],{"start":"images/flat/smith-machine-reverse-lunge-start.webp","peak":"images/flat/smith-machine-reverse-lunge-peak.webp"},"strength"],["smith-machine-shoulder-press","Smith Machine Shoulder Press","beginner","smith_machine","shoulders","A standing overhead press in the Smith machine, with the guided bar path providing stability for the shoulders.",["Stand inside a Smith machine with your feet hip-width apart and the bar at shoulder level.","Grip the bar slightly wider than shoulder-width at shoulder level.","Unrack the bar and press it overhead until your arms are extended.","Lower the bar back to shoulder level under control.","Keep your core tight throughout.","Repeat for the desired number of reps."],["Stand directly under the bar path before unracking.","Tilt your head back slightly as the bar passes your face.","Avoid flaring your ribs as the bar travels overhead."],{"start":"images/flat/smith-machine-shoulder-press-start.webp","peak":"images/flat/smith-machine-shoulder-press-peak.webp"},"strength"],["smith-machine-shrug","Smith Machine Shrug","beginner","smith_machine","back","A Smith machine isolation exercise elevating the shoulders to target the trapezius with a fixed bar path.",["Stand upright inside a Smith machine with the bar at thigh height.","Grip the bar slightly wider than shoulder-width with an overhand grip.","Unrack the bar and let it hang in front of your thighs.","Shrug your shoulders straight up toward your ears.","Hold the top for a moment, then lower slowly.","Repeat for the desired number of reps."],["Keep your arms straight so the traps, not the biceps, do the work.","Lift straight up and down rather than rolling the shoulders.","Keep your neck neutral and avoid jutting the chin forward."],{"start":"images/flat/smith-machine-shrug-start.webp","peak":"images/flat/smith-machine-shrug-peak.webp"},"strength"],["smith-machine-split-squat","Smith Machine Split Squat","intermediate","smith_machine","upper_legs","A stationary split squat under a Smith machine bar, with the rear foot resting on the floor rather than a bench, so the guided path takes balance out of a single-leg movement.",["Set the bar on the hooks just below shoulder height, then step under it and rest it across your upper traps.","Unrack the bar and take a long stride forward with one foot, leaving the rear foot planted on the floor with the heel lifted.","Check that your front shin will stay roughly vertical when you descend; adjust the stride length before you start loading it.","Lower straight down by bending both knees until the rear knee is just above the floor and the front thigh is close to parallel.","Drive through the front heel to return to the start, keeping both feet in place, and repeat for the desired reps before switching sides."],["Set the stride length first, unloaded. Once the bar is on your back the fixed path will not let you shuffle forward to fix a stance that is too short.","Go straight down rather than forward. The bar can only travel vertically, so pushing the hips forward just jams your front knee past your toes.","Do the same number of reps on each side and start with the weaker leg, since a machine-guided split squat hides a side-to-side difference that a free bar would expose."],{"start":"images/flat/smith-machine-split-squat-start.webp","peak":"images/flat/smith-machine-split-squat-peak.webp"},"strength"],["smith-machine-squat","Smith Machine Squat","beginner","smith_machine","upper_legs","A squat performed on the Smith machine, using the fixed bar path for added stability while training quads and glutes.",["Set the Smith machine bar at shoulder height and step under it.","Position the bar across your upper traps and unrack it.","Stand with feet shoulder-width apart, slightly forward of the bar.","Descend until your thighs are parallel to the floor.","Drive through your heels to return to standing.","Repeat for the desired number of reps."],["Keep your knees tracking in line with your toes.","Brace your core and keep your chest up throughout the movement.","Set the safety stops just below your lowest squat depth."],{"start":"images/flat/smith-machine-squat-start.webp","peak":"images/flat/smith-machine-squat-peak.webp"},"strength"],["smith-machine-upright-row","Smith Machine Upright Row","beginner","smith_machine","shoulders","An upright row on the Smith machine, pulling the guided bar up the front of the torso with the elbows leading, to work the side deltoids and the upper traps.",["Set the bar at hip height, take an overhand grip a little wider than shoulder-width and stand close to it with your arms straight.","Unrack the bar and stand tall with your shoulders back and your core braced.","Pull the bar straight up the front of your body, leading with your elbows and keeping the bar close.","Stop when the bar reaches your lower chest and your elbows are level with your shoulders, then pause briefly.","Lower the bar under control until your arms are straight again, and repeat for the desired reps."],["Stop at chest height. Pulling the bar to the collarbone rotates the shoulder into the position that causes the impingement this exercise is known for.","Lead with the elbows, not the hands. If the wrists come up first the biceps take over and the side deltoids barely work.","Widen the grip if the movement pinches. A narrow grip forces more internal rotation, and the fixed bar path gives you nowhere else to go."],{"start":"images/flat/smith-machine-upright-row-start.webp","peak":"images/flat/smith-machine-upright-row-peak.webp"},"strength"],["snatch","Snatch","intermediate","barbell","full_body","An Olympic lift pulling a barbell from the floor to overhead in one motion, caught in an overhead squat.",["Stand with feet hip-width apart and grip the bar wide.","Hinge down, keeping your back flat and chest up.","Explosively extend hips, knees, and ankles to drive the bar up.","Pull yourself under the bar into an overhead squat.","Stand up with the bar locked out overhead.","Return the bar to the floor and repeat."],["Keep the bar close to your body as it travels up.","Extend your hips fully before pulling under the bar.","Lock your arms out and stabilize before standing up."],{"start":"images/flat/snatch-start.webp","peak":"images/flat/snatch-peak.webp"},"olympic"],["sphinx-pose","Sphinx Pose","beginner","bodyweight","core","A gentle prone backbend on the forearms: the elbows stay under the shoulders and the chest lifts, so the lower back extends without any strain from the arms.",["Lie face down and place the forearms on the floor with the elbows directly under the shoulders.","Press the forearms and the tops of the feet down and lift the chest.","Draw the shoulders away from the ears and lengthen the back of the neck.","Hold the position for the prescribed time, breathing into the front of the chest.","Lower the chest to the floor and rest."],["Slide the elbows slightly forward for a gentler bend, back for a deeper one.","Keep the glutes soft so the lower back does not clench.","Stop where the position feels like a stretch, not like a pinch."],{"main":"images/flat/sphinx-pose-main.webp"},"stretching"],["spider-curl","Spider Curl","intermediate","dumbbell","upper_arms","A curl lying face-down on an incline bench with arms hanging vertical, isolating the biceps through a strict range.",["Lie face down on an incline bench with arms hanging straight down.","Hold a dumbbell in each hand with an underhand grip.","Keep your upper arms vertical as you curl the weights up.","Squeeze the biceps hard at the top.","Lower the dumbbells under control to full extension.","Repeat for the desired number of reps."],["Keep your chest glued to the pad for the whole set.","Squeeze at the top without letting the elbows drift backward.","Use the full range - the stretch at the bottom is half the value."],{"start":"images/flat/spider-curl-start.webp","peak":"images/flat/spider-curl-peak.webp"},"strength"],["spiderman-push-up","Spiderman Push-Up","intermediate","bodyweight","chest","A push-up in which one knee is drawn up toward the elbow on the same side as the body lowers, like a spider climbing a wall. It trains the chest, shoulders and triceps while the obliques and hip flexors hold the trunk steady.",["Start in a high plank with the hands slightly wider than the shoulders and the body in a straight line.","Begin to lower the chest toward the floor and at the same time lift one foot off the floor.","Draw that knee out and up toward the elbow on the same side, keeping the hips low.","Press back up to the plank while returning the leg to the starting position.","Repeat on the other side and keep alternating."],["Keep the hips level; letting them pike or sag takes the work off the trunk.","Bring the knee toward the elbow without letting the foot touch the floor.","Lower with control and keep the elbows at about 45 degrees to the body."],{"start":"images/flat/spiderman-push-up-start.webp","peak":"images/flat/spiderman-push-up-peak.webp"},"strength"],["split-jerk","Split Jerk","intermediate","barbell","full_body","An overhead lift driving the barbell up with a leg dip and receiving it in a split stance with locked arms.",["Hold the barbell across your front rack with elbows high.","Dip straight down by bending your knees slightly.","Explosively drive the bar overhead with your legs and arms.","Split your feet forward and back as the bar locks out.","Stand up by bringing your feet back together under the bar.","Lower the bar and repeat."],["Dip straight down rather than letting your torso tip forward.","Split your feet front and back as the bar locks out.","Bring your front foot back first when recovering."],{"start":"images/flat/split-jerk-start.webp","peak":"images/flat/split-jerk-peak.webp"},"olympic"],["split-squat","Split Squat","intermediate","bodyweight","upper_legs","A stationary lunge lowering straight down in a split stance, building single-leg strength without a step.",["Stand in a split stance with one foot forward and one back.","Keep your torso upright and core braced.","Lower your hips straight down by bending both knees.","Stop when the back knee is just above the floor.","Drive through the front heel to return to the start.","Complete reps on one side, then switch."],["Lower straight down rather than lunging forward.","Keep most of your weight over the front foot.","Keep the front heel planted throughout the rep."],{"start":"images/flat/split-squat-start.webp","peak":"images/flat/split-squat-peak.webp"},"strength"],["spoto-press","Spoto Press","intermediate","barbell","chest","A bench press variation pausing the bar just above the chest to build control and pressing power.",["Lie on a flat bench and grip the barbell slightly wider than shoulders.","Unrack the bar and hold it over your chest with arms extended.","Lower the bar until it is one inch above your chest.","Pause there for a full second without touching the chest.","Press the bar back up until your arms are extended.","Repeat for the desired number of reps."],["Keep your shoulder blades retracted and pinned to the bench.","Hold the bar motionless during the pause instead of letting it drift.","Use a lighter load than your standard bench press."],{"start":"images/flat/spoto-press-start.webp","peak":"images/flat/spoto-press-peak.webp"},"strength"],["squat","Barbell Back Squat","intermediate","barbell","upper_legs","A compound lower-body movement targeting the quadriceps, glutes, and hamstrings.",["Position the bar on your upper traps.","Unrack and step back, feet shoulder-width apart.","Brace your core and squat down until thighs are parallel.","Drive through your heels to stand back up.","Repeat."],["Keep your chest up throughout the movement.","Push your knees out in line with your toes."],{"start":"images/flat/squat-start.webp","peak":"images/flat/squat-peak.webp"},"strength"],["squat-hold","Squat Hold","beginner","bodyweight","upper_legs","A static squat held with the thighs about parallel to the floor and the arms reaching forward for balance. It builds endurance in the quadriceps and glutes without equipment.",["Stand with the feet shoulder-width apart and the toes turned slightly out.","Reach the arms straight forward to counterbalance.","Squat down until the thighs are parallel to the floor, keeping the chest up and the heels down.","Hold the position, keeping the knees in line with the toes.","Stand up to finish."],["Keep the weight through the middle of the feet and the heels on the floor.","Do not let the knees cave in or the back round.","Build the hold time gradually and rest when the thighs begin to shake."],{"main":"images/flat/squat-hold-main.webp"},"strength"],["squat-pulse","Squat Pulse","beginner","bodyweight","upper_legs","A bodyweight squat variation in which you drop into the squat and then make short, controlled up-and-down pulses in the lower half of the movement without standing up. The constant tension keeps the thighs and glutes working through the whole set.",["Stand with the feet about shoulder-width apart and the toes turned slightly out, arms reaching forward for balance.","Squat down until the thighs are at least parallel to the floor, keeping the chest up and the heels down.","From the bottom, rise only a short way, a few inches, then sink back down.","Keep pulsing in the lower range without locking out or resting at the top.","Stand up fully when the set is finished."],["Keep the knees tracking over the toes; do not let them cave inward.","Stay in the bottom half of the squat; standing up between pulses removes the tension this move is for.","Keep the pulses small and quick but controlled; do not bounce off the bottom."],{"start":"images/flat/squat-pulse-start.webp","peak":"images/flat/squat-pulse-peak.webp"},"strength"],["stability-ball-hip-bridge","Stability Ball Hip Bridge","beginner","stability_ball","upper_legs","A glute bridge with the feet on a stability ball, adding an anti-rotation and balance demand to the basic bridge pattern.",["Lie face-up on the floor and place both feet on top of a stability ball.","Arms rest at the sides on the floor for balance.","Squeeze the glutes and press the heels into the ball to raise the hips.","Finish with a straight line from shoulders to knees.","Lower the hips under control without the ball rolling away.","Repeat for the recommended number of repetitions."],["The ball will try to drift - keep the feet pressed straight down.","No hyperextension at the top; stop when the body is in a line."],{"start":"images/flat/stability-ball-hip-bridge-start.webp","peak":"images/flat/stability-ball-hip-bridge-peak.webp"},"strength"],["stability-ball-knee-tuck","Stability Ball Knee Tuck","intermediate","stability_ball","core","A plank-position knee tuck with the feet on a stability ball, rolling the ball in under the hips to load the abs dynamically.",["Start in a high plank with both shins or the tops of the feet on top of a stability ball.","Hands are under the shoulders, body in a straight line.","Brace the core and pull the ball toward the chest by tucking the knees in.","Roll it back out by extending the legs fully back to the plank position.","Repeat for the recommended number of repetitions."],["Hips do not pike up; keep a level trunk throughout the roll-in.","Shoulders stay over the wrists - don't let them drift forward."],{"start":"images/flat/stability-ball-knee-tuck-start.webp","peak":"images/flat/stability-ball-knee-tuck-peak.webp"},"strength"],["stability-ball-push-up","Stability Ball Push-Up","intermediate","stability_ball","chest","A push-up performed with the feet on a stability ball, adding a strong anti-rotation demand to a standard push-up.",["Kneel in front of a stability ball and place your shins or feet on top of it.","Set the hands on the floor under the shoulders in a high-plank position.","Brace the core hard - the ball will want to roll sideways.","Lower the chest to the floor by bending the elbows.","Press back up to the starting position without letting the ball wobble.","Repeat for the recommended number of repetitions."],["Start with shins on the ball; feet-only is much harder.","If the ball drifts side to side, you're lacking core bracing - slow down."],{"start":"images/flat/stability-ball-push-up-start.webp","peak":"images/flat/stability-ball-push-up-peak.webp"},"strength"],["stability-ball-push-up-hands-on-ball","Stability Ball Push-Up (Hands on Ball)","intermediate","stability_ball","chest","An incline push-up performed with both hands on a stability ball and the feet on the floor. The unstable surface forces the chest, shoulders, and triceps to work harder while the core fights to keep the body rigid.",["Place both hands on top of a stability ball and walk your feet back into a straight-arm plank, body in a straight line from head to heels.","Brace your core and keep the ball steady beneath your hands.","Bend your elbows to lower your chest toward the ball under control.","Press back up to full arm extension without letting the ball roll.","Repeat for the desired number of reps."],["Keep your body in a rigid straight line - do not let your hips sag or pike up.","Move slowly and deliberately; the wobble of the ball is what makes the exercise work, so resist it rather than fight it fast.","Set your hands slightly wider than shoulder width on the ball for a more stable base, and keep your elbows tucked to about 45 degrees."],{"start":"images/flat/stability-ball-push-up-hands-on-ball-start.webp","peak":"images/flat/stability-ball-push-up-hands-on-ball-peak.webp"},"strength"],["stability-ball-wall-squat","Stability Ball Wall Squat","beginner","stability_ball","upper_legs","A bodyweight squat with a stability ball pinned between the lower back and a wall, keeping the spine guided.",["Place a stability ball between your lower back and a wall.","Step the feet forward about a foot, slightly wider than shoulder-width.","Squat down, letting the ball roll up the back as you descend.","Stop when thighs are parallel to the floor.","Drive through the heels to stand back up."],["Keep the weight in the heels and mid-foot.","Do not let the knees travel past the toes.","The ball should roll smoothly - do not lean off it."],{"start":"images/flat/stability-ball-wall-squat-start.webp","peak":"images/flat/stability-ball-wall-squat-peak.webp"},"strength"],["stair-climber","Stair Climber","beginner","stair_climber","upper_legs","A cardio machine movement that climbs a revolving staircase step after step, loading the glutes and quads continuously with no landing impact.",["Step onto the bottom stair with the machine at its slowest setting and take the rails lightly for balance.","Climb one step at a time, placing the whole foot on each stair rather than just the toes.","Stand upright with your chest open and your hips under your shoulders instead of hunching over the console.","Push the step down through the heel of the front foot, letting the glute of that leg do the work.","Set the pace so you can hold your posture, and keep climbing for the desired time or number of floors."],["Do not lean on the rails or hook your forearms over them - supporting your weight there takes the load off the legs and the readout stops meaning anything.","Full foot on the step, heel included. Climbing on the toes shifts the whole session into the calves and burns them out early.","Take one step at a time before you try skipping steps; deliberate, upright climbing beats a fast shuffle at the bottom of the staircase."],{"main":"images/flat/stair-climber-main.webp"},"cardio"],["standing-adductor-stretch","Standing Adductor Stretch","beginner","bodyweight","upper_legs","A standing stretch for the inner thigh: with your feet wide apart, you bend one knee and shift your weight to that side while the other leg stays straight. The straight leg's adductors lengthen as your hips sink toward the bent side.",["Stand with your feet about twice shoulder-width apart and your toes pointing forward.","Put your hands on the bent knee or in front of you for support.","Bend one knee and shift your hips sideways over that leg, keeping the other leg straight.","Keep your chest up and both feet flat on the floor.","Sink down until you feel a stretch along the inner thigh of the straight leg and hold it.","Shift to the other side and repeat."],["Keep the straight leg's foot flat or lift only the toes slightly; letting the foot roll out takes the stretch away.","Use your hands on the bent thigh to support your weight and keep your torso tall.","Do not bounce; sink slowly and stay within a stretch that feels strong but comfortable."],{"main":"images/flat/standing-adductor-stretch-main.webp"},"stretching"],["standing-calf-raise","Standing Calf Raise","beginner","standing_calf_raise_machine","lower_legs","A calf raise performed standing to develop the gastrocnemius through a full range of motion.",["Stand on the edge of a platform or calf raise machine.","Lower heels below the platform.","Push up onto your toes.","Lower slowly.","Repeat."],["Pause at the top to maximize contraction.","Full heel drop increases range of motion."],{"start":"images/flat/standing-calf-raise-start.webp","peak":"images/flat/standing-calf-raise-peak.webp"},"strength"],["standing-calf-stretch","Standing Calf Stretch","beginner","bodyweight","lower_legs","A staggered-stance stretch that lengthens the calf by pressing the rear heel down with the back leg straight.",["Step one foot back into a staggered stance.","Keep the back leg straight and the heel pressed down.","Bend the front knee and lean your weight forward.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep the rear heel flat and toes pointing forward.","Bend the rear knee slightly to target the lower calf."],{"main":"images/flat/standing-calf-stretch-main.webp"},"stretching"],["standing-forward-fold","Standing Forward Fold","beginner","bodyweight","upper_legs","A standing stretch that lengthens the hamstrings and lower back by folding the torso over straight legs.",["Stand tall with your feet hip-width apart and legs straight.","Hinge at your hips and fold your torso down toward the floor.","Let your hands and head hang toward your feet.","Hold for 20 to 30 seconds, breathing steadily."],["Bend your knees slightly if your hamstrings feel tight.","Ease into the stretch slowly - never bounce."],{"main":"images/flat/standing-forward-fold-main.webp"},"stretching"],["standing-forward-fold-to-half-lift","Standing Forward Fold to Half Lift","beginner","bodyweight","upper_legs","The familiar half-lift articulation: from a standing forward fold the chest lifts to a flat back with the spine long, then folds again. It teaches the difference between a rounded fold and a long-spine hinge.",["Stand with the feet hip-width apart and fold forward from the hips.","Rest the hands on the shins, the floor or blocks.","Slide the hands up the shins and lift the chest until the back is flat and the spine is long.","Fold back down, letting the head and neck release.","Continue alternating between the two for the desired number of repetitions."],["Keep a soft bend in the knees so the movement comes from the hips.","Lift to a flat back rather than looking up; the neck follows the spine.","Draw the shoulders away from the ears in the lifted position."],{"start":"images/flat/standing-forward-fold-to-half-lift-start.webp","peak":"images/flat/standing-forward-fold-to-half-lift-peak.webp"},"stretching"],["standing-hip-abduction","Standing Hip Abduction","beginner","bodyweight","upper_legs","A bodyweight leg raise to the side while standing on the other leg. It trains the gluteus medius on the side of the lifted leg and, on the standing leg, the muscles that keep your hips level.",["Stand tall with your hands on your hips and your feet close together.","Shift your weight onto one leg and keep that knee slightly bent.","Lift the other leg straight out to the side, keeping the toes pointing forward and your trunk upright.","Raise the leg only as high as you can without leaning your upper body away from it.","Lower the leg slowly back next to the standing foot.","Complete the planned repetitions, then repeat on the other leg."],["Keep your hips square and your trunk still; leaning away from the lifted leg takes the work away from the hip.","Move with control on the way down as well; do not let the leg swing.","Hold on to a wall or a chair if you cannot stay balanced; add a loop band around your thighs once the movement is easy."],{"start":"images/flat/standing-hip-abduction-start.webp","peak":"images/flat/standing-hip-abduction-peak.webp"},"strength"],["standing-quad-stretch","Standing Quad Stretch","beginner","bodyweight","upper_legs","A standing balance stretch that lengthens the quadriceps by pulling the heel toward the glute.",["Stand on one leg, holding a wall for balance if needed.","Bend the other knee and grab that ankle behind you.","Pull the heel toward your glute, keeping knees together.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Tuck your pelvis under to deepen the stretch.","Keep your knees close together throughout."],{"main":"images/flat/standing-quad-stretch-main.webp"},"stretching"],["standing-side-bend","Standing Side Bend","beginner","bodyweight","core","A standing stretch that lengthens the obliques and lats by reaching overhead and bending to one side.",["Stand with feet hip-width and reach both arms overhead.","Clasp your hands and lengthen up tall.","Bend smoothly to one side in a long curve.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep both feet planted and hips steady.","Reach up and over rather than just leaning down."],{"main":"images/flat/standing-side-bend-main.webp"},"stretching"],["standing-side-bend-flow","Standing Side Bend Flow","beginner","bodyweight","core","A standing lateral flow: the arms reach overhead and the trunk bends from side to side in a controlled rhythm, lengthening the side body without holding either end position.",["Stand with the feet hip-width apart and reach both arms overhead.","Bend the trunk to one side, keeping both feet planted and the hips level.","Return through the centre with the ribs stacked over the pelvis.","Bend to the other side in the same way.","Keep alternating for the desired number of repetitions."],["Bend sideways only: letting the chest rotate turns it into a twist.","Keep both heels down so the movement stays in the trunk.","Move with the breath rather than bouncing at the end of the range."],{"start":"images/flat/standing-side-bend-flow-start.webp","peak":"images/flat/standing-side-bend-flow-peak.webp"},"stretching"],["standing-split","Standing Split","advanced","bodyweight","upper_legs","A standing forward fold with one leg lifted behind: the torso folds over the standing leg while the free leg reaches towards the ceiling.",["From a forward fold, place both hands on the floor or on blocks beside the standing foot.","Shift the weight onto one leg and lift the other leg behind you.","Keep the standing leg straight and the hips as level as the lift allows.","Hold the position for the prescribed time, drawing the chest towards the standing shin.","Lower the lifted foot down and repeat on the other side."],["Level the hips first and accept a lower lift; an open hip turns this into a different pose.","Use blocks under the hands so the spine can stay long.","Hold the standing ankle with one hand only when the balance is already steady."],{"main":"images/flat/standing-split-main.webp"},"stretching"],["stationary-bike","Stationary Bike","beginner","stationary_bike","upper_legs","A seated cardio machine movement that drives a flywheel through a continuous pedalling cycle, training the legs with no impact through the joints.",["Set the saddle height so your knee stays slightly bent at the bottom of the pedal stroke, then sit down and place the balls of your feet on the pedals.","Take the handlebars with a relaxed grip and sit tall, with your back neutral and your shoulders down.","Push one pedal down and forward while the other rises, keeping the effort in your legs rather than pulling on the bars.","Keep pedalling in a smooth, even circle at a steady cadence, breathing in rhythm with the stroke.","Adjust the resistance to hold your target effort, and continue for the desired time or distance."],["Set the saddle before you start: too low grinds the knees, too high rocks your hips side to side at the bottom of every stroke.","Drive with the legs and keep the upper body quiet - gripping and hauling on the bars adds nothing but neck and shoulder tension.","Raise the resistance rather than spinning the pedals loose and fast; a light flywheel at high cadence feels hard on the lungs but does little for the legs."],{"main":"images/flat/stationary-bike-main.webp"},"cardio"],["step-up-to-balance","Step-Up to Balance","beginner","bodyweight","upper_legs","A single-leg step-up that finishes with a balance hold: you step onto a low platform, drive the free knee up in front of you and stand tall on the working leg before stepping back down. The quadriceps and glutes lift the body while the hips and ankle work to keep you steady.",["Stand facing a low, stable step or bench and place one foot flat on top of it.","Press through the whole of the front foot and straighten that leg to lift your body onto the step.","As you rise, drive the other knee up in front of you until the thigh is about hip height.","Stand tall on the working leg and hold the knee-up position for a moment without leaning back.","Lower the free foot back to the floor under control, then step the working leg down as well.","Complete the planned repetitions on one leg, then switch to the other."],["Keep the whole foot on the step and push through it; pushing off the floor leg takes the work away from the front leg.","Keep the trunk upright and your hips level during the balance hold rather than tilting toward the lifted knee.","Choose a step low enough to stand up on without hopping; use a hand on a wall to start if balance is a limit."],{"start":"images/flat/step-up-to-balance-start.webp","peak":"images/flat/step-up-to-balance-peak.webp"},"strength"],["step-ups","Step Ups","intermediate","bodyweight","upper_legs","A lower-body exercise stepping onto a bench, building strength in the quads and glutes.",["Stand facing a sturdy box or bench.","Place one foot fully on the box surface.","Drive through that heel to lift your body onto the box.","Bring your trailing foot up to stand fully on the box.","Step back down leading with the same foot.","Alternate legs or complete all reps on one side before switching."],["Push through the lead heel rather than springing off the back leg.","Keep your torso upright and avoid leaning forward excessively.","Control the descent instead of dropping off the box."],{"start":"images/flat/step-ups-start.webp","peak":"images/flat/step-ups-peak.webp"},"strength"],["stiff-leg-deadlift","Stiff Leg Deadlift","intermediate","barbell","back","A hip hinge with nearly straight legs, lowering the bar along the thighs to stretch and load the hamstrings.",["Stand with feet hip-width apart and hinge at the hips, legs nearly straight, holding a barbell low in front of your shins with a flat back.","Keep your legs nearly straight with only a slight knee bend throughout.","Drive the hips forward and stand upright, the bar travelling along your legs.","Hinge at the hips again and lower the bar along your legs.","Go as low as your hamstring flexibility allows with a flat back.","Repeat for the desired number of reps."],["Push your hips back and keep the bar close to your legs.","Go only as deep as a flat back allows.","Feel the hamstrings load in the stretch, then drive the hips forward to stand."],{"start":"images/flat/stiff-leg-deadlift-start.webp","peak":"images/flat/stiff-leg-deadlift-peak.webp"},"strength"],["straight-arm-pulldown","Straight-Arm Pulldown","intermediate","cable","back","An isolation exercise for the lats using a cable with arms kept straight.",["Stand facing a cable machine with a straight bar attached to the high pulley.","With arms nearly straight, push the bar down in an arc toward your thighs.","Squeeze your lats at the bottom.","Slowly return the bar to the starting position.","Repeat."],["Maintain a slight elbow bend without turning the movement into a pressdown.","Hinge slightly at the hips and keep your back flat.","Avoid using body momentum to swing the bar down."],{"start":"images/flat/straight-arm-pulldown-start.webp","peak":"images/flat/straight-arm-pulldown-peak.webp"},"strength"],["straight-bar-cable-front-raise","Straight-Bar Cable Front Raise","intermediate","cable","shoulders","A front raise on a low cable pulley with a straight bar attachment held in both hands. Unlike the one-armed cable front raise, both arms drive the same bar, and the cable keeps tension on the front delts through the whole range.",["Attach a straight bar to a low cable pulley and stand facing away from the machine with the cable running forward past your legs.","Hold the bar with an overhand grip, hands about shoulder-width apart, arms hanging straight down in front of your thighs.","Keep the elbows almost straight and the core braced so the torso does not lean back.","Raise the bar forward in a smooth arc until it reaches shoulder height.","Lower it under control back to the thighs and repeat for the desired number of repetitions."],["Use a light weight - swinging the bar up with the legs or leaning back takes the work off the front delts.","Stop at shoulder height; raising the bar higher shifts the load onto the traps.","Keep the wrists neutral rather than letting them bend back under the bar."],{"start":"images/flat/straight-bar-cable-front-raise-start.webp","peak":"images/flat/straight-bar-cable-front-raise-peak.webp"},"strength"],["straight-bar-dips","Straight Bar Dips","intermediate","pull_up_bar","chest","A dip performed on top of a single straight bar instead of parallel bars: from a straight-arm support over the bar, the body lowers until the chest nears the bar, then presses back up.",["Grip a straight bar overhand, slightly wider than shoulder-width, and jump into a straight-arm support on top of it with the bar at your hips.","Lean your chest slightly forward and bend your elbows to lower yourself toward the bar, keeping the elbows pointing back.","Stop when the bar is close to your upper chest or at the deepest point you can control.","Press down through the bar to straighten your arms and return to the support position.","Repeat for the desired number of reps."],["Lean the chest forward over the bar as you lower; the bar is in front of you, so staying upright tips you backwards.","Engage your core to keep your body from swinging.","This is a harder wrist and shoulder position than standard dips -- build up volume gradually."],{"start":"images/flat/straight-bar-dips-start.webp","peak":"images/flat/straight-bar-dips-peak.webp"},"strength"],["strict-curl","Strict Curl","intermediate","dumbbell","upper_arms","A standing curl performed without any body English - the torso stays still and the elbows stay pinned, so the biceps do all the work.",["Stand tall with a dumbbell in each hand, arms at your sides and palms facing forward.","Pin your elbows against your sides and brace your core so your torso cannot swing.","Curl both dumbbells up by bending only at the elbows.","Lower them under control until your arms are straight.","Repeat for the desired number of reps."],["Standing with your back against a wall or post is a useful self-check - if your shoulders or hips leave it, you are using momentum.","Keep the elbows from drifting forward; the upper arms should stay vertical throughout.","Lower slower than you lift - the strict version lives in the descent."],{"start":"images/flat/strict-curl-start.webp","peak":"images/flat/strict-curl-peak.webp"},"strength"],["suitcase-carry","Suitcase Carry","beginner","kettlebell","core","A loaded walk with the weight in one hand only, so the trunk has to resist bending toward the load for the whole distance - the unilateral counterpart to the farmer's walk.",["Stand beside a single kettlebell or dumbbell with your feet under your hips.","Hinge at the hips, take the handle in one hand and stand up with the weight hanging at your side.","Pull that shoulder down and back, and brace as if you were about to be pushed sideways.","Walk forward with normal, even strides, keeping your torso upright and square rather than leaning away from the weight.","Keep the free arm relaxed at your side instead of sticking it out as a counterweight.","Carry for the desired distance or time, set the weight down under control, then repeat on the other side."],["Do the same distance on both sides. The whole value is in the asymmetry, and it only works if you load both directions equally.","If you find yourself tipping toward the weight or hiking the opposite hip, the weight is too heavy - this is a posture drill first.","Grip usually gives out before the trunk does. That is a legitimate training effect, but if it is always the limit, use straps for the heavier sets."],{"main":"images/flat/suitcase-carry-main.webp"},"strength"],["sumo-deadlift","Sumo Deadlift","intermediate","barbell","back","A deadlift variation with a wide stance that shifts emphasis to the glutes, quads, and inner thighs.",["Stand with feet wider than shoulder-width, toes pointed outward.","Grip the bar between your legs.","Brace your core and drive through your heels to stand.","Lower under control.","Repeat."],["Keep the bar close to your body.","Push your knees out in line with your toes."],{"start":"images/flat/sumo-deadlift-start.webp","peak":"images/flat/sumo-deadlift-peak.webp"},"strength"],["sumo-squat","Sumo Squat","intermediate","barbell","upper_legs","A barbell squat performed with a wide stance and turned-out toes, emphasizing the glutes and quads.",["Stand with feet wider than shoulder-width and toes turned out.","Hold a barbell across your upper back.","Brace your core and keep your chest up.","Bend at the hips and knees to lower into a deep squat.","Drive through your heels to stand back up.","Repeat for the desired number of reps."],["Push your knees outward in line with your toes.","Keep the bar path vertical over the middle of your feet.","Avoid letting your lower back round at the bottom of the squat."],{"start":"images/flat/sumo-squat-start.webp","peak":"images/flat/sumo-squat-peak.webp"},"strength"],["superman","Superman","beginner","bodyweight","back","A bodyweight lower-back exercise performed prone, lifting arms and legs simultaneously.",["Lie face down with arms extended overhead.","Simultaneously lift your arms, chest, and legs off the floor.","Hold briefly at the top.","Lower under control.","Repeat."],["Squeeze glutes as you lift.","Avoid jerking movements."],{"start":"images/flat/superman-start.webp","peak":"images/flat/superman-peak.webp"},"strength"],["supine-spinal-twist","Supine Spinal Twist","beginner","bodyweight","back","A lying twist that stretches the lower back, glutes and obliques by dropping a bent knee across the body.",["Lie on your back and bend one knee toward your chest.","Guide that knee across your body toward the floor.","Stretch your arms out wide and turn your head away.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],["Keep both shoulders on the floor.","Relax and keep breathing throughout."],{"main":"images/flat/supine-spinal-twist-main.webp"},"stretching"],["supine-windshield-wipers","Supine Windshield Wipers","intermediate","bodyweight","core","A lying rotation drill: with the knees bent or the legs raised, both legs swing from side to side like wipers while the shoulders stay pinned to the floor.",["Lie on your back with the arms out to the sides and the knees bent over the hips.","Brace the trunk so the lower back does not lift off the floor.","Lower both legs together towards one side as far as the shoulders stay down.","Bring them back through the centre and lower to the other side.","Keep alternating for the desired number of repetitions."],["Both shoulders stay on the floor; the range is defined by them, not by the legs.","Keep the knees together so the pelvis moves as one unit.","Straighten the legs for a much harder version once the control is there."],{"start":"images/flat/supine-windshield-wipers-start.webp","peak":"images/flat/supine-windshield-wipers-peak.webp"},"strength"],["supported-shoulderstand","Supported Shoulderstand","intermediate","bodyweight","core","An inversion resting on the shoulders and upper arms with the hands supporting the back, the body stacked vertically over the shoulders.",["Lie on your back, ideally with a folded blanket under the shoulders and the head off it.","Lift the legs overhead and support the lower back with both hands, elbows shoulder-width apart.","Walk the hands up the back and stack the hips over the shoulders until the body is vertical.","Hold the position for the prescribed time, keeping the head and neck completely still.","Lower the legs overhead and roll down slowly with the hands supporting the back."],["Keep the weight on the shoulders and upper arms, never on the neck.","Do not turn the head while inverted.","Build up with legs-up-the-wall and plow pose before holding this one for long."],{"main":"images/flat/supported-shoulderstand-main.webp"},"strength"],["supported-single-leg-stand","Supported Single-Leg Stand","beginner","bodyweight","lower_legs","A basic balance exercise in which you stand on one leg with a light hand on a chair or wall for support. The raised knee is held at hip height, and the standing leg keeps the ankle, knee and hip steady, which makes it a gentle starting point for balance work.",["Stand tall beside a sturdy chair, wall or rail and rest one hand lightly on it.","Shift your weight onto the leg nearer the support and keep that knee soft.","Lift the other knee in front of you until your thigh is about hip height.","Keep your chest tall, your hips level and your eyes on a fixed point ahead.","Hold the position for the planned time, using the support only as much as needed.","Lower the foot, rest briefly and repeat on the other leg."],["Press the standing foot evenly into the floor and let the toes spread; the ankle makes constant small adjustments.","Use only your fingertips on the support, and let go for a moment once you feel steady.","Do not lean toward the support or lift the hip; keep the pelvis level the whole time."],{"main":"images/flat/supported-single-leg-stand-main.webp"},"strength"],["svend-press","Svend Press","beginner","plates","chest","A plate-squeeze press that loads the pecs through isometric adduction as you extend the weight away from the chest.",["Stand upright holding a single weight plate (or two pressed together) between your palms at chest height.","Squeeze the plates hard to generate tension through the pecs.","Press the plates straight out in front of you until the arms are fully extended.","Pause briefly, keeping the squeeze, then return the plates to the chest.","Repeat for the recommended number of repetitions."],["The harder you squeeze the plates, the more chest activation you get.","Keep the plates at sternum height throughout - do not let them drop toward the hips."],{"start":"images/flat/svend-press-start.webp","peak":"images/flat/svend-press-peak.webp"},"strength"],["t-bar-row","T-Bar Row","intermediate","barbell","back","A compound row performed straddling a loaded T-bar, building thickness in the lats and rhomboids.",["Straddle the loaded T-bar with feet shoulder-width apart.","Hinge at the hips until your torso is around 45 degrees.","Grip the handles and keep your back flat.","Pull the bar up toward your chest by driving your elbows back.","Squeeze your shoulder blades at the top.","Lower the bar under control and repeat."],["Keep your hips fixed and avoid heaving the torso upright.","Maintain a soft bend in your knees to protect the lower back.","Let the weight stretch your lats fully at the bottom."],{"start":"images/flat/t-bar-row-start.webp","peak":"images/flat/t-bar-row-peak.webp"},"strength"],["tandem-stance","Tandem Stance","beginner","bodyweight","lower_legs","A balance hold in which one foot is placed directly in front of the other, heel touching toes, so your base of support is as narrow as a line. Holding the position with your arms out trains the ankles and hips to keep the body steady.",["Stand tall with your feet together and your arms out to the sides at shoulder height.","Step one foot forward and place it directly in front of the other, heel against toes.","Spread your weight evenly over both feet and keep your knees soft.","Look at a fixed point ahead of you and keep your hips and shoulders level.","Hold the position for the planned time, using your arms to correct small sways.","Swap the front foot and repeat."],["Do this beside a counter or wall at first so you can reach out if you lose your balance.","Keep your gaze on a fixed point; looking down makes it harder.","Make it harder by closing your eyes or standing on a folded towel once you can hold it for 30 seconds."],{"main":"images/flat/tandem-stance-main.webp"},"strength"],["thoracic-bridge","Thoracic Bridge","intermediate","bodyweight","core","A mobility hold that lifts the hips from a seated, hands-behind position into a reverse tabletop and opens the chest, extending the thoracic spine while the glutes and shoulders hold the bridge.",["Sit on the floor with knees bent and hands behind you, fingers pointing back.","Press through your hands and feet to lift your hips off the floor.","Continue pressing until your chest opens and your arms are extended.","Drop your head back and hold the position.","Breathe steadily while maintaining the bridge.","Lower back down under control."],["Drive the hips high and squeeze the glutes to protect the lower back.","Keep the feet flat and the weight even between hands and feet."],{"main":"images/flat/thoracic-bridge-main.webp"},"strength"],["thread-the-needle","Thread the Needle","beginner","bodyweight","back","A kneeling rotation: one arm slides under the body and the shoulder and side of the head rest on the floor, rotating the thoracic spine passively.",["Start on all fours with the hands under the shoulders and the knees under the hips.","Slide one arm underneath the body, palm facing up, until the shoulder and the side of the head rest on the mat.","Keep the hips stacked over the knees and walk the top hand forward or wrap it behind the back.","Hold the twist for the prescribed time, breathing into the upper back.","Press the top hand into the floor to come up and repeat on the other side."],["Keep the hips high over the knees; dropping them turns the rotation into a side bend.","Rest the head on a block if the shoulder cannot reach the floor comfortably.","Let the shoulder settle with the breath instead of pushing the twist deeper by force."],{"main":"images/flat/thread-the-needle-main.webp"},"stretching"],["thread-the-needle-flow","Thread the Needle Flow","beginner","bodyweight","back","The moving version of thread the needle: from all fours the arm threads under the body and then opens back up towards the ceiling, rotating the thoracic spine through its full range.",["Start on all fours with the hands under the shoulders and the knees under the hips.","Slide one arm under the body until the shoulder approaches the mat.","Reverse the motion and open that arm up towards the ceiling, following the hand with the eyes.","Return through the centre and repeat for the desired number of repetitions.","Change sides and repeat."],["Keep the hips over the knees so the rotation stays in the upper back.","Move at an even tempo instead of throwing the arm open.","Let the head follow the hand rather than leading the movement."],{"start":"images/flat/thread-the-needle-flow-start.webp","peak":"images/flat/thread-the-needle-flow-peak.webp"},"stretching"],["three-legged-dog","Three-Legged Downward Dog","intermediate","bodyweight","shoulders","Downward dog with one leg lifted: the shoulders carry more load while the lifted leg extends in line with the spine and the hips stay square.",["Set up in downward dog with the hands shoulder-width apart and the hips high.","Press both hands evenly into the floor and shift the weight slightly forward.","Lift one leg behind you until it is in line with the spine, keeping both hip points level.","Hold the position for the prescribed time with the standing heel reaching down.","Lower the leg and repeat on the other side."],["Keep the lifted hip from opening; a square pelvis matters more than height.","Press the base of the index finger down so the wrists stay comfortable.","Bend the standing knee slightly if the hamstring limits the shape."],{"main":"images/flat/three-legged-dog-main.webp"},"strength"],["thruster","Thruster","intermediate","barbell","shoulders","A full-body barbell movement combining a front squat with an overhead press in one fluid drive.",["Hold a barbell in a front rack position with elbows high.","Stand with feet shoulder-width apart.","Squat down to parallel while keeping your torso upright.","Drive up out of the squat and press the bar overhead in one motion.","Lock out your arms at the top with the bar overhead.","Lower the bar back to the front rack and repeat."],["Use the momentum from the squat drive to launch the press.","Keep your elbows high so the bar rests on your shoulders, not your wrists.","Finish each rep with the bar locked out over your ears."],{"start":"images/flat/thruster-start.webp","peak":"images/flat/thruster-peak.webp"},"strength"],["toes-to-bar","Toes to Bar","intermediate","pull_up_bar","core","An advanced hanging core exercise on a pull-up bar requiring hip flexion strength and lat engagement to touch the toes to the bar.",["Hang from a pull-up bar with an overhand grip, arms fully extended and body still.","Engage your lats and core to prevent swinging.","Raise your legs with straight knees, reaching your toes up toward the bar.","Touch the bar with your toes, then lower your legs under control.","Repeat for the desired reps."],["Initiate the movement from your core, not by kicking with momentum.","Exhale forcefully as you raise your legs to increase intra-abdominal pressure.","If you cannot reach the bar yet, build up with hanging leg raises first; they are the easier step towards it."],{"start":"images/flat/toes-to-bar-start.webp","peak":"images/flat/toes-to-bar-peak.webp"},"strength"],["torso-twists","Torso Twists","beginner","bodyweight","core","A standing rotational warm-up that turns the rib cage from side to side while the pelvis stays comparatively stable, mobilising the thoracic spine and trunk.",["Stand with the feet about shoulder-width apart and the knees softly bent.","Brace lightly and hold the hands together in front of the chest.","Rotate the rib cage to one side without shifting the feet.","Return through centre and rotate to the other side.","Continue alternating smoothly through a comfortable range."],["Turn from the upper back rather than wrenching the lower spine.","Keep the hips mostly forward and distribute the weight evenly between the feet.","Use a controlled rhythm; this is mobility work, not a ballistic swing."],{"main":"images/flat/torso-twists-main.webp"},"stretching"],["treadmill-running","Treadmill Running","beginner","treadmill","full_body","A running cardio movement performed on a motorised belt, holding a chosen pace and distance indoors with the surface and gradient under your control.",["Step onto the treadmill with a foot on each side rail, start the belt at a walking speed and step on once it is moving.","Build up to your running pace, landing under your hips rather than reaching out in front of you.","Run tall with your shoulders relaxed, your elbows bent at about ninety degrees and your arms swinging forward and back, not across your body.","Keep your eyes forward and stay in the middle of the belt instead of drifting back toward the rear roller.","Hold the pace for the desired time or distance, then slow the belt and walk for a few minutes before stepping off."],["Clip the safety key to your waistband - it is the only thing that stops the belt if you lose your footing.","Do not hold the handrails while running. Leaning on them shortens your stride, twists your posture and hides how hard you are actually working.","A one to two percent incline makes indoor running feel closer to running outdoors, where you have to push through air resistance."],{"main":"images/flat/treadmill-running-main.webp"},"cardio"],["tree-pose","Tree Pose","intermediate","bodyweight","upper_legs","A one-legged standing balance with the sole of the free foot placed on the inner calf or thigh and the hips level.",["Stand tall and shift the weight onto one foot.","Place the sole of the other foot on the inner calf or the inner thigh, avoiding the knee.","Press the foot and the leg into each other and level the hips.","Bring the hands to the chest or overhead and hold for the prescribed time.","Lower the foot and repeat on the other side."],["Never rest the foot against the side of the knee; above or below it only.","Fix the gaze on a still point to steady the balance.","Keep the pelvis facing forward instead of letting the lifted knee pull it open."],{"main":"images/flat/tree-pose-main.webp"},"strength"],["triangle-pose","Triangle Pose","intermediate","bodyweight","upper_legs","A wide-stance pose with both legs straight and the torso tilting sideways over the front leg, lengthening the hamstring and the whole side body.",["Stand wide with the front foot turned out and the back foot angled slightly in.","Keep both legs straight and reach the front hand forward as the hips shift back.","Tilt sideways and bring the bottom hand to the shin, a block or the floor, top arm reaching up.","Hold the position for the prescribed time, turning the chest towards the ceiling.","Press into the feet to come up and repeat on the other side."],["Reach out over the front leg before you tilt down; folding early collapses the pose.","Use a block under the bottom hand rather than dragging the chest towards the floor.","Keep both legs straight and the kneecaps lifted."],{"main":"images/flat/triangle-pose-main.webp"},"stretching"],["tricep-kickback","Dumbbell Tricep Kickback","beginner","dumbbell","upper_arms","An isolation exercise for the triceps performed in a bent-over position with a dumbbell in each hand.",["Hinge forward at the hips, holding a dumbbell in each hand with the elbows bent at 90 degrees.","Extend both arms straight back, squeezing the triceps.","Hold briefly at full extension.","Lower with control.","Repeat for the planned number of reps."],["Keep your elbows close to your sides and finish with your arms in line with your torso.","Use light dumbbells and avoid swinging them with momentum.","Keep your back flat and your knees slightly bent to hold the hinge."],{"start":"images/flat/tricep-kickback-start.webp","peak":"images/flat/tricep-kickback-peak.webp"},"strength"],["tricep-pushdown","Cable Tricep Pushdown","beginner","cable","upper_arms","An isolation exercise targeting the triceps using a cable machine.",["Stand facing a cable machine with a straight bar attachment.","Grip the bar and pin your elbows to your sides.","Push the bar down until your arms are fully extended.","Slowly return to the starting position.","Repeat."],["Keep your torso upright.","Only your forearms should move."],{"start":"images/flat/tricep-pushdown-start.webp","peak":"images/flat/tricep-pushdown-peak.webp"},"strength"],["triceps-dip-hold-bars","Triceps Dip Hold on Dip Bars","intermediate","dip_station","upper_arms","An isometric hold at the bottom of the parallel-bar dip: you lower yourself between the bars and stop with the elbows bent, leaning slightly forward. The triceps, the chest and the front of the shoulders stay under tension at the point where the dip is hardest.",["Grip the parallel bars of a dip station, press up and straighten your arms with your shoulders pushed down away from your ears.","Lean slightly forward, keep your legs together and cross your feet behind you if you want.","Lower yourself slowly by bending your elbows until your upper arms are about parallel to the floor.","Stop there and hold, with your elbows pointing back and your chest open.","Keep your shoulders down and your body steady while you hold for the planned time.","Press back up to straight arms and step down."],["Do not sink so far that your shoulders roll forward; if they do, hold a little higher.","Keep the elbows close to your body to load the triceps; flaring them sends the work to the chest and the shoulders.","Use a bench or a pair of stable boxes under your feet if the hold is too hard at first."],{"main":"images/flat/triceps-dip-hold-bars-main.webp"},"strength"],["triceps-dip-hold-bench","Triceps Dip Hold on Bench","intermediate","bodyweight","upper_arms","An isometric hold at the bottom of the bench dip: with your hands on the edge of a bench behind you and your legs out in front, you lower your body and stop with the elbows bent. The triceps work hard at the point where the dip is hardest, with less load on the shoulders than a deep dip on bars.",["Sit on the edge of a bench, place your hands next to your hips with your fingers pointing forward and walk your feet out so that your legs are straight.","Slide your hips off the bench and straighten your arms to hold your weight.","Lower your body by bending your elbows until they reach about 90 degrees, keeping your back close to the bench.","Stop there and hold, with your elbows pointing straight back and your chest open.","Keep your shoulders down and away from your ears while you hold for the planned time.","Press up to straight arms and sit back down."],["Do not drop lower than 90 degrees at the elbow; going deeper puts a lot of stress on the front of the shoulders.","Keep your back close to the bench and your elbows pointing back, not out to the sides.","Bend your knees and bring your feet closer to make the hold easier."],{"main":"images/flat/triceps-dip-hold-bench-main.webp"},"strength"],["trx-bicep-curl","TRX Bicep Curl","beginner","suspension_trainer","upper_arms","This exercise uses a suspension trainer to isolate and strengthen the biceps brachii and brachialis muscles, building upper arm strength and hypertrophy.",["Adjust the suspension trainer straps to a medium length.","Stand facing the anchor point, grasp the handles with an underhand grip, and lean back until your arms are fully extended.","Keep your body straight and core engaged, pull your chest towards your hands by bending your elbows.","Squeeze your biceps at the top of the movement.","Slowly extend your arms back to the starting position, controlling the descent.","Maintain tension throughout the set."],["Adjust your body angle to increase or decrease difficulty; leaning further back makes it harder.","Keep your elbows high and fixed to isolate the biceps effectively.","Avoid swinging your body or using momentum; focus on a controlled contraction.","Ensure a full range of motion, from full extension to a strong peak contraction."],{"start":"images/flat/trx-bicep-curl-start.webp","peak":"images/flat/trx-bicep-curl-peak.webp"},"strength"],["trx-chest-press","TRX Chest Press","beginner","suspension_trainer","chest","A compound push exercise using a suspension trainer to build chest strength and stability.",["Adjust the suspension trainer handles to mid-calf height.","Stand facing away from the anchor point, holding a handle in each hand, arms extended.","Lean forward into a plank position, keeping your body straight from head to heels.","Lower your chest towards your hands by bending your elbows, maintaining tension in the straps.","Press back up to the starting position, fully extending your arms and squeezing your chest."],["Keep your core engaged throughout the movement to maintain a rigid plank.","Control the eccentric (lowering) phase for better muscle activation.","Adjust your foot position to modify difficulty: closer to the anchor (more horizontal) is harder, further away (more upright) is easier.","Ensure your elbows track slightly out and back, not flaring wide."],{"start":"images/flat/trx-chest-press-start.webp","peak":"images/flat/trx-chest-press-peak.webp"},"strength"],["trx-face-pull","TRX Face Pull","beginner","suspension_trainer","shoulders","The TRX Face Pull is a compound pulling exercise targeting the posterior deltoids and rhomboids, using a suspension trainer to improve upper back strength and posture.",["Grasp the TRX handles with an overhand grip, palms facing down.","Lean back until your arms are fully extended and your body forms a straight line.","Pull the handles towards your face, driving your elbows high and wide.","Squeeze your shoulder blades together at the peak contraction.","Slowly extend your arms back to the starting position with control."],["Maintain a rigid torso throughout the movement; avoid arching your lower back.","Focus on initiating the pull with your upper back muscles, not just your arms.","Adjust your body angle to modify difficulty: a more horizontal position is harder."],{"start":"images/flat/trx-face-pull-start.webp","peak":"images/flat/trx-face-pull-peak.webp"},"strength"],["trx-hamstring-curl","TRX Hamstring Curl","intermediate","suspension_trainer","upper_legs","This isolation exercise uses a suspension trainer to target the hamstrings, glutes, and calves by curling the heels towards the glutes.",["Lie on your back with heels in the suspension trainer cradles, knees bent at 90 degrees.","Lift your hips off the floor, creating a straight line from knees to shoulders.","Extend your legs forward, maintaining hip elevation and core tension.","Pull your heels back towards your glutes, contracting your hamstrings forcefully.","Control the movement, avoiding any drop in hip height throughout the set."],["Keep your core braced to prevent your hips from sagging.","Focus on a strong hamstring contraction at the peak of the curl.","Control the eccentric phase by slowly extending your legs."],{"start":"images/flat/trx-hamstring-curl-start.webp","peak":"images/flat/trx-hamstring-curl-peak.webp"},"strength"],["trx-lunge","TRX Lunge","beginner","suspension_trainer","upper_legs","A beginner-friendly unilateral lower body exercise using a suspension trainer to target the quadriceps and glutes, while also engaging the hamstrings and gluteus medius for stability.",["Stand facing away from the anchor point with the suspension trainer straps behind you, hands on your hips or free for balance.","Place the top of one foot in the foot cradles and extend that leg behind you.","Brace your core and lower your body by bending the front knee, keeping your torso upright.","Descend until your front thigh is parallel to the floor or just below, maintaining tension on the suspension trainer.","Drive through your front heel to return to the starting position, extending the front leg.","Complete all reps on one side, then switch legs and repeat per side."],["Keep your front knee tracking over your toes, avoiding inward collapse.","Maintain a neutral spine throughout the movement, preventing excessive arching or rounding.","Control the eccentric (lowering) phase to maximize muscle engagement.","Adjust your distance from the anchor point to modify difficulty."],{"start":"images/flat/trx-lunge-start.webp","peak":"images/flat/trx-lunge-peak.webp"},"strength"],["trx-pistol-squat","TRX Pistol Squat","intermediate","suspension_trainer","upper_legs","A challenging unilateral leg exercise using a suspension trainer to assist balance and depth, primarily targeting the quadriceps and glutes.",["Anchor the suspension trainer and hold the handles with both hands, arms extended.","Stand tall, lift one leg straight out in front of you, keeping it off the ground.","Initiate the squat by pushing your hips back and bending the standing knee, lowering your body as deep as possible.","Keep your chest up, back straight, and use the TRX for balance and support as needed.","Drive through your heel to return to the starting position, extending the standing leg fully.","Complete all reps on one side before switching to the other."],["Maintain tension on the TRX straps throughout the movement for stability.","Focus on controlled descent and powerful ascent.","Keep the non-working leg extended and elevated to engage the hip flexors.","Adjust your grip on the TRX to modify the level of assistance."],{"start":"images/flat/trx-pistol-squat-start.webp","peak":"images/flat/trx-pistol-squat-peak.webp"},"strength"],["trx-plank","TRX Plank","intermediate","suspension_trainer","core","A plank variation with feet suspended in TRX straps, increasing instability and core demand.",["Place both feet in the TRX foot cradles.","Assume a forearm or high plank position on the floor.","Keep your body in a straight line from head to heels.","Brace your core and squeeze your glutes.","Hold the position for the desired time.","Lower your knees to exit safely."],["Do not let your hips sag toward the floor or pike upward.","Stack your shoulders directly over your elbows or hands.","Minimize strap sway by pressing your feet gently into the cradles."],{"main":"images/flat/trx-plank-main.webp"},"strength"],["trx-row","TRX Row","beginner","suspension_trainer","back","This bodyweight pulling exercise uses a suspension trainer to target your entire back, building strength in the lats, rhomboids, and biceps.",["Grasp the handles of a suspension trainer with a neutral grip, palms facing each other.","Lean back, extending your arms fully, keeping your body straight from head to heels.","Engage your core and pull your chest towards your hands, squeezing your shoulder blades together.","Pause briefly at the top, then slowly lower yourself back to the starting position with control.","Maintain a rigid body throughout the movement, avoiding any sagging in the hips."],["Adjust your foot position: the closer your feet are to the anchor point, the harder the exercise.","Keep your elbows close to your body to emphasize the lats, or flare them slightly for more upper back.","Focus on initiating the pull with your back muscles, not just your arms.","Control the eccentric (lowering) phase to maximize muscle engagement."],{"start":"images/flat/trx-row-start.webp","peak":"images/flat/trx-row-peak.webp"},"strength"],["trx-side-plank","TRX Side Plank","intermediate","suspension_trainer","core","A side plank with both feet suspended in TRX cradles, intensifying the demand on the obliques.",["Place both feet in the TRX foot cradles and lie on your side.","Prop up on your bottom forearm with your elbow under your shoulder.","Lift your hips so your body forms a straight line.","Stack your top foot over the bottom foot.","Hold the position while breathing steadily.","Lower and switch sides after the set."],["Brace your obliques before lifting your hips off the floor.","Do not let your hips drop toward the floor.","Press the forearm into the floor to keep the shoulder active."],{"main":"images/flat/trx-side-plank-main.webp"},"strength"],["trx-squat","TRX Squat","beginner","suspension_trainer","upper_legs","This bodyweight compound exercise utilizes a suspension trainer to assist in performing a squat, effectively targeting the quadriceps, glutes, and hamstrings for lower body strength and stability.",["Stand facing the anchor point, holding the handles with palms facing each other, arms extended.","Lean back slightly, keeping your body straight and core engaged, with feet shoulder-width apart.","Initiate the squat by pushing your hips back and bending your knees, lowering your body as if sitting in a chair.","Descend until your thighs are parallel to the floor or as deep as comfortable, maintaining tension on the straps.","Drive through your heels to return to the starting position, extending your hips and knees fully."],["Keep your chest up and gaze forward throughout the movement to maintain a neutral spine.","Use the suspension trainer for assistance to control your descent and ascent, especially if new to squats.","Focus on pushing your knees out slightly to engage your glutes more effectively."],{"start":"images/flat/trx-squat-start.webp","peak":"images/flat/trx-squat-peak.webp"},"strength"],["trx-tricep-extension","TRX Triceps Extension","intermediate","suspension_trainer","upper_arms","This exercise targets the triceps brachii using a suspension trainer, focusing on elbow extension for upper arm development and strength.",["Stand facing away from the anchor point, holding the TRX handles with an overhand grip, palms facing down.","Lean forward, extending your arms straight out in front of you at shoulder height, creating tension in the straps.","Keeping your elbows high and fixed, bend them to lower your body by letting your hands move towards your temples.","Extend your elbows forcefully to push your body back to the starting position, squeezing your triceps.","Maintain a rigid plank position throughout the movement, engaging your core and glutes."],["Adjust your body angle to increase or decrease difficulty; the more horizontal, the harder the exercise.","Keep your elbows pointing forward and high to maximize triceps isolation and minimize shoulder involvement.","Control the eccentric (lowering) phase for better muscle engagement and growth."],{"start":"images/flat/trx-tricep-extension-start.webp","peak":"images/flat/trx-tricep-extension-peak.webp"},"strength"],["trx-y-fly","TRX Y-Fly","intermediate","suspension_trainer","shoulders","This suspension trainer exercise targets the posterior deltoids and trapezius, improving shoulder health and posture by strengthening the upper back.",["Stand facing the anchor point, holding the handles with an overhand grip, palms facing down.","Lean back, extending your arms straight in front of you, maintaining a plank position with your body.","Raise your arms up and out into a 'Y' overhead, pulling your shoulder blades together and down as your body rises toward the anchor.","Keep a slight, fixed bend in the elbows throughout and squeeze your shoulder blades at the top.","Slowly control the descent back to the starting position, resisting the pull of the straps."],["Adjust your body angle to modify difficulty: leaning further back increases the challenge.","Focus on retracting and depressing your shoulder blades throughout the movement.","Maintain a rigid core and straight body line to prevent sagging hips."],{"start":"images/flat/trx-y-fly-start.webp","peak":"images/flat/trx-y-fly-peak.webp"},"strength"],["upright-row","Barbell Upright Row","intermediate","barbell","shoulders","A compound pulling movement for the lateral deltoids and upper traps.",["Stand holding a barbell with a shoulder-width overhand grip.","Pull the bar straight up along your body toward your chin.","Lead with your elbows, keeping them above your hands.","Lower the bar with control.","Repeat."],["Use a lighter weight if you feel pinching in your shoulders.","Avoid bending your wrists excessively as the bar rises.","Avoid swinging or using your legs to heave the weight up."],{"start":"images/flat/upright-row-start.webp","peak":"images/flat/upright-row-peak.webp"},"strength"],["upward-dog","Upward-Facing Dog","intermediate","bodyweight","core","A prone backbend on straight arms with the thighs lifted off the floor, so the arms and back extensors hold the chest open and the spine long.",["Lie face down with the hands beside the lower ribs and the tops of the feet on the floor.","Press the hands down and straighten the arms, lifting the chest and then the thighs off the mat.","Draw the shoulders back and down and keep the neck long.","Hold the position for the prescribed time with only the hands and the tops of the feet on the floor.","Bend the arms and lower down under control."],["Keep the shoulders over the wrists rather than behind them.","Press the tops of the feet down; that is what lifts the thighs.","If the thighs cannot lift, stay in cobra instead of forcing the position."],{"main":"images/flat/upward-dog-main.webp"},"stretching"],["v-bar-lat-pulldown","V-Bar Lat Pulldown","beginner","lat_pulldown_machine","back","A neutral-grip pulldown performed with a narrow V-handle, maximizing lat stretch and allowing a deeper contraction.",["Attach a V-bar (double-D handle) to a lat pulldown cable.","Sit with the thighs secured under the pad and grip the handle, palms facing each other.","Begin with the arms fully extended overhead.","Pull the handle down to the sternum by driving the elbows down and slightly back.","Squeeze the lats at the bottom, then return slowly under control.","Repeat for the recommended number of repetitions."],["The neutral grip is easier on the shoulders than pronated or supinated grips.","Imagine pulling your ribs toward your hips - think lats, not arms."],{"start":"images/flat/v-bar-lat-pulldown-start.webp","peak":"images/flat/v-bar-lat-pulldown-peak.webp"},"strength"],["v-bar-tricep-pushdown","V-Bar Tricep Pushdown","beginner","cable","upper_arms","A cable tricep pushdown using a V-handle, which locks the wrists in a pronated, slightly-angled position and loads the lateral head.",["Attach a V-bar handle to a high cable pulley.","Stand facing the stack and grip the V-bar with both hands, palms down.","Start with the elbows tucked to the sides, forearms parallel to the floor.","Press the handle down until the arms are fully extended.","Squeeze the triceps, then return under control to the starting position.","Repeat for the recommended number of repetitions."],["Keep the elbows pinned to the sides the entire set.","Don't lean into the bar; a small forward lean is fine, but let the triceps do the work."],{"start":"images/flat/v-bar-tricep-pushdown-start.webp","peak":"images/flat/v-bar-tricep-pushdown-peak.webp"},"strength"],["v-sit","V-Sit","intermediate","bodyweight","core","A static core hold balancing on the sit bones with the legs and torso lifted into a V, challenging the abdominals and hip flexors.",["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the floor.","Reach your arms forward so your body forms a V shape.","Balance on your sit bones with core tight.","Hold the position while breathing steadily.","Lower your legs and torso to exit."],["Keep your chest lifted and spine long rather than rounding the back.","Bend the knees if you cannot hold straight legs yet."],{"main":"images/flat/v-sit-main.webp"},"strength"],["v-ups","V Ups","intermediate","bodyweight","core","A dynamic core exercise raising the legs and torso together into a V shape, training the abs and hip flexors.",["Lie flat on your back with arms extended overhead and legs straight.","Simultaneously raise your legs and upper body toward each other.","Reach your hands toward your feet at the top, forming a V shape.","Keep your legs straight throughout the movement.","Lower both ends under control back to the floor.","Repeat for the desired number of reps."],["Keep your legs straight as you lift them.","Reach your hands toward your feet at the top.","Lower both ends under control rather than dropping flat."],{"start":"images/flat/v-ups-start.webp","peak":"images/flat/v-ups-peak.webp"},"strength"],["walking","Walking","beginner","bodyweight","full_body","Unaided gait on level ground, keeping one foot in contact with the floor throughout, which makes it the lowest-impact way to accumulate aerobic work.",["Stand tall with your weight over the middle of your feet and your shoulders relaxed, not pulled back.","Step forward and land on your heel, then roll through the foot and push off the ball and toes.","Keep at least one foot on the ground at all times - as soon as both leave the floor you are running, not walking.","Let your arms swing naturally from the shoulder, opposite arm to opposite leg, with the elbows softly bent.","Look ahead rather than down at your feet, and breathe through a steady, repeatable rhythm.","Continue for the desired time or distance, picking a pace at which you could still hold a conversation."],["Pace is the whole variable here. A stroll and a brisk walk are different training stimuli, so pick one deliberately instead of drifting.","Lengthen the push behind you rather than reaching further in front - overstriding lands you on a straight leg and brakes every step.","This is the one piece of conditioning you can do daily without needing to recover from it, which is what makes it worth programming rather than leaving to chance."],{"main":"images/flat/walking-main.webp"},"cardio"],["walking-lunge","Walking Lunge","intermediate","bodyweight","upper_legs","A traveling lunge stepping forward leg over leg, training the quads and glutes with an added balance challenge.",["Stand tall with feet hip-width apart and hands on hips.","Step one foot forward into a long lunge.","Lower until both knees are around 90 degrees.","Drive through the front heel and step the back foot forward.","Continue alternating legs as you walk forward.","Repeat for the desired number of reps."],["Lower until both knees reach about 90 degrees.","Keep your torso upright as you step.","Drive through your front heel to step forward smoothly."],{"start":"images/flat/walking-lunge-start.webp","peak":"images/flat/walking-lunge-peak.webp"},"strength"],["wall-ball","Wall Ball","intermediate","wall_ball","full_body","A full-body conditioning exercise that joins a front squat and a throw: holding a soft wall ball at your chest, you squat down, drive up and throw the ball to a target high on a wall, then catch it and go straight into the next squat. The legs and hips produce the power and the arms finish the throw.",["Stand facing a wall about an arm's length away, feet shoulder-width apart, holding the ball at your chest with both hands.","Keep your elbows under the ball and your chest up.","Squat down until your hips are at or below knee height, keeping your heels on the floor.","Drive up hard through your legs and hips and, as you rise, throw the ball up to the target with both arms.","Catch the ball at chest height as it comes down, letting your arms absorb it.","Go straight into the next squat with the catch and repeat for the planned repetitions."],["Let the legs throw the ball: the push from the squat should carry it most of the way, the arms only finish the movement.","Keep your chest up and the ball close to your body in the squat so your back stays neutral.","Catch and squat in one movement; resting with the ball at the top breaks the rhythm and tires the shoulders."],{"main":"images/flat/wall-ball-main.webp"},"strength"],["wall-hamstring-stretch","Wall Hamstring Stretch","beginner","bodyweight","upper_legs","A restful stretch for the back of the thigh: lying on your back with one leg raised and its heel resting on a wall, you let the hamstring lengthen under gravity. The wall holds the leg in place so you can relax and control the amount of stretch by how close you lie to it.",["Lie on your back on the floor next to a wall or an open doorway, with your hips close to the wall.","Raise one leg and rest the heel on the wall with the knee as straight as you can comfortably get it.","Keep the other leg flat on the floor and your lower back relaxed.","Shuffle your hips closer to the wall to increase the stretch, or move away to ease it.","Breathe slowly and hold for the planned time while the hamstring relaxes.","Lower the leg and repeat on the other side."],["Keep your tailbone on the floor; lifting it off the floor takes the stretch out of the hamstring.","A slight bend in the knee is fine; straighten it only as far as feels comfortable.","Do not strain; the stretch should feel like a long pull, not sharp pain or tingling."],{"main":"images/flat/wall-hamstring-stretch-main.webp"},"stretching"],["wall-push-ups","Wall Push Ups","beginner","bodyweight","chest","A beginner-friendly push-up performed standing against a wall, reducing load on the chest and arms.",["Stand facing a wall and place your palms on it at shoulder height.","Step your feet back until your arms are fully extended.","Bend your elbows to bring your chest toward the wall.","Keep your body in a straight line throughout.","Press back to the starting position.","Repeat for the desired number of reps."],["Avoid flaring your elbows straight out to the sides.","Step your feet farther from the wall to increase the difficulty.","Keep your core engaged so your hips do not sag."],{"start":"images/flat/wall-push-ups-start.webp","peak":"images/flat/wall-push-ups-peak.webp"},"strength"],["wall-sit","Wall Sit","beginner","bodyweight","upper_legs","A static isometric exercise holding a squat position against a wall to build quad endurance.",["Stand with back against a wall.","Slide down until thighs are parallel to the floor.","Hold the position.","Stand back up when done."],["Keep knees at 90 degrees.","Press your back flat against the wall."],{"main":"images/flat/wall-sit-main.webp"},"strength"],["warrior-one","Warrior I","intermediate","bodyweight","upper_legs","A split-stance standing pose with the back foot planted at an angle, the front knee bent and the arms overhead, hips facing forward.",["Step one foot back and turn it out about forty-five degrees, planting the whole sole.","Bend the front knee until it stacks over the ankle and keep the back leg straight.","Draw both hip points towards the front of the mat and lift the arms overhead.","Hold the position for the prescribed time with the ribs down and the chest lifted.","Step the feet together and repeat on the other side."],["Widen the stance sideways so both hips can face forward without straining the back knee.","Press the outer edge of the back foot down to keep the base stable.","Take the arms shoulder-width apart if bringing the palms together arches the lower back."],{"main":"images/flat/warrior-one-main.webp"},"strength"],["warrior-three","Warrior III","intermediate","bodyweight","upper_legs","A single-leg balance with the torso and the lifted leg parallel to the floor, forming one long line from the fingertips to the raised heel.",["Stand on one leg with the knee soft and the hips level.","Hinge forward from the hips as the other leg lifts behind you.","Continue until the torso and the lifted leg are roughly parallel to the floor.","Reach the arms forward, back along the body or out to the sides, and hold for the prescribed time.","Lower the leg and repeat on the other side."],["Keep the lifted hip from opening upwards; both hip points face the floor.","Flex the lifted foot and press the heel back to keep the leg active.","Rest the hands on blocks or a wall while you are building the balance."],{"main":"images/flat/warrior-three-main.webp"},"strength"],["warrior-two","Warrior II","intermediate","bodyweight","upper_legs","A wide-stance pose with the front knee bent, the hips open to the side and the arms extended in line with the shoulders.",["Stand wide with the front foot turned out ninety degrees and the back foot slightly in.","Bend the front knee until it stacks over the ankle and tracks towards the middle toes.","Open the hips and chest to the side and extend the arms parallel to the floor.","Hold the position for the prescribed time, gazing over the front hand.","Straighten the front leg and repeat on the other side."],["Keep the front knee from drifting inwards; press it towards the little-toe side.","Stack the shoulders over the hips rather than leaning towards the front leg.","Shorten the stance if the front thigh cannot get close to parallel."],{"main":"images/flat/warrior-two-main.webp"},"strength"],["weighted-dips","Weighted Dips","advanced","dip_station","chest","A parallel-bar dip performed with extra load - most often a plate hung from a dip belt between the legs - to keep the movement in a strength rep range once bodyweight dips are easy.",["Attach a plate to a dip belt around your waist so the weight hangs between your legs.","Grip the parallel dip bars and press yourself up to the top position with your arms locked out and your feet off the floor.","Lean your torso slightly forward and lower your body by bending your elbows until your shoulders are below them.","Press back up through your palms until your arms are locked out again, keeping the hanging plate from swinging.","Repeat for the desired number of reps."],["Add weight only once you can do clean bodyweight dips through a full range - small jumps of 2.5-5 kg are enough, since the load stacks on top of your own bodyweight.","Keep your legs together and your core braced so the plate does not start swinging; a swinging weight throws off the bottom of the rep.","Keep your shoulders pulled down away from your ears and stop the descent if you feel pinching at the front of the shoulder."],{"start":"images/flat/weighted-dips-start.webp","peak":"images/flat/weighted-dips-peak.webp"},"strength"],["weighted-pull-up","Weighted Pull-Up","advanced","pull_up_bar","back","A pull-up performed with extra load - most often a plate hung from a dip belt between the legs - to keep the movement in a strength rep range once bodyweight pull-ups are easy.",["Attach a plate to a dip belt around your waist so the weight hangs between your legs, or hold the load between your feet.","Grip the pull-up bar with an overhand grip slightly wider than shoulder-width and hang at full arm extension with your legs together.","Pull your elbows down and back to drive your chest toward the bar until your chin clears it.","Lower yourself under control back to the full dead hang, keeping tension on your lats and letting the weight settle before the next rep.","Repeat for the desired number of reps."],["Add weight only once you can do clean bodyweight pull-ups through a full range - small jumps of 2.5-5 kg are enough, since the load stacks on top of your own bodyweight.","Keep your legs together and your core braced so the hanging plate does not start swinging; a swinging weight turns the rep into a kip.","Do not cut the bottom short - return to a full dead hang each rep, and stop the set when your chin stops clearing the bar rather than grinding out partials."],{"start":"images/flat/weighted-pull-up-start.webp","peak":"images/flat/weighted-pull-up-peak.webp"},"strength"],["weighted-wall-crunch","Weighted Wall Crunch","intermediate","plates","core","A crunch variation with the legs parked out of the way -- feet braced against a wall or box, or the legs simply held up -- so the hips stay quiet and the abs do the work.",["Lie on your back and park your legs so your hips cannot help: brace your feet against a wall or a box, or hold your legs up with the knees bent.","Hold a weight against your chest with both hands -- a plate, a dumbbell, or a kettlebell all work.","Crunch up, lifting your shoulder blades off the floor.","Lower with control.","Repeat."],["Exhale as you crunch up and inhale on the way down.","Keep your neck relaxed instead of pulling your head forward.","Press your lower back into the floor throughout the movement."],{"start":"images/flat/weighted-wall-crunch-start.webp","peak":"images/flat/weighted-wall-crunch-peak.webp"},"strength"],["wide-grip-bench-press","Wide-Grip Bench Press","intermediate","barbell","chest","A bench press variation with a wider-than-shoulder-width grip to maximize chest activation.",["Lie on a flat bench. Grip the barbell wider than shoulder-width.","Lower the bar to mid-chest.","Press back up to full extension.","Repeat."],["A wider grip reduces triceps involvement.","Avoid excessive wrist bending."],{"start":"images/flat/wide-grip-bench-press-start.webp","peak":"images/flat/wide-grip-bench-press-peak.webp"},"strength"],["wide-grip-pull-ups","Wide Grip Pull Ups","intermediate","pull_up_bar","back","A pull-up performed with a wide overhand grip, emphasizing the lats and upper-back width.",["Grip the pull-up bar with an overhand grip wider than shoulder-width.","Hang with arms fully extended and core braced.","Pull your chest toward the bar by driving your elbows down.","Keep your shoulders pulled back as you rise.","Lower yourself under control to full extension.","Repeat for the desired number of reps."],["Initiate each rep by depressing your shoulder blades before bending the arms.","Avoid kipping or swinging your legs for momentum.","Squeeze the bar firmly and keep your wrists straight."],{"start":"images/flat/wide-grip-pull-ups-start.webp","peak":"images/flat/wide-grip-pull-ups-peak.webp"},"strength"],["wide-grip-push-ups","Wide Grip Push Ups","intermediate","bodyweight","chest","A push-up variation with a wider hand placement to emphasize the chest.",["Start in a high plank with hands wider than shoulder-width.","Keep your body in a straight line from head to heels.","Lower your chest toward the floor by bending your elbows.","Keep your core braced and glutes engaged.","Press back up until your arms are extended.","Repeat for the desired number of reps."],["Keep your elbows at roughly 45 degrees from your torso.","Maintain a straight line from head to heels.","Lower until your chest is close to the floor."],{"start":"images/flat/wide-grip-push-ups-start.webp","peak":"images/flat/wide-grip-push-ups-peak.webp"},"strength"],["wide-grip-seated-cable-row","Wide Grip Seated Cable Row","intermediate","cable","back","A seated rowing variation with a wide grip emphasizing the upper back.",["Sit at a cable row station with feet on the platform.","Grip a wide bar with an overhand grip.","Pull the bar toward your upper abdomen, squeezing your shoulder blades.","Extend your arms back to the starting position with control.","Repeat."],["Keep your torso upright and avoid rocking back and forth.","Drive your elbows high and wide to target the upper back.","Maintain a slight bend in your knees throughout the set."],{"start":"images/flat/wide-grip-seated-cable-row-start.webp","peak":"images/flat/wide-grip-seated-cable-row-peak.webp"},"strength"],["wide-legged-forward-fold","Wide-Legged Forward Fold","beginner","bodyweight","upper_legs","A standing fold from a wide stance with the hands on the floor, lengthening the hamstrings and the inner thighs while the spine hangs long.",["Stand with the feet wide apart and the outer edges parallel.","Place the hands on the hips, lift the chest and hinge forward from the hip joints.","Bring the hands to the floor under the shoulders and let the head hang.","Hold the fold for the prescribed time, shifting the weight slightly into the balls of the feet.","Bring the hands back to the hips and come up with a flat back."],["Micro-bend the knees so the fold comes from the hips rather than the lower back.","Keep the feet parallel; turning them out takes the stretch out of the inner thighs.","Rest the hands on blocks when the floor is out of reach."],{"main":"images/flat/wide-legged-forward-fold-main.webp"},"stretching"],["wide-stance-leg-press","Wide-Stance Leg Press","beginner","leg_press","upper_legs","A leg press with a wide, slightly turned-out stance that increases the contribution of the adductors alongside hip and knee extension while the back stays supported.",["Set the back pad and seat so your lower back remains supported at the bottom of the repetition.","Place your feet wide on the platform with the toes turned out only as far as the knees can follow comfortably.","Lower the sled by bending the hips and knees while keeping the knees aligned with the toes and the feet flat.","Press through the whole foot and extend the hips and knees without forcing the knees into lockout.","Lower the sled under control and repeat for the desired number of repetitions."],["Use a width and toe angle that your hips can control; wider is not automatically better.","Keep the knees moving in the same direction as the toes rather than letting them collapse inward.","Stop the descent before the pelvis rolls under and the lower back loses contact with the pad."],{"start":"images/flat/wide-stance-leg-press-start.webp","peak":"images/flat/wide-stance-leg-press-peak.webp"},"strength"],["worlds-greatest-stretch","World's Greatest Stretch","beginner","bodyweight","full_body","A flowing mobility drill that combines a deep lunge with a trunk rotation. From a low lunge with both hands on the floor, you turn your chest toward the front leg and reach one arm to the ceiling, opening the hips, the upper back and the shoulder in one movement.",["Start in a push-up position with your hands under your shoulders and your body in a straight line.","Step one foot forward, outside the same-side hand, into a deep lunge and keep the back leg straight.","Keep the hand on the back-leg side planted under your shoulder and sink your hips toward the floor.","Rotate your chest toward the front leg, lifting the arm on that side up until it points at the ceiling, and follow your hand with your eyes.","Hold the open position for a breath, then lower your hand back to the floor.","Step back to the push-up position and repeat on the other side, alternating sides for the planned repetitions."],["Keep the back knee off the floor and the back leg active so the stretch runs through the front of the hip.","Rotate from the upper back rather than leaning sideways; the hips stay square and low throughout.","Move slowly and breathe out as you rotate; the stretch should feel open and controlled, never forced."],{"start":"images/flat/worlds-greatest-stretch-start.webp","peak":"images/flat/worlds-greatest-stretch-peak.webp"},"stretching"],["wrist-curl","Bilateral Dumbbell Wrist Curl","beginner","dumbbell","lower_arms","A dumbbell wrist curl performed with both arms at once, isolating the forearm flexors for a time-efficient forearm session.",["Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms up.","Let both dumbbells roll down to your fingertips.","Curl both dumbbells up by flexing your wrists.","Squeeze at the top, then lower under control.","Repeat for the desired number of reps."],["Keep your forearms pinned to your thighs throughout -- only the wrists move.","Use a lighter load per hand than you would single-arm, since both sides work simultaneously."],{"start":"images/flat/wrist-curl-start.webp","peak":"images/flat/wrist-curl-peak.webp"},"strength"],["wrist-roller","Wrist Roller","intermediate","wrist_roller","lower_arms","A forearm exercise winding a hanging weight up and down a roller, building grip and wrist strength.",["Grip the wrist roller handle with your elbows bent at your sides and your forearms in front of you at waist height.","Let the weight hang from the cord.","Roll the handle forward with alternating wrist movements to wind the weight up.","Keep your elbows at your sides throughout.","Once fully wound, reverse the rotation to lower the weight.","Repeat for the desired number of reps."],["Use full wrist rotations rather than small partial turns.","Keep your shoulders relaxed and avoid shrugging as you roll.","Control the unwinding phase instead of letting the weight drop."],{"start":"images/flat/wrist-roller-start.webp","peak":"images/flat/wrist-roller-peak.webp"},"strength"],["zercher-squat","Zercher Squat","advanced","barbell","upper_legs","A squat in which the barbell is held in the crooks of the elbows at the front of the body. The front-loaded bar keeps the torso upright and works the quadriceps, glutes, upper back and core.",["Set a barbell in a rack at about waist height, step in and hook it into the crooks of the elbows, with the forearms crossed or the hands clasped in front of the chest.","Lift the bar out of the rack, step back and stand with the feet about shoulder-width apart.","Brace the core and keep the chest up and the elbows pressed together.","Squat down by bending the hips and knees until the thighs are at least parallel to the floor.","Drive through the middle of the feet to stand back up.","Repeat for the desired number of repetitions, then re-rack the bar."],["Wrap the bar in a pad or towel; the elbow crease is sensitive and can bruise.","Keep the elbows high and together so the bar does not roll toward the hands.","Keep the torso upright; if the chest drops, lower the load."],{"start":"images/flat/zercher-squat-start.webp","peak":"images/flat/zercher-squat-peak.webp"},"strength"],["zottman-curl","Zottman Curl","intermediate","dumbbell","upper_arms","A standing dumbbell curl that lifts with a supinated grip, rotates to palms-down at the top, and lowers in pronation to combine biceps work with a forearm-heavy eccentric.",["Stand with your feet about hip-width apart, arms extended at your sides, and a dumbbell in each hand with the palms facing forward.","Keep your upper arms beside your ribs and curl both dumbbells toward your shoulders without swinging the torso.","At the top, keep the elbows bent and rotate the forearms until the palms face down.","Lower the dumbbells slowly with the pronated grip until the arms are straight.","Turn the palms forward again at the bottom and repeat for the desired number of repetitions."],["Use less weight than for a standard dumbbell curl; the palms-down lowering phase is usually the limiting part.","Rotate through the forearms while keeping the wrists straight rather than bending them around the handles.","Keep the elbows close to the ribs and avoid turning the curl into a shoulder swing."],{"start":"images/flat/zottman-curl-start.webp","peak":"images/flat/zottman-curl-peak.webp"},"strength"]];
for(const [sourceId,name,difficulty,equipment,body,description,instructions,tips,images,category] of REPDB_CATALOG){
 const id=REPDB_ALIASES[sourceId]||sourceId;
 const old=WORKOUT_LIBRARY.find(x=>x.id===id);
 if(old){old.sourceId=sourceId;old.sourceName=name;old.equipment=equipment;continue;}
 REPDB_IMAGES[id]=images;WORKOUT_MEDIA[id]=Object.keys(images);
 WORKOUT_LIBRARY.push({id,sourceId,sourceName:name,name,level:({beginner:'easy',intermediate:'medium',advanced:'hard'})[difficulty]||'medium',equipment,group:category==='stretching'?'Mobilitāte':REPDB_GROUPS[body]||'Pilns ķermenis',sets:'Apjoms nav noteikts',minutes:0,guide:description||instructions[0]||'',instructions,cues:tips,tags:[REPDB_GROUPS[body]||body,REPDB_EQUIPMENT[equipment]||equipment],catalog:true});
}
for(const x of WORKOUT_LIBRARY)if(!x.equipment)x.equipment='bodyweight';
function lbEquipmentName(x){return REPDB_EQUIPMENT[x.equipment]||x.equipment;}
function lbDurationLabel(x){return x.minutes?x.minutes+' min':'Ilgums nav noteikts';}
function lbTimeSummary(ids){const entries=ids.map(id=>lbEntry(id)).filter(Boolean),known=entries.reduce((n,x)=>n+(x.minutes||0),0),unknown=entries.filter(x=>!x.minutes).length;return (known?'~'+known+' min':'')+(unknown?(known?' + ':'')+unknown+' bez noteikta ilguma':'');}
